(window.GIM_TP=window.GIM_TP||{})["Z.Vaetchanan.0"]={"from":0,"a":[[["(דברים ג׳:כ״ג-כ״ד) וָאֶתְחַנַּן אֶל יְיָ' בָּעֵת הַהִיא לֵאמֹר. אֲדֹנָ\"י ידִֹוִ\"ד אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ וְגוֹ'. רִבִּי (בראשית י\"א) יוֹסֵי פָּתַח, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל יְיָ'. תָּא חֲזֵי, כַּמָּה הוּא חֵילָא תַּקִּיפָא דְּאוֹרַיְיתָא, וְכַמָּה הוּא עִלָּאָה עַל כֹּלָּא. דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, לָא דָּחִיל מֵעִלָּאֵי וְתַתָּאֵי. וְלָא דָּחִיל מֵעִרְעוּרִין בִּישִׁין דְּעָלְמָא. בְּגִין דְּאִיהוּ אָחִיד בְּאִילָנָא דְּחַיֵּי, וְאָכִיל מִנֵּיהּ בְּכָל יוֹמָא.","דְּהָא אוֹרַיְיתָא אוֹלִיף לֵיהּ לְבַּר נָשׁ, לְמֵיהַךְ בְּאֹרַח קְשׁוֹט. אוֹלִיף לֵיהּ עֵיטָא הֵיךְ יְתוּב קַמֵּי מָארֵיהּ (לבטלה לההיא גזרה). וַאֲפִילּוּ יִתְגְּזָר עָלֵיהּ מוֹתָא, כֹּלָּא יִתְבָּטַּל וְיִסְתְּלַּק מִנֵּיהּ, וְלָא שַׁרְיָא עֲלוֹי. (עיטא דבר נש בהאי עלמא) וְעַל דָּא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, וְלָא יִתְעֲדֵי מִנַהּ, הֲדָא הוּא דִכְתִיב, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְאִי אַעְדֵי מִינֵּיהּ אוֹרַיְיתָא, אוֹ אִתְפְּרַשׁ מִנַּהּ, כְּאִלּוּ אִתְפְּרַשׁ מִן חַיֵּי.","תָּא חֲזֵי, עֵיטָא דְּבַּר נָשׁ כַּד אִיהוּ סָלִיק בְּלֵילְיָא עַל עַרְסֵיהּ, בָּעֵי לְקַבְּלָא עָלֵיהּ עוֹל מַלְכוּתָא דִּלְעֵילָּא, בְּלִבָּא שְׁלִים. וּלְאַקְדְמֵי לְמִימְסַר גַּבֵּיהּ פִּקְדּוֹנָא דְּנַפְשֵׁיהּ. וְהָא אוּקְמוּהָ, בְּגִין דְּכָל עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא, דְּהָא אִילָנָא דְּמוֹתָא שַׁרְיָא בְּעָלְמָא, וְכָל רוּחֵי דִּבְנֵי נָשָׁא נָפְקִין, וְסַלְּקִין וְאִתְטַמְּרָן (ס\"א ואתמסרו) גַּבֵּיהּ. וּבְגִין דְּאִינּוּן בְּפִקְדּוֹנָא, כֻּלְּהוּ תַּיְיבִין לְאַתְרַיְיהוּ.","תָּא חֲזֵי, כַּד אִתְּעַר רוּחַ צָפוֹן בְּפַלְגּוּת לֵילְיָא, וְכָרוֹזָא נָפִיק. וְקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, כְּדֵין מִתְכָּוְונֵי (נ\"א מתערי) כָּל בְּנֵי מַטְרוֹנִיתָא, וְכָל בְּנֵי הֵיכָלָא, לְשַׁבְּחָא לֵיהּ לְמַלְכָּא קַדִּישָׁא. וּכְדֵין כָּל אִינּוּן פִּקְדּוֹנִין דְּרוּחִין דְּאִתְמַסְּרָן בִּידָהּ, כֻּלְּהוּ אָתִיב לְמָארֵיהוֹן. וְרוּבָּא דִּבְנֵי עָלְמָא מִתְעָרִין בְּהַהִיא שַׁעֲתָא, וְהָא פִּקְדוֹנֵיהּ דְּכֻלְּהוּ אָתִיב לְגַבַּיְיהוּ.","אִינּוּן דִּבְנֵי הֵיכָלָא עִלָּאָה קַיְימֵי בְּקִיּוּמַיְיהוּ, מִתְעֲרֵי מִשְׁתַּדְּלֵי בְּתוּשְׁבַּחְתָּא דְּאוֹרַיְיתָא, וּמִשְׁתַּתְּפֵי בִּכְנֶסֶת יִשְׂרָאֵל, עַד דְּנָהִיר יְמָמָא. כַּד אָתֵי צַפְרָא, הִיא, וְכָל בְּנֵי הֵיכָלָא (דמלכא) כֻּלְּהוּ אַתְיָין לְגַבֵּי מַלְכָּא קַדִּישָׁא, וְאִינּוּן אִקְרוּן בְּנִין דְּמַלְכָּא וּמַטְרוֹנִיתָא. וְהָא אוּקְמוּהָ.","כַּד אָתֵי צַפְרָא, בָּעֵי לְנַקָּאָה גַּרְמֵיהּ בְּכֹלָּא, וּלְמֵיזַן זַיְינֵיהּ, לְאִשְׁתַּדְּלָא עִם מַלְכָּא קַדִּישָׁא, דְּהָא בְּלֵילְיָא אִשְׁתְּדַּל בְּמַטְרוֹנִיתָא. הַשְׁתָּא אַתְיָא עִם מַטְרוֹנִיתָא, לְזַוְּוגָא לָהּ עִם מַלְכָּא.","אָתֵי לְבֵי כְּנִישְׁתָּא, מַדְכֵּי גַּרְמֵיהּ בְּקָרְבְּנִין, מְשַׁבַּח בְּתוּשְׁבַּחְתַּיְיהוּ דְּדָוִד מַלְכָּא. אָחִיד תְּפִילִין בְּרֵישֵׁיהּ, (ס\"א בידיה וברישיה) וְצִיצִית בְּגַדְפֵיהּ, אוֹמֵר תְּהִלָּה לְדָוִד. וְהָא אוּקְמוּהָ, צַלֵּי צְלוֹתָא קַמֵּי מָארֵיהּ, בִּצְלוֹתָא בָּעֵי לְמֵיקָם, כְּגַוְונָא (ס\"א בזווגא) דְּמַלְאֲכֵי עִלָּאֵי, לְאִתְחַבְּרָא בַּהֲדַיְיהוּ, דְּאִינּוּן אִקְרוּן הָעוֹמְדִים, כְּמָה דְאַתְּ אָמֵר, (זכריה ג׳:ז׳) וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים. וּלְכַוְּונָא רְעוּתֵיהּ קַמֵּי מָארֵיהּ, וְיִתְבַּע בָּעוּתֵיהּ.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַּר נָשׁ קָאִים בְּפַלְגּוּת לֵילְיָא מֵעַרְסֵיהּ, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כָּרוֹזָא קָארֵי עָלֵיהּ וְאָמַר, (תהילים קל״ד:א׳) הִנֵּה בָּרְכוּ אֶת יְיָ' כָּל עַבְדֵי יְיָ' הָעוֹמְדִים בְּבֵית יְיָ' בַּלֵּילוֹת. הַשְׁתָּא כַּד אִיהוּ קָאִים בִּצְלוֹתָא קַמֵּי מָארֵיהּ, הַהוּא כָּרוֹזָא קָּארֵי עָלֵיהּ וְאָמַר, וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶּה.","בָּתַר דִּמְסַיֵּים צְלוֹתָא בִּרְעוּ (וקאים בעיטא) קַמֵּי מָארֵיהּ, הָא אוּקְמוּהָ, דְּבָעֵי לְמִימְסַר נַפְשֵׁיהּ בִּרְעוּתָא דְּלִבָּא, לְהַהוּא אֲתָר דְּאִצְטְרִיךְ. וְכַמָּה עֵיטִין אִית לֵיהּ לְבַר נָשׁ בְּכֹלָּא. וּבְשַׁעֲתָא דִּצְלוֹתָא קַיְּימָא (ס\"א סיימא), כָּל אִינּוּן מִלִּין דְּאַפִּיק בַּר נָשׁ מִפּוּמֵיהּ בְּהַהִיא צְלוֹתָא, כֻּלְּהוּ סַלְּקִין לְעֵילָּא, וּבָקְעִין אֲוִירִין וּרְקִיעִין, עַד דְּמָטוּ לְהַהוּא אֲתָר דְּמָטוּ וּמִתְעַטְּרוּ בְּרֵישָׁא דְּמַלְכָּא, וְעָבִיד מִנַּיְיהוּ עֲטָרָה. וְהָא אוֹקְמוּהָ חַבְרַיָּיא, צְלוֹתָא דְּבָעֵי בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, לְכַוְּונָא דִּיהֵא צְלוֹתָא תַּחֲנוּנִים. מְנָלָן. מִמֹּשֶׁה, דִּכְתִּיב וָאֶתְחַנַּן אֶל יְיָ'. דָּא אִיהוּ צְלוֹתָא מֵעַלְיָא."],[[0,"ואתחנן אל ה' וגו':","ר' יוסי פתח, ויסב חזקיהו פניו אל הקיר ויתפלל אל ה'. בוא וראה כמה חזק כח התורה, וכמה היא עליונה על הכל. כי כל מי שעוסק בתורה אינו ירא מעליונים ותחתונים, ואינו ירא מהמקרים הרעים שבעולם, משום שהוא אחוז בעץ החיים, שהוא התורה, ואוכל ממנו בכל יום."],[1,"דהא אורייתא אוליף וכו':","כי התורה מלמדת את האדם ללכת בדרך האמת, מלמדת לו עצה איך לשוב לפני אדונו, ואפילו מות נגזר עליו, הכל מתבטל ומסתלק ממנו, ואינו שורה עליו. וע\"כ צריך לעסוק בתורה יומם ולילה, ולא יסור ממנה. ז\"ש והגית בו יומם ולילה. ואם מסיר ממנו התורה, או שנפרד ממנה, הוא כאלו נפרד מן החיים."],[2,"ת\"ח עיטא דב\"נ וכו':","בוא וראה, עצה לאדם. כשהוא עולה על מטתו בלילה, צריך לקבל עליו עול מלכות שמים בלב שלם, ולהקדים למסור אליו פקדון הנפש. והעמידוהו,משום שכל אדם טועם בלילה טעם המות, כי אילן המות שורה בעולם, שהוא המלכות, וכל רוחות בני אדם יוצאים ועולים ומסתתרים אצלו. אצל המלכות. ומשום שהם נתנים בפקדון, כולם חוזרים אח\"כ למקומם."],[3,"ת\"ח כד אתער וכו':","בוא וראה, כשמתעורר רוח צפון בחצות לילה, והכרוז יוצא. והקב\"ה בא לגן עדן להשתעשע ברוחות הצדיקים, אז מתעוררים כל בני המלכה וכל בני ההיכל לשבח את המלך הקדוש, ז\"א, ואז כל אלו הפקדונות של הרוחות שנמסרו בידה של המלכות, כולם מחזרת לבעליהם. ורוב בני העולם נעורים משינתם בשעה ההיא. ופקדונות של כולם מוחזרים להם."],[4,"אינון דבני היכלא וכו':","אלו שהם מבני ההיכל העליון, דהיינו עובדי השי\"ת, עומדים בקיומם, ומתעוררים ועוסקים בתשבחות התורה, ומתחברים עם כנסת ישראל, שהיא המלכות, עד שמאיר היום, כשבא הבוקר, הוא, וכל בני היכל המלך כולם באים אל המלך הקדוש, ז\"א. והם נקראים, בני המלך והמלכה. וכבר העמידוהו[1, 2]."],[5,"כד אתי צפרא וכו':","כשבא הבוקר צריך לנקות את עצמו בכל. הן נקיות הגוף והן נקיות הנפש, ולהזדיין בזיון שלו. דהיינו בציצית ותפלין, להשתדל עם מלך הקדוש, ז\"א, כי בלילה השתדל בהמלכה, עתה בבוקר, בא עם המלכה לחבר אותה עם המלך."],[6,"אתי לבי כנישתא וכו':","בא לבית הכנסת, מטהר את עצמו באמירת הקרבנות, משבח בתשבחותיו של דוד המלך. אחוז תפילין בראשו, ציצית בכנפי בגדו, אומר תהלה לדוד. והרי העמידו, המתפלל תפלה לפני אדונו, צריך לעמוד בתפלה כמו מלאכים העליונים,להתחבר עמהם, שהם נקראים העומדים. כמש\"א, ונתתי לך מהלכים בין העומדים. וצריך לכוון רצונו לפני אדונו, ויבקש בקשתו."],[7,"ת\"ח בשעתא דב\"נ וכו':","בוא וראה, בשעה שהאדם קם בחצות לילה ממטתו, לעסוק בתורה. כרוז קורא עליו ואומר, הנה ברכו את ה' כל עבדי ה' העומדים בבית ה' בלילות. עתה בבוקר, כשהוא עומד בתפלה לפני אדונו, הכרוז ההוא קורא עליו ואומר, ונתתי לך מהלכים בין העומדים האלה."],[8,"בתר דמסיים צלותא וכו':","אחר שגומר תפלתו ברצון לפני אדונו, הרי העמידו, שצריך למסור נפשו ברצון הלב, לאותו מקים שצריך, דהיינו למלכות. וכמה עצות יש לאדם בכל דבר. ובשעה שהוא נמצא בתפלה, כל אלו המלים שהאדם מוציא מפיו בתפלה ההיא, כולם עולים למעלה ובוקעים אוירים ורקיעים, עד שמגיעים למקום שמגיעים, (כמ\"ש לעיל ויקהל אות ק\"ל בהסולם) ומתעטרות בראש המלך. ועושה מהם עטרה. והרי העמידו החברים, התפלה שמבקש האדם להקב\"ה צריך לכוון שתהיה תפלת תחנונים. מאין לנו זה. ממשה, שכתוב, ואתחנן אל ה'. זו היא תפילה טובה."]],[[0,"","וָאֶתְחַנַּן אֶל ה' בָּעֵת הַהִוא לֵאמֹר. אֲדֹנָ\"י יֱהִֹוִ\"ה אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, [ישעיה לח] וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. בֹּא וּרְאֵה כַּמָּה הוּא הַכֹּחַ הֶחָזָק שֶׁל הַתּוֹרָה וְכַמָּה הוּא עֶלְיוֹן עַל הַכֹּל, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, לֹא פוֹחֵד מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, וְלֹא פוֹחֵד מִמִּקְרִים רָעִים שֶׁל הָעוֹלָם, מִשּׁוּם שֶׁהוּא אָחוּז בְּעֵץ הַחַיִּים וְאוֹכֵל מִמֶּנּוּ בְּכָל יוֹם."],[1,"","שֶׁהֲרֵי הַתּוֹרָה מְלַמֶּדֶת אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ אֱמֶת, מְלַמֶּדֶת אוֹתוֹ עֵצָה אֵיךְ יָשׁוּב לִפְנֵי רִבּוֹנוֹ [לבטל לאותה הגזרה], וַאֲפִלּוּ שֶׁתִּגָּזֵר עָלָיו מִיתָה – הַכֹּל יִתְבַּטֵּל וְיִסְתַּלֵּק מִמֶּנּוּ וְלֹא יִשְׁרֶה עָלָיו. [עצה של אדם בעולם הזה] וְעַל כֵּן צָרִיךְ לְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה וְלֹא יָזוּז מִמֶּנָּה, זֶהוּ שֶׁכָּתוּב [יהושע א] וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְאִם מֵזִיז מִמֶּנּוּ אֶת הַתּוֹרָה אוֹ נִפְרָד מִמֶּנָּה, כְּאִלּוּ נִפְרָד מִן הַחַיִּים."],[2,"","בֹּא וּרְאֵה, עֵצָה שֶׁל הָאָדָם, כְּשֶׁהוּא בַּלַּיְלָה עַל מִטָּתוֹ, צָרִיךְ לְקַבֵּל עָלָיו עֹל מַלְכוּת שֶׁל מַעְלָה בְּלֵב שָׁלֵם, וּלְהַקְדִּים לִמְסֹר אֵלָיו פִּקְדוֹן נַפְשׁוֹ. וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁכָּל הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, שֶׁהֲרֵי עֵץ הַמָּוֶת שָׁרוּי בָּעוֹלָם, וְכָל רוּחוֹת בְּנֵי אָדָם יוֹצְאוֹת וְעוֹלוֹת וּמִתְחַבְּאוֹת [ונמסרו] אֶצְלוֹ. וּמִשּׁוּם שֶׁהֵן בְּפִקָּדוֹן, כֻּלָּן שָׁבוֹת לִמְקוֹמוֹתֵיהֶן."],[3,"","בֹּא וּרְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן בַּחֲצוֹת הַלַּיְלָה, וְכָרוֹז יוֹצֵא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ בְּרוּחוֹת הַצַּדִּיקִים, אָז מִתְכַּוְּנִים [מתעוררים] כָּל בְּנֵי הַמַּלְכָּה וְכָל בְּנֵי הַהֵיכָל לְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ. וְאָז כָּל אוֹתָם פִּקְדוֹנוֹת שֶׁל הָרוּחוֹת שֶׁנִּמְסְרוּ בְיָדָהּ, אֶת כֻּלָּם מֵשִׁיב לְבַעְלֵיהֶם. וְרֹב בְּנֵי הָעוֹלָם מִתְעוֹרְרִים בְּאוֹתָהּ שָׁעָה, וַהֲרֵי פִּקָּדוֹן שֶׁל כֻּלָּם מֵשִׁיב אֲלֵיהֶם."],[4,"","אוֹתָם שֶׁבְּנֵי הַהֵיכָל הָעֶלְיוֹן עוֹמְדִים בְּעָמְדָם מִתְעוֹרְרִים, מִשְׁתַּדְּלִים בְּתִשְׁבְּחוֹת הַתּוֹרָה, וּמִשְׁתַּתְּפִים בִּכְנֶסֶת יִשְׂרָאֵל עַד שֶׁמֵּאִיר הַיּוֹם. כְּשֶׁמַּגִּיעַ הַבֹּקֶר, הִיא וְכָל בְּנֵי הַהֵיכָל [המלך], כֻּלָּם בָּאִים לַמֶּלֶךְ הַקָּדוֹשׁ, וְהֵם נִקְרָאִים בְּנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, וַהֲרֵי פֵּרְשׁוּהָ."],[5,"","כְּשֶׁמַּגִּיעַ הַבֹּקֶר צָרִיךְ לְנַקּוֹת עַצְמוֹ בַּכֹּל וְלַחְגֹּר כְּלֵי מִלְחַמְתּוֹ לְהִשְׁתַּדֵּל עִם הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי בַּלַּיְלָה הִשְׁתַּדֵּל בַּמַּלְכָּה. כָּעֵת בָּא עִם הַמַּלְכָּה לְזַוֵּג אוֹתָהּ עִם הַמֶּלֶךְ."],[6,"","בָּא לְבֵית הַכְּנֶסֶת, מְטַהֵר עַצְמוֹ בַּקָּרְבָּנוֹת, מְשַׁבֵּחַ בְּתִשְׁבְּחוֹת דָּוִד הַמֶּלֶךְ, אוֹחֵז תְּפִלִּין בְּרֹאשׁוֹ [בידו ובראשו] וְצִיצִית בִּכְנָפָיו, אוֹמֵר \"תְּהִלָּה לְדָוִד\". וַהֲרֵי פֵּרְשׁוּהָ, מִתְפַּלֵּל תְּפִלָּה לִפְנֵי רִבּוֹנוֹ, בַּתְּפִלָּה צָרִיךְ לַעֲמֹד, כְּמוֹ [בזווג] מַלְאָכִים הָעֶלְיוֹנִים, לְהִתְחַבֵּר עִמָּם, שֶׁהֵם נִקְרָאִים הָעוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר [זכריה ג] וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים, וּלְכַוֵּן רְצוֹנוֹ לִפְנֵי רִבּוֹנוֹ, וְיִתְבַּע בַּקָּשָׁתוֹ."],[7,"","בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָדָם קָם בַּחֲצוֹת הַלַּיְלָה מִמִּטָּתוֹ לְהִשְׁתַּדֵּל בַּתּוֹרָה, הַכָּרוֹז קוֹרֵא עָלָיו וְאוֹמֵר: [תהלים קלד] הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה' הָעֹמְדִים בְּבֵית ה' בַּלֵּילוֹת. עַכְשָׁו כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה לִפְנֵי רִבּוֹנוֹ, אוֹתוֹ כָּרוֹז קוֹרֵא עָלָיו וְאוֹמֵר: וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה."],[8,"","אַחַר שֶׁמְּסַיֵּם תְּפִלָּה בְרָצוֹן [ועומד בעצה] לִפְנֵי רִבּוֹנוֹ, הֲרֵי פֵּרְשׁוּהָ שֶׁצָּרִיךְ לִמְסֹר נַפְשׁוֹ בִּרְצוֹן הַלֵּב לְאוֹתוֹ מָקוֹם שֶׁצָּרִיךְ. וְכַמָּה עֵצוֹת יֵשׁ לָאָדָם בַּכֹּל. וּבְשָׁעָה שֶׁהַתְּפִלָּה קַיֶּמֶת [הסתימה], כָּל אוֹתָם דִּבּוּרִים שֶׁמּוֹצִיא אָדָם מִפִּיו בְּאוֹתָהּ תְּפִלָּה, כֻּלָּם עוֹלִים לְמַעְלָה וּבוֹקְעִים אֲוִירִים וּרְקִיעִים, עַד שֶׁמַּגִּיעִים לְאוֹתוֹ מָקוֹם שֶׁמַּגִּיעִים, וּמִתְעַטְּרִים בְּרֹאשׁ הַמֶּלֶךְ וְעוֹשִׂים מֵהֶם עֲטָרָה. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, תְּפִלָּה שֶׁצָּרִיךְ לַקָּדוֹשׁ־בָּרוּךְ־הוּא, לְכַוֵּן שֶׁתִּהְיֶה תְפִלַּת תַּחֲנוּנִים. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב וָאֶתְחַנַּן אֶל ה'. זוֹהִי תְפִלָּה מְעֻלָּה."]]],[["תָּא חֲזֵי, מַאן דְּקָאִים בִּצְלוֹתָא, בָּעֵי לְכַוְּונָא רַגְלוֹי, וְאוֹקְמוּהָ. וּבָעֵי לְחַפְּיָא רֵישֵׁיהּ, כְּמַאן דְּקָאִים קַמֵּי מַלְכָּא. וּבָעֵי לְמִכְסְיָיה (למכסייא) (ס\"א לאסתמא) עֵינוֹי, בְּגִין דְּלָא יִסְתָּכַּל בִּשְׁכִינְתָּא. וּבְסִפְרָא דְּרַב הַמְנוּנָא סָבָא אָמַר, מַאן דְּפָקַח עֵינוֹי בְּשַׁעֲתָא דִּצְלוֹתָא, אוֹ דְּלָא מָאִיךְ עֵינוֹי בְּאַרְעָא, אַקְדִּים עָלֵיהּ מַלְאַךְ הַמָּוֶת, וְכַד תִּיפּוּק נַפְשֵׁיהּ, לָא יִסְתָּכַּל בִּנְהִירוּ דִּשְׁכִינְתָּא, וְלָא יָמוּת בִּנְשִׁיקָה. מַאן דִּמְזַלְזֵל בִּשְׁכִינְתָּא מִתְּזַלְזֵּל הוּא בְּהַהוּא שַׁעֲתָא דְּאִצְטְרִיךְ בֵּיהּ, הֲדָא הוּא דִכְתִיב, (שמואל א ב׳:ל׳) כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ.","הַאי מַאן דְּאִסְתָּכַּל בִּשְׁכִינְתָּא, בְּשַׁעֲתָא דְּאִיהוּ מְצַלֵּי. וְהֵיךְ יָכִיל לְאִסְתַּכְּלָא בִּשְׁכִינְתָּא. אֶלָּא לִינְדַע דְּוַדַּאי שְׁכִינְתָּא קַיְּימָא קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, דְּתַמָּן שָׁארֵי שְׁכִינְתָּא. בְּגִין כָּךְ לָא בַּעְיָא לְמֶהֱוֵי חוֹצֵץ בֵּינוֹ וּבֵין הַקִּיר, וְאוֹקְמוּהָ.","מַאן דְּקָאִים בִּצְלוֹתָא, בָּעֵי לְסַדְּרָא שְׁבָחָא דְּמָארֵיהּ בְּקַדְמִיתָא, וּלְבָתַר יִתְבַּע בָּעוּתֵיהּ. דְּהָא מֹשֶׁה הָכִי אָמַר בְּקַדְמִיתָא, אַתָּה הַחִלּוֹתָ וְגוֹ'. וּלְבַסּוֹף אֶעְבְּרָה וְגוֹ'. רִבִּי יְהוּדָה אָמַר, מַאי שְׁנָא הָכָא דִּכְתִּיב אֲדֹנָ\"י בְּקַדְמִיתָא, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד, וּלְבַסּוֹף ידו\"ד, וְקָרֵינָן אֱלֹהִי\"ם. אֶלָּא סִדּוּרָא הָכִי הוּא מִתַּתָּא לְעֵילָּא, וּלְאַכְלְלָא מִדַּת יוֹם בַּלַּיְלָה, וּמִדַּת לַיְלָה בַּיוֹם וּלְזַוְּוגָא כֹּלָּא כַּחֲדָא כַּדְּקָא יָאוּת.","(דברים ג׳:כ״ד) אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ. מַאי שֵׁירוּתָא הָכָא. אֶלָּא וַדַּאי מֹשֶׁה שֵׁירוּתָא הֲוָה בְּעָלְמָא, לְמֶהֱוֵי שְׁלִים בְּכֹלָּא. וְאִי תֵּימָא יַעֲקֹב שְׁלִים הֲוָה, וְאִילָנָא אִשְׁתְּלִים לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. הָכִי הוּא וַדַּאי, אֲבָל מַה דְּהֲוָה לְמֹשֶׁה, לָא הֲוָה לְבַּר נָשׁ אַחֲרָא, דְּהָא אִתְעֲטָּר בִּשְׁלִימוּ יַתִּיר, בְּכַמָּה אֶלֶף וְרִבְּבָן מִיִּשְׂרָאֵל, בְּאוֹרַיְיתָא, בְּמַשְׁכְּנָא, בְּכֹהַנִין, בְּלֵיוָאֵי, בִּתְרֵיסַר שְׁבָטִין, רַבְרְבִין מְמָנָן עָלַיְיהוּ, בְּשִׁבְעִין סַנְהֶדְרִין. הוּא אִשְׁתְּלִים בְּגוּפָא שְׁלִים. אַהֲרֹן לִימִינָא, נַחְשׁוֹן לִשְׂמָאלָא, הוּא בֵּינַיְיהוּ.","בְּגִין כַּךְ אֶת גָּדְלְךָ, מִימִינָא, דָּא אַהֲרֹן. וְאֶת יָדְךָ הַחֲזָקָה, מִשְּׂמָאלָא, דָּא נַחְשׁוֹן. וְהָא אִתְּמַר. בְּגִין כָּךְ מֹשֶׁה שֵׁירוּתָא בְּעָלְמָא הֲוָה. וְאִי תֵּימָא מַאן הֲוָה סִיּוּמָא (דהא משה שירותא הוה). סִיּוּמָא מַלְכָּא מְשִׁיחָא הוּא, דְּהָא כְּדֵין יִשְׁתְּכַּח שְׁלִימוּ בְּעָלְמָא, מַה דְּלָא הֲוָה כֵּן לְדָרֵי דָּרִין. בְּהַהוּא זִמְנָא יִשְׁתְּכַּח שְׁלִימוּ לְעֵילָּא וְתַתָּא, וְיֵהוֹן עָלְמִין כֻּלְּהוּ בְּזִוּוּגָא חַד, כְּדֵין כְּתִיב (זכריה י״ד:ט׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.","(דברים ד') וַיֹּאמֶר יְיָ' אֵלַי רַב לָךְ אַל תּוֹסֶף וְגוֹ'. אָמַר רִבִּי חִיָּיא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, מֹשֶׁה, רַב לָךְ דְּאִזְדַּוְּוגַת בִּשְׁכִינְתָּא, מִכָּאן וּלְהָלְאָה אַל תּוֹסֶף, רִבִּי יִצְחָק אָמַר, רַב לָךְ בִּנְהִירוּ דְּשִׁמְשָׁא דְּהֲוָה גַּבָּךְ, אַל תּוֹסֶף, דְּהָא זִמְנָא דְּסִיהֲרָא מָטָא, וְסִיהֲרָא לָא יָכִיל לְאַנְהָרָא, עַד דְּיִתְכְּנִישׁ שִׁמְשָׁא. אֲבָל וְצַו אֶת יְהוֹשֻׁעַ וְחַזְּקֵהוּ וְאַמְּצֵהוּ. אַנְתְּ דְּהוּא שִׁמְשָׁא, בָּעֵי לְאַנְהָרָא לְסִיהֲרָא, וְהָא אִתְּמַר.","(דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם וְגוֹ'. רִבִּי יוֹסֵי אָמַר (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ וְגוֹ'. זַכָּאָה עַמָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּחַר בְּהוּ מִכָּל עַמִּין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְסָלִיק לוֹן לְעַדְבֵיהּ, וּבָרִיךְ לוֹן בְּבִרְכָתָא דִּילֵיהּ בְּבִרְכָתָא דִּשְׁמֵיהּ, הֲדָא הוּא דִּכְתִּיב, (ישעיהו ס״א:ט׳) כִּי הֵם זֶרַע בֵּרַךְ יְיָ', בֵּרַךְ יְיָ' מַמָּשׁ.","תָּא חֲזֵי, כָּל שְׁאַר עַמִּין דְּעָלְמָא, יָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְרַבְרְבֵי מְמָנָן, דְּשַׁלְטִין עָלַיְיהוּ. וְיִשְׂרָאֵל אָחִיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְעַדְבֵיהּ, לְחוּלָקֵיהּ, לְאִתְאַחֲדָא בֵּיהּ מַמָּשׁ. וְיָהִיב לוֹן אוֹרַיְיתָא קַדִּישָׁא, בְּגִין לְאִתְאַחֲדָא בִּשְׁמֵיהּ, וְעַל דָּא וְאַתֶּם הַדְּבֵקִים בַּיְיָ', וְלָא בִּמְמָנָא אַחֲרָא כִּשְׁאַר עַמִּין, וְהָא אוֹקְמוּהָ בְּכַמָּה אֲתָר."],[[0,"ת\"ח מאן דקאים וכו':","בוא וראה מי שעומד בתפלה, צריך ליישר רגליו, וכבר העמידו, וצריך לכסות ראשו כמי שעומד לפני המלך, וצריך לכסות עיניו, כדי שלא יסתכל בהשכינה. ובספרו של רב המנונא סבא, אמר, מי שפותח עיניו בשעת התפלה, או שאינו משפיל עיניו לארץ, מקדים עליו מלאך המות. וכשנפשו יוצאת, דהיינו בשעת פטירתו מן העולם, לא יסתכל באור השכינה, ולא ימות בנשיקה. מי שמזלזל בשכינה, הוא מזדלזל בשעה שנצרך לה, ז\"ש, כי מכבדי אכבד ובוזי יקלו."],[1,"האי מאן דאסתכל וכו':","אתה אומר, מי שמסתכל בשכינה בשעה שהוא מתפלל. ואיך יכול להסתכל בשכינה. ומשיב, אלא לדעת אשר ודאי השכינה עומדת לפניו בשעת תפלתו, וע\"כ אסור לו לפתוח עיניו. ז\"ש ויסב חזקיהו פניו אל הקיר, כי שם שרתה השכינה. משום זה צריך שלא יהיה דבר חוצץ בינו ובין הקיר בשעת תפלתו. והעמידוהו."],[2,"מאן דקאים בצלותא וכו':","מי שעומד בתפלה, צריך תחילה לסדר שבחו של אדונו ואח\"כ להתפלל תפלתו. כי משה כך אמר בתחילה, אתה החילות וגו', ולבסוף אמר תפלתו, אעברה נא וגו'. ר' יהודה אמר, מהו השינוי כאן שכתוב תחילה אדני, באלף דלת נון יוד, ולבסוף הויה שאנו קוראים אלקים. דהיינו אדני הויה אתה החילות וגו'. ומשיב, אלא הסדר כך הוא ממטה למעלה, כי אדני הוא מלכות, הוי\"ה הוא ז\"א, ואמר כך כדי לכלול מדת יום בלילה ומדת לילה ביום ולחבר הכל יחד כראוי. מדת יום הוא ז\"א. ומדה לילה הוא מלכות."],[3,"אתה החלות להראות וגו':","שואל איזו התחלה היא כאן, שאמר אתה החלות. ומשיב, אלא ודאי משה היה התחלה בעולם, להיות שלם לגמרי. ואם תאמר יעקב היה שלם תחילה למשה שהאילן שהוא ז\"א, נשלם בו למטה כעין של מעלה. כי היו לו י\"ב בנים, כנגד י\"ב גבולים דז\"א, וע' נפש, כנגד ע' ענפין שבאילן העליון, שהוא ז\"א, כך הוא ודאי, אבל מה שהיה למשה, לא היה לאדם אחר, כי נתעטר ביתר שלמות, בכמה אלפים ורבבות מישראל, בתורה, במשכן, בכהנים ובלוים, בי\"ב שבטים, בי\"ב נשיאים הממונים עליהם, בע' סנהדרין. והוא נשלם בגוף שלם, שה\"ס תפארת הכולל ימין ושמאל, כי אהרן היה לימינו, נחשון לשמאלו, והוא ביניהם."],[4,"בגין כך את וכו':","משום זה, כתוב, אתה החלות להראות \u0003את גדלך\u0004, היינו מימין שזהו אהרן. \u0003ואת ידך החזקה\u0004 היינו משמאל, שזהו נחשון. וכבר למדנו. וע\"כ משה היה התחלה בעולם, ולא יעקב. ואם תאמר מי הוא הסיום. ומשיב, מלך המשיח הוא הסיום, כי אז תמצא שלמות בעולם, מה שלא היה כן לדורי דורות. בעת ההיא תמצא שלמות למעלה ולמטה, ויהיו כל העולמות בזווג אחד. אז כתוב, ביום ההוא יהיה ה' אחד ושמו אחד."],[5,"ויאמר ה' אלי רב לך וגו':","א\"ר חייא, אמר לו הקב\"ה למשה, משה, \u0003רב לך\u0004 שנתחברת בשכינה, מכאן ולהלאה, \u0003אל תוסף\u0004. רבי יצחק אמר, \u0003רב לך\u0004 באור השמש שהיה אצלך, \u0003אל תוסף\u0004 כי הגיע זמן הלבנה, שהיא יהושע, והלבנה אינה יכולה להאיר עד שיאסף השמש. אבל, וצו את יהושע וחזקהו ואמצהו. אתה, שהוא השמש, צריך להאיר אל הלבנה. וכבר למדנו."],[6,"ואתם הדבקים בה' וגו':","ר' יוסי אמר, אשרי העם שככה לו וגו'. אשרי העם שהקב\"ה בחר בהם מכל העמים עכו\"ם, והעלה אותם לגורלו, וברך אותם בברכתו בברכת שמו, ז\"ש כי הם זרע ברך ה'. ברך ה' ממש. דהיינו ברכת שמו."],[7,"תא חזי כל וכו':","בוא וראה, כל שאר העמים שבעולם מסר אותם הקב\"ה לשרים ממונים השולטים עליהם. וישראל אחז אותם הקב\"ה לגורלו ולחלקו להתאחד בהם ממש, ונתן להם התורה הקדושה, כדי להתאחד בשמו, וע\"כ, ואתם הדבקים בה', ולא בממונה אחר כשאר העמים, וכבר העמידוהו בכמה מקומות."]],[[0,"","בֹּא וּרְאֵה, מִי שֶׁעוֹמֵד בַּתְּפִלָּה, צָרִיךְ לְכַוֵּן רַגְלָיו, וּפֵרְשׁוּהָ. וְצָרִיךְ לְכַסּוֹת רֹאשׁוֹ כְּמִי שֶׁעוֹמֵד לִפְנֵי הַמֶּלֶךְ, וְצָרִיךְ לְכַסּוֹת [לכסות] [לסתם] עֵינָיו כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בַּשְּׁכִינָה. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא אָמַר, מִי שֶׁפּוֹקֵחַ עֵינָיו בִּשְׁעַת הַתְּפִלָּה אוֹ שֶׁלֹּא מַנְמִיךְ אֶת עֵינָיו לָאָרֶץ, מַקְדִּים עָלָיו מַלְאַךְ הַמָּוֶת, וּכְשֶׁתֶּצֵא נַפְשׁוֹ לֹא יִסְתַּכֵּל בְּאוֹר הַשְּׁכִינָה וְלֹא יָמוּת בִּנְשִׁיקָה. מִי שֶׁמְּזַלְזֵל בַּשְּׁכִינָה הוּא מִתְזַלְזֵל בְּאוֹתָהּ שָׁעָה שֶׁהוּא צָרִיךְ אוֹתָהּ, זֶהוּ שֶׁכָּתוּב [שמואל א ב] כִּי מְכַבְּדַי אֲכַבֵּד וּבֹזַי יֵקָלּוּ."],[1,"","זְהִ מִי שֶׁמִּסְתַּכֵּל בַּשְּׁכִינָה בְּשָׁעָה שֶׁהוּא מִתְפַּלֵּל. וְאֵיךְ יָכוֹל לְהִסְתַּכֵּל בַּשְּׁכִינָה? אֶלָּא לָדַעַת שֶׁוַּדַּאי הַשְּׁכִינָה עוֹמֶדֶת לְפָנָיו. זֶהוּ שֶׁכָּתוּב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, שֶׁשָּׁם שׁוֹרָה הַשְּׁכִינָה. מִשּׁוּם כָּךְ לֹא צָרִיךְ לִהְיוֹת חוֹצֵץ בֵּינוֹ וּבֵין הַקִּיר, וּפֵרְשׁוּהָ."],[2,"","מִי שֶׁעוֹמֵד בַּתְּפִלָּה צָרִיךְ לְסַדֵּר שֶׁבַח רִבּוֹנוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ יְבַקֵּשׁ בַּקָּשָׁתוֹ. שֶׁהֲרֵי מֹשֶׁה כָּךְ אָמַר בַּתְּחִלָּה, אַתָּה הַחִלּוֹתָ וְגוֹ', וּלְבַסּוֹף אֶעְבְּרָה וְגוֹ'. רַבִּי יְהוּדָה אָמַר, מַה שּׁוֹנֶה כָּאן שֶׁכָּתוּב אֲדֹנָ\"י בַּהַתְחָלָה, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד, וּלְבַסּוֹף יֱהִֹוִ\"ה, וְקוֹרְאִים אֱלֹהִי\"ם? אֶלָּא הַסִּדּוּר כָּךְ הוּא – מִלְּמַטָּה לְמַעְלָה, וּלְהַכְלִיל מִדַּת יוֹם בַּלַּיְלָה וּמִדַּת לַיְלָה בַּיּוֹם, וּלְזַוֵּג הַכֹּל כְּאֶחָד כָּרָאוּי."],[3,"","אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ. מָה הָרֵאשִׁית כָּאן? אֶלָּא וַדַּאי מֹשֶׁה רֵאשִׁית הָיָה בָּעוֹלָם לִהְיוֹת שָׁלֵם בַּכֹּל. וְאִם תֹּאמַר, יַעֲקֹב הָיָה שָׁלֵם, וְהָאִילָן הִשְׁתַּלֵּם לְמַטָּה כְּמוֹ לְמַעְלָה – כָּךְ זֶה בְּוַדַּאי, אֲבָל מַה שֶּׁהָיָה לְמֹשֶׁה לֹא הָיָה לְאָדָם אַחֵר, שֶׁהֲרֵי הִתְעַטֵּר בִּשְׁלֵמוּת יְתֵרָה בְּכַמָּה אֲלָפִים וּרְבָבוֹת מִיִּשְׂרָאֵל, בַּתּוֹרָה, בַּמִּשְׁכָּן, בַּכֹּהֲנִים, בַּלְוִיִּם, בַּשְּׁנֵים עָשָׂר שְׁבָטִים, גְּדוֹלִים מְמֻנִּים עֲלֵיהֶם, בְּשִׁבְעִים סַנְהֶדְרִין. הוּא הִשְׁתַּלֵּם בְּגוּף שָׁלֵם. אַהֲרֹן לְיָמִין, נַחְשׁוֹן לִשְׂמֹאל, וְהוּא בֵּינֵיהֶם."],[4,"","מִשּׁוּם זֶה אֶת גָּדְלְךְ, מִיָּמִין, זֶה אַהֲרֹן. וְאֶת יָדְךְ הַחֲזָקָה, מִשְּׂמֹאל, זֶה נַחְשׁוֹן. וַהֲרֵי נִתְבָּאֵר. מִשּׁוּם כָּךְ מֹשֶׁה הָיָה רֵאשִׁית בָּעוֹלָם. וְאִם תֹּאמַר, מִי הָיָה הַסִּיּוּם [שהרי משה היה הראשית] ? הַסִּיּוּם הוּא מֶלֶךְ הַמָּשִׁיחַ, שֶׁהֲרֵי אָז תִּמָּצֵא שְׁלֵמוּת בָּעוֹלָם מַה שֶּׁלֹּא הָיָה כֵּן לְדוֹרֵי דוֹרוֹת. בְּאוֹתוֹ זְמַן תִּמָּצֵא שְׁלֵמוּת לְמַעְלָה וּלְמַטָּה, וְיִהְיוּ הָעוֹלָמוֹת כֻּלָּם בְּזִוּוּג אֶחָד, וְאָז כָּתוּב [זכריה יד] בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד."],[5,"","וַיֹּאמֶר ה' אֵלַי רַב לָךְ אַל תּוֹסֶף וְגוֹ'. אָמַר רַבִּי חִיָּיא, אָמַר לוֹ הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְמֹשֶׁה, מֹשֶׁה, רַב לָךְ שֶׁהִזְדַּוַּגְתָּ בַּשְּׁכִינָה, מִכָּאן וְאֵילָךְ אַל תּוֹסֶף. רַבִּי יִצְחָק אָמַר, רַב לָךְ בְּאוֹר הַשֶּׁמֶשׁ שֶׁהָיָה לָךְ, אַל תּוֹסֶף, שֶׁהֲרֵי זְמַן הַלְּבָנָה הִגִּיעַ, וּלְבָנָה לֹא יְכוֹלָה לְהָאִיר עַד שֶׁיִּתְכַּנֵּס הַשֶּׁמֶשׁ. אֲבָל, וְצַו אֶת יְהוֹשֻׁעַ וְחַזְּקֵהוּ וְאַמְּצֵהוּ. אַתָּה, שֶׁהוּא הַשֶּׁמֶשׁ, צָרִיךְ לְהָאִיר לַלְּבָנָה, וַהֲרֵי נִתְבָּאֵר."],[6,"","וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'. רַבִּי יוֹסֵי אָמַר, [תהלים קמד] אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ וְגוֹ'. אַשְׁרֵי הָעָם שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא בָּחַר בָּהֶם מִכָּל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְהֶעֱלָה אוֹתָם לְגוֹרָלוֹ וּבֵרְכָם בְּבִרְכָתוֹ, בְּבִרְכַּת שְׁמוֹ, זֶהוּ שֶׁכָּתוּב [ישעיה סא] כִּי הֵם זֶרַע בֵּרַךְ ה', בֵּרַךְ ה' מַמָּשׁ."],[7,"","בֹּא וּרְאֵה, אֶת כָּל שְׁאָר עַמֵּי הָעוֹלָם נָתַן הַקָּדוֹשׁ־בָּרוּךְ־הוּא לִמְמֻנִּים גְּדוֹלִים שֶׁשּׁוֹלְטִים עֲלֵיהֶם, וְאֶת יִשְׂרָאֵל אָחַז הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְגוֹרָלוֹ וּלְחֶלְקוֹ, לְהֵאָחֵז בּוֹ מַמָּשׁ. וְנָתַן לָהֶם תּוֹרָה קְדוֹשָׁה כְּדֵי לְהֵאָחֵז בִּשְׁמוֹ, וְעַל זֶה וְאַתֶּם הַדְּבֵקִים בַּה', וְלֹא בִמְמֻנֶּה אַחֵר כִּשְׁאָר הָעַמִּים, וַהֲרֵי פֵּרְשׁוּהָ בְּכַמָּה מְקוֹמוֹת."]]],[["(דברים ד׳:י״ב) וַיְדַבֵּר יְיָ' אֲלֵיכֶם מִתּוֹךְ הָאֵשׁ קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וְגוֹ'. אָמַר רִבִּי אֶלְעָזָר, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, קוֹל דְּבָרִים, מַאי קוֹל דְּבָרִים. אֶלָּא קוֹל דְּאִקְרֵי דִּבּוּר, דְּכָל דִּבּוּרָא בֵּיהּ תַּלְיָא. וְעַל דָּא כְּתִיב, וַיְדַבֵּר ה' אֲלֵיכֶם, דְּהָא דִּבּוּר בַּאֲתָר דָּא תַּלְיָא, לְהַאי אִקְרֵי קוֹל דְּבָרִים.","אַתֶּם שׁוֹמְעִים, דִּשְׁמִיעָה לָא תַּלְיָא אֶלָּא בְּהַאי. בְּגִין דִּשְׁמִיעָה בְּדִבּוּר תַּלְיָא. וּבְּגִין כָּךְ אַתֶּם שׁוֹמְעִים. (ס\"א אתם שומעים, ושמיעה בדבור תליא) וְהָא אוֹקְמוּהָ, (שמות כ״א:ו׳) וְרָצַע אֲדוֹנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ, בְּגִין דְּפָגִים אַתְרָא דְּאִקְרֵי שְׁמִיעָה, וְהוּא דִּבּוּר וְהוּא שְׁמִיעָה.","קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וּתְמוּנָה אֵינְכֶם רוֹאִים. מַאי וּתְמוּנָה. כְּמָה דְאַתְּ אָמֵר (במדבר יב) וּתְמוּנַת יְיָ' יַבִּיט. דָּבָר אַחֵר וּתְמוּנָה, דָּא קוֹל פְּנִימָאָה, דְּלָא הֲוָה מִתְחֲזֵי כְּלַל. זוּלָתִי קוֹל, דָּא קוֹל אַחֲרָא דְּקָאַמְרָן. וּתְמוּנָה, אֲמַאי אִקְרֵי הָכִי. בְּגִין דְּכָל תִּקּוּנָא דְּגוּפָא מִינֵּיהּ נָפְקָא.","וְאִי תֵּימָא אַחֲרָא אִקְרֵי הָכִי נָמֵי. אִין. דְּהַאי אַחֲרָא תִּקּוּנָא דִּלְתַתָּא מִינֵּיהּ נָפְקָא, וּבְּגִין כָּךְ, ה' עִלָּאָה ה' תַּתָּאָה, ה' עִלָּאָה, קוֹל גָּדוֹל וְלָא יָסָף, דְּלָא פַּסְקֵי מַבּוּעֵי לְעָלְמִין, וְכָל אִינּוּן קוֹלוֹת תַּמָּן אִשְׁתְּכָחוּ כַּד אִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל. וְכֹלָּא נָפְקָא מֵהַהוּא קוֹל פְּנִימָאָה דְּכֹלָּא, בְּגִין דְּבֵיהּ תַּלְיָא מִלְּתָא.","הַאי דְּאִקְרֵי מִשְׁנֵה תּוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אַמָרָן. וְהָא אוֹקִימְנָא מִלָּה. אֲמַאי הָכִי. אֶלָּא חָכְמָה עִלָּאָה, כְּלָלָא דְּאוֹרַיְיתָא אִתְקְרֵי, וּמִנָהּ נָפְקָא כֹּלָּא, בְּהַהוּא קוֹל פְּנִימָאָה. לְבָתַר מִתְיַשְּׁבָא כֹּלָּא וְאִתְאֲחָד, בַּאֲתָר דְּאִקְרֵי עֵץ הַחַיִּים, וּבֵיהּ תַּלְיָא כְּלַל וּפְרָט, תּוֹרָה שֶׁבִּכְתָּב ושֶׁבְּעַל פֶּה, וְהוּא אִקְרֵי תּוֹרָה וּמִשְׁנֵה תּוֹרָה. בְּקַדְמִיתָא גְּבוּרָה דְּלָא פָּסִק, וְהַשְׁתָּא כֹּלָּא כַּחֲדָא. בְּגִין כָּךְ הָכָא בְּאִלֵּין י' הַדִּבְּרוֹת, כֹּלָּא רָשִׁים בְּוָא\"ו, וְלֹא תִּנְאָף, וְלֹא תִּגְנוֹב, וְלֹא תַעֲנֶה, וְלֹא תַחְמוֹד, וְלֹא תִתְאַוֶּה, וְהָא אוֹקְמוּהָ.","אָמַר רִבִּי יוֹסֵי, מַאי וְלֹא תִתְאַוֶּה, כֵּיוָן דִּכְתִּיב וְלֹא תַחְמוֹד, דְּהָא בְּהַאי סַגֵּי. אָמַר לֵיהּ, זַכָּאִין אִינּוּן מָארֵי קְשׁוֹט. חֲמִידָה חַד דַּרְגָּא. תַּאֲוָה דַּרְגָּא אַחֲרָא. חֲמִידָה, דְּאִי יָכִיל, אָזִיל לְמֵיסַב דִּילֵיהּ בְּגִין הַהִיא חֲמִידָה דְּנָקַט, אָזִיל לְמֶעְבַּד עוֹבָדָא. תַּאֲוָה, לָאו הָכִי. דְּהָא אֲפִילּוּ דְּלָא יִנְקוּט אוֹרְחָא לְמֵהַךְ אֲבַּתְרֵיהּ, וְהָא אוֹקְמוּהָ חַבְרַיָּיא.","אָמַר לֵיהּ רִבִּי יוֹסֵי, אֲמַאי לָא כְּתִיב וְלֹא תִרְצַח, כְּהָנֵי אַחֲרִינֵי. אָמַר לֵיהּ בְּגִין דְּדַרְגָּא דְּדִינָא בִּגְבוּרָה תַּלְיָא, וְלָא בַּאֲתָר דְּרַחֲמֵי, בְּגִין כָּךְ לֹא תִרְצַח לָא כְּתִיב בֵּיהּ וָא\"ו. וּבְגִין דְּבַעְיָין ה' וָוִין אִתּוֹסָף וָא\"ו וְלֹא תִתְאַוֶּה, דְּהָא בְּלֹא תִרְצַח לָא בָּעֵי לְמִשְׁרֵי וָא\"ו, וְאִתּוֹסַף הָכָא.","שָׁמַע רִבִּי פִּנְחָס דְּיָתִיב אֲבַּתְרֵיהּ, וּנְשָׁקֵיהּ. בָּכָה וְחָיִיךְ. אָמַר גּוּר אַרְיֵה, לֵית מַאן דְּקָאִים קַמַּיְיהוּ, מַאן יָכִיל לְקַיְּימָא קַמֵּיהּ וַאֲבוּהָּ בְּעָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, וְזַכָּאָה חוּלָקִי בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, דְּזָכֵינָא לְהַאי. עַל דָּא כְּתִיב, (איוב כ״ב:י״ט) יִרְאוּ צַדִּיקִים וְיִשְׂמָחוּ.","רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (דברים ה׳:כ״ד) קְרַב אַתָּה וּשֲׁמָע וְגוֹ'. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל, (כלהו) כֻּלְּהוֹן קוֹלוֹת אִשְׁתְּכָחוּ. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כּוּרְסְיָּיא, וְדָא מִגּוֹ דְּדָא אִתְחֲזֵי, וּמִלּוּלָא דְּדָא נָפִיק מִגּוֹ עִלָּאָה דְּעָלֵיהּ, וְדָא הוּא רָזָא דִּכְתִּיב, (דברים ה׳:ד׳) פָּנִים בְּפָנִים דִּבֶּר יְיָ' עִמָּכֶם בָּהָר מִתּוֹךְ הָאֵשׁ, דְּמִלּוּלָא נָפְקָא, וּמַלִּיל מִגּוֹ אֶשָּׁא וְשַׁלְהוֹבָא, דְּדָחֵי לֵיהּ לְבַר, בִּדְפִיקוּ דְּרוּחָא וּמַיָּיא, דְּיָהֲבִין חֵילָא. דְּאֶשָּׁא וְרוּחָא וּמַיָּיא, מִגּוֹ שׁוֹפָר, דְּאִיהוּ כָּלִיל לְכֻלְּהוּ נָפִיק. וְיִשְׂרָאֵל אִתְרַחִיקוּ מִדְּחִילוּ דָּא.","וּבְּגִין כָּךְ, וְאַתְּ תְּדַבֵּר אֵלֵינוּ, לָא בָּעֵינָן בְּתּוּקְפָא עִלָּאָה דִּלְעֵילָּא, אֶלָּא מֵאֲתָר דְּנוּקְבָּא וְלָא יַתִּיר, וְאַתְּ תְּדַבֵּר אֵלֵינוּ וְגוֹ'. אָמַר מֹשֶׁה וַדַּאי חָלַשְׁתּוּן חֵילָא דִּילִי, חָלַשְׁתּוּן חֵילָא אַחֲרָא, דְּאִלְמָלֵא לָא אִתְרַחֲקוּ יִשְׂרָאֵל, וְיִשְׁמְעוּן כָּל הַהִיא מִלָּה כַּד בְּקַדְמִיתָא, לָא הֲוָה יָכִיל עָלְמָא לְמֶהֱוֵי חָרִיב לְבָתַר, וְאִינּוּן הֲווֹ קַיְימִין לְדָרֵי דָּרִין."],[[0,"וידבר ה' אליכם מתוך האש וגו':","א\"ר אלעזר, מקרא הזה יש להסתכל בו. אומר \u0003קול דברים\u0004, מהו קול דברים. ומשיב. אלא שפירושו, \u0003קול\u0004 הנקרא דבור, שכל הדבור תלוי בו. קול הוא ז\"א, ודבור היינו המלכות, אלא כיון שהדבור תלוי בקול, ע\"כ נקראת המלכות קול דברים. וע\"כ כתוב, וידבר ה' אליכם מתוך האש, כי דבור תלוי במקום זה, במלכות הנקראת אש, וזו המלכות, נקראת קול דברים."],[1,"אתם שומעים:","כי שמיעה אינה תלויה אלא בזו, במלכות, משום ששמיעה תלויה בדבור, ומשום זה כתוב, אתם שומעים. וכבר העמידוהו, ורצע אדוניו את אזנו במרצע, שהוא משום שפגם המקום שנקרא שמיעה, והיינו דבור והיינו שמיעה."],[2,"קול דברים אתם וגו':","קול דברים אתם שומעים ותמונה אינכם רואים. שואל, מהו ותמונה. ומשיב, הוא כש\"א ותמונת ה' יביט, שהיא המלכות, שזה נאמר רק בשבחו של משה, שהיה מסתכל באספקלריא, המאירה, שהוא ז\"א, וע\"כ ותמונת ה' יביט, שהיא המלכות, המגלה את הויה. פירוש אחר. \u0003ותמונה\u0004, זה הוא קול פנימי, דהיינו בינה, שלא היתה נראית כלל אפילו למשה, \u0003זולתי קול\u0004, זה קול אחר, חיצון, שאמרנו, דהיינו המלכות הנקראת קול דברים. \u0003ותמונה\u0004, למה נקראת הבינה תמונה. ומשיב, משום שכל תקון הגוף, שהוא ז\"א, המכונה גוף, דהיינו ציור ו\"ק וי\"ב גבולים, וע' ענפין וכו'. יוצא ממנה מן הבינה."],[3,"ואי תימא אחרא וכו':","ואם תאמר, אחר, דהיינו המלכות, נקרא גם כן תמונה, ולמה נקראת היא תמונה. ומשיב, כן. כי האחר הזה, נקרא ג\"כ תמונה, משום שהתקונים שלמטה, דהיינו תקוני בי\"ע, ממנו יוצאים. ומשום זה נקראות הבינה והמלכות \u0003ה'\u0004 עלאה ו \u0003ה'\u0004 תתאה, משום ששוין זו לזו. \u0003ה'\u0004 עליונה, הסו\"ה, קול גדול ולא יסף, כי המבועים שלה אינם פוסקים לעולם. כי היא עם אבא, שהוא חכמה, בזווג דלא פסיק לעלמין. וכל אלו הקולות נמצאו שמה בעת שניתנה התורה לישראל שה\"ס ז' קולות דז\"א, כולם יצאו מהקול ההוא הפנימי, של הכל, שהוא בינה, משום שבו תלוי הדבר. כי הם נאצלו מן הבינה."],[4,"האי דאקרי משנה תורה וכו':","זו שנקראת משנה תורה. משה מפי עצמו אמרם. וכבר העמידו הדבר. ושואל, למה הוא כך. ומשיב, אלא חכמה עלאה נקראת כלל התורה, וממנה יוצא הכל אל הקול הפנימי ההוא, שהוא הבינה. אח\"כ מתישב הכל ונאחז במקום שנקרא עץ החיים, שהוא ז\"א, שנקרא משה, ובו תלוי כלל ופרט, דהיינו תורה שבכתב, שהוא ז\"א שנקרא כלל, ותורה שבעל פה, שהיא המלכות שנקראת פרט. וכן הם נקראים תורה ומשנה תורה. שז\"א נקרא תורה, והמלכות נקראת משנה תורה. וע\"כ אמרו שמשנה תורה, שהיא מלכות משה שהוא ז\"א, מפי עצמו אמרם, דהיינו שנאצלה ע\"י משה שהוא ז\"א. בתחילה, עשרת הדברות הראשונות, הם יצאו מגבורה דלא פסיק, דהיינו מבינה, שעליה נאמר קול גדול ולא יסף כנ\"ל. ועתה, דהיינו עשרת הדברות שבמשנה תורה, יצאו הכל ביחד, דהיינו מז\"א ומלכות, בסוד שמשה שהוא ז\"א מפי עצמו אמרם, משום זה כאן בעשרת הדברות אלו, רשומים כולם ב \u0003ו'\u0004, ולא תנאף, ולא תגנוב, ולא תענה, ולא תחמוד, ולא תתאוה, שה \u0003ו'\u0004 רומזת על ז\"א."],[5,"אמר ר' יוסי וכו':","אר\"י, מהו ולא תתאוה, כיון שכתוב. ולא תחמוד הרי די בזה. אמר לו אשרי הם צדיקי אמת, החמדה היא מדרגה אחת, התאוה היא מדרגה אחרת. חמדה פירושו, שאם יוכל, ילך לקחת אותה, כי משום אותה החמדה שאחזה אותו, ילך לעשות מעשה. תאוה אינו כך, אלא אפילו שלא יקח דרך ללכת אחריה, נחשב גם כן לתאוה. וכבר העמידו החברים."],[6,"א\"ל רבי יוסי וכו':","א\"ל ר\"י, למה לא כתוב ולא תרצח עם \u0003ו'\u0004 תחילה, כמו אלו האחרים. אמר לו, משום שהמדרגה של רציחה היא דין, ותלויה בגבורה, בקו שמאל, ולא במקום הרחמים, שהוא ז\"א שנקרא \u0003ו'\u0004, וע\"כ בלא תרצח לא כתובה בו \u0003ו'\u0004. ומשום שצריכים ה' ווין, כנגד חג\"ת נ\"ה, נתוסף \u0003ו'\u0004 אצל \u0003ו\u0004 לא תתאוה, כי בלא תרצח לא צריכה ה \u0003ו'\u0004 לשרות בו, משום שהוא בגבורה, כנ\"ל ע\"כ נתוספה ה \u0003ו'\u0004 כאן."],[7,"שמע רבי פנחס וכו':","שמע ר\"פ שישב אחרי ר' אלעזר, ונשקו. בכה וצחק. אמר על ר' אלעזר, גור אריה, אין מי שיעמוד לפניהם, מי יוכל לעמוד לפניו ולפני אביו, בעולם. אשרי חלקם של הצדיקים ואשרי חלקי בעולם הזה ובעולם הבא, שזכיתי לזה. על זה כתוב, יראו צדיקים וישמחו."],[8,"ר' אלעזר פתח וכו':","רא\"פ ואמר, קרב אתה ושמע וגו'. בוא וראה בשעה שנתנה התורה לישראל, כל הקולות נמצאו, דהיינו מבינה ומז\"א וממלכות, שבינה נקראת קול פנימי, וז\"א קול חיצוני, והמלכות קול דברים. והקב\"ה ישב על הכסא, שהוא מלכות, וזה מתוך זה נראה, שהז\"א נראה מתוך המלכות, והדיבור של זה, של המלכות, יצא מתוך העליון שעליו, שהוא ז\"א, וזהו סוד שכתוב, פנים בפנים דבר ה' עמכם מתוך האש. שז\"א ומלכות היו פב\"פ, והדבור יוצא ודיבר מתוך האש והשלהבת, שהוא קו שמאל, שדחה הדבור לחוץ, מז\"א, על ידי הדפיקה של רוח ומים, שהם קו אמצעי, וקו ימין, הנותנים כח אל השמאל, ונמצא הדבור שהיא המלכות יוצא מכל ג' הקוין דז\"א. כי אש רוח ומים, שהם ג' קוין דז\"א יצאו מן השופר, שהוא בינה, שהוא הבינה, כולל את כולם. וישראל נתרחקו מתוך היראה הזו."],[9,"ובג\"כ ואת תדבר וכו':","ומשום זה, משום היראה כנ\"ל, אמרו ישראל למשה ואת תדבר אלנו. שאמרו, אין אנו רוצים בתוקף העליון שלמעלה, דהיינו מז\"א, אלא ממקום הנוקבא, שהיא המלכות, ולא יותר. וז\"ש, ו \u0003את\u0004 תדבר אלינו וגו'. אשר \u0003את\u0004 רומז על הנוקבא. אמר להם משה, ודאי החלשתם הכח שלי, והחלשתם כח אחר, של המלכות. כי לולא לא נתרחקו ישראל, והיו שומעים כל אלו הדברים מז\"א, כבתחילה, לא היה העולם יכול אחר כך להחרב, וישראל היו חיים לדורי דורות."]],[[0,"","וַיְדַבֵּר ה' אֲלֵיכֶם מִתּוֹךְ הָאֵשׁ קוֹל דְּבָרִים אַתֶּם שּמְעִים וְגוֹ' [דברים ד]. אָמַר רַבִּי אֶלְעָזָר, בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל. קוֹל דְּבָרִים, מַה זֶּה קוֹל דְּבָרִים? אֶלָּא קוֹל שֶׁנִּקְרָא דִבּוּר, שֶׁכָּל דִּבּוּר תָּלוּי בּוֹ. וְעַל זֶה כָּתוּב וַיְדַבֵּר ה' אֲלֵיכֶם, שֶׁהֲרֵי דִּבּוּר בְּמָקוֹם זֶה תָּלוּי, לָזֶה נִקְרָא קוֹל דְּבָרִים."],[1,"","אַתֶּם שּמְעִים, שֶׁשְּׁמִיעָה לֹא תְלוּיָה אֶלָּא בָּזֶה, מִשּׁוּם שֶׁשְּׁמִיעָה תְּלוּיָה בַּדִּבּוּר, וּמִשּׁוּם כָּךְ אַתֶּם שׁוֹמְעִים. [אתם שומעים, ושמיעה תלויה בדיבור] וַהֲרֵי פֵּרְשׁוּהָ, [שמות כא] וְרָצַע אֲדנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ, מִשּׁוּם שֶׁפָּגַם מָקוֹם שֶׁנִּקְרָא שְׁמִיעָה, וְהוּא דִּבּוּר וְהוּא שְׁמִיעָה."],[2,"","קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וּתְמוּנָה אֵינְכֶם רֹאִים. מַה זֶּה וּתְמוּנָה? כְּמוֹ שֶׁנֶּאֱמַר [במדבר יב] וּתְמוּנַת ה' יַבִּיט. דָּבָר אַחֵר וּתְמוּנָה – זֶה קוֹל פְּנִימִי שֶׁלֹּא הָיָה נִרְאֶה כְּלָל. זוּלָתִי קוֹל, זֶה קוֹל אַחֵר שֶׁאָמַרְנוּ. וּתְמוּנָה, לָמָּה נִקְרָא כָּךְ? מִשּׁוּם שֶׁכָּל תִּקּוּן הַגּוּף יוֹצֵא מִמֶּנָּה."],[3,"","וְאִם תֹּאמַר, אַחֵר נִקְרָא גַּם כָּךְ – כֵּן. שֶׁזֶּה הָאַחֵר הַתִּקּוּן שֶׁלְּמַטָּה מִמֶּנּוּ יוֹצֵא. וּמִשּׁוּם זֶה ה' עֶלְיוֹנָה ה' תַּחְתּוֹנָה. ה' עֶלְיוֹנָה – קוֹל גָּדוֹל וְלֹא יָסָף [דברים ה], שֶׁלֹּא פוֹסְקִים הַמַּבּוּעִים לְעוֹלָמִים, וְכָל אוֹתָם קוֹלוֹת נִמְצָאִים שָׁם כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל, וְהַכֹּל יוֹצֵא מֵאוֹתוֹ קוֹל פְּנִימִי שֶׁל הַכֹּל, מִשּׁוּם שֶׁבּוֹ תָּלוּי הַדָּבָר."],[4,"","זְהִ שֶׁנִּקְרָא מִשְׁנֵה תוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אָמַר אוֹתָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדָּבָר. לָמָּה כָּךְ? אֶלָּא חָכְמָה עֶלְיוֹנָה, כְּלַל הַתּוֹרָה נִקְרֵאת, וּמִמֶּנָּה הַכֹּל יוֹצֵא בְּאוֹתוֹ קוֹל פְּנִימִי. אַחַר כָּךְ הַכֹּל מִתְיַשֵּׁב וּמִתְאַחֵד בְּמָקוֹם שֶׁנִּקְרָא עֵץ הַחַיִּים, וּבוֹ תָּלוּי כְּלָל וּפְרָט, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וְהוּא נִקְרָא תוֹרָה וּמִשְׁנֵה תוֹרָה. בַּהַתְחָלָה גְּבוּרָה שֶׁלֹּא פוֹסֶקֶת, וְעַכְשָׁו הַכֹּל כְּאֶחָד. מִשּׁוּם כָּךְ כָּאן בְּאוֹתָם עֲשֶׂרֶת הַדִּבְּרוֹת, הַכֹּל רָשׁוּם בְּוָא\"ו, וְלֹא תִאְנָף, וְלֹא תִגְנֹב, וְלֹא תַעֲנֶה, וְלֹא תַחְמֹד, וְלֹא תִתְאַוֶּה, וַהֲרֵי פֵּרְשׁוּהָ."],[5,"","אָמַר רַבִּי יוֹסֵי, מַה זֶּה וְלֹא תִתְאַוֶּה, כֵּיוָן שֶׁכָּתוּב וְלֹא תַחְמֹד, שֶׁהֲרֵי בָּזֶה מַסְפִּיק? אָמַר לוֹ, אַשְׁרֵי בַּעֲלֵי הָאֱמֶת, חֲמִידָה דַּרְגָּה אַחַת, תַּאֲוָה דַּרְגָּה אַחֶרֶת. חֲמִידָה – שֶׁאִם יָכוֹל, הוֹלֵךְ לָקַחַת אֶת שֶׁלּוֹ מִשּׁוּם אוֹתָהּ חֲמִידָה שֶׁלָּקַח, הוֹלֵךְ לַעֲשׂוֹת מַעֲשֶׂה. תַּאֲוָה לֹא כָּךְ, שֶׁהֲרֵי אֲפִלּוּ שֶׁלֹּא יִקַּח דֶּרֶךְ לָלֶכֶת אַחֲרֵי זֶה, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים."],[6,"","אָמַר לוֹ רַבִּי יוֹסֵי, לָמָּה לֹא כָתוּב וְלֹא תִרְצַח, כְּמוֹ הָאֲחֵרִים הַלָּלוּ? אָמַר לוֹ, מִשּׁוּם שֶׁדַּרְגַּת הַדִּין תְּלוּיָה בִּגְבוּרָה, וְלֹא בִּמְקוֹם הָרַחֲמִים, וּמִשּׁוּם זֶה לֹא כָתוּב וָא\"ו בְּלֹא תִרְצַח. וּמִשּׁוּם שֶׁצְּרִיכִים חָמֵשׁ וָוִי\"ם, הִתּוֹסֵף וָא\"ו וְלֹא תִתְאַוֶּה, שֶׁהֲרֵי בְּלֹא תִרְצַח לֹא צָרִיךְ לָשִׂים וָא\"ו, וְהִתּוֹסֵף כָּאן."],[7,"","שָׁמַע רַבִּי פִּנְחָס שֶׁיָּשַׁב אַחֲרָיו וּנְשָׁקוֹ. בָּכָה וְחִיֵּךְ. אָמַר, גּוּר אַרְיֵה, אֵין מִי שֶׁיַּעֲמֹד לִפְנֵיהֶם, מִי יָכוֹל לַעֲמֹד לְפָנָיו וְאָבִיו בָּעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, וְאַשְׁרֵי חֶלְקִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא שֶׁזָּכִיתִי לָזֶה. עַל זֶה כָּתוּב, [איוב כב] יִרְאוּ צַדִּיקִים וְיִשְׂמָחוּ."],[8,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, קְרַב אַתָּה וּשֲׁמָע וְגוֹ'. בּא וּרְאֵה, בְּשָׁעָה שֶׁנִּתְּנָה תּוֹרָה לְיִשְׂרָאֵל, כָּל הַקּוֹלוֹת נִמְצְאוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יָשַׁב עַל הַכִּסֵּא, וְזֶה מִתּוֹךְ זֶה נִרְאָה, וְדִבּוּר שֶׁל זֶה יָצָא מִתּוֹךְ הָעֶלְיוֹן שֶׁמֵּעָלָיו. וְזֶהוּ סוֹד הַכָּתוּב פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם בָּהָר מִתּוֹךְ הָאֵשׁ. שֶׁדִּבּוּר יָצָא, וְדִבֵּר מִתּוֹךְ אֵשׁ וְשַׁלְהֶבֶת שֶׁדָּחָה אוֹתוֹ הַחוּצָה בְּדפֶק שֶׁל רוּחַ וּמַיִם שֶׁנּוֹתְנִים כֹּחַ. שֶׁאֵשׁ וְרוּחַ וּמַיִם מִתּוֹךְ שׁוֹפָר שֶׁכּוֹלֵל אֶת כֻּלָּם יוֹצְאִים, וְיִשְׂרָאֵל הִתְרַחֲקוּ מִפַּחַד זֶה."],[9,"","וּמִשּׁוּם כָּךְ, וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לֹא רוֹצִים בְּכֹחַ עֶלְיוֹן שֶׁלְּמַעְלָה, אֶלָּא מִמָּקוֹם שֶׁל הַנְּקֵבָה וְלֹא יוֹתֵר, וְאַתְּ תְּדַבֵּר אֵלֵינוּ וְגוֹ'. אָמַר מֹשֶׁה, וַדַּאי הֶחֱלַשְׁתֶּם אֶת כֹּחִי, הֶחֱלַשְׁתֶּם כֹּחַ אַחֵר, שֶׁאִלְמָלֵא לֹא הִתְרַחֲקוּ יִשְׂרָאֵל וְיִשְׁמְעוּ כָּל אוֹתוֹ דָּבָר כְּמוֹ בַּתְּחִלָּה, לֹא הָיָה יָכוֹל הָעוֹלָם לִהְיוֹת חָרֵב אַחַר כָּךְ, וְהֵם הָיוּ קַיָּמִים לְדוֹרֵי דוֹרוֹת."]]],[["דְּהָא בְּשַׁעֲתָא קַדְמִיתָא מִיתוּ. מַאי טַעְמָא. בְּגִין דְּהָכִי אִצְטְרִיךְ, דְּהָא אִילָנָא דְּמוֹתָא גָּרִים. לְבָתַר דְּחַייוּ (דחיו) וְקָמוּ וְקָא סָגּוּ, וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲלָא לוֹן לְאִילָנָא דְּחַיֵּי, דְּקָאִים עַל הַהוּא אִילָנָא דְּמוֹתָא, בְּגִין לְמֶהֱוֵי קַיְימִין לְעָלְמִין, אִתְרְחַק וְלָא בָּעוּן, כְּדֵין אִתְחֲלָשׁ חֵילָא דְּמֹשֶׁה עָלַיְיהוּ, וְאִתְחַלָּשׁ חֵילָא אַחֲרָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא בָּעֵינָא לְקַיְּימָא לְכוּ בַּאֲתָר עִלָּאָה, וּלְאִתְדַּבְּקָא בַּחַיִּים, אַתּוּן בָּעִיתוּן אֲתָר דְּנוּקְבָּא שַׁרְיָא. וּבְּגִין כָּךְ, לֵךְ אֱמוֹר לָהֶם וְגוֹ'. כָּל חַד יְהַךְ לְנוּקְבֵיהּ, וְיִתְיַחֵד בָּהּ.","וְעִם כָּל דָּא, כֵּיוָן דְּיִשְׂרָאֵל לָא עָבְדוּ, אֶלָּא בִּדְחִילוּ עִלָּאָה דְּהֲוָה עָלַיְיהוּ, לָא אִתְּמַר עָלַיְיהוּ, אֶלָּא מִי יִתֵּן וְהָיָה לְבָבָם זֶה לָהֶם וְגוֹ'. מִכָּאן אוֹלִיפְנָא, כָּל מַאן דְּעָבִיד מִלָּה, וְלִבָּא וּרְעוּתֵיהּ לָא שַׁוֵּי לְסִטְרָא בִּישָׁא, אַף עַל גַּב דְּאִיהוּ בִּישׁ, הוֹאִיל וְלָא עָבִיד בִּרְעוּתָא, עוֹנְשָׁא לָא שַׁרְיָא עָלֵיהּ. וְלָא כְּבַּר נָשׁ אַחֲרָא. וְקוּדְשָׁא בְּרִיךְ הוּא לָא דָּאִין לֵיהּ לְבִישׁ.","(דברים ה׳:כ״ח) וְאַתָּה פֹּה עֲמוֹד עִמָּדִי. מֵהָכָא, אִתְפְּרַשׁ מִכֹּל וָכֹל, מְאִתְּתֵיהּ, וְאִתְדַּבָּק וְאִסְתַּלָּק בַּאֲתָר אַחֲרָא דִּדְכוּרָא, וְלָא בְּנוּקְבָּא. זַכָּאָה חוּלָקָא דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, דְּזָכָה לְדַרְגִּין עִלָּאִין, מַה דְּלָא זָכָה בַּר נָשׁ אָחֳרָא לְעָלְמִין. עַל דָּא כְּתִיב, (קהלת ז׳:כ״ו) טוֹב לִפְנֵי הָאֱלֹהִים יִמָּלֵט מִמֶּנָּה. מַאי טוֹב. דָּא מֹשֶׁה. דִּכְתִּיב, (שמות ב) כִּי טוֹב הוּא. וּבְגִין דְּהֲוָה טָב, סָלִיק לְדַרְגָּא אַחֲרָא עִלָּאָה. וְעַל דָּא כְּתִיב, (שמות ג׳:ה׳) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא, עוֹמֵד עָלָיו דַּיְיקָא. מַאי טַעְמָא. בְּגִין כִּי טוֹב הוּא, וְטוֹב הוּא דְּכוּרָא.","וְאִי תֵּימָא, דְּהָא אָמַר רִבִּי יְהוּדָה, הָא דָּוִד דִּכְתִּיב בֵּיהּ טוֹב, כְּמָה דְאַתְּ אָמֵר (שמואל א ט״ז:י״ב) וְטוֹב רֹאִי, אֲמַאי לָא הֲוָה יַתִּיר. אָמַר לֵיהּ וְטוֹב רֹאִי כְּתִיב. טוֹב רֹאִי, דָּא דְּאִיהוּ חֵיזוּ לְאִסְתַּכְּלָא, הָכִי הֲוָה דָּוִד. טוֹב רֹאִי, הֲוָה טוֹב דְּאִיהוּ חֵיזוּ. וּבְמֹשֶׁה כְּתִיב טוֹב הוּא מַמָּשׁ, וְהָכָא טוֹב רֹאִי. וְעִם כָּל דָּא, בְּתַרְוַויְיהוּ הֲוָה אָחִיד, דְּהָא דָּא בְּדָא אָחִיד. וּמֹשֶׁה לְבָתַר דְּהֲוָה טַב, סָלִיק לְמֶהֱוֵי גּוּפָא אִישׁ. (דברים כ\"ג) אִישׁ הָאֱלֹהִים, (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד.","אָמַר רִבִּי יְהוּדָה, בְּכָל עוֹבָדוֹי, בָּעֵי בַּר נָשׁ לְשַׁוָּאָה לָקֳבְלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא אוֹקִימְנָא מִלָּה. רִבִּי יְהוּדָה לְטַעְמֵיהּ, דְּאָמַר רִבִּי יְהוּדָה, הַאי מַאן דְּאָזִיל בְּאָרְחָא, יְכַוֵּין לִתְלַת מִלִּין, וְעֵילָּא מִנְּהוֹן צְלוֹתָא, וְאַף עַל גַּב דִּצְלוֹתָא יַתִּיר עִלָּאָה מִכֹּלָּא, תְּרֵי חַבְרֵי אוֹ תְּלָתָא דְּלָעָאן בְּמִלֵי דְּאוֹרַיְיתָא. דְּהָא לָא מִסְתָּפֵי, בְּגִין דִּשְׁכִינְתָּא (ס\"א ועילא מנהון צלותא, ועלאה מכלהו, חברייא במלי דאורייתא. דהא שכינתא) אִשְׁתַּתְּפָא בַּהֲדַיְיהוּ.","(כי הא ד)רִבִּי אֶלְעָזָר וְרִבִּי חִיָּיא הֲווֹ אַזְלֵי בְּאָרְחָא, אָמַר רִבִּי אֶלְעָזָר (ס\"א חייא) כְּתִיב, (בראשית ג׳:כ״א) וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר. וְכִי עַד הַשְׁתָּא פְּשִׁיטֵי הֲווֹ מֵהַהוּא עוֹר. אִין. אֶלָּא מָאנֵי לְבוּשֵׁי יְקַר הֲווֹ. אָמַר לֵיהּ רִבִּי חִיָּיא, אִי הָכִי לָא אִתְחָזוּן לְהוּ אֲפִילּוּ כָּתְנוֹת עוֹר. וְכִי תֵּימָא דְּעַד לָא חָאבוּ אַלְבִּישׁוּ לְהוּ, לָא. אֶלָּא לְבָתַר דְּחָבוּ כְּתִיב, וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם וְגוֹ'.","אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, בְּקַדְמִיתָא הֲווֹ כְּגַוְונָא דִּלְעֵילָּא, וּמִתְפָּשְׁטִן מִן גְּוָונֵי דִּלְתַּתָּא, וַהֲוָה נְהוֹרָא דִּלְעֵילָּא אַסְחַר עָלַיְיהוּ. וּלְבָתַר דְּחָבוּ, אַהְדָּר לוֹן בִּגְוָונֵי דְּהַאי עָלְמָא, וְאַעְבַּר מִנַּיְיהוּ גַּוְונֵי דִּלְעֵילָּא. מַה כְּתִיב. וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם מִגַּוְונָא דְּהַאי עָלְמָא. כְּתִיב (שמות כ״ט:ד׳) וְאֶת אַהֲרֹן וְאֶת בָּנָיו תַּקְרִיב וְהִלְבַּשְׁתָּם כָּתְנוֹת, הָתָם כְּגַוְונָא דִּלְעֵילָּא. הָכָא כְּגַוְונָא דִּלְתַּתָּא. הָתָם כָּתְנוֹת שֵׁשׁ, הָכָא כָּתְנוֹת עוֹר. וְאַף עַל גַּב דְּאִיהוּ הָכִי, שַׁפִּירָא דְּאִינּוּן לְבוּשִׁין סָלִיק עַל כֹּלָּא.","(בראשית ג׳:ז׳) וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם (בטיפסא) (בעפושא) דְּהַאי עָלְמָא, מַה דְּלָא הֲוָה קוֹדֶם, דַּהֲווֹ מַשְׁגִּחִין וּפַקְחִין לְעֵילָּא. לְזִמְנָא דְּאָתֵי כְּתִיב, (ישעיהו מ״ב:ט״ז) וְהוֹלַכְתִּי עִוְרִים בְּדֶּרֶךְ לֹא יָדָעוּ וְגוֹ'. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַפְקְחָא עַיְינִין דְּלָא חַכִּימִין, וּלְאִסְתַּכְּלָא בְּחָכְמְתָא עִלָּאָה, וּלְאִתְדַּבְּקָא בְּמַאי דְּלָא אִתְדָּבָקוּ בְּהַאי עָלְמָא, בְּגִין דְּיִנְדְּעוּן לְמָארֵיהוֹן. זַכָּאִין אִינּוּן צַדִּיקַיָּא, דְּיִזְכּוּן לְהַהִיא חָכְמְתָא, דְּלָאו חָכְמְתָא כְּהַהִיא חָכְמְתָא, וְלָאו יְדִיעָה כְּהַהִיא יְדִיעָה, וְלָאו דְּבֵקוּתָא כְּהַהִיא דְּבֵקוּתָא."],[[0,"דהא בשעתא קדמיתא וכו':","כי בשעה הראשונה, אחר ששמעו דבור הראשון, מתו. מהו הטעם, משום שכך צריך, כי אילן המות, שהיא המלכות, גרם להם. ואח\"כ חזרו לתחיה, וקמו ונתגדלו, דהיינו שהשיגו המוחין דגדלות. ורצה הקב\"ה להכניסם. לעץ החיים שהוא ז\"א, העומד למעלה מאילן המות ההוא, כדי שיהיו חיים לעולם, הם נתרחקו ולא רצו, כנ\"ל, אז נחלש כחו של משה שעליהם, ונחלש כח אחד, של המלכות. אמר הקב\"ה, אני רוצה לקיים אתכם במקום עליון, שתתדבקו בחיים, ואתם רוצים את המקום שהנוקבא שורה בו. ומשום זה, לך אמור להם שובו לכם לאהליכם. כל אחד ילך לנוקביה, ויתיחד בה. כיון שירדו לעלמא דנוקבא."],[1,"ועם כל דא וכו':","ועם כל זה, כיון שישראל לא עשו זה אלא מחמת יראה עליונה שהיתה עליהם, לא נאמר עליהם, אלא, מי יתן והיה לבבם זה להם ליראה אותי וגו' מכאן למדנו, שכל מי שעושה דבר ואינו משים לבו ורצונו לצד הרע, אע\"פ שהדבר הוא רע, כיון שלא עשה ברצון, אין עונש שורה עליו, ואינו כאדם אחר העושה ברצון, והקב\"ה אינו דן אותו לרע."],[2,"ואתה פה עמוד עמדי:","מכאן נשמע שנפרד מכל וכל מאשתו, ונתדבק ונתעלה במקום אחר של עולם הזכר, ולא בנוקבא. אשרי חלקו של משה הנביא הנאמן שזכה למדרגות עליונות מה שלא זכה אדם אחר לעולם. על זה כתוב, טוב לפני האלקים ימלט ממנה. מהו טוב. זהו משה, שכתוב בו, כי טוב הוא. ומשום שהיה טוב, עלה למדרגה אחרת עליונה, שהיא מדרגת ז\"א, וע\"כ כתוב, כי המקום אשר אתה עומד עליו אדמת קדש הוא. \u0003עומד עליו\u0004, הוא בדיוק, ומה הטעם כתוב בו עמידה, משום, כי טוב הוא, וטוב הוא זכר, שהוא יסוד ז\"א, ובזכר נוהג עמידה."],[3,"ואי תימא דהא וכו':","ואם תאמר, הרי אמר ר' יהודה, שדוד כתוב בו טוב, כמש\"א וטוב רואי. וא\"כ למה לא עלה יותר, דהיינו למדרגת ז\"א, כמו משה, אמר לו, וטוב רואי כתוב, טוב רואי היינו, אשר המראה להסתכל שה\"ס המלכות, שנקראת מראה, היתה טוב, כך היה דוד טוב רואי, שהמראה שלו היה טוב. ובמשה כתוב, \u0003טוב הוא\u0004, דהיינו הוא ממש. וכאן נאמר רק וטוב רואי. ועם כל זה היה אחוז דוד בשניהם, דהיינו ביסוד שנקרא טוב, ובמלכות שנקראת מראה, כי זה אחוז בזה, כי יסוד ומלכות הם תמיד אחוזים זה בזה. אלא שעיקרו היה בבחינת מלכות, ובה נשאר. ומשה, אחר שהיה טוב, שהוא יסוד דז\"א, עלה להיות בבחינת גוף, שהוא ז\"א עצמו, הנקרא איש. שכתוב, איש האלקים. והאיש משה ענו מאד."],[4,"אמר ר' יהודה וכו':","אר\"י, בכל מעשיו צריך האדם לשום כנגדו את הקב\"ה. וכבר העמדנו הדבר. ר' יהודה הולך לטעמו, שאמר ר' יהודה, כל מי שהולך בדרך, שמתירא מפני לסטים, יכוין לג' דברים, לדורון ולתפלה ולמלחמה, כמו יעקב, בשעה שהיה מתירא מפני עשו (כמ\"ש [מקץ ר\"ס] ל הלן אות קע\"א) והחשוב מהם, היא תפלה. ואע\"פ שהתפלה חשובה יותר. שני חברים או שלשה שעוסקים בדברי תורה, הוא עוד יותר חשוב מכל. כי אינם מתיראים מפני לסטים, משום שהשכינה מחוברת עמהם מחמת שעוסקים בתורה."],[5,"ר' אלעזר ור' חייא וכו':","ר\"א ור\"ח היו הולכים בדרך. א\"ר אלעזר, כתוב, ויעש ה' אלקים לאדם ולאשתו כתנות עור. וכי עד עתה היו מופשטים מעור ההוא. ומשיב, כן, שעד עתה לא היו להם אלו כתנות עור, כי כלי לבושי יקר היו. אמר לו ר' חייא אם כן, לא היה ראוי להם, אפילו כתנות עור, מאחר שחטאו בעץ הדעת. ואם תאמר שמטרם שחטאו הלביש אותם כתנות עור, אינו כן, אלא לאחר שחטאו כתוב, ויעש ה' אלקים לאדם ולאשתו כתנות עור וילבישם."],[6,"א\"ל הכי הוא וכו':","אמר לו, כך הוא ודאי שלאחר החטא היה. אלא בתחילה היו מלובשים כעין של מעלה דהיינו בזהר העליון של ז\"א, והיו מופשטים מן הגוונים שלמטה, של עולם הזה, והיה אור העליון מסבב אותם, ואחר שחטאו, החזיר אותם בגוונים של עולם הזה, והעביר מהם הגוונים של מעלה, שהיה להם מז\"א, מה כתוב, ויעש ה' אלקים לאדם ולאשתו כתנות עור וילבישם, כעין עולם הזה. כתוב, ואת אהרן ואת בניו תקריב והלבשתם כתנות. שם היה כעין של מעלה, דהיינו מבחינת אור ז\"א, וכאן, בכתנות עור של אדם הראשון, היו כעין שלמטה, לפיכך שם נקראים כתנות שש, הרומז על ז\"א, שהוא נקרא שש. ע\"ש ו\"ק, וכאן כתנות עור. שהם מבחינת המלכות הנקראת עור, שהיא בחינת עולם הזה. ואע\"פ שהוא כך, היופי של אלו הלבושים, היה עולה על הכל."],[7,"ותפקחנה עיני שניהם:","היינו שנפקחו עיניהם בטופס של עולם הזה, דהיינו בציור הרגיל בעולם הזה. מה שלא היה מקודם, שהיו משגיחים ופקחים למעלה. בעולם העליון. לעתיד לבא, כתוב והולכתי עורים בדרך לא ידעו וגו'. כי עתיד הקב\"ה לפקוח עינים שלא היו חכמות, שיסתכלו בחכמה עליונה, ולהשיג מה שלא השיגו בעולם הזה, כדי שיכירו את רבונם. אשריהם הצדיקים שיזכו לחכמה ההיא, שאין חכמה כאותה החכמה, ואין ידיעה כאותה הידיעה, ואין דבקות כאותה הדבקות."]],[[0,"","שֶׁהֲרֵי בְּשָׁעָה רִאשׁוֹנָה מֵתוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ צָרִיךְ, שֶׁהֲרֵי עֵץ הַמָּוֶת גָּרַם. אַחַר שֶׁחָיוּ וְקָמוּ וְהִתְרַבּוּ וְרָצָה הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְהַכְנִיסָם לְעֵץ הַחַיִּים שֶׁעוֹמֵד עַל אוֹתוֹ עֵץ הַמָּוֶת כְּדֵי לִהְיוֹת קַיָּמִים לְעוֹלָמִים, הִתְרַחֲקוּ וְלֹא רָצוּ, וְאָז נֶחֱלַשׁ כֹּחַ מֹשֶׁה עֲלֵיהֶם וְנֶחֱלַשׁ כֹּחַ אַחֵר. אָמַר הַקָּדוֹשׁ־בָּרוּךְ־הוּא, אֲנִי רָצִיתִי לְקַיֵּם אֶתְכֶם בְּמָקוֹם עֶלְיוֹן וּלְהִדָּבֵק בַּחַיִּים – אַתֶּם רְצִיתֶם מָקוֹם שֶׁשְּׁרוּיָה הַנְּקֵבָה, וְלָכֵן לֵךְ אֱמֹר לָהֶם וְגוֹ'. כָּל אֶחָד יֵלֵךְ לַנְּקֵבָה שֶׁלּוֹ וְיִתְיַחֵד עִמָּהּ."],[1,"","וְעִם כָּל זֶה, כֵּיוָן שֶׁיִּשְׂרָאֵל לֹא עָשׂוּ אֶלָּא בְּפַחַד עֶלְיוֹן שֶׁהָיָה עֲלֵיהֶם, לֹא נֶאֱמַר עֲלֵיהֶם, אֶלָּא מִי יִתֵּן וְהָיָה לְבָבָם זֶה לָהֶם וְגוֹ'. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁעוֹשֶׂה דָבָר, וְלִבּוֹ וּרְצוֹנוֹ לֹא שָׂם בַּצַּד הָרָע, אַף עַל גַּב שֶׁהוּא רַע – הוֹאִיל וְלֹא עָשָׂה בְרָצוֹן, לֹא שׁוֹרֶה עָלָיו עֹנֶשׁ, וְלֹא כְאָדָם אַחֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא דָן אוֹתוֹ לְרַע."],[2,"","וְאַתָּה פֹּה עֲמֹד עִמָּדִי. מִכָּאן נִפְרַד מִכֹּל וָכֹל מֵאִשְׁתּוֹ, וְנִדְבַּק וְעָלָה בְּמָקוֹם אַחֵר שֶׁל הַזָּכָר, וְלֹא בִנְקֵבָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, נְבִיא הָאֱמֶת, שֶׁזָּכָה לִדְרָגוֹת עֶלְיוֹנוֹת, מַה שֶּׁלֹּא זָכָה אָדָם אַחֵר לְעוֹלָמִים. וְעַל זֶה כָּתוּב, [קהלת ז] טוֹב לִפְנֵי הָאֱלֹהִים יִמָּלֵט מִמֶּנָּה. מַה זֶּה טוֹב? זֶה מֹשֶׁה, שֶׁכָּתוּב [שמות ב] כִּי טוֹב הוּא. וּמִשּׁוּם שֶׁהָיָה טוֹב, עָלָה לְדַרְגָּה אַחֶרֶת עֶלְיוֹנָה. וְעַל זֶה כָּתוּב [שם ג] כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. עוֹמֵד עָלָיו דַּוְקָא. מָה הַטַּעַם? מִשּׁוּם כִּי טוֹב הוּא, וְטוֹב הוּא זָכָר."],[3,"","וְאִם תֹּאמַר שֶׁהֲרֵי אָמַר רַבִּי יְהוּדָה, הֲרֵי דָּוִד שֶׁכָּתוּב בּוֹ טוֹב, כְּמוֹ שֶׁנֶּאֱמַר [שמואל א טז] וְטוֹב רֹאִי, לָמָּה לֹא הָיָה יוֹתֵר? אָמַר לוֹ, כָּתוּב וְטוֹב רֹאִי. טוֹב רֹאִי זֶה שֶׁהוּא מַרְאֶה לְהִסְתַּכֵּל, כָּךְ הָיָה דָּוִד. טוֹב רֹאִי – הָיָה טוֹב שֶׁהוּא מַרְאֶה. וּבְמֹשֶׁה כָּתוּב טוֹב הוּא, מַמָּשׁ, וְכָאן טוֹב רֹאִי, וְעִם כָּל זֶה בִּשְׁנֵיהֶם הָיָה אָחוּז, שֶׁהֲרֵי זֶה בָּזֶה אָחוּז. וּמֹשֶׁה, אַחַר שֶׁהָיָה טוֹב, עָלָה לִהְיוֹת גּוּף אִישׁ. [דברים לג] אִישׁ הָאֱלֹהִים. [במדבר יב] וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד."],[4,"","אָמַר רַבִּי יְהוּדָה, בְּכָל מַעֲשָׂיו צָרִיךְ הָאָדָם לָשִׂים כְּנֶגְדּוֹ אֶת הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וַהֲרֵי בֵּאַרְנוּ אֶת הַדָּבָר. רַבִּי יְהוּדָה לְטַעֲמוֹ. שֶׁאָמַר רַבִּי יְהוּדָה, מִי שֶׁהוֹלֵךְ בַּדֶּרֶךְ יְכַוֵּן לִשְׁלֹשָׁה דְבָרִים, וְעֶלְיוֹן מִכֻּלָּם זוֹ הַתְּפִלָּה. וְאַף עַל גַּב שֶׁתְּפִלָּה יוֹתֵר עֶלְיוֹנָה מֵהַכֹּל, שְׁנֵי חֲבֵרִים אוֹ שְׁלֹשָׁה שֶׁעוֹסְקִים בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי לֹא יִפְחֲדוּ, כִּי הַשְּׁכִינָה [ולמעלה מהם תפלה, ועליונה מכלם, חברים בדברי תורה. שהרי השכינה] מִשְׁתַּתֶּפֶת עִמָּם."],[5,"","[כמו זה ש] רַבִּי אֶלְעָזָר וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב [בראשית ג] וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר. וְכִי עַד עַכְשָׁו מֻפְשָׁטִים הָיוּ מֵאוֹתוֹ הָעוֹר? כֵּן. אֶלָּא כְּלֵי לְבוּשֵׁי כָבוֹד הָיוּ. אָמַר לוֹ רַבִּי חִיָּיא, אִם כָּךְ לֹא רָאוּי לָהֶם אֲפִלּוּ כָּתְנוֹת עוֹר. וְאִם תֹּאמַר שֶׁעַד שֶׁלֹּא חָטְאוּ הִלְבִּישׁוּ אוֹתָם – לֹא. אֶלָּא אַחַר שֶׁחָטְאוּ כָּתוּב [בראשית ג] וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹ עוֹר וַיַּלְבִּשֵׁם וְגוֹ'."],[6,"","אָמַר לוֹ, כָּךְ זֶה בְּוַדַּאי. בַּהַתְחָלָה הָיוּ כְּמוֹ שֶׁלְּמַעְלָה, וּמֻפְשָׁטִים מֵהַגְּוָנִים שֶׁלְּמַטָּה, וְהָיָה הָאוֹר הָעֶלְיוֹן סוֹבֵב עֲלֵיהֶם. אַחַר שֶׁחָטְאוּ הֶחֱזִירָם בְּצוּרוֹת הָעוֹלָם הַזֶּה, וְהֶעֱבִיר מֵהֶם הַצּוּרוֹת שֶׁלְּמַעְלָה. מַה כָּתוּב? וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם, מִצּוּרַת הָעוֹלָם הַזֶּה. כָּתוּב [שמות כט] [ואת אהרן] וְאֶת בָּנָיו תַּקְרִיב וְהִלְבַּשְׁתָּם כֻּתֳּנֹת. שָׁם כְּגוֹן עֶלְיוֹן, כָּאן כְּגוֹן תַּחְתּוֹן. שָׁם כָּתְנוֹת שֵׁשׁ, כָּאן כָּתְנוֹת עוֹר. וְאַף עַל גַּב שֶׁכָּךְ הוּא, הַיֹּפִי שֶׁל אוֹתָם לְבוּשִׁים עָלָה עַל הַכֹּל."],[7,"","וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם [בראשית ג]. [בצורת] [בדפוס] הָעוֹלָם הַזֶּה, מַה שֶּׁלֹּא הָיָה קֹדֶם שֶׁהָיוּ מַשְׁגִּיחִים וּפוֹקְחִים לְמַעְלָה, לֶעָתִיד לָבֹא כָּתוּב [ישעיה מב] וְהוֹלַכְתִּי עִוְרִים בְּדֶרֶךְ לֹא יָדָעוּ וְגוֹ'. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְקֹחַ עֵינַיִם שֶׁל אֲנָשִׁים לֹא חֲכָמִים, וּלְהִסְתַּכֵּל בְּחָכְמָה עֶלְיוֹנָה וּלְהִדָּבֵק בְּמַה שֶּׁלֹּא נִדְבְּקוּ בָּעוֹלָם הַזֶּה, כְּדֵי שֶׁיֵּדְעוּ אֶת רִבּוֹנָם. אַשְׁרֵי הַצַּדִּיקִים שֶׁיִּזְכּוּ לְאוֹתָהּ חָכְמָה, שֶׁאֵין חָכְמָה כְּאוֹתָהּ חָכְמָה, וְלֹא יְדִיעָה כְּאוֹתָהּ יְדִיעָה, וְלֹא דְבֵקוּת כְּאוֹתָהּ דְּבֵקוּת."]]],[["עַד דַּהֲווֹ אַזְלֵי, חֲזוּ אִינּוּן לִסְטִים אָזְלֵי בַּתְרַיְיהוּ, לְאַקְפְּחָא לוֹן. אִסְתָּכַּל בְּהוּ רִבִּי אֶלְעָזָר, אָתוּ תְּרֵין חֵיוָן בָּרָא וְקַטְלֵי לוֹן. אָמַר רִבִּי אֶלְעָזָר, בְּרִיךְ רַחֲמָנָא דְּשֵׁיזְבָן, קָרָא עָלַיְיהוּ, (משלי ד׳:י״ב) בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וּכְתִיב (תהילים צ״א:י״ד) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ'. וּכְתִיב (שם) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.","תָּאנָא בְּרָזָא עִלָּאָה בְּסִפְרָא דִּצְנִיעוּתָא, ג' חֲלָלִין דְּאַתְוָון רְשִׁימִין, אִתְגַּלְּיָין בָּהּ בְּגוּלְגַּלְתָּא דִּזְעֵיר אַנְפִּין. וְתָנֵינָן, ג' מוֹחֵי אִינּוּן, דִּסְתִּימוּ בְּאִינּוּן חַלָלִין. וּמִשֵּׁירוּתָא (וממשיכותא) דְּמוֹחָא עִלָּאָה סְתִימָאָה דְּעַתִּיקָא קַדִּישָׁא דְּאִתְמְשִׁיךְ בְּהַהוּא זְעֵיר אַנְפִּין, אִשְׁתְּכָחוּ ד' מוֹחֵי. וְאִלֵּין ד' מוֹחִין, (ס\"א דינא לית כתראי מכל כתרי מלכא) מִשְׁתַּכְּחִין וּמִתְפָּשְּׁטִין (ס\"א בכלא ואינון) בְּכָל גּוּפָא וְאִינּוּן ד' רִיהֲטֵי, דְּאַרְבַּע בָּתֵּי דִּתְפִילִין, דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא.","וּבְּגִין כָּךְ בָּעֵי בַּר נָשׁ לַאֲנָחָא בְּכָל יוֹמָא, בְּגִין דְּאִינּוּן שְׁמָא קַדִּישָׁא עִלָּאָה בְּאַתְווֹי רְשִׁימָן, דִּכְתִּיב, (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ. וּתְנָן, שֵׁם יְיָ' מַמָּשׁ, וְאִלֵּין תְּפִלִּין דְּרֵישָׁא. (מוחא עלאה דאתמשך במוחא תתאה אקרון תרי מוחין ואינון דכתיב חכמות, ומתפרשן בחד)","רִבִּי יִצְחָק אָמַר, הוּא דִּכְתִּיב, (שמות י״ג:ב׳) קַדֶּשׁ לִי כָל בְּכוֹר, דָּא הִיא כִּתְרָא דְּכָלִיל וְאַסְתִּים כָּל אִינּוּן אַחֲרָנִין. (כל בכור כל בכור סתם, לעלאה) מְשִׁיכוּתָא (ס\"א משרייתא) דִּלְעֵילָּא סְתִימָא בֵּיהּ. (דכלא) וְדָא אִקְרֵי פֶּטֶר כָּל רֶחֶם, פְּתִיחוּתָא דְּכָל מְשִׁיכוּתָא דְּרַחֲמֵי, וִיסוֹדָא (נ\"א ונהירו) דִּלְעֵילָּא.","אָמַר רִבִּי שִׁמְעוֹן, וְסָתִים בְּיוֹ\"ד דִּשְׁמָא קַדִּישָׁא. וְדָא (ס\"א יו\"ד) חַד בֵּיתָא דִּתְפִלִּין, דְּהוּא קַדֶּשׁ לִי כָל בְּכוֹר סְתָם. מוֹחָא (נ\"א אבא) עִלָּאָה, חָכְמָה.","בֵּיתָא תִּנְיָינָא, וְהָיָה כִּי יְבִיאֲךָ יְיָ' (אלהיך). אָמַר רִבִּי יְהוּדָה מוֹחָא דְּתַרְעוֹי נָפְקִין לְחַמְשִׁין תַּרְעִין. תַּרְעִין סַגִּיאִין, וְאִינּוּן לָקֳבֵל זִמְנִין סַגִּיאִין דִּכְתִּיב, (שמות כ׳:ב׳) אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם. (שמות י״ג:י״ח) הוֹצִיאֲךָ יְיָ' מִמִּצְרַיִם. וְאִדְכַּר זִמְנִין סַגִּיאִין דּוּכְרָנָא דְּמִצְרַיִם. וְאִינּוּן חַמְשִׁין לָקֳבֵל חַמְשִׁין.","וְתָנֵינָן בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, דְּאָמַר תַּרְעִין סַגִּיאִין דִּלְעֵילָּא וְתַתָּא, תָּבַר קוּדְשָׁא בְּרִיךְ הוּא, דַּהֲווֹ סְתִימִין וּמִתְקַטְּרִין בְּשַׁלְשְׁלֵיהוֹן, בְּגִין לְאַפָּקָא לְהוּ לְיִשְׂרָאֵל (לבר). דְּהָא מֵאִלֵּין תַּרְעִין דְּהַהוּא מוֹחָא, מִתְפַּתְּחֵי וּמִשְׁתְּרוּ כָּל שְׁאַר תַּרְעִין. וְאִלְמָלֵא דְּאִתְעָרוּ וְאִתְפְּתָּחוּ אִינּוּן תַּרְעִין דְּהַאי מוֹחָא, לָא הֲווֹ מִתְפַּתְּחִין אִינּוּן אַחֲרָנִין לְמֶעְבַּד דִּינָא, וּלְאַפָּקָא לוֹן לְיִשְׂרָאֵל מִן עַבְדּוּתָא.","וְכֹלָּא סָתִים בְּהַאי דְּאִקְרֵי אִימָא עִלָּאָה, דְּמִנָהּ אִתְּעַר חֵילָא לְאִימָא תַּתָּאָה. וּמַאי אִיהוּ. דִּכְתִּיב בָּהּ (ישעיהו נ״א:ד׳) וּלְאוּמִּי אֵלַי הַאֲזִינוּ. אַל תִּקְרֵי לְאוּמִּי, אֶלָּא לְאִמִּי. דְּלָא זָז קוּדְשָׁא בְּרִיךְ הוּא מֵחַבְּבָהּ לִכְנֶסֶת יִשְׂרָאֵל, עַד דִּקְרָאָהּ אִמִּי. וְהַאי נָפְקָא מֵאִימָא עִלָּאָה, דְּהִיא בֵּיתָא תִּנְיָינָא, דְּאִקְרֵי ה' דִּשְׁמָא קַדִּישָׁא, דְּאִתְפַּתְּחָא לְחַמְשִׁין תַּרְעִין. וּמֵהַאי נָפַק רוּחָא לְחַד נוּקְבָּא דְּפַרְדַּשְׁקָא דְּחוֹטָמָא.","וְתָנֵינָן, יוֹבְלָא דְּנָפְקִין בֵּיהּ עַבְדִּין לְחֵירוּ, בְּהַאי מוֹחָא אִתְאֲחָד. וְאִינּוּן חַמְשִׁין שְׁנִין דְּיוֹבְלָא. וְאִינּוּן חַמְשִׁין יוֹמִין דְּחוּשְׁבָּנָא דְּעוֹמֶר, בֵּיהּ אִתְאֲחָדוּ. דִּבְהוּ נַיְיחִין רוּחֵי דְּעַבְדִּין, וּמַפְּקֵי רוּחֵיהוֹן (נ\"א ומפיק רוחיה) לְנַיְיחָא. כְּמָה דִּכְתִּיב, (ישעיהו י״ד:ג׳) בְּיוֹם הָנִיחַ יְיָ' לְךָ מֵעָצְבְּךָ וּמִרָגְזֶךָ וּמִן הָעֲבוֹדָה וְגוֹ'. וּבְגִין כַּךְ, ה' נַיְיחָא דְּרוּחָא, וּלְאַפָּקָא רוּחָא לְחֵירוּ. וְהַאי בֵּיתָא יְצִיאַת מִצְרַיִם בָּהּ תַּלְיָיא, וּבְאָת ה' דִּשְׁמָא קַדִּישָׁא, כְּמָה דְּאִתְּמַר. עֲד כָּאן כְּלָלָא דְּי\"ה דִּשְׁמָא קַדִּישָׁא.","תָּא חֲזֵי, מִסִּטְרָא דְּאַבָּא נָפִיק חֶסֶד. מִסִּטְרָא דְּאִמָּא נָפִיק גְּבוּרָה. וְכֹלָּא אָחִיד קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְעַטָּר בְּהוּ, אָת וָא\"ו."],[[0,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, ראו אשר לסטים הולכים אחריהם לשדוד אותם. הסתכל בהם ר' אלעזר. באו ב' חיות השדה והרגו אותם. אמר ר' אלעזר ברוך הרחמן שהצילנו. קרא עליהם, בלכתך לא יצר צעדך ואם תרוץ לא תכשל. וכתוב, כי מלאכיו יצוה לך וגו'. וכתוב, כי בי חשק ואפלטהו."],[1,"תאנא ברזא עלאה וכו':","למדנו בסוד העליון, בספרא דצניעותא, (אות כ\"ז) ג' חללים של אותיות רשומות, שהם יה\"ו דהויה, מתגלים בגלגלתא דז\"א. ולמדנו ג' מוחין הם, שהם חכמה בינה דעת, הסתומים באלו החללים, החללים הם כלים, והמוחין הם האורות המתלבשים בהם. ומתחילת מוח העליון הסתום דעתיקא קדישא, כלומר, מהתפשטות הראשון של מוחא סתימאה דא\"א, שהתפשטות זו נקראת אבא ואמא עלאין (כנ\"ל בראשית א' דף ח' אות ג' ד\"ה וכדין ע\"ש) שנמשך במוחין של ז\"א ההוא, נמצאים ד' מוחין, שהם חכמה בינה, וימין דדעת, שה\"ס ת\"ת, ושמאל דדעת שה\"ס מלכות (כנ\"ל באדרא רבא אות קפ\"ט ע\"ש) ואלו ד' מוחין נמצאים בראש ז\"א, ומתפשטים בכל הגוף. והם ד' פרשות שבד' בתים של התפלין, שהקב\"ה מניחם. \u0003ריהטי\u0004 פירושו פרשות לפי הענין."],[2,"ובג\"כ בעי ב\"נ וכו':","ומשום זה צריך האדם להניח תפלין בכל יום, משום שהם השם הקדוש העליון, באותיות רשומות, שהן י\"ה ו\"ה, דהיינו ד' מוחין הנ\"ל בסמוך. שכתוב, וראו כל עמי הארץ כי שם הוי\"ה נקרא עליך. ולמדנו, שם הויה ממש, ואלו הם התפלין שבראש."],[3,"ר' יצחק אמר וכו':","רי\"א, היינו שכתוב, קדש לי כל בכור, זו היא ספירה, הכוללת וסותמת כל אלו האחרות. דהיינו ספירת החכמה, שכוללת בתוכה כל הספירות, המשכת אור שלמעלה, סתומה בה. וזו נקראת פטר כל רחם, שהיא פתיחת כל המשכת הרחמים ואור העליון."],[4,"אמר ר\"ש וסתים וכו':","אר\"ש, וספירת החכמה הזו, סתומה בה \u0003י'\u0004 של שם הקדוש הוי\"ה, וזו היא בית אחד של התפלין, שהוא קדש לי כל בכור, בכור סתם, הוא מוח העליון, חכמה."],[5,"ביתא תניינא והיה וגו':","הבית השני של התפלין, הוא, והיה כי יביאך ה'. א\"ר יהודה, הוא מוח, ששעריו יוצאים לחמשים שערים, דהיינו בינה, המתפשטת לחמשים שערי בינה. אלו שערים הרבים הם כנגד הרבה פעמים שכתוב אשר הוצאתיך מארץ מצרים, הוציאך ה' ממצרים. והרבה פעמים נזכר זכר יציאת מצרים, והם חמשים פעמים, כנגד חמשים שערי בינה. כי יציאת מצרים היתה בהארת הבינה, וע\"כ הם חמשים, כנגד חמשים שעריה."],[6,"ותנינן בספרא דרב וכו':","ולמדנו בספרו של רב המנונא סבא, שאמר, שערים רבים שלמעלה ושלמטה, שהיו סתומים וקשורים בשלשלאות, שיבר הקב\"ה כדי להוציא את ישראל ממצרים, כי מאלו שערים של מוח בינה ההוא, נפתחו והותרו כל שאר השערים, הסתומים הנ\"ל. ולולא שנתעוררו ונפתחו השערים של מוח בינה הזה, לא היו נפתחים שערים האחרים הסתומים לעשות דין במצרים, ולהוציא את ישראל מן העבדות. שמשום זה נזכרו חמשים פעמים יציאת מצרים, שהיו ע\"י חמשים שערי בינה."],[7,"וכלא סתים בהאי וכו':","והכל סתום במוח בינה הזה, הנקרא אמא עלאה, שממנה נתעורר כח לאמא תתאה, שהיא מלכות. ומה היא. היינו שכתוב בה, ולאמי אלי האזינו. אל תקרי לאומי אלא לאמי, כי לא זז הקב\"ה מחבבה לכנסת ישראל, שהיא המלכות עד שקראה אמי. דהיינו עד שהמלכות קיבלה אורות דאמא עליונה. כי אורות אלו יוצאים מאמא עליונה, שהוא הבית השני של התפלין, שנקרא \u0003ה'\u0004 של השם הקדוש הויה, שנפתחה לחמשים שערים. וממוח הזה יוצא רוח לנקב אחד של חלון החוטם דז\"א (עי' לעיל באדרא רבא אות רל\"ד בהסולם)."],[8,"ותנינן יובלא דנפקין וכו':","ולמדנו יובל, שבו יוצאים העבדים לחירות, מתאחד במוח בינה הזה. וחמשים שערי בינה, הם חמשים שנה של יובל, ואלו חמשים ימים של ספירת העומר, מתאחדים במוח בינה הזה, שבו נחים הרוחות של העבדים, ורוחם יוצא לחירות למנוחה. כמו שכתוב, ביום הניח ה' לך מעצבך ומרגזך ומן העבודה וגו'. ומשום זה, \u0003ה'\u0004 ראשונה דהויה שהיא בינה, היא מנוחת הרוח ומוציא הרוח לחירות. והבית השני הזה של התפלין תלויה בו יציאת מצרים, ובאות \u0003ה'\u0004 ראשונה של השם הקדוש, כמו שלמדנו. עד כאן, דהיינו בב' בתים הראשונים דתפלין, הם כלל \u0003י\"ה\u0004 של השם הקדוש."],[9,"תא חזי מסטרא וכו':","בוא וראה מצד אבא, שהוא חכמה, יוצא חסד, ומצד אמא, שהיא בינה, יוצאת גבורה, והכל אוחז הקב\"ה, שהוא ז\"א, ומתעטר בהם, שהוא אות \u0003ו'\u0004. כי ז\"א, הוא קו האמצעי הכולל לימין ושמאל, שהם אבא וחסד שבימין, ואמא וגבורה שבשמאל."]],[[0,"","עַד שֶׁהָיוּ הוֹלְכִים רָאוּ אוֹתָם לִיסְטִים הוֹלְכִים אַחֲרֵיהֶם לְקַפֵּחַ אוֹתָם. הִסְתַּכֵּל בָּהֶם רַבִּי אֶלְעָזָר. בָּאוּ שְׁתֵּי חַיּוֹת שָׂדֶה וְהָרְגוּ אוֹתָם. אָמַר רַבִּי אֶלְעָזָר, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילָנוּ. קָרָא עֲלֵיהֶם, [משלי ד] בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וְכָתוּב [תהלים לא] כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ', וְכָתוּב [שם] כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ."],[1,"","לָמַדְנוּ בְּסוֹד עֶלְיוֹן בְּסִפְרָא דִצְנִיעוּתָא, שְׁלֹשָׁה חֲלָלִים שֶׁל אוֹתִיּוֹת רְשׁוּמוֹת הִתְגַּלּוּ בַגֻּלְגֹּלֶת שֶׁל זְעֵיר אַנְפִּין. וְשָׁנִינוּ, שְׁלֹשָׁה מֹחוֹת הֵם שֶׁנִּסְתָּרִים בְּאוֹתָם חֲלָלִים. וּמֵרֵאשִׁית [וממשיכות] הַמֹּחַ הָעֶלְיוֹן הַנִּסְתָּר שֶׁל הָעַתִּיק הַקָּדוֹשׁ שֶׁנִּמְשָׁךְ בְּאוֹתוֹ זְעֵיר אַנְפִּין נִמְצְאוּ אַרְבָּעָה מֹחוֹת. וְאַרְבָּעָה הַמֹּחוֹת הַלָּלוּ [דין אין כתר מכל כתרי המלך] נִמְצָאִים וּמִתְפַּשְּׁטִים [בכל, והם] בְּכָל הַגּוּף, וְהֵם אַרְבַּע פָּרָשִׁיּוֹת שֶׁל אַרְבָּעָה בָּתֵי הַתְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","וְלָכֵן צָרִיךְ הָאָדָם לְהָנִיחַ בְּכָל יוֹם, מִשּׁוּם שֶׁהֵן שֵׁם קָדוֹשׁ עֶלְיוֹן בְּאוֹתִיּוֹתָיו רְשׁוּמוֹת, שֶׁכָּתוּב [דברים כח] וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ. וְשָׁנִינוּ שֵׁם ה' מַמָּשׁ, וְאֵלּוּ תְפִלִּין שֶׁל רֹאשׁ. [מח עליון שנמשך במח תחתון נקראו שני מחין, והם שכתוב חכמות, והתפרשו באחד]."],[3,"","רַבִּי יִצְחָק אָמַר, הוּא שֶׁכָּתוּב [שמות יג] קַדֶּשׁ לִי כָל בְּכוֹר. זֶהוּ כֶּתֶר שֶׁכָּלוּל וּמַסְתִּיר כָּל אוֹתָם הָאֲחֵרִים. [כל בכור, כל בכור סתם, לעליון] מְשִׁיכוּת [מחנה] שֶׁלְּמַעְלָה נִסְתֶּרֶת בּוֹ. [של הכל] וְזֶה נִקְרָא פֶּטֶר כָּל רֶחֶם, פְּתִיחוּת שֶׁל כָּל מְשִׁיכוּת הָרַחֲמִים וִיסוֹד [ואור] עֶלְיוֹן."],[4,"","אָמַר רַבִּי שִׁמְעוֹן, וְנִסְתָּר בַּיּוֹ\"ד שֶׁל הַשֵּׁם הַקָּדוֹשׁ. וְזֶה [יו\"ד] בַּיִת אֶחָד שֶׁל תְּפִלִּין, שֶׁהוּא קַדֶּשׁ לִי כָל בְּכוֹר סְתָם. מֹחַ [אבא] עֶלְיוֹן, חָכְמָה."],[5,"","בַּיִת שֵׁנִי – וְהָיָה כִּי יְבִיאֲךְ ה' [אלהיך]. אָמַר רַבִּי יְהוּדָה, מֹחַ שֶׁשְּׁעָרָיו יוֹצְאִים לַחֲמִשִּׁים שְׁעָרִים, שְׁעָרִים גְּדוֹלִים, וְהֵם כְּנֶגֶד זְמַנִּים רַבִּים, שֶׁכָּתוּב [שם כ] אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם. [שם יג] הוֹצִיאֲךְ ה' מִמִּצְרַיִם. וְנִזְכַּר פְּעָמִים רַבּוֹת זִכְרוֹן מִצְרַיִם, וְהֵם חֲמִשִּׁים כְּנֶגֶד חֲמִשִּׁים."],[6,"","וְשָׁנִינוּ בְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא שֶׁאָמַר, שְׁעָרִים רַבִּים שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה שָׁבַר הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהָיוּ נִסְתָּרִים וּקְשׁוּרִים בְּשַׁלְשְׁלָאוֹתֵיהֶם כְּדֵי לְהוֹצִיא אֶת יִשְׂרָאֵל [לחוץ], שֶׁהֲרֵי מֵהַשְּׁעָרִים הַלָּלוּ שֶׁל אוֹתוֹ הַמֹּחַ נִפְתָּחִים וּמֻתָּרִים כָּל שְׁאָר הַשְּׁעָרִים, וְאִלְמָלֵא שֶׁהִתְעוֹרְרוּ וְנִפְתְּחוּ אוֹתָם שְׁעָרִים שֶׁל הַמֹּחַ הַזֶּה, לֹא הָיוּ נִפְתָּחִים אוֹתָם הָאֲחֵרִים לַעֲשׂוֹת דִּין וּלְהוֹצִיא אֶת יִשְׂרָאֵל מִן הָעַבְדוּת."],[7,"","וְהַכֹּל נִסְתָּר בָּזֶה שֶׁנִּקְרֵאת אֵם הָעֶלְיוֹנָה, שֶׁמִּמֶּנָּה מִתְעוֹרֵר כֹּחַ לָאֵם הַתַּחְתּוֹנָה. וּמַהוּ? שֶׁכָּתוּב בָּהּ, [ישעיה נא] וּלְאוּמִּי אֵלַי הַאֲזִינוּ. אַל תִּקְרֵי לְאוּמִּי אֶלָּא לְאִמִּי. שֶׁלֹּא זָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּחַבֵּב אֶת כְּנֶסֶת יִשְׂרָאֵל עַד שֶׁקָּרָא לָהּ אִמִּי. וְזֶה יוֹצֵא מֵהָאֵם הָעֶלְיוֹנָה, שֶׁהִיא בַּיִת שֵׁנִי, שֶׁנִּקְרֵאת ה' שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁנִּפְתַּחַת לַחֲמִשִּׁים שְׁעָרִים, וּמִזֶּה יוֹצֵא רוּחַ לְנֶקֶב אֶחָד שֶׁל חוֹר הַחֹטֶם."],[8,"","וְשָׁנִינוּ, הַיּוֹבֵל שֶׁיּוֹצְאִים בּוֹ הָעֲבָדִים לְחֵרוּת, בַּמֹּחַ הַזֶּה נֶאֱחָז, וְהֵם חֲמִשִּׁים שְׁנוֹת הַיּוֹבֵל, וְהֵם חֲמִשִּׁים יְמֵי סְפִירַת הָעֹמֶר בּוֹ נֶאֱחָזִים, שֶׁבָּהֶם נָחוֹת רוּחוֹת הָעֲבָדִים וּמוֹצִיאִים רוּחָם [ומוציא רוחו] לִמְנוּחָה, כְּמוֹ שֶׁכָּתוּב [שם יד] בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמִרָגְזֶךְ וּמִן הָעֲבֹדָה וְגוֹ'. וּמִשּׁוּם זֶה, ה' מְנוּחַת הָרוּחַ, וּלְהוֹצִיא רוּחַ לַחֵרוּת. וּבְבַיִת זֶה תְּלוּיָה יְצִיאַת מִצְרַיִם, וּבָאוֹת ה' שֶׁל הַשֵּׁם הַקָּדוֹשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר. עַד כָּאן כְּלָל שֶׁל י\"ה שֶׁל הַשֵּׁם הַקָּדוֹשׁ."],[9,"","בֹּא וּרְאֵה, מִצַּד אַבָּא יוֹצֵא חֶסֶד, מִצַּד אִמָּא יוֹצֵאת גְּבוּרָה, וְהַכֹּל אוֹחֵז הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר בָּהֶם אוֹת וָא\"ו."]]],[["בֵּיתָא תְּלִיתָאָה שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. תָּאנָא רִבִּי שִׁמְעוֹן, דָּא הוּא רָזָא עִלָּאָה, דְּיִשְׂרָאֵל עִלָּאָה אִתְעֲטָּר בְּסִטְרָא דְּאַבָּא. וּמַאי אִיהוּ. אַבְרָהָם. וְאִתְעֲטָּר בְּסִטְרָא דְּאִימָּא. וּמַאי אִיהוּ. יִצְחָק.","תָּנֵינָן, וְאָהַבְתָּ מַאן דְּרָחִים לֵיהּ לְמַלְכָּא, עָבִיד יַתִּיר טִיבוּ חֶסֶד עִם כֹּלָּא. וְחֶסֶד יַתִּירָא, הַהוּא דְּאִקְרֵי חֶסֶד דֶּאֱמֶת, דְּלָא בָּעֵי אֲגָר עָלֵיהּ, אֶלָּא בְּגִין רְחִימוּתָא דְּמַלְכָּא, דְּרָחִים לֵיהּ יַתִּיר, וּבִרְחִימוּתָא דְּמַלְכָּא תַּלְיָא חֶסֶד. וְעַל דָּא אִקְרֵי (ישעיהו מ״א:ח׳) אַבְרָהָם אוֹהֲבִי. וּבְגִין דְּרָחִים לֵיהּ יַתִּיר, אַסְגֵּי חֶסֶד בְּעָלְמָא. וְעַל דָּא, הָכָא וְאָהַבְתָּ. וּבִרְחִימוּתָא תַּלְיָא חֶסֶד, וְדָא הִיא בֵּיתָא תְּלִיתָאָה.","בֵּיתָא רְבִיעָאָה, וְהָיָה אִם שָׁמוֹעַ. הִשָּׁמְרוּ לָכֶם. וְחָרָה אַף יְיָ'. גְּבוּרָה תַּקִּיפָא, וְדִינָא קַשְׁיָא הִיא, וְנַפְקַת מִסִּטְרָא דְּאִימָּא עִלָּאָה. וְתָנֵינָן, אַף עַל גַּב דְּלֵית הִיא דִּינָא, מִסִּטְרָהָא נָפְקָא דִּינָא, (דנפק) גְּבוּרָה עִלָּאָה. וְאִי תֵּימָא, וְהָיָה אִם שָׁמוֹעַ דְּלָאו הִיא דִּינָא. לֵית כִּתְרָא מִכָּל כִּתְרֵי מַלְכָּא, דְּלָא יִתְכְּלִיל דִּינָא וְרַחֲמֵי, כָּל שֶׁכֵּן גְּבוּרָה דְּאִתְכְּלִיל טַב וּבִישׁ.","וְאִלֵּין אַרְבָּעָה נָטִיל לוֹן וָא\"ו, וְאִתְעֲטָּר בְּהוּ. וְאִלֵּין אִינּוּן תְּפִילִין דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא. תָּנֵינָן, הַאי וָא\"ו סָלִיק וְאִתְעֲטָּר בְּעִטְרוֹי, וְאָחִיד לְהַאי וּלְהַאי, וְאִתְעֲטָּר בְּכֻלְּהוּ, וְעַל דָּא וָא\"ו, אֶמְצָעִיתָא דְּכֹלָּא, דְּעֵילָּא וְתַתָּא, לְאַחֲזָאָה חָכְמְתָא שְׁלֵימָתָא מִכָּל סִטְרוֹי.","(תאני רבי אבא, כתיב (דברים י׳:ט״ו)) רַק בַּאֲבוֹתֶיךָ חָשַׁק יְיָ'. מִכָּאן אָמַר רִבִּי שִׁמְעוֹן, אֲבָהָתָא אִינּוּן רְתִיכָא קַדִּישָׁא עִלָּאָה, וּכְתִיב חָשַׁק יְיָ'. תָּא חֲזֵי, כְּמָה דְּאִית רְתִיכָא קַדִּישָׁא לְתַתָּא, כַּךְ אִית רְתִיכָא קַדִּישָׁא לְעֵילָּא. וּמַאי נִיהוּ, הָא דְּאַמָרָן, רְתִיכָא קַדִּישָׁא כֹּלָּא אִקְרֵי, וְכֹלָּא אִתְקְשַׁר דָּא בְּדָא, וְאִתְעָבִיד כֹּלָּא חַד.","רַק בַּאֲבוֹתֶיךָ תְּלָתָא, וּרְתִיכָא אַרְבְּעָה, ד' מְנָלָן. דִּכְתִּיב (דברים י׳:ט״ו) וַיִּבְחַר בְּזַרְעָם אַחֲרֵיהֶם. מַאי מַשְׁמַע. לְאַכְלְלָא בְּהוּ דָּוִד מַלְכָּא, דְּאִיהוּ רְבִיעָאָה, לְאִתְתַּקְנָא בִּרְתִיכָא קַדִּישָׁא. דְּתָנֵינָן, אֲבָהָתָא תִּקּוּנָא וּשְׁלֵימוּתָא דְּכֹלָּא, וְגוּפָא בְּהוּ אִשְׁתַּכְלָל וְאִתְבְּנֵי, וּבְהוּ אִתְאֲחִיד. אָתָא דָּוִד מַלְכָּא, וְשַׁכְלִיל כֹּלָּא, וְאַתְקִין גּוּפָא, וְאַשְׁלְמֵיהּ בְּהוּ. וְאָמַר רִבִּי יִצְחָק, כְּמָה דְּזָכוּ אֲבָהָתָא לְאִתְעַטְּרָא בִּרְתִיכָא קַדִּישָׁא, כַּךְ זָכָה דָּוִד לְאִתְתַּקְנָא בְּסַמְכָא רְבִיעָאָה דִּרְתִיכָא.","אָמַר רִבִּי יְהוּדָה, כְּתִיב בֵּיהּ בְּדָוִד, (שמואל א ט״ז:י״ב) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. מַאי טַעֲמָא אַדְמוֹנִי. מִשּׁוּם דְּחוּלָקָא דְּעַדְבֵיהּ גַּרְמָא לֵיהּ. אַדְמוֹנִי דִּינָא וַדַּאי. עִם יְפֵה עֵינַיִם, דִּינָא בְּרַחֲמֵי. כְּמָה דִּכְתִּיב, (ישעיהו נ״ה:ג׳) חַסְדֵּי דָּוִד הַנֶּאֱמָנִים.","אָמַר רִבִּי יִצְחָק, חַסְדֵּי דָּוִד, בְּאַתְרֵיהּ אוֹקִימְנָא. אֶלָּא וְהוּא אַדְמוֹנִי, כִּדְאַמָרָן. עִם יְפֵה עֵינַיִם, אִלֵּין אֲבָהָתָא. תָּא חֲזֵי, יְרוּשָׁלַיִם וְצִיּוֹן, דִּינָא וְרַחֲמֵי. וְאַף עַל פִּי כֵּן כְּתִיב, (מלכים א ח׳:א׳) עִיר דָּוִד הִיא צִיּוֹן. וּכְתִּיב (הושע י״א:ט׳) בְּקִרְבְּךָ קָדוֹשׁ וְלֹא אָבֹא בְּעִיר, נִשְׁבַּע קוּדְשָׁא בְּרִיךְ הוּא שֶׁלֹּא יִכָּנֵּס בִּיְרוּשָׁלַ ם שֶׁל מַעֲלָה וְכוּ'. אֵימָתַי. אָמַר רִבִּי יְהוּדָה, כַּד אִתְהַדָּר מַלְכוּ בֵּית דָּוִד לְאַתְרֵיהּ לְתַתָּא.","רִבִּי יִצְחָק אָמַר, ש' דִּרְשִׁימָא בִּתְלַת קִשְׁרֵי, (דד' קשרין רמיזא היא לתלתא ורמיזא לארבעה, תלת הא דאמרן. ארבעה למהוי רתיכא קדישא כחדא. דהא הוא כללא דתקונא עלאה ומהכא מתפרשן ואתמשכן תתאי באורחייהו ברצועיהון דתליין בהני שערי דרישא דתליין בהו ואתמשכן מנייהו כל אינון אחרנין עד דאתקשרן באתרייהו).","תָּנֵינָן, ו' נָטִיל אִינּוּן עִלָּאֵי דְּאַמָרָן, וְאִלֵּין תְּפִלִּין דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין כַּךְ בָּעֵי בַּר נָשׁ לְאִתְפָּאֲרָא בְּהוּ, עָלֵיהּ כְּתִיב (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ, שֵׁם יְיָ' מַמָּשׁ. וְאִלֵּין אִינּוּן תְּפִלִּין דְּרֵישָׁא, תְּפִלִּין דִּדְרוֹעָא הִיא שְׂמָאלָא, דְּאִקְרֵי עֹז, וְיָרְתָא מֵעֹז, הֲדָא הוּא דִכְתִיב, (שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה בְּהֵ\"א, וְהִיא הֵ\"א דְּאוֹקִימְנָא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל. וְעַל דָּא, הֵ\"א בַּתְרָאָה נַטְלָא תְּפִלִין, דְּהִיא שְׂמָאלָא."],[[0,"ביתא תליתאה שמע וגו':","הבית השלישי של התפלין הוא שמע ישראל, שהוא ישראל סבא, עם ואהבת את ה' אלקיך. תאנא ר' שמעון, זה הוא סוד עליון, שישראל העליון, שהוא ז\"א, נתעטר מצד אבא, ומה הוא. הוא אברהם. ונתעטר מצד אמא, ומה הוא. הוא יצחק."],[0,"","פירוש. הקו האמצעי המכריע ומיחד את אבא ואמא, ה\"ס ז\"א שעלה ונעשה לדעת בין או\"א. וז\"ש \u0003שמע ישראל ישראל סבא\u0004. שפירושו, ישראל העליון שעלה להיות דעת, לאבא ואמא. וכיון שהוא מיחד או\"א, ע\"כ הוא כלול משניהם. והתכללותו מאבא ה\"ס הימין דדעת, ונקרא חסד, שהוא אברהם. והתכללותו מצד אמא, נקראת גבורה, שהוא יצחק. וז\"ש, \u0003אתעטר בסטרא דאבא\u0004, היינו מה שהדעת נכללת מצד אבא, \u0003ומאי איהו אברהם\u0004. שהוא חסד דדעת. וה\"ס פרשת שמע עם ואהבת. \u0003אתעטר בסטרא דאמא\u0004, דהיינו מה שהדעת כלולה מאמא, \u0003ומאי איהו יצחק\u0004, שהוא גבורה שבדעת. וה\"ס פרשת והיה אם שמוע, כמ\"ש להלאה."],[1,"תנינן ואהבת, מאן וכו':","למדנו, ואהבת, מי שאוהב את המלך עושה חסד ביותר, שעושה חסד עם הכל. וחסד יותר ההוא נקרא חסד של אמת, שאינו רוצה שכר בעד מעשיו, אלא עושה משום אהבת המלך שאוהב אותו ביותר. וע\"כ באהבת המלך תלוי חסד. וע\"כ נקרא אברהם אוהבי, שמשום שאהב אותו ביותר הרבה חסד בעולם. וע\"כ כתוב כאן, בבית הג' דתפלין שהוא חסד, ואהבת, משום שבאהבה תלוי חסד. וזה הוא בית השלישי שבתפלין."],[2,"ביתא רביעאה, והיה וגו':","הבית הרביעי של התפלין הוא והיה אם שמוע וגו'. השמרו לכם וגו' וחרה אף ה' וגו' שכל זה מורה על דין חזק, ודין קשה הוא, שיוצא מצד אמא עלאה, כלומר שהיא בחינת השמאל שבדעת, הכלולה מאמא עלאה שהיא גבורה (כנ\"ל אות מ\"ו) ולמדנו, אע\"פ שאמא אינה דין, הדין יוצא מצדה, שהיא גבורה עלאה, כלומר קו השמאל שבבינה, שהוא שורש כל הדינין דשמאל. ואם תאמר. והיה אם שמוע אינו דין, שהרי כתוב בו גם כן ונתתי מטר ארצכם בעתו וגו' ואכלת ושבעת. ומשיב, אין ספירה בכל ספירות המלך שלא תהיה כלולה מדין ורחמים, כל שכן גבורה שנכללים בה טוב ורע. וע\"כ כתוב בוהיה אם שמוע, גם טוב, אבל בכלל היא דין קשה."],[3,"ואלין ארבעה נטיל וכו':","ואלו ארבע פרשיות, שהן, חכמה, בינה, ימין דדעת, ושמאל דדעת, לוקח אותם ה \u0003ו'\u0004, שהיא ז\"א, ומתעטר בהם, דהיינו שנעשו לו מוחין. ואלו הם התפלין שמניח הקב\"ה. למדנו \u0003ו'\u0004 זו שהיא ז\"א עולה אל הבינה, ומתעטרת בעטרותיו ואוחז לזה ולזה. דהיינו לקו ימין שהוא חכמה שלה, ולקו שמאל שהוא בינה שלה. ומתעטרת בכולם, שמשום שיחד קו ימין ושמאל שבבינה ויצא שם ג' קוין שהם חכמה בינה דעת, זכה גם ז\"א באותם ג' מוחין חב\"ד ומתעטר בהם, כמ\"ש לעיל (ב\"א דף רפ\"ז ד\"ה תלת, ובאד\"ר אות קפ\"א) כיון דתלת מחד נפקי חד בתלת קיימא ע\"ש. וע\"כ ה \u0003ו'\u0004 שהיא ז\"א, היא אמצע הכל, למעלה ולמטה, שהוא קו אמצעי למעלה בין ימין ושמאל דבינה, והוא קו אמצעי למטה בימין ושמאל של המוחין שלו עצמו, להראות שלמות החכמה מכל צדדיה. כי הכרעת קו האמצעי משלים החכמה מכל צדדיה."],[4,"תאני ר' אבא וכו':","למד ר' אבא. כתוב רק באבותיך חשק ה'. מכאן אמר ר\"ש, האבות הן המרכבה הקדושה העליונה. וכתוב חשק ה'. בוא וראה, כמו שיש מרכבה קדושה למטה, במלכות שהיא מחזה ולמטה דז\"א, כך יש מרכבה קדושה למעלה, דהיינו מחזה ולמעלה דז\"א, ומי הם, היינו זה שאמרנו, שהם האבות הנקראים חג\"ת. והכל נקרא המרכבה הקדושה, כי הכל נקשר זה בזה ונעשו הכל אחד."],[5,"רק באבותיך תלתא וכו':","שואל רק באבותיך חשק ה', שאמרת שהם המרכבה, אינם אלא שלשה, והמרכבה היא ארבעה, ומאין לנו הרביעי. ומשיב, שכתוב, ויבחר בזרעם אחריהם. שואל, מה זה משמע, ומשיב, שהכתוב הזה בא לכלול בהאבות את דוד המלך, שהוא הרביעי להתתקן במרכבה הקדושה. כי למדנו, האבות, הם תקון ושלמות הכל, והם גוף, דהיינו חג\"ת דז\"א הנקרא גוף, ובהם נשתכלל הגוף ונבנה, ובהם נתאחד. כלומר, שעיקר הגוף שהוא ז\"א, הוא רק החג\"ת שבו, שהם למעלה מחזה, הנקראים אבות. בא דוד המלך ושכלל הכל, והתקין הגוף, והשלימו בהם. כי נעשה להם רביעי, שה\"ס המלכות, המשלמת את ז\"א, שנקרא גוף. ואמר ר' יצחק, כמו שזכו האבות להתעטר בהמרכבה הקדושה, כך זכה דוד להתתקן בעמוד הרביעי של המרכבה."],[6,"א\"ר יהודה כתיב וכו':","אר\"י, כתוב בו בדוד, והוא אדמוני עם יפה עינים וטוב רואי. מהו הטעם שנקרא אדמוני. הוא משום שחלק גורלו גרם לו, כי להיותו מרכבה למלכות היה בבחינת דין כמו המלכות. \u0003אדמוני\u0004 הוא ודאי דין. \u0003עם יפה עינים\u0004, היינו שהדין היה כלול ברחמים. כמ\"ש חסדי דוד הנאמנים."],[7,"א\"ר יצחק חסדי וכו':","אר\"י, חסדי דוד הנאמנים ביארנו במקומו, ואינם רומזים על התכללות הדין בחסד. אלא והוא אדמוני, פירושו כמו שאמרנו, שהוא דין, \u0003עם יפה עינים\u0004 הם האבות. שהם חג\"ת, שמאירים בג' גוונים שבעין. בוא וראה, ירושלים וציון הם דין ורחמים, ואע\"פ כן כתוב עיר דוד היא ציון. ללמד שהדין כלול ברחמים. וכתוב בקרבך קדוש ולא אבוא בעיר. שאמרו, שזה רומז, שנשבע הקב\"ה שלא יכנס בירושלים של מעלה עד שיכנסו ישראל לירושלים של מטה, שואל, מתי יהיה זה. א\"ר יהודה כשתחזור מלכות בית דוד למקומה למטה. אז יכנס הקב\"ה בירושלים של מעלה."],[8,"רבי יצחק אמר וכו':","רי\"א, \u0003ש'\u0004 הרשומה בג' קשרים, דהיינו בג' ראשים, ו \u0003ש'\u0004 של ארבעה קשרים. דהיינו בד' ראשים. רומזת לג' ורומזת לארבעה. ג' הוא זה שאמרנו, דהיינו ג' אבות חג\"ת, ארבעה, כוללת גם המלכות, שיהיו מרכבה קדושה ביחד. כי המלכות היא כלל של התקון העליון. כי מלכות משלמת את ז\"א. ומכאן מתפרשים ונמשכים המדרגות התחתונות בדרכיהן ברצועותיהן. כלומר שב' שינין הרשומים בצדי התפלין הם \u0003ש'\u0004 דשדי. שאחת מורה על חג\"ת לבד, ואחת מורה חג\"ת ומלכות. ו \u0003ד' י'\u0004 דשדי נמשכים ברצועות התפלין, שקשר של ראש הוא \u0003ד'\u0004 וקשר של יד, הוא \u0003י'\u0004. והן תלויות בשערות הראש, שתלויות בהן ונמשכות מהן כל אלו מדרגות האחרות, שהן \u0003ד' י'\u0004 דשדי, עד שנקשרים במקומם. כי אחר שהן מקבלות שפע משערות ראש הם נקשרים בש' דשדי ונשלם השם \u0003שדי\u0004. וענין שערות ראש עי' לעיל (באדרא רבא דף קי\"ח ד\"ה וכדי)."],[9,"תנינן ו' נטיל וכו':","למדנו ה \u0003ו'\u0004 שהיא ז\"א, לוקח אלו המוחין העליונים חב\"ד שאמרנו, והם התפלין שמניח הקב\"ה. משום זה, צריך האדם להתפאר בהם, כי התפלין נקראים פאר, עליהם כתוב, וראו כל עמי הארץ כי שם הויה נקרא עליך. שם הויה ממש, שהם המוחין חכמה ובינה שהם \u0003י\"ה\u0004 וימין ושמאל דדעת, שהם \u0003ו\"ה\u0004. ואלו הם תפלין של ראש. תפלין של הזרוע היא שמאל, הנקרא \u0003עז\u0004, בסו\"ה נשבע ה' בימינו ובזרוע עזו, שימינו זה תורה וזרוע עזו הוא תפלין (ויחי בחילופי גרסאות אות ו') והמלכות יורשת מן \u0003עז\u0004 שה\"ס קו השמאל. ז\"ש, והיה לאות על ידכה עם \u0003ה'\u0004 יתרה. והיא ה \u0003ה'\u0004 שהעמדנו, דהיינו המלכות. אשרי חלקם של ישראל. וע\"כ \u0003ה'\u0004 אחרונה, שהיא המלכות, לוקחת התפלין, שהיא שמאל. כי המלכות נבנית מקו שמאל. ע\"כ לוקחת התפלין שבזרוע השמאלית."]],[[0,"","בַּיִת שְׁלִישִׁי – שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. שָׁנָה רַבִּי שִׁמְעוֹן, זֶהוּ סוֹד עֶלְיוֹן שֶׁיִּשְׂרָאֵל הָעֶלְיוֹן הִתְעַטֵּר בְּצַד הָאַבָּא, וּמַהוּ? אַבְרָהָם. וְהִתְעַטֵּר בְּצַד הָאִמָּא, וּמַהוּ? יִצְחָק."],[1,"","שָׁנִינוּ, וְאָהַבְתָּ – מִי שֶׁאוֹהֵב אֶת הַמֶּלֶךְ, עוֹשֶׂה יוֹתֵר טוּב חֶסֶד עִם הַכֹּל. וְחֶסֶד יוֹתֵר, אוֹתוֹ שֶׁנִּקְרָא חֶסֶד שֶׁל אֱמֶת, שֶׁלֹּא רוֹצֶה עָלָיו שָׂכָר, אֶלָּא בִּשְׁבִיל אַהֲבַת הַמֶּלֶךְ שֶׁאוֹהֵב אוֹתוֹ יוֹתֵר, וּבְאַהֲבַת הַמֶּלֶךְ תָּלוּי הַחֶסֶד. וְעַל זֶה נִקְרָא [ישעיה מא] אַבְרָהָם אוֹהֲבִי. וּמִשּׁוּם שֶׁאוֹהֵב אוֹתוֹ יוֹתֵר, מַגְדִּיל חֶסֶד בָּעוֹלָם. וְעַל זֶה כָּאן וְאָהַבְתָּ. וּבָאַהֲבָה תָּלוּי הַחֶסֶד, וְזֶהוּ הַבַּיִת הַשְּׁלִישִׁי."],[2,"","הַבַּיִת הָרְבִיעִי – [דברים יא] וְהָיָה אִם שָׁמוֹעַ. הִשָּׁמְרוּ לָכֶם. וְחָרָה אַף ה'. גְּבוּרָה חֲזָקָה וְדִין קָשֶׁה הִיא, וְיוֹצֵאת מִצַּד הָאִמָּא הָעֶלְיוֹנָה. וְשָׁנִינוּ, אַף עַל גַּב שֶׁהִיא אֵינָהּ דִּין, מִצִּדָּהּ יוֹצֵא דִין, [שיוצא] גְּבוּרָה עֶלְיוֹנָה. וְאִם תֹּאמַר, וְהָיָה אִם שָׁמוֹעַ שֶׁאֵינֶנּוּ דִין, אֵין כֶּתֶר בְּכָל כִּתְרֵי הַמֶּלֶךְ שֶׁלֹּא יִכָּלְלוּ בוֹ דִּין וְרַחֲמִים, כָּל שֶׁכֵּן גִּבוּרָה שֶׁנִּכְלָל טוֹב וָרַע."],[3,"","וְאַרְבָּעָֹה אֵלֶּה לוֹקֵחַ אוֹתָם וָא\"ו וּמִתְעַטֵּר בָּהֶם, וְאֵלּוּ הֵן תְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא. שָׁנִינוּ, הַוָּא\"ו הַזֶּה עוֹלֶה וּמִתְעַטֵּר בְּעַטְרוֹתָיו, וְאוֹחֵז אֶת זֶה וְאֶת זֶה וּמִתְעַטֵּר בְּכֻלָּם, וְעַל זֶה וָא\"ו אֶמְצַע הַכֹּל, שֶׁלְּמַעְלָה וּלְמַטָּה, לְהַרְאוֹת חָכְמָה שְׁלֵמָה מִכָּל צְדָדָיו."],[4,"","[שנה רבי אבא,] כָּתוּב [דברים י] רק באבתיך חשק ה'. מכאן אמר רבי שמעון, האבות הם מרכבה קדושה עליונה, וכתוב חשק ה'. בּא וּרְאֵה, כְּמוֹ שֶׁיֵּשׁ מֶרְכָּבָה קְדוֹשָׁה לְמַטָּה, כָּךְ יֵשׁ מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה. וּמַה הִיא? זֶה שֶׁאָמַרְנוּ, מֶרְכָּבָה קְדוֹשָׁה הַכֹּל נִקְרָא, וְהַכֹּל נִקְשָׁר זֶה בָּזֶה, וְנַעֲשֶׂה הַכֹּל אֶחָד."],[5,"","רַק בַּאֲבֹתֶיךְ – שְׁלֹשָׁה, וּמֶרְכָּבָה – אַרְבָּעָה. אַרְבָּעָה מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיִּבְחַר בְּזַרְעָם אַחֲרֵיהֶם. מַה מַּשְׁמִיעַ? לְהַכְלִיל בָּהֶם אֶת דָּוִד הַמֶּלֶךְ, שֶׁהוּא רְבִיעִי לְהִתְתַּקֵּן בַּמֶּרְכָּבָה הַקְּדוֹשָׁה. שֶׁשָּׁנִינוּ, הָאָבוֹת תִּקּוּן שְׁלֵמוּת הַכֹּל, וְהַגּוּף מִשְׁתַּכְלֵל בָּהֶם וְנִבְנֶה, וּבָהֶם נֶאֱחָז. בָּא דָוִד הַמֶּלֶךְ וְשִׁכְלֵל הַכֹּל, וְהִתְקִין הַגּוּף וְהִשְׁלִימָם בָּהֶם. וְאָמַר רַבִּי יִצְחָק, כְּמוֹ שֶׁזָּכוּ הָאָבוֹת לְהִתְעַטֵּר בַּמֶּרְכָּבָה הַקְּדוֹשָׁה, כָּךְ זָכָה דָוִד לְהִתְתַּקֵּן בָּעַמּוּד הָרְבִיעִי שֶׁל הַמֶּרְכָּבָה."],[6,"","אָמַר רַבִּי יְהוּדָה, כָּתוּב בְּדָוִד [שמואל א טז] וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. מָה הַטַּעַם אַדְמוֹנִי? מִשּׁוּם שֶׁחֵלֶק גּוֹרָלוֹ גָּרַם לוֹ. אַדְמוֹנִי, דִּין וַדַּאי. עִם יְפֵה עֵינַיִם, דִּין בְּרַחֲמִים, כְּמוֹ שֶׁכָּתוּב [ישעיה נה] חַסְדֵי דָוִד הַנֶּאֱמָנִים."],[7,"","אָמַר רַבִּי יִצְחָק, חַסְדֵי דָוִד, בִּמְקוֹמוֹ בֵּאַרְנוּ. אֶלָּא וְהוּא אַדְמוֹנִי, כְּמוֹ שֶׁאָמַרְנוּ. עִם יְפֵה עֵינַיִם – אֵלּוּ הָאָבוֹת. בֹּא וּרְאֵה, יְרוּשָׁלַיִם וְצִיּוֹן – דִּין וְרַחֲמִים, וְאַף עַל פִּי כֵן כָּתוּב [מלכים א ח] [מ] עִיר דָּוִד הִיא צִיּוֹן, וּכְתִיב [הושע יא] בְּקִרְבְּךְ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר. נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס בִּירוּשָׁלַיִם שֶׁל מַעְלָה וְכוּ'. אֵימָתַי? אָמַר רַבִּי יְהוּדָה, כְּשֶׁתַּחֲזֹּר מַלְכוּת בֵּית דָּוִד לִמְקוֹמָהּ לְמַטָּה."],[8,"","רַבִּי יִצְחָק אָמַר, ש' שֶׁמְּצֻיֶּרֶת בִּשְׁלֹשֶׁת הַקְּשָׁרִים, [של ארבעה קשרים, רמוזה היא לשלשה, ורמוזה לארבעה. שלשה זה שאמרנו. ארבעה, להיות מרכבה קדושה כאחד, שהרי הוא כלל התקון העליון. ומכאן נפרדים ונמשכים התחתונים בדרכיהם ברצועותיהם, שתלויים בשערות הללו של הראש שתלויים בהם, ונמשכים מהם כל אותם אחרים, עד שנקשרים במקומם]."],[9,"","שָׁנִינוּ, ו' נוֹטֵל אוֹתָם עֶלְיוֹנִים שֶׁאָמַרְנוּ, וְאֵלּוּ תְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא. מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִתְפָּאֵר בָּהֶם, עֲלֵיהֶם כָּתוּב וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ, שֵׁם ה' מַמָּשׁ. וְאֵלּוּ אוֹתָם תְּפִלִּין שֶׁל רֹאשׁ. תְּפִלִּין שֶׁל זְרוֹעַ הִיא שְׂמֹאל, שֶׁנִּקְרָא עֹז, וְיָרְשָׁה מֵעֹז, זֶהוּ שֶׁכָּתוּב [שמות יג] וְהָיָה לְאוֹת עַל יָדְכָה, בְּהֵ\"א, וְהִיא הֵ\"א שֶׁבֵּאַרְנוּ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל. וְעַל זֶה הֵ\"א אַחֲרוֹנָה לָקְחָה תְפִלִּין, שֶׁהִיא שְׂמֹאל."]]],[["לְמַאן (נ\"א ומאן) אִינּוּן אִלֵּין אַרְבְּעָה, דְּאִינּוּן חַד גּוּפָא, וְעַל דָּא כְּלִילָן בְּחַד, וּמַאן אִינּוּן. תִּפְאֶרֶת נֶצַח הוֹד יְסוֹד. וְהִיא הֵ\"א דְּיָדְכָה, וְכֻלְּהוּ אֲחִידָא בָּהּ, בְּגִין לְאִתְבָּרְכָא מִנַּיְיהוּ, וּכְלִילָא מִכֻּלְּהוּ.","אָמַר רִבִּי חִיָּיא, אִי הָכִי הָא כְּתִיב (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי, וְתָנֵינָן דָּא קֶשֶׁר שֶׁל תְּפִלִּין. אָמַר לֵיהּ, הָא אוֹקְמוּהָ, וְשַׁפִּיר הוּא, וְכֹלָּא בְּרִירָא דְּמִלָּה. וְעַל דָּא מֵהַאי תַּלְיָיא רְצוּעָה חַד לְתַתָּא, דְּהָא מִנָהּ תַּלְיָין תַּתָּאֵי, וְאִתְּזָנוּ מִנָהּ. וְעַל דָּא אִיתְקְרֵי אוֹת. כְּמָה דְאַתְּ אָמֵר (בראשית ט׳:י״ב) זֹאת אוֹת הַבְּרִית. וּכְתִיב (שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה בְּה' וְהָא אוֹקְמוּהָ.","(דברים ו') שְׁמַע יִשְׂרָאֵל. אָמַר רִבִּי יֵיסָא, יִשְׂרָאֵל סָבָא. רִבִּי יִצְחָק אָמַר ע' רַבְרְבָא, לְאַכְלְלָא שִׁבְעִין שְׁמָהָן, סַהֲדוּתָא דְּכֹלָּא שְׁמַע יִשְׂרָאֵל, כְּמָה דִּכְתִּיב, (ישעיהו א׳:ב׳) שִׁמְעוּ שָׁמַיִם. וּכְתִיב (דברים ל״ב:א׳) הַאֲזִינוּ הַשָּׁמַיִם. אוּף הָכָא שְׁמַע יִשְׂרָאֵל. וְכֹלָּא חַד מִלָּה הוּא. יְדוָֹ\"ד, רֵישָׁא דְּכֹלָּא, בִּנְהִירוּ דְּעַתִּיקָא קַדִּישָׁא. וְהַאי הוּא דְּאִקְרֵי אָ\"ב. אֱלֹהֵינוּ, עֲמִיקְתָא דְּנַחֲלִין וּמַבּוּעִין, דְּנָפְקִין וְנַגְדִּין לְכֹלָּא.","יְדוָֹ\"ד, גוּפָא דְּאִילָנָא שְׁלִימוּ דְּשָׁרָשִׁין. אֶחָד, כְּנֶסֶת יִשְׂרָאֵל. וְכֹלָּא חַד שְׁלֵימוּתָא, וְאִתְקְשַׁר דָּא בְּדָא, וְלָא אִשְׁתְּכַח פִּרוּדָא, אֶלָּא כֹּלָּא חַד.","תָּנֵי רִבִּי יִצְחָק, רְתִיכָא קַדִּישָׁא עִלָּאָה, אַרְבַּע בָּתֵּי דִּתְפִילִין דְּאָנַח ו'. כְּמָה דְּאִתְּמַר. רְתִיכָא קַדִּישָׁא אָחֳרָא, אַרְבַּע אַחֲרָנִין דִּכְלִילָן בְּחַד, דְּאָנַח ה' בַּתְרָאָה כְּמָה דְּאוֹקְמוּהָ.","\u0003רעיא מהימנא\u0004 (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, פִּקּוּדָא דָּא, (ד) (עיין בהקדמה י\"ג ע\"ב) לְיַחֲדָא שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, דְּהָא כְּמָה דִּמְיַיחֲדֵי שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא, הָכִי אִתְיָיחָד שְׁמֵיהּ לְעֵילָּא. אִשְׁתְּכַח קוּדְשָׁא בְּרִיךְ הוּא יְחִידָאי עֵילָּא וְתַתָּא. מַאן דִּמְיַיחֵד שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, יְשַׁוִּי לִבֵּיהּ וּרְעוּתֵיהּ בְּהַהוּא יִחוּדָא דְּקָאַמְרָן, וִיחַבֵּר כָּל שַׁיְיפוֹי בְּהוּא יִחוּדָא בְּהַהוּא רְעוּתָא לְמֶהֱוִי כֻּלְּהוּ אֶחָד. כְּמָה דְּשַׁוִּי כָּל שַׁיְיפוֹי בְּרָזָא דְּחָד, הָכִי לְעֵילָּא מְחַבֵּר כָּל שַׁיְיפִין עִלָּאִין בְּהַהוּא יִחוּדָא, לְמֶהֱוִי כֻּלְּהוּ חַד.","בְּשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְיַיחְדָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל חֵילֵי שְׁמַיָא כֻּלְּהוּ, קַיְימִין שׁוּרִין שׁוּרִין, בְּגִין לְאִתְתַּקְנָא וּלְאִתְכַּלְּלָא כֻּלְּהוּ בְּהַהוּא יִחוּדָא, לְמֵיקָם בְּרָזָא דְּחָד בְּיִחוּדָא חֲדָא. כֻּלְּהוּ מִתְתַּקְּנָן בְּתִקּוּנֵיהוֹן כְּדְקָא יָאוּת. בְּהַאי שַׁעֲתָא קַיְּימָא חַד מְמָנָא שַׁמָשָׁא, דְּקַיְּימָא תְּחוֹת רמ\"ח עָלְמִין, וְכֻלְּהוּ אִקְרוּן שַׁיְיפִין דְּגוּפָא. וְדָא אִקְרֵי הלני\"ו, קַיְּימָא מְחַכָּה לְהַהוּא יִחוּדָא, וְדָא אִיהוּ מְלַקֵּט שׁוֹשַׁנִּים, כְּמָה דְאַתְּ אָמֵר (שיר השירים ו׳:ב׳) וְלִלְקוֹט שׁוֹשַׁנִּים. דְּאִינּוּן שַׁיְיפִין דְּגוּפָא.","שַׁיְיפִין עִלָּאִין לָקִיט לוֹן שְׁמָא עִלָּאָה, בְּרָזָא דְּיִחוּדָא דְּקָא אִתְיָיחָד בְּרָזָא דְּמ\"ב שְׁמָהָן. וְלָקִיט כָּל אִינּוּן שׁוֹשַׁנִּים עִלָּאִין, וְשַׁמָּשָׁא דָּא לָקִיט כָּל אִינּוּן תַּתָּאִין, דִּי כֻּלְּהוּ מְמָנָן בִּכְלָלָא דְּע\"ב שְׁמָהָן, וְאִתְלְקִּיטוּ כֻּלְּהוּ בְּהַהוּא יִחוּדָא, וְאִתְעָבִידוּ כֻּלְּהוּ גּוּפָא חֲדָא. בְּרָזָא חֲדָא. וְהַהוּא יִחוּדָא סַלְּקָא, וְקָא מְיַיחֵד כֹּלָּא בִּתְרֵין סִטְרִין בְּיִחוּדָא חֲדָא. בְּהַהוּא שַׁעֲתָא מִתְלַקְּטִין שַׁיְיפִין כֻּלְּהוּ, וּמִתְחַבְּרָן בְּחִבּוּרָא חֲדָא, לְמֶהֱוִי כֻּלְּהוּ בְּרָזָא דְּחָד, עֵילָּא וְתַתָּא, בְּרָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד.","וְעַל דָּא מַאֲרִיכִין בְּאֶחָד, בִּתְרֵי אַתְוָון. לְמִלְקַּט שׁוֹשַׁנִּים, לְאִתְיַיחֲדָא בְּרָזָא דְּאֶחָד בְּיִחוּדָא שְׁלִים. כֵּיוָן דְּאִתְיַיחֲדָן שַׁיְיפִין כֻּלְּהוּ, בְּרָזָא חֲדָא דְּיִחוּדָא חֲדָא, כְּדֵין אִתְקְרֵי כֹּלָּא קָרְבָּן שְׁלִים. וְעַל רָזָא דָּא, אָעִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּגַּן עֵדֶן לְאָדָם קַדְמָאָה, כְּמָה דִּכְתִּיב, (בראשית ב׳:ט״ו) לְעָבְדָהּ וּלְשָׁמְרָהּ. וְתָנֵינָן, דְּאִלֵּין אִינּוּן קָרְבְּנִין תְּרֵין, רָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד. דְּאִינּוּן קָרְבְּנִין כְּתִיב, וְלִלְקוֹט שׁוֹשַׁנִּים. (ד\"א דקודשא בריך הוא איהו לקיט שושנים לקיט כל אינון שייפין דעילא ותתא לחברא לון ביחודא בההוא דקאמרן. כדין אתער מאן דאתער ללקוט שושנים) אִלֵּין שַׁיְיפִין דִּתְרֵין סִטְרִין, דְּאִינּוּן חַד.","שׁוֹשַׁנִּים רָזָא אִיהוּ. דְּכַד מִתְחַבְּרָן כָּל (אינון) שַׁיְיפִין כַּחֲדָא, לְמֶהֱוִי כֻּלְּהוּ בְּיִחוּדָא חֲדָא, רָזָא דְּקָרְבָּן, כְּדֵין מִתְעַטֵר קוּדְשָׁא בְּרִיךְ הוּא בַּעֲטָרָה בְּרֵישָׁא דְּכֶתֶם פָּז, לְמֶהֱוִי בִּיקָרוֹי מִתְעַטְרָא. וְרָזָא דָּא הֲוִי דִּכְתִּיב שׁוֹשַׁנִּים, רָזָא דְּכָל אִינּוּן שַׁיְיפִין דְּעֵילָּא וְתַתָּא. וְרָזָא דְּהַהוּא פָּז, עִטוּרָא דְּמִתְעַטְרָא וְסַלְּקָא מִבֵּינַיְיהוּ, וְכֹלָּא אִיהוּ בֵּיהּ."],[[0,"למאן אינון אלין וכו':","שואל, למי הם אלו ארבע הפרשיות שהן גוף אחד, שע\"כ כלולים בבית אחד, ומי הם. ומשיב. הם תפארת נצח הוד יסוד, דהיינו ד' הספירות שמחזה ולמטה דז\"א, והם \u0003ה'\u0004 של ידכה, שהיא המלכות, שכולם, כל ד' הספירות תנה\"י שמחזה ולמטה אחוזים במלכות, כדי שתתברך מהם, וע\"כ היא כלולה מכל ד' הספירות שמחזה ולמטה דז\"א."],[1,"א\"ר חייא אי וכו':","אר\"ח, אם כן הרי כתוב, וראית את אחורי, ולמדנו שזה קשר של תפלין, וכיון שכתוב בה ראיה, משמע שהיא מלכות (כנ\"ל ב\"א אות ס\"ט). ואתה אומר שתפלין של יד הם מלכות. אמר לו, הרי כבר העמדנו (לעיל בא אות רמ\"ה רמ\"ו) שתפלין של יד ה\"ס המלכות המתקשרת ב \u0003י'\u0004 שהוא יסוד דז\"א. והקשר של \u0003ד'\u0004 היא המלכות דאחורים, שמבחינת מחזה ולמעלה דז\"א, מטרם שקבלה החסדים דיסוד דז\"א שאז היתה דלה וריקה מאור, מחמת שהחכמה שבה אינה מאירה בלי חסדים. כמ\"ש בסולם. ופירוש הזה יפה היא וכולו בירורו של הדבר. וע\"כ מזו, מתפלין של יד, תלויה רצועה אחת למטה, שזה מורה, שממנה תלוים התחתונים ונזונים ממנה. וע\"כ נקראת אות, ע\"ש שהיא דבוקה ביסוד, כש\"א זאת אות הברית. וכתוב, והיה לאות על ידכה ב \u0003ה'\u0004 יתרה. וכבר העמידוהו. משא\"כ ממלכות דאחורים שהיא קשר של \u0003ד'\u0004, אין התחתונים יכולים לקבל ממנה. להיותה חכמה בלי חסדים. וע\"כ היא נקראת ג\"כ יבשה, בסוד \u0003ד'\u0004 ואחד (כנ\"ל בהקדמת ספר הזהר אות כ\"ה)."],[2,"שמע ישראל אמר וכו':","שמע ישראל, אמר ר' ייסא שהוא ישראל סבא כלומר, שכל היחוד של ה' אלקינו ה', הוא בישסו\"ת, ר' יצחק אמר, \u0003ע'\u0004 גדולה שבשמ \u0003ע\u0004, היא כוללת \u0003ע'\u0004 שמות שה\"ס השם ע\"ב, שעקרו הוא ע' שמות, וב' סהדי. (כנ\"ל בשלח אות קס\"ג) שהוא עדות הכל. דהיינו המשכת הארת החכמה מ \u0003עדן\u0004 העליון, הנקראת \u0003עדות\u0004. שמע ישראל, כמו שכתוב, שמעו שמים. וכתוב, האזינו השמים. שפירושם שיהיו עדים, אף כאן \u0003שמע ישראל\u0004, מורה על מוחין דעדות. והכל הוא ענין אחד."],[3,"הויה. רישא דכלא וכו':","אחר שביאר שמע ישראל, הוא ממשיך ומבאר כל המלים שבשמע ישראל. \u0003הויה\u0004, היינו ראש הכל שבהארת עתיקא קדישא, שהוא \u0003חכמה\u0004, וזה הוא שנקרא \u0003אב\u0004. דהיינו אבא. \u0003אלקינו\u0004, הוא עמקות הנחלים והמבועים שמשם יוצאים ונמשכים לכל, דהיינו \u0003בינה\u0004 שזו\"ן וכל התחתונים מקבלים ממנה, שנקראת אמא. \u0003הויה\u0004 הב', הוא גוף האילן, דהיינו \u0003ז\"א\u0004, שהוא שלמות השרשים, משום שהוא קו האמצעי הכולל חכמה ובינה, שהם הויה אלקינו. \u0003אחד\u0004, הוא כנסת ישראל, דהיינו \u0003המלכות\u0004. והכל, כל הספירות הנ\"ל, הם שלמות אחת, ונקשרים זה בזה, ולא נמצא ביניהם פרוד, אלא הכל אחד."],[4,"תני ר' יצחק וכו':","ר\"י למד, מרכבה הקדושה העליונה, שהם חו\"ב תו\"מ, הם ארבע בתים של התפלין שמניח \u0003ו'\u0004, שהיא ז\"א. כמו שלמדנו. מרכבה קדושה אחרת, שהם ת\"ת נצח הוד יסוד, הם ארבע פרשות אחרות הכלולות בבית אחד, שהם התפלין שמנחת \u0003ה'\u0004 אחרונה דהויה, שהיא מלכות. כמו שהעמדנו (לעיל אות נ\"ו)."],[5,"שמע ישראל ה' אלקינו ה' אחד:","מצוה זו היא ליחד שמו של הקב\"ה בכל יום. כי כמו שמיחדים שמו של הקב\"ה למטה, כך מתיחד שמו למעלה, ונמצא הקב\"ה יחיד למעלה ולמטה. מי שמיחד שמו של הקב\"ה, ישום לבו ורצונו ביחוד ההוא שאמרנו. דהיינו שייחד שמו למטה. ויחבר כל אבריו, דהיינו הספירות, באותו היחוד, שיהיו כולם אחד. כי כמו שמשים כל אבריו, של השם, בסוד אחד למטה, כך למעלה מחבר כל אברים העליונים באותו היחוד, שיהיו כולם אחד."],[6,"בשעתא דאתי ב\"נ וכו':","בשעה שהאדם בא ליחד שם הקב\"ה. כל צבאות השמים, כולם עומדים שורות שורות כדי להתתקן ושיתכללו כולם באותו היחוד, לעמוד בסוד אחד ביחוד אחד. כולם מתתקנים בתקונם, ע\"י יחוד הזה, כראוי. בשעה זו עומד ממונה ושמש אחד, העומד תחת רמ\"ח עולמות, שכולם נקראים אברי הגוף. ושמש הזה נקרא הלנ\"ו (הלני\"ו ל\"ג) והוא עומד ומחכה ליחוד ההוא. וזה הוא מלקט שושנים. כש\"א, וללקוט שושנים, שהם אברי הגוף."],[7,"שייפין עלאין לקיט וכו':","אברים העליונים לוקט אותם השם העליון, בסוד היחוד שמתיחד בסוד מ\"ב שמות. והוא לוקט כל אלו שושנים העליונים. ושמש זה לוקט כל אלו התחתונים, שכולם ממונים, בכלל ע\"ב שמות, ונלקטים כולם ע\"י יחוד ההוא, ונעשו כולם גוף אחד, בסוד אחד. ויחוד ההוא עולה ומיחד הכל בב' צדדים ביחוד אחד. בשעה ההיא מתלקטים כל האברים, ומתחברים בחבור אחד, שיהיו כולם בסוד אחד למעלה ולמטה, בסוד הויה אחד ושמו אחד."],[8,"וע\"ד מאריכין באחד וכו':","ועל כן מאריכים באחד בב' אותיות, ב \u0003ח'\u0004 וב \u0003ד'\u0004, ללקוט שושנים להתיחד בסוד אחד ביחוד השלם. כיון שנתיחדו כל האברים בסוד אחד דיחוד אחד, אז נקרא הכל, קרבן שלם. ועל סוד זה הכניס הקב\"ה את אדם הראשון בגן עדן, כמ\"ש, \u0003לעבדה ולשמרה\u0004, ולמדנו שאלו הם ב' קרבנות, בסוד הויה אחד ושמו אחד. שעל אלו הקרבנות כתוב, וללקוט שושנים. אלו הם האברים של ב' צדדים שהם אחד."],[9,"שושנים רזא איהו וכו':","שושנים, הוא סוד. כאשר מתחברים כל אלו האברים יחד, שיהיו כולם ביחוד אחד, בסוד הקרבן, אז מתעטר הקב\"ה בראשו בעטרה דכתם פז, שיהיה מתעטר ביקרו. וזה הוא הסוד, שכתוב שושנים, שהם סוד כל אלו האברים שלמעלה ושלמטה, וסוד פז ההוא, שהוא עטרה המתעטרת ועולה מביניהם. והכל הוא בהם. בשושנים."]],[[0,"","לְמִי הֵם אַרְבַּע אֵלֶּה, שֶׁהֵם גּוּף אֶחָד, וְעַל זֶה כְּלוּלִים בְּאֶחָד, וּמִי הֵם? תִּפְאֶרֶת נֵצַח הוֹד יְסוֹד. וְהִיא הֵ\"א שֶׁל יָדְכָה, וְכֻלָּם אֲחוּזִים בָּהּ בִּשְׁבִיל לְהִתְבָּרֵךְ מֵהֶם, וּכְלוּלָה מִכֻּלָּם."],[1,"","אָמַר רַבִּי חִיָּיא, אִם כָּךְ, הֲרֵי כָּתוּב [שמות לג] וְרָאִיתָ אֶת אֲחֹרָי, וְשָׁנִינוּ, זֶה קֶשֶׁר שֶׁל תְּפִלִּין. אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ, וְיָפֶה הוּא, וְהַכֹּל בֵּרוּר הַדָּבָר. וְעַל זֶה מִזֶּה תְּלוּיָה רְצוּעָה אַחַת לְמַטָּה, שֶׁהֲרֵי מִמֶּנָּה תְּלוּיִים הַתַּחְתּוֹנִים וְנִזּוֹנִים מִמֶּנָּה. וְעַל זֶה נִקְרָא אוֹת, כְּמוֹ שֶׁנֶּאֱמַר [בראשית ט] זֹּאת אוֹת הַבְּרִית. וְכָתוּב וְהָיָה לְאוֹת עַל יָדְכָה, בְּהֵ\"א, וַהֲרֵי פֵּרְשׁוּהָ."],[2,"","שְׁמַע יִשְׂרָאֵל. אָמַר רַבִּי יֵיסָא, יִשְׂרָאֵל סָבָא. רַבִּי יִצְחָק אָמַר, ע' גְּדוֹלָה, לִכְלֹל שִׁבְעִים שֵׁמוֹת, עֵדוּת הַכֹּל שְׁמַע יִשְׂרָאֵל, כְּמוֹ שֶׁכָּתוּב [ישעיה א] שִׁמְעוּ שָׁמַיִם. וְכָתוּב [דברים לב] הַאֲזִינוּ הַשָּׁמַיִם. גַּם כָּאן שְׁמַע יִשְׂרָאֵל. וְהַכֹּל דָּבָר אֶחָד הוּא. יְהֹוָ\"ה – רֹאשׁ הַכֹּל בְּאוֹר הָעַתִּיק הַקָּדוֹשׁ, וְזֶהוּ שֶׁנִּקְרָא אָ\"ב. אֱלֹהֵינוּ – עֹמֶק הַנְּחָלִים וְהַמַּבּוּעִים שֶׁיּוֹצְאִים וְשׁוֹפְעִים לַכֹּל."],[3,"","יְהֹוָ\"ה – גּוּף הָאִילָן, שְׁלֵמוּת הַשָּׁרָשִׁים. אֶחָד – כְּנֶסֶת יִשְׂרָאֵל. וְהַכֹּל שְׁלֵמוּת אַחַת, וְנִקְשָׁר זֶה בָּזֶה, וְלֹא נִמְצָא פֵרוּד, אֶלָּא הַכֹּל אֶחָד."],[4,"","שָׁנָה רַבִּי יִצְחָק, מֶרְכָּבָה קְדוֹשָׁה עֶלְיוֹנָה, אַרְבָּעָה בָּתֵּי תְפִלִּין שֶׁמֵּנִיחַ ו', כְּמוֹ שֶׁנֶּאֱמַר. מֶרְכָּבָה קְדוֹשָׁה אַחֶרֶת, אַרְבָּעָה אֲחֵרִים שֶׁכְּלוּלִים בְּאֶחָד, שֶׁמֵּנִיחַ ה' הָאַחֲרוֹנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[5,"","שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד. מִצְוָה זוֹ לְיַחֵד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם, שֶׁהֲרֵי כְּמוֹ שֶׁמְּיַחֲדִים שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, כָּךְ מִתְיַחֵד שְׁמוֹ לְמַעְלָה. נִמְצָא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָחִיד מַעְלָה וּמַטָּה. מִי שֶׁמְּיַחֵד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, יָשִׂים לִבּוֹ וּרְצוֹנוֹ בְּאוֹתוֹ יִחוּד שֶׁאָמַרְנוּ, וִיחַבֵּר כָּל אֵיבָרָיו בְּאוֹתוֹ יִחוּד לִהְיוֹת כֻּלָּם אֶחָד. כְּמוֹ שֶׁשָּׂם כָּל אֵיבָרָיו בְּסוֹד אֶחָד, כָּךְ לְמַעְלָה מְחַבֵּר כָּל הָאֵיבָרִים הָעֶלְיוֹנִים בְּאוֹתוֹ יִחוּד לִהְיוֹת כֻּלָּם אֶחָד."],[6,"","בְּשָׁעָה שֶׁבָּא אָדָם לְיַחֵד אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל חֵילוֹת הַשָּׁמַיִם עוֹמְדִים שׁוּרוֹת שׁוּרוֹת כְּדֵי לְהִתְתַּקֵּן וּלְהִכָּלֵל כֻּלָּם בְּאוֹתוֹ יִחוּד, לַעֲמֹד בְּסוֹד אֶחָד בְּיִחוּד אֶחָד. כֻּלָּם מִתְתַּקְּנִים בְּתִקּוּנֵיהֶם כָּרָאוּי. בְּאוֹתָהּ שָׁעָה עוֹמֵד מְמֻנֶּה אֶחָד שַׁמָּשׁ שֶׁעוֹמֵד תַּחַת מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה עוֹלָמוֹת, וְכֻלָּם נִקְרָאִים אֵיבְרֵי הַגּוּף. וְזֶה נִקְרָא הלני\"ו, עוֹמֵד וּמְחַכֶּה לְאוֹתוֹ יִחוּד, וְזֶהוּ מְלַקֵּט שׁוֹשַׁנִּים, כְּמוֹ שֶׁנֶּאֱמַר [שיר השירים ו] וְלִלְקֹט שׁוֹשַׁנִּים, שֶׁהֵם אֵיבְרֵי הַגּוּף."],[7,"","הָאֵיבָרִים הָעֶלְיוֹנִים לוֹקֵט אוֹתָם הַשֵּׁם הָעֶלְיוֹן בְּסוֹד הַיִּחוּד שֶׁהִתְיַחֵד בְּסוֹד אַרְבָּעִים וּשְׁנַיִם שֵׁמוֹת, וְלוֹקֵט כָּל אוֹתָם שׁוֹשַׁנִּים עֶלְיוֹנִים, וְשַׁמָּשׁ זֶה לוֹקֵט כָּל אוֹתָם הַתַּחְתּוֹנִים, שֶׁכֻּלָּם מְמֻנִּים בַּכְּלָל שֶׁל שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וְנִלְקָטִים כֻּלָּם בְּאוֹתוֹ הַיִּחוּד, וְנַעֲשִׂים כֻּלָּם גּוּף אֶחָד בְּסוֹד אֶחָד. וְאוֹתוֹ הַיִּחוּד עוֹלֶה, וּמְיַחֵד הַכֹּל בִּשְׁנֵי צְדָדִים בְּיִחוּד אֶחָד. בְּאוֹתָהּ שָׁעָה מִתְלַקְּטִים כָּל הָאֵיבָרִים וּמִתְחַבְּרִים בְּחִבּוּר אֶחָד, לִהְיוֹת כֻּלָּם בְּסוֹד אֶחָד, לְמַעְלָה וּלְמַטָּה, בְּסוֹד שֶׁל ה' אֶחָד וּשְׁמוֹ אֶחָד."],[8,"","וְעַל כֵּן מַאֲרִיכִים בְּאֶחָד בִּשְׁתֵּי אוֹתִיּוֹת, לִלְקֹט שׁוֹשַׁנִּים, לְהִתְיַחֵד בְּסוֹד שֶׁל אֶחָד בְּיִחוּד שָׁלֵם. כֵּיוָן שֶׁכָּל הָאֵיבָרִים מִתְיַחֲדִים בְּסוֹד אֶחָד שֶׁל יִחוּד אֶחָד, אָז נִקְרָא הַכֹּל קָרְבָּן שָׁלֵם, וְעַל סוֹד זֶה הִכְנִיס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן לְגַן עֵדֶן, כְּמוֹ שֶׁכָּתוּב [בראשית ב] לְעָבְדָהּ וּלְשָׁמְרָהּ. וְשָׁנִינוּ שֶׁאֵלֶּה אוֹתָם קָרְבָּנוֹת שְׁנַיִם, סוֹד שֶׁל ה' אֶחָד וּשְׁמוֹ אֶחָד. שֶׁבְּאֵלּוּ קָרְבָּנוֹת כָּתוּב וְלִלְקֹט שׁוֹשַׁנִּים. [שהקדוש ברוך הוא הוא לוקט שושנים, לוקט כל אותם איברים שלמעלה ומטה לחבר אותם ביחוד באותו שאמרנו. אז מתעורר מי שמתעורר ללקט שושנים] אֵלּוּ הָאֵיבָרִים שֶׁל שְׁנֵי צְדָדִים שֶׁהֵם אֶחָד."],[9,"","שׁוֹשַׁנִּים, סוֹד הוּא. שֶׁכְּשֶׁמִּתְחַבְּרִים כָּל [אותם] אֵיבָרִים כְּאֶחָד, לִהְיוֹת כֻּלָּם בְּיִחוּד אֶחָד, סוֹד הַקָּרְבָּן, אָז מִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בַּעֲטָרָה בָּרֹאשׁ שֶׁל כֶּתֶם פָּז, לִהְיוֹת בִּכְבוֹדוֹ מִתְעַטֵּר. וְסוֹד זֶה הָיָה, שֶׁכָּתוּב שׁוֹשַׁנִּים, סוֹד שֶׁל כָּל אוֹתָם אֵיבָרִים שֶׁלְּמַעְלָה וּלְמַטָּה. וְסוֹד שֶׁל אוֹתוֹ פָּז, עִטּוּר שֶׁמִּתְעַטֵּר וְעוֹלֶה מִבֵּינֵיהֶם, וְהַכֹּל נִמְצָא בּוֹ."]]],[["בְּהָנֵי שׁוֹשַׁנִּים אִית בָּהּ שִׁית מְאָה וּתְלֵיסָר פִּקּוּדִין, דְּאִינּוּן שַׁיְיפִין דִּתְרֵין סִטְרִין, רָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד. וְאִית בֵּיהּ סְלִיקוּ דְּהַהוּא פָּז, דְּקָא סָלִיק מִבֵּינַיְיהוּ. וּבְכָל אֲתָר דְּאִינּוּן מִשְׁתַּכְּחִין, הַהוּא סְלִיקוּ עִלָּאָה אִשְׁתְּכַח מִבֵּינַיְיהוּ לְאִסְתַּלְּקָא. וְרָזָא דָּא (שיר השירים ב׳:ג׳) תַּפּוּחַ בַּעֲצֵּי הַיַּעַר. וְשׁוֹשַׁנָּה בֵּין הַחוֹחִים. דָּא וְדָא אִצְּטְרִיךְ לְאִסְתַּלְּקָא כַּחֲדָא בְּיִחוּדָא שְׁלִים. זַכָּאָה אִיהוּ מַאן דְּקָרִיב קָרְבְּנִין אִלֵּין, וַדַּאי לְרַעֲוָא לֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.","פִּקּוּדָא לְיִרְאָה (ה) בְּאֹרַח כְּלָל, וּבְאֹרַח פְּרָט. וְהָא יִרְאָה אוֹקִימְנָא, בְּגִין דְּאִית עָלֵיהּ דְּבַּר נָשׁ לְדַחֲלָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא תָּדִיר. כְּמָה דְאַתְּ אָמֵר, (דברים כ״ח:נ״ח) לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא הַזֶּה אֵת יְיָ' אֱלֹהֶיךָ. וּבְגִין יִרְאָה דָּא, יִסְתָּמָר בְּאָרְחוֹי. וְיִרְאָה, אֲתָר הוּא דְּאִקְרֵי יִרְאָה, בְּגִין דְּתַמָּן שַׁרְיָא דַּחֲלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ יִרְאַת יְיָ' לְדַחֲלָא מִנֵּיהּ, וְדָא אִיהוּ רָזָא דִּכְתִּיב, וּמִמִּקְדָּשִׁי תִּירָאוּ בְּהַאי יִרְאָה שַׁרְיָא פּוּלְסָא דְּנוּרָא, לְאַלְקָאָה לוֹן לְחַיָּיבַיָּא, דְּלָא נַטְרִין פִּקּוּדֵי אוֹרַיְיתָא וְעַל דָּא בְּאֹרַח כְּלַל, אִית לְדַחֲלָא.","וּבָתַר בְּאֹרַח פְּרָט, כַּד יָדַע בַּר נָשׁ מַאן אִיהִי יִרְאַת יְיָ', וְדָא אִיהוּ דַּחֲלָא דַּחֲבִיבוּתָא, דְּאִיהִי עִיקָר וִיסוֹדָא לְמִרְחַם לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. (בתר) הַאי יִרְאָה עָבִיד לְנַטְרָא כָּל פִּקּוּדוֹי דְּאוֹרַיְיתָא, לְמֶהֱוִי בַּר נָשׁ עֶבֶד נֶאֱמָן לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּדְּקָא יָאוּת. (יראה)","פִּקּוּדָא (ו) לְאַהֲבָה, וְהָא אוֹקִימְנָא רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּבָעֵי בַּר נָשׁ לְרַחֲמָא לֵיהּ רְחִימוּ סַגֵּי כְּאַבְרָהָם, דְּרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה רְחִימוּ, וּמָסַר גּוּפֵיהּ וְנַפְשֵׁיהּ לְגַבֵּיהּ. מִכָּאן אוֹלִיפְנָא, מַאן דְּרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ מְקַיֵּים עֶשֶׂר אֲמִירָן עֵילָּא וְתַתָּא. וְעַל דָּא כָּל אִינּוּן עֶשֶׂר נִסְיוֹנֵי דְּאִתְנַסָּא אַבְרָהָם, וְקָאִים בְּכֻלְּהוּ לָקֳבֵל עֶשֶׂר אֲמִירָן, כָּל נִסְיוֹנָא אֲמִירָא הִיא, וְאִתְנָסָּא בְּהַהוּא אֲמִירָא, וְקָאִים בֵּיהּ.","וְעַל דָּא אִינּוּן עֶשֶׂר נִסְיוֹנֵי, וְכֻלְּהוּ קָאִים בְּהוּ אַבְרָהָם, בְּגִין דְּאִתְקְשַּׁר וְאִתְדַּבָּק בִּימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהִי אַהֲבָה רַבָּה. מַאי טַעְמָא אִיקְרֵי אַהֲבָה רַבָּה. בְּגִין מַאן דְּקָאִים בְּהַאי אַהֲבָה, אִתְקְשַּׁר בְּעָלְמָא עִלָּאָה. אַהֲבַת עוֹלָם, דָּא רָזָא דְּעָלְמָא תַּתָּאָה, דְּאִתְקְשַׁר בֵּיהּ רְחִימוּ דִּילֵיהּ, וְכֹלָּא רָזָא חֲדָא, בְּלָא פִּרוּדָא, וְהָא אִתְּמַר רָזָא דְּאַהֲבָה, רְחִימוּ דָּא סָלִיק עַל כָּל פּוּלְחָנִין דְּעָלְמָא, בְּהַאי אִתְיְיקַר שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא יַתִּיר מִכֹּלָּא, וְאִתְבְּרַךְ. בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמִין, וְרָזָא דְּאַהֲבָה אִתְּמַר. ע\"כ (קע\"ב ע\"ב ציצית וכו')","פִּקּוּדָא (ז) לְמִקְרֵי קְרִיאַת שְׁמַע ב' זִמְנִין בְּכָל יוֹמָא. חַד, לָקֳבֵל דַּרְגָּא דִּימָמָא. וְחַד, לָקֳבֵל דַּרְגָּא דְּלֵילְיָא. וּלְאַכְלְלָא בִּימָמָא דַּרְגָּא דְּלֵילְיָא, וּלְאַכְלְלָא בְּלֵילְיָא דַּרְגָּא דִּימָמָא, וְהָא אִתְּמַר. וְעַל דָּא תְּרֵין זִמְנִין בְּכָל יוֹמָא, חַד בִּימָמָא וְחַד בְּלֵילְיָא.","פִּקּוּדָא לְמִקְבַּע בַּר נָשׁ מְזוּזָה לְתַרְעֵיהּ, לְמֶהֱוִי כָּל בַּר נָשׁ נָטִיר מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, כַּד נָפִיק וְכַד עָיִּיל. וְרָזָא (תהילים קכ״א:ח׳) יְיָ' יִשְׁמָר צֵּאתְךָ וּבֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. בְּגִין דְּרָזָא דִּמְזוּזָה אִיהוּ קָאִים תָּדִיר לְפִתְחָא. וְדָא אִיהוּ פִּתְחָא דִּלְעֵילָּא, וְדָא אִיהוּ דַּרְגָּא דְּאִקְרֵי שׁוֹמֵר, לְאִשְׁתַּכְּחָא בִּנְטִירוּ.","דְּבַּר נָשׁ לָאו אִיהוּ נָטִיר, בַּר נְטִירוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ נָטִיר תָּדִיר, וְקָאִים לְפִתְחָא, וּבַּר נָשׁ לְגוֹ. וְתוּ, דְּלָא יִנְשֵׁי בַּר נָשׁ דּוּכְרָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. וְדָא אִיהוּ כְּגַוְונָא דְּצִּיצִּית, כְּמָה דְאַתְּ אָמֵר (במדבר ט״ו:ל״ט) וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם אֶת וְגוֹ'. כֵּיוָן דְּחָמֵי בַּר נָשׁ לְהַאי דּוּכְרָנָא, אִדְכַּר בְּגַרְמֵיהּ לְמֶעְבַּד פִּקּוּדָא דְּמָארֵיהּ. וְרָזָא דִּמְהֵימְנוּתָא, מְזוּזָה כְּלָלָא דְּכַר וְנוּקְבָּא כַּחֲדָא.","בְּסִפְרָא דִּשְׁלֹמֹה, סָמִיךְ לְפִתְחָא, לָקֳבֵל תְּרֵין דַּרְגִּין, אִזְדְּמַן חַד שִׁידָא (ודא איהו) וְאִית לֵיהּ רְשׁוּ לְחַבְּלָא. וְאִיהוּ קָאִים לִסְטַר שְׂמָאלָא. זָקִיף בַּר נָשׁ עֵינוֹי, חָמֵי לֵיהּ לְרָזָא דִּשְׁמָא דְּמָארֵיהּ, וְאִדְכַּר לֵיהּ, וְלָא יָכִיל לֵיהּ לְאַבְאָשָׁא. וְאִי תֵּימָא, אִי הָכִי כִּי נָפִיק בַּר נָשׁ מִתַּרְעֵיהּ לְבַר, הָא הַהוּא שִׁידָא קָאִים לִימִינֵיהּ, וּמְזוּזָה לִשְׂמָאלֵיהּ, וְהֵיאַךְ אִתְנְטִיר בַּר נָשׁ, אִי אִיהוּ שָׁארֵי לִשְׂמָאלֵיהּ.","אֶלָּא כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא, כָּל מִלָּה וּמִלָּה אִתְמְשַׁךְ בָּתַר זִינֵיהּ. בְּבַר נָשׁ קַיְימִין תְּרֵין דַּרְגִּין, חַד מִימִינָא, וְחַד מִשְּׂמָאלָא. הַהוּא דִּימִינָא אִקְרֵי יֵצֶּר הַטוֹב, וְהַהוּא דִּשְׂמָאלָא אִקְרֵי יִצֶּר הָרָע. כֵּיוָן דְּנָפַק בַּר נָשׁ מִתַּרְעָא דְּבֵיתֵיהּ, הַהוּא שִׁידָא זָקִיף עֵינוֹי, וְחָמֵי לְיִצֶּר הָרָע, דְּשָׁארִי לִשְׂמָאלָא, אִתְמְשַׁךְ לְהַהוּא סִטְרָא וְאִתְעָדֵי מִימִינָא. וּבְהַהוּא סִטְרָא, קָאִים שְׁמָא דְּמָארֵיהּ, וְלָא יָכִיל לְקָרְבָא וּלְאַבְאָשָׁא לֵיהּ, וְנָפִיק בַּר נָשׁ וְאִשְׁתְּזִיב מִנֵּיהּ. כַּד עָיִּיל, הָא שְׁמָא קַדִּישָׁא לִימִינָא קָאִים, וְלָא יָכִיל לְקַטְרְגָא בַּהֲדֵיהּ."],[[0,"בהני שושנים אית וכו':","בשושנים אלו, יש בהם תרי\"ג מצות, שהם האברים של ב' הצדדים, בסוד הויה אחד ושמו אחד, ויש בהם העליה של הפז ההוא העולה מביניהם. ובכל מקום שהם נמצאים, דהיינו יחוד האברים של ב' הצדדים, עליה ההיא העליונה, דעטרת פז, נמצאת עולה מביניהם. וזה סוד תפוח בעצי היער, ושושנה בין החוחים, שזה וזה צריך לעלות כאחד ביחוד השלם. אשרי הוא מי שמקריב אלו הקרבנות, דהיינו שמיחד אלו היחודים, שהוא ודאי לרצון לו בעולם הזה ובעולם הבא."],[0,"","ביאור המאמר. כי יש בשמע ישראל, שש מלים הרומזות על שש ספירות חג\"ת נה\"י דז\"א, שצריכים ליחד אותן שיהיו אחד. וכיון שז\"א נחלק על החזה, שמחזה ולמעלה נחשב לבחינתו עצמו, ומחזה ולמטה נחשב לבחינת המלכות, ע\"כ יש ליחד ב' יחודים, יחוד אחד לחג\"ת דז\"א שמחזה ולמעלה, שהם ז\"א עצמו, ויחוד אחד לנה\"י דז\"א שמחזה ולמטה שהם בחינת המלכות. והטעם שמחזה ולמטה שייך למלכות, הוא, כי ז\"א ה\"ס קו האמצעי אשר במסך דחירק שבו ממעט ג\"ר דשמאל, ומיחדו עם הימין. ומסך הזה הוא כח הדין (כמ\"ש לעיל לך דף י\"ג ד\"ה ונתבאר) והוא עומד בנקודת החזה של ז\"א. ולפיכך מחזה ולמטה שכבר שולט שם הדין כבר נסתיים בחינת ז\"א, ונחשב למלכות, ולפיכך נחלק ז\"א על החזה."],[0,"","וסוד היחוד, הוא בעיקר. לקשר וליחד ימין ושמאל שיהיו אחד, שעי\"ז נקשרים כל שש הספירות להיות אחד. כי אע\"פ שהמסך דחירק עומד בקביעות בחזה דז\"א, כנ\"ל, עכ\"ז אין יחוד ימין ושמאל אצלו בקביעות, מב' טעמים שהם אחד, א) מפני שעונות התחתונים הולכים ומגבירים כח השמאל ומפרידים אותו מן הימין, שעי\"ז נמצא מתבטל קשר הכרעת קו אמצעי שבמסך דחירק. ב) שאין המסך דחירק מיחד ימין ושמאל אלא אם כן, שנעשה עליו זווג אור עליון על המסך שממשיך קומת החסדים. ואז אברהם מהאי סטרא דהיינו החסדים דקו ימין, ויעקב מהאי סטרא דהיינו החסדים דקו האמצעי מכניעים הדינים דיצחק, שה\"ס קו שמאל ומתיחד עם הימין, (כנ\"ל אמור אות ר' ע\"ש). אמנם בסבת עונות התחתונים, דהיינו בזמן הגלות, נפסק הזווג דחסדים מן המסך דחירק, ואינו נוהג אלא בזמן העלאת מ\"ן ע\"י התפלה ומע\"ט, ואח\"כ נפסק. וכיון שנפסק אור החסדים חוזר ומתגבר השמאל ונפרד מן הימין. ולפיכך צריכים בכל יום לחזור ולהעלות מ\"ן לעורר המסך דחירק שיהיה ראוי להכניע השמאל וליחדו עם הימין. וזה שאנו עושים בקריאת שמע. שמעוררים המסך דחירק שבקו אמצעי, וממשיכים עליו הארת החסדים, אשר אז הוא מיחד קו ימין וקו שמאל שיכללו זה בזה ויהיו כמו קו אחד. שבזה נקשרים כל ג' הקוין ומתלכדים להיות אור אחד, שאינו מאיר אלא ביחודם ביחד, כי קו ימין בלי שמאל, נחשב כחסר ג\"ר מטעם כי יציאת ה \u0003י'\u0004 מן האויר נעשה רק בקו שמאל (עי' בראשית א' דף ט\"ו ד\"ה ההוא). וע\"כ אין הימין יכול להאיר בשלמותו אלא ע\"י התכללותו לאחד עם קו השמאל. וקו השמאל בלי ימין אינו יכול להאיר כלום, כי אין החכמה יכולה להאיר משהו אלא בהתכללות בחסדים דימין. הרי שאין קו השמאל יכול להאיר אלא אחר שנעשה אחד עם הימין. אמנם אין השמאל ראוי להתחבר עם הימין רק בכח מסך דחירק שבקו אמצעי, נמצא שהן קו ימין והן קו שמאל, אינם יכולים להאיר זולת כשמתחברים עם קו האמצעי להיות אחד. הרי שהקשר דימין ושמאל הנעשה ע\"י מסך דחירק מקשר ועושה כל ג' הקוין לאור אחד ממש. שבהתחלש אחד מהם מתבטלים כולם. ולפיכך נקרא זה בשם \u0003יחוד\u0004."],[0,"","אמנם יש ביחוד הזה ב' אפנים, אפן א) הוא, שכל ג' הקוין מתיחדים לאחד תחת שליטת אור החסדים, והארת החכמה מתכסה באור החסדים. ויחוד הזה נוהג בז\"א, דהיינו יחוד ג' קוין שמחזה ולמעלה הנקראים חג\"ת, עד החזה, ששם מסתיים ז\"א כנ\"ל. אפן ב) הוא, שכל ג' הקוין מתיחדים לאחד תחת הארת החכמה בחסדים, ויחוד הזה נוהג במלכות, דהיינו בג' קוין שמחזה דז\"א ולמטה, הנקראים נצח הוד יסוד, שהם נחשבים לבחינת המלכות להיותם מתחת המסך דחזה, כנ\"ל. ונמצא שיש לעורר את המסך דקו אמצעי שיעשה ב' יחודים, שהם יחוד העליון דז\"א, שהוא יחוד דחג\"ת, ויחוד התחתון דנה\"י. שהוא דמלכות. וגם אלו ב' יהודים מתקשרים זה בזה, כי יחוד העליון ממשיך חסדים בשביל יחוד התחתון. ויחוד התחתון ממשיך הארת חכמה בשביל יחוד העליון, ולפיכך מתקשרים ג\"כ חג\"ת עם נה\"י להיות לאור אחד. וז\"ס יחוד של קריאת שמע שיש בו שש מלים כנגד ב' יחודים האלו, חג\"ת, נה\"י, שצריכים ליחד מקודם ב' יחודים אלו כל אחד במקומו, ואח\"כ לקשר החג\"ת עם הנה\"י כנ\"ל, עד שנעשו כולם אור אחד ממש. וזה נבחן שמיחדים שש ספירות דז\"א, ועושים אותן לגוף אחד. ונמצא שעיקר היחוד אינו אלא קשר ימין ושמאל שיהיו אחד, אלא כיון שקו האמצעי הוא הפועל, הוא מתחבר ג\"כ עמהם, ויש ע\"כ ימין ושמאל אמצע, וכיון שיש הפרש בין ג' קוין שלמעלה מחזה לג' קוין שלמטה מחזה, צריכים ליחד את הימין והשמאל בב' מקומות, נמצא שהיחוד הוא לבסוף בשש ספירות."],[0,"","וזה אמרו (באות סא) \u0003דהא כמה דמייחדי שמא דקב\"ה לתתא\u0004, דהיינו למטה מחזה בג' קוין נה\"י, \u0003הכי אתייחד שמיה לעילא\u0004, דהיינו למעלה מחזה בג' קוין חג\"ת, \u0003אשתכח קב\"ה יחידאי עילא ותתא\u0004, שקב\"ה שה\"ס ז\"א, נמצא שהוא אור אחד, למעלה בחג\"ת, ולמטה בנה\"י. כלומר שכל שש הספירות חג\"ת נה\"י הן אחד, כמו שבארנו, שז\"ס יחוד שש המלים שבקריאת שמע, שה\"ס שש הספירות דז\"א, שיהיו אחד, ע\"י העלאת מ\"ן לעורר המסך דקו האמצעי, כמו שבארנו. וז\"ש \u0003מאן דמייחד\u0004 וכו' \u0003בההוא יחודא דקאמרן\u0004, דהיינו בב' מקומות מחזה ולמעלה ומחזה ולמטה, \u0003ויחבר כל שייפוי\u0004, דהיינו כל שש הספירות, \u0003בההוא יחודא, למהוי כלהו אחד.\u0004 דהיינו שיאירו כולם כאור אחד, כנ\"ל שכל קו צריך לחבירו וג' קוין שלמעלה מחזה צריכים לג' קוין שלמטה מחזה, באפן שהם כולם שלמות אחת, ובהתחלש אחד מהם מתבטל כל האור. \u0003כמה דשוי כל שייפוי ברזא דחד\u0004, כמו שאדם התחתון מעלה מ\"ן ומיחד כל הספירות בסוד אחד ע\"ד שבארנו, \u0003הכי לעילא מחבר כל שייפין עלאין בההוא יחודא למהוי כלהו חד\u0004, כך נעשה למעלה ביחוד הזה, שמתקשרים כל שש הספירות להיות אור אחד."],[0,"","וזה אמרו (באות סב) \u0003בשעתא דאתי ב\"נ ליחדא שמא דקב\"ה\u0004, דהיינו בקריאת שמע, \u0003כל חילי שמיא כלהו קיימין שורין שורין\u0004, דהיינו שהמלאכים מסתדרים תחת ג' קוין, כל אחד בקו שלו, \u0003בגין לאתתקנא ולאתכללא כלהו בההוא יחודא\u0004, כדי שיקבלו הקשר דמסך דקו האמצעי מיחוד העליון, שנעשה בחג\"ת נה\"י דז\"'א, בקריאת שמע, \u0003למיקם ברזא דחד\u0004, שגם הימין והשמאל שבהם, וחג\"ת נה\"י שבהם, יתקשרו להיות אור אחד, כמו בז\"א, \u0003כלהו מתתקנן בתקוניהון כדקא יאות\u0004 וכולם מתתקנים כמו שביארנו בחג\"ת נה\"י דז\"א. כי כל מה שנעשה למעלה בז\"א, נמשך לכל העולמות."],[0,"","ויש לדעת שכל המסכים והדינים שמתבארים באצילות, אין פעולתם ניכרת כלל בעולם אצילות עצמו, אלא כל מה שנרשם שם, הוא להפעיל כך בעולמות התחתונים. וגם אותו המסך דחירק העומד בחזה דז\"א. מראה פעולתו רק למטה בעולם היצירה, שהוא בבחינת ז\"א, ששם עומדים המלאכים, שעל כל בחינה ובחינה שאנו מבחינים בז\"א דאצילות, יש שם מלאך ממונה מיוחד. ואותו מסך דקו אמצעי העומד בחזה דאצילות, נמשך כחו בחזה דעולם דיצירה, והממונה עליו שם, נקרא \u0003הלנ\"ו\u0004, וטעם השם הזה, כי אותו מסך דחירק שהוא נושא, כמו שבשעת היחוד, כל התקונים וכל האורות יוצאים ע\"י פעולתו שמיחד ימין ושמאל זה בזה, הנה שלא בשעת היחוד, כל הדינים נמשכים ממנו והוא הממעט כל המדרגות לו\"ק בלי ראש, ובמקומות החסרון שנעשה מחמת המיעוט שלו נאחזים הקליפות. ואין הפירוש שהוא משתנה, אלא בשעה שנעשה גורם ליציאת כל האורות דקדושה, הרי הרע שבו נהפך לטוב, ובשעה שאינו גורם ליציאות האורות דקדושה, ניכר הרע והדינים שבו. ולפיכך, כל הרואה אותו ממונה הנושא את מסך דחירק שבחזה דיצירה, שואל, \u0003הלנו\u0004 אתה או לצרינו. כי מטעם שעומד במקום הקדושה, מסתבר שאלינו הוא דהיינו שעוזר אל הקדושה. אבל מתוך הדינים והמיעוטים שממעט כל מדרגות הקדושה מג'\"ר, מסתבר שהוא לצרינו, שהוא אויב הקדושה ועוזר לסטרא אחרא. אמנם בשעת יחוד העליון, שעל ידו מתיחד הימין ושמאל. וחג\"ת נה\"י, וכל המוחין מתגלים יודעים הכל שהוא לנו, ולא לצרינו. וע\"כ נקרא המלאך בשם \u0003הלנו\u0004."],[0,"","וז\"ש (באות ס\"ב) \u0003בהאיי שעתא\u0004, דהיינו קודם היחוד דקריאת שמע, \u0003קיימא חד ממנא שמשא\u0004, דהיינו הממונה על מסך דקו אמצעי שבמקום החזה דיצירה, \u0003דקיימא תחות רמ\"ח עלמין, וכלהו אקרון שייפין דגופא\u0004 דהיינו שנקראים רמ\"ח אברי הגוף, שהם מתחלקים לפי ג' קוין, שאותו הממונה מקשר כל אלו אברים בכח המסך דחירק, ועושה אותם לגוף אחד, ע\"ד שנתבאר בחג\"ת נה\"י דז\"א. \u0003ודא אקרי הלנו\u0004 (כצ\"ל) שממונה הזה נקרא \u0003הלנו\u0004, מטעם שמטיל ספק, אם הוא \u0003הלנו\u0004 או לצרינו כנ\"ל. והוא, \u0003קיימא מחכה לההוא יחודא\u0004, דהיינו ליחוד בקריאת שמע, שיתיחדו חג\"ת נה\"י דז\"א כנ\"ל, שמשם מקבל גם הוא כח ליחד כל האברים לגוף אחד. \u0003ודא איהו מלקט שושנים\u0004, שהמסך דחירק מלקט כל האברים המפולגים לימין ושמאל כמו מלקט שושנים ועושה אותם לגוף אחד. \u0003כד\"א וללקוט שושנים, דאינון שייפין דגופא\u0004, שלוקט אברי הגוף ומיחד אותם, כמבואר."],[0,"","ונודע שיש ב' שמות, שם מ\"ב, ושם ע\"ב. והם כנגד ב' יחודים הנ\"ל, כי שם \u0003מ\"ב\u0004 מורה על יחוד העליון שמחזה ולמעלה, שמבחי' התכללות חג\"ת נה\"י אלו באלו, נבחן שיש חג\"ת נה\"י בחג\"ת למעלה מחזה, ויש חג\"ת נה\"י בנה\"י למטה מחזה. וכיון שיחוד העליון הוא בחסדים מכוסים מחכמה, ע\"כ הוא נבחן שאין בכל ספירה שבו\"ק שלמעלה מחזה רק שבע ספירות. ושש פעמים שבע הם בגי' מ\"ב. ושם \u0003ע\"ב\u0004, מורה על יחוד התחתון שמחזה ולמטה, שהם נה\"י, ומטעם התכללות יש גם שם חג\"ת נה\"י. וכיון שיחוד התחתון מגלה הארת חכמה, ע\"כ יש בו סוד י\"'ב פנים בכל ספירה, שהם חו\"ב תו\"מ שבכל אחד ג' קוין' ושש פעמים י\"ב הם ע\"ב. ומחזה ולמעלה דעולם היצירה מקבל מהארת השם מ\"ב, שהוא חסדים מכוסים. ומחזה ולמטה דעולם היצירה מקבל מהארת השם ע\"ב, שיש בו הארת חכמה, ואין הפירוש שהשמות בעצמם מאירים שם, כי הם מאירים רק בעולם אצילות, אלא כל עולם ועולם מקבל מהם כפי יכלתו. וז\"ש, (באות ס\"ג) \u0003שייפין עלאין\u0004, שהם האברים שלמעלה מחזה דיצירה, \u0003לקיט\u0004 \u0003לון שמא עלאה ברזא דיחודא דקא אתייחד ברזא דמ\"ב\u0004, שעל אברים העליונים, שולט השם מ\"ב שהוא שליטת החסדים. \u0003ולקיט כל אינון שושנים עלאין\u0004, דהיינו אברים שלמעלה מחזה דיצירה. \u0003ושמשא דא לקיט כל אינון תתאין\u0004, ושמש הזה, לוקט כל אלו האברים התחתונים דהיינו אותם שמחזה ולמטה, \u0003די כלהו ממנן\u0004, שכולם הם ממונים, שכל אבר הוא ממונה מיוחד כנ\"ל, \u0003בכללא דע\"ב שמהן\u0004, כי מחזה ולמטה מקבל מהארת ע\"ב. כנ\"ל. \u0003ואתלקיטו כלהו בההוא יחודא\u0004, ונלקטו כולם, הן אותם שלמעלה מחזה, והן אותם שלמטה מחזה, \u0003ואתעבידו כלהו גופא חדא, ברזא חדא.\u0004 כמבואר."],[0,"","וז\"ש \u0003וההוא יחודא סלקא\u0004, היינו היחוד של שמע ישראל. \u0003וקא מייחד כלא בתרין סטרין ביחודא חדא\u0004, שהוא מיחד בכל העולמות ב' הצדדים שבהם, שהם קו ימין וקו שמאל ביחוד אחד. שזהו עיקר היחוד (כנ\"ל דף כ\"א ד\"ה אמנם יש) \u0003בההיא שעתא\u0004, שנעשה היחוד דימין ושמאל ע\"י מסד דחזה, מתלקטים כל האברים, הן למעלה מחזה והן למטה מהזה, \u0003ומתחברן בחבורא חדא למהוי כלהו ברזא דחד\u0004 שחג\"ת נה\"י מתיחדים ג\"כ להיות בסוד אחד, כמו שביארנו (שם) \u0003עילא ותתא\u0004, למעלה מחזה ולמטה מחזה, \u0003ברזא דהויה אחד ושמו אחד\u0004. כי למעלה מחזה דז\"א ה\"ס \u0003הויה אחד\u0004, כי ז\"א נקרא הויה. ומחזה דז\"א ולמטה, כבר שייך למלכות, כנ\"ל, הנקראת \u0003שם\u0004, וה\"ס \u0003ושמו אחד\u0004."],[0,"","וז\"ש (באות ס\"ד) \u0003וע\"ד מאריכין באחד בתרי אתוון\u0004, דהיינו ב \u0003ח'\u0004 וב \u0003ד'\u0004, שמאריכים ב \u0003ד'\u0004, ובלבד שלא יחטוף ב \u0003ח'\u0004 (ברכות י\"ג:) כי \u0003ח'\u0004 רומזת על ז\"א שה\"ס הויה אחד. וה \u0003ד'\u0004 רומזת על המלכות שה\"ס ושמו אחד. וז\"ש, \u0003למלקט\u0004 וכו' \u0003ביחודא שלים\u0004, שזהו יחוד השלם, \u0003כיון דאתייחדן שייפין כלהו ברזא חדא\u0004 וכו' \u0003אתקרי כלא קרבן שלים.\u0004 קרבן פירושו יחוד, דהיינו יחוד השלם. וז\"ש, \u0003ועל רזא דא\u0004 וכו' \u0003לעבדה ולשמרה, ותנינן דאלין אינון קרבנין תרין, רזא דהויה אחד ושמו אחד\u0004, כי לעבדה ה\"ס יחוד העליון, ולשמרה ה\"ס יחוד התחתון, שב' יחודים אלו, ה\"ס הויה אחד ושמו אחד. \u0003דאינון קרבנין כתיב וללקוט שושנים\u0004, שעל ב' הקרבנות האלו, נאמר וללקוט שושנים. \u0003אלין שייפין דב' סטרין, דאינון חד\u0004 שהם אברים של ב' בחינות, כי האברים שמחזה ולמעלה הם בחינת חסדים, והאברים שמחזה ולמטה הם בחינת הארת חכמה, וב' בחינות אלו מתיחדות להיות אור אחד. (כנ\"ל דף כ\"א ד\"ה אמנם יש)."],[0,"","וזה אמרו (באות ס\"ה) \u0003שושנים, רזא איהו, דכד מתחברן כל אינון שייפין\u0004 וכו' \u0003כדין מתעטר קב\"ה בעטרה ברישא, דכתם פז.\u0004 מתי נקראים האברים שושנים, היינו בשעה שמתחברים האברים שלמעלה מחזה עם האברים שלמטה מחזה, שאז נכלל ז\"א, מחכמה שבמלכות, ומקבל מזה עטרה דכתם פז, שה\"ס הארת החכמה. ואז נקראים האברים כולם שושנים. פירוש. כי השם שושנה הוא שם המלכות, שיחוד שלה הוא למטה מחזה. אלא אחר שז\"א שלמעלה מחזה, נכלל עם למטה מחזה ביחד, נקראים גם האברים שלמעלה מחזה על שם המלכות דהיינו שושנים. וז\"ש \u0003ורזא דא\u0004 וכו'. כמבואר. וז\"ש, \u0003בהני שושנים אית בה תרי\"ג פקודין, דאינון שייפין דתרין סטרין\u0004, כי בתרי\"ג מצות יש ימין ושמאל, שהם רמ\"ח לימין ושס\"ה לשמאל. והם \u0003רזא דהויה אחד ושמו אחד\u0004, שרמ\"ח מצות עשה ה\"ס הויה אחד, ושס\"ה ל\"ת ה\"ס ושמו אחד. וז\"ש, \u0003ובכל אתר דאינון משתכחין\u0004, דהיינו שנמצאים חג\"ת נה\"י נכללים זה בזה, \u0003ההוא סליקו עלאה אשתכח מבינייהו לאסתלקא\u0004, דהיינו העליה דכתם פז, שעטרה זו ז\"א מקבל מחמת היחוד דחג\"ת נה\"י זה בזה."],[0,"","וז\"ש, \u0003ורזא דא תפוח בעצי היער\u0004, שה\"ס יחוד העליון, הויה אחד, \u0003ושושנה בין החוחים\u0004, שה\"ס יחוד התחתון של מטה מחזה, שהיא המלכות הנקראת שושנה כנ\"ל. \u0003ודא ודא אצטריך לאסתלקא כחדא ביחודא שלים\u0004, שיחוד התחתון צריך לכלול כאחד ביחוד העליון ויחוד העליון בתחתון, אז הוא יחוד השלם."],[1,"פקודא ליראה בארח וכו':","מצוה, ליראה את הקב\"ה בדרך כלל ובדרך פרט. ומפרש, והרי יראה, העמדנו, שפירושו, משום שיש לאדם להתירא מפני הקב\"ה תמיד. כש\"א, ליראה את השם הנכבד והנורא הזה את ה' אלקיך. ומשום יראה זו ישמור את דרכיו. ויראה, היא מקום שנקרא יראה, דהיינו מלכות, משום ששם שורה יראת הקב\"ה, היא נקראת יראת הויה, שצריכים לירא מפניו, וזה הוא סוד שכתוב וממקדשי תיראו. כי ביראה זו, שהיא המלכות, שורה שבט של אש להכות את הרשעים שאינם שומרים מצות התורה, כי העונשים באים ממלכות, וע\"כ יש לפחד \u0003בדרך כלל\u0004. דהיינו יראת העונש."],[2,"ובתר בארח פרט וכו':","ואחר כך יש לפחד מפניו \u0003בדרף פרט\u0004, דהיינו כשאדם יודע מה היא יראת ה', דהיינו כשמשיג מדת המלכות עצמה, שזו היא יראה מחמת אהבה, שהיא העיקר והיסוד לאהוב את הקב\"ה. יראה זו עושה שישמור כל מצות התורה, שהאדם יהיה עבד נאמן להקב\"ה, כראוי."],[3,"פקודא לאהבה וכו':","מצוה, לאהבה. והרי העמדנו, שאהבת הקב\"ה פירושו, שהאדם צריך לאהוב אותו אהבה רבה כאברהם, שאהב את הקב\"ה באהבה רבה, ומסר גופו ונפשו אליו. מכאן למדנו, מי שאוהב את הקב\"ה הוא מקיים עשרה מאמרות דהיינו עשר ספירות, למעלה ולמטה. וע\"כ כל אלו עשרה נסיונות שנתנסה בהם אברהם, ועמד בכולם, הם כנגד עשרה מאמרות, כי כל נסיון הוא מאמר אחד, דהיינו ספירה אחת, שנתנסה במאמר ההוא ועמד בו."],[4,"וע\"ד אינון עשר וכו':","וע\"כ הם עשרה נסיונות, כנגד ע\"ס, ובכולם עמד אברהם, משום שנקשר ונתדבק בימינו של הקב\"ה שנקרא \u0003אהבה רבה\u0004, דהיינו חסד דז\"א. מה הטעם שנקרא אהבה רבה. הוא, משום שמי שעומד באהבה זו נקשר בעולם העליון, שהוא ז\"א. \u0003אהבת עולם\u0004 הוא סוד עולם התחתון, דהיינו מלכות. שאהבת הקב\"ה נקשרת בה. והכל, אהבה רבה ואהבת עולם, הוא סוד אחד בלי פרוד ביניהם. והנה למדנו, סוד האהבה, שהאהבה עולה על כל עבודות שבעולם, באהבה, מתייקר שמו של הקב\"ה יותר מכל, ומתברך. ברוך הוא לעולם ולעולמי עולמים. ונתבאר סוד האהבה."],[5,"פקודא למקרי קריאת וכו':","מצוה, לקרוא קריאת שמע ב' פעמים בכל יום, אחת, כנגד מדרגת היום, שהוא ז\"א. ואחת, כנגד מדרגת הלילה, שהיא המלכות. לכלול ביום מדרגת לילה. ולכלול בלילה מדרגת יום. וכבר למדנו. וע\"כ צריכים ב' פעמים בכל יום, א' ביום וא' בלילה."],[6,"פקודא למקבע ב\"נ וכו':","מצוה, שהאדם יקבע מזוזה לפתחו, שיהיה כל אדם נשמר ע\"י הקב\"ה כשיוצא מן הבית וכשיבא אל הבית. וזה סוד, ה' ישמר צאתך ובואך מעתה ועד עולם. כי סוד המזוזה הוא נמצא תמיד על הפתח. וזה הוא הפתח של מעלה, שהוא המלכות, שהיא פתח לז\"א, בסוד, זה השער לה'. וזה הוא מדרגה שנקרא שומר, להמצא בשמירה."],[7,"דב\"נ לאו איהו וכו':","כי האדם אינו שומר, חוץ משמירה של הקב\"ה, שהוא שומר תמיד, ונמצא בפתח הבית, והאדם בפנים הבית. ועוד, טעם למזוזה, כדי שלא ישכח האדם זכרון הקב\"ה לעולם. וטעם זה הוא, כמו ציצית, כש\"א, וראיתם אותו וזכרתם את וגו'. כיון שהאדם רואה זכרון ההוא, נזכר בעצמו לעשות מצות אדונו. וסוד האמונה, היא שמזוזה כוללת דכר ונוקבא יחד."],[8,"בספרא דשלמה וכו':","בספרו של שלמה כתוב, סמוך לפתח, כנגד ב' מדרגות, מזדמן שד אחד, שיש לו רשות להזיק. והוא עומד בצד שמאל של הפתח. נושא אדם את עיניו ורואה סוד השם של אדונו, שבמזוזה, שבימין הפתח ונזכר בו, אין השד יכול להזיק. ואם תאמר, אם כן, זה נכון כשהאדם בא אל הבית, אבל כשיוצא מן פתח הבית לחוץ, הרי השד, שנמצא בצד שמאל של הפתח, עומד אז לימינו של האדם, והמזוזה בשמאלו, ואיך נשמר האדם אם המזוזה שורה לשמאלו."],[9,"אלא כל מה וכו':","ומשיב, אלא כל מה שעשה הקב\"ה כל דבר ודבר הולך אחר מינו. באדם נמצאים ב' מדרגות, אחת מימינו ואחת משמאלו, אותה שבימין נקראת יצר הטוב, ואותה שבשמאל נקראת יצר הרע. כיון שיוצא האדם מפתח ביתו, אותו השד נושא עיניו, ורואה את יצר הרע כשהוא שורה לשמאל, הוא נמשך לאותו הצד שהיצר הרע נמצא, דהיינו לשמאל, והוסר מימין, ואז באותו צד שמאל עומד אז השם של אדונו, דהיינו המזוזה. ואינו יכול לקרב אליו להזיק לו. והאדם יוצא וניצל ממנו. וכשנכנס אל הבית, נמצא השם הקדוש שבמזוזה, עומד לימינו, ועי\"ז שולט הימין על השמאל. ואינו יכול לקטרג עליו."]],[[0,"","בַּשּׁוֹשַׁנִּים הַלָּלוּ יֵשׁ שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה מִצְווֹת, שֶׁהֵם אֵיבָרִים שֶׁל שְׁנֵי צְדָדִים, סוֹד שֶׁל יְהֹוָ\"ה אֶחָד וּשְׁמוֹ אֶחָד. וְיֵשׁ בּוֹ עֲלִיָּה שֶׁל אוֹתוֹ פָּז שֶׁעוֹלֶה מִבֵּינֵיהֶם. וּבְכָל מָקוֹם שֶׁהֵם נִמְצָאִים, אוֹתָהּ עֲלִיָּה עֶלְיוֹנָה נִמְצֵאת מִבֵּינֵיהֶם לַעֲלוֹת. וְסוֹד זֶה [שיר השירים ב] תַּפּוּחַ בַּעֲצֵי הַיַּעַר, וְשׁוֹשַׁנָּה בֵּין הַחוֹחִים. זֶה וָזֶה צְרִיכִים לַעֲלוֹת כְּאֶחָד בְּיִחוּד שָׁלֵם. אַשְׁרֵי מִי שֶׁמַּקְרִיב קָרְבָּנוֹת אֵלּוּ, וַדַּאי לְרָצוֹן לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","מִצְוָה לְיִרְאָה [ה] בְּדֶרֶךְ כְּלָל וּבְדֶרֶךְ פְּרָט. וַהֲרֵי יִרְאָה בֵּאַרְנוּ, מִשּׁוּם שֶׁיֵּשׁ עַל הָאָדָם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר [דברים כח] לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא הַזֶּה אֵת ה' אֱלֹהֶיךְ. וּבִשְׁבִיל יִרְאָה זוֹ יִשָּׁמֵר בִּדְרָכָיו. וְיִרְאָה, מָקוֹם הוּא שֶׁנִּקְרָא יִרְאָה, מִשּׁוּם שֶׁשָּׁם נִמְצֵאת יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא, הִיא יִרְאַת ה' לִירָא מִמֶּנּוּ, וְזֶהוּ סוֹד הַכָּתוּב [ויקרא יט] וּמִקְדָּשִׁי תִּירָאוּ. בַּיִּרְאָה הַזּוֹ שְׁרוּיָה מַכַּת אֵשׁ, לְהַלְקוֹת אֶת הָרְשָׁעִים שֶׁלֹּא שׁוֹמְרִים מִצְווֹת הַתּוֹרָה, וְעַל זֶה בְּדֶרֶךְ כְּלָל יֵשׁ לִירָא."],[2,"","וְאַחַר כָּךְ בְּדֶרֶךְ פְּרָט, כְּשֶׁיּוֹדֵעַ הָאָדָם מַהִי יִרְאַת ה', וְזוֹהִי יִרְאָה שֶׁל חֲבִיבוּת, שֶׁהִיא עִקָּר וִיסוֹד לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. [אחר] יִרְאָה זוֹ עוֹשֶׂה כְּדֵי לִשְׁמֹר כָּל מִצְווֹת הַתּוֹרָה, לִהְיוֹת אָדָם עֶבֶד נֶאֱמָן לַקָּדוֹשׁ־בָּרוּךְ־הוּא כָּרָאוּי. [יראה]"],[3,"","מִצְוָה [ו] לְאַהֲבָה, וַהֲרֵי בֵּאַרְנוּ אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁצָּרִיךְ הָאָדָם לֶאֱהֹב אוֹתוֹ אַהֲבָה רַבָּה כְּמוֹ אַבְרָהָם שֶׁאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה אֲהָבוֹת וּמָסַר אֵלָיו גּוּפוֹ וְנַפְשׁוֹ. מִכָּאן לָמַדְנוּ, מִי שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מְקַיֵּם עֶשֶׂר אֲמִירוֹת מַעְלָה וּמַטָּה. וְעַל זֶה כָּל אוֹתָם עֲשָׂרָה נִסְיוֹנוֹת שֶׁהִתְנַסָּה אַבְרָהָם וְעָמַד בְּכֻלָּם, כְּנֶגֶד עֶשֶׂר אֲמִירוֹת, כָּל נִסָּיוֹן הִיא אֲמִירָה, וְהִתְנַסָּה בְּאוֹתָהּ אֲמִירָה וְעָמַד בָּהּ."],[4,"","וְעַל זֶה אוֹתָם עֲשָׂרָה נִסְיוֹנוֹת, וּבְכֻלָּם עָמַד אַבְרָהָם, מִשּׁוּם שֶׁהִתְקַשֵּׁר וְנִדְבַּק בִּימִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִיא אַהֲבָה רַבָּה. מָה הַטַּעַם נִקְרֵאת אַהֲבָה רַבָּה? מִשּׁוּם מִי שֶׁעוֹמֵד בָּאַהֲבָה הַזּוֹ, מִתְקַשֵּׁר בָּעוֹלָם הָעֶלְיוֹן. אַהֲבַת עוֹלָם, זֶה סוֹד הָעוֹלָם הַתַּחְתּוֹן, שֶׁהִתְקַשְּׁרָה בּוֹ אַהֲבָתוֹ, וְהַכֹּל סוֹד אֶחָד בְּלִי פֵרוּד. וַהֲרֵי נִתְבָּאֵר סוֹד הָאַהֲבָה, אַהֲבָה זוֹ עוֹלָה עַל כָּל עֲבוֹדוֹת הָעוֹלָם, בָּזֶה נִכְבָּד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מֵהַכֹּל וּמִתְבָּרֵךְ. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, וְסוֹד הָאַהֲבָה נִתְבָּאֵר."],[5,"","מִצְוָה [ז] לִקְרֹא קְרִיאַת שְׁמַע פַּעֲמַיִם בְּכָל יוֹם, אַחַת כְּנֶגֶד דַּרְגַּת יוֹם, וְאַחַת כְּנֶגֶד דַּרְגַּת לַיְלָה, לְהַכְלִיל בַּיּוֹם דַּרְגַּת הַלַּיְלָה, וּלְהַכְלִיל בַּלַּיְלָה דַּרְגַּת יוֹם, וַהֲרֵי נִתְבָּאֵר. וְעַל זֶה פַּעֲמַיִם בְּכָל יוֹם, אֶחָד בַּיּוֹם וְאֶחָד בַּלַּיְלָה."],[6,"","מִצְוָה שֶׁיִּקְבַּע אָדָם מְזוּזָה לְשַׁעֲרוֹ, לִהְיוֹת כָּל אָדָם שָׁמוּר מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁיּוֹצֵא וּכְשֶׁנִּכְנָס. וְהַסּוֹד – [תהלים קכא] ה' יִשְׁמָר צֵאתְךְ וּבֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. מִשּׁוּם שֶׁסּוֹד הַמְּזוּזָה עוֹמֵד תָּמִיד לַפֶּתַח, וְזֶהוּ פֶּתַח שֶׁלְּמַעְלָה, וְזוֹהִי דַרְגָּה שֶׁנִּקְרֵאת שׁוֹמֵר, לְהִמָּצֵא בִשְׁמִירָה."],[7,"","שֶׁאָדָם אֵינוֹ שָׁמוּר, רַק מִשְּׁמִירַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא תָּמִיד שׁוֹמֵר, וְעוֹמֵד לַפֶּתַח, וְהָאָדָם בִּפְנִים. וְעוֹד, שֶׁלֹּא יִשְׁכַּח אָדָם זִכְרוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. וְזֶהוּ כְּמוֹ הַצִּיצִית, כְּמוֹ שֶׁנֶּאֱמַר [במדבר טו] וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת וְגוֹ'. כֵּיוָן שֶׁרוֹאֶה הָאָדָם אֶת הַזִּכָּרוֹן הַזֶּה, נִזְכָּר בְּעַצְמוֹ לַעֲשׂוֹת מִצְוַת רִבּוֹנוֹ. וְסוֹד הָאֱמוּנָה, מְזוּזָה כְּלָל שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד."],[8,"","בְּסִפְרוֹ שֶׁל שְׁלֹמֹה, סָמוּךְ לַפֶּתַח, כְּנֶגֶד שְׁתֵּי דְרָגוֹת, מִזְדַּמֵּן שֵׁד אֶחָד [וזהו] וְיֵשׁ לוֹ רְשׁוּת לְחַבֵּל, וְהוּא עוֹמֵד לְצַד שְׂמֹאל. מֵרִים הָאָדָם אֶת עֵינָיו, וְרוֹאֶה אֶת סוֹד שֵׁם רִבּוֹנוֹ, וְנִזְכָּר בּוֹ, וְלֹא יָכוֹל לְהָרַע לוֹ. וְאִם תֹּאמַר, אִם כָּךְ, כְּשֶׁהָאָדָם יוֹצֵא מֵהַשַּׁעַר הַחוּצָה הֲרֵי אוֹתוֹ שֵׁד עוֹמֵד לִימִינוֹ, וּמְזוּזָה לִשְׂמֹאלוֹ, וְאֵיךְ נִשְׁמָר הָאָדָם כְּשֶׁהוּא שׁוֹרֶה לִשְׂמֹאלוֹ?"],[9,"","אֶלָּא כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל דָּבָר וְדָבָר נִמְשָׁךְ אַחַר מִינוֹ. בָּאָדָם יֵשׁ שְׁתֵּי דְרָגוֹת, אַחַת מִיָּמִין וְאַחַת מִשְּׂמֹאל. אוֹתוֹ שֶׁמִּיָּמִין נִקְרָא יֵצֶר הַטּוֹב, וְאוֹתוֹ שֶׁל הַשְּׂמֹאל נִקְרָא יֵצֶר הָרָע. כֵּיוָן שֶׁיָּצָא אָדָם מִשַּׁעַר בֵּיתוֹ, אוֹתוֹ שֵׁד מֵרִים עֵינָיו, וְרוֹאֶה אֶת הַיֵּצֶר הָרָע שֶׁשּׁוֹרֶה לִשְׂמֹאל, נִמְשָׁךְ לְאוֹתוֹ צַד וְזָז מִיָּמִין. וּבְאוֹתוֹ צַד עוֹמֵד שֵׁם שֶׁל רִבּוֹנוֹ, וְלֹא יָכוֹל לְהִתְקָרֵב וּלְהָרַע לוֹ, וְיוֹצֵא הָאָדָם וְנִצּוֹל מִמֶּנּוּ. כְּשֶׁנִּכְנָס, הֲרֵי הַשֵּׁם הַקָּדוֹשׁ עוֹמֵד לְיָמִין וְלֹא יָכוֹל לְקַטְרֵג עִמּוֹ."]]],[["וְעַל דָּא אִצְּטְרִיךְ בַּר נָשׁ, דְּלָא יַעְבִּיד (ס\"א יעביר) טִנּוּפָא וְלִכְלוּכָא בְּתַרְעָא דְּבֵיתֵיהּ, וְלָא יוֹשִׁיד מַיִין עֲכוּרִין. חַד, דְּלָא יַעְבִּיד קְלָנָא לְגַבֵּי שְׁמָא דְּמָארֵיהּ. וְחַד, דְּאִית לֵיהּ רְשׁוּ לְהַהוּא מְחַבְּלָא לְחַבְּלָא. וּבְּגִין כָּךְ יִזְדַּהֵר בַּר נָשׁ מֵהַאי, וְיִזְדְּהַר בַּר נָשׁ דְּלָא יִמְנַע מִתַּרְעָא דְּבֵיתֵיהּ שְׁמָא דְּמָארֵיהּ.","וְכַד בַּר נָשׁ אַתְקִין מְזוּזָה לְפִתְחֵיהּ, כַּד עָיִּיל (ס\"א ההוא בר נש), הַהוּא יִצֶּר הָרָע וְהַהוּא שִׁידָא בַּעַל כָּרְחַיְּיהוּ נַטְרֵי לֵיהּ, וְאַמְרֵי (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ' צַּדִּיקִים יָבֹאוּ בוֹ. וְכַד לָא קָאִים מְזוּזָה לְפִתְחֵיהּ דְּבַּר נָשׁ, יִצֶּר הָרָע וְהַהוּא שִׁידָא מִתְתַּקְנִין כַּחֲדָא, שַׁוּוּ יְדַיְיהוּ עַל רֵישֵׁיהּ בְּזִמְנָא דְּעָיִּיל, פַּתְחֵי וְאַמְרֵי, וַוי לֵיהּ לִפְלַנְיָּא, דְּהָא נָפַק מֵרְשׁוּתָא דְּמָארֵיהּ, מֵהַהוּא זִמְנָא קָאִים בְּלָא נְטִירוּ, דְּלֵית מַאן דְּנָטִיר עָלֵיהּ, רַחֲמָנָא לִישֵׁזְבָן (צ\"א ע\"ב פקודאי לאומאה וכו').","(דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, דָּא אִיהוּ יִחוּדָא חַד. בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, הָא יִחוּדָא אַחֲרָא, לְמֶהֱוִי שְׁמֵיהּ רָזָא חַד. וְרָזָא דָּא, (מלכים א יח) יְיָ' הוּא הָאֱלֹהִים, דָּא כְּתִיב, כַּד אִינּוּן בְּיִחוּדָא חַד.","וְאִי תֵּימָא, אִי הָכִי כְּגַוְונָא דִּכְתִּיב, (זכריה יד) יְיָ' אֶחָד וּשְׁמוֹ אֶחָד, (נדפס בתרומה קע\"א ע\"ב) לָאו אִיהוּ יְיָ' הוּא הָאֱלֹהִים, דְּאִי כְּתִיב יְיָ' וּשְׁמוֹ הוּא אֶחָד, הֲוִינָא אַמְרֵי הָכִי, לָא כְּתִיב אֶלָּא יְיָ' אֶחָד וּשְׁמוֹ אֶחָד, וְאִצְּטְרִיךְ לוֹמַר בְּגַוְונָא דָּא, יְיָ' הוּא הָאֱלֹהִים הוּא, וְיִתְחֲזֵי יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.","אֶלָּא כֹּלָּא חַד, דְּכַד אִתְאַחֲדָן תְּרֵין שְׁמָהָן אִלֵּין, דָּא בְּיִחוּדָא חַד, וְדָא בְּיִחוּדָא חַד, כְּדֵין תְּרֵין שְׁמָהָן אִלֵּין אִתְעָבִידוּ חַד, וְאִתְכְּלִילָן דָּא בְּדָא, וַהֲוִי כֹּלָּא שְׁמָא שְׁלִים בְּיִחוּדָא חֲדָא, וּכְדֵין יְיָ' הוּא הָאֱלֹהִים, דְּהָא כְּדֵין אִתְכְּלִיל כֹּלָּא דָּא בְּדָא לְמֶהֱוִי חַד, וְעַד דְּאִתְיַיחֲדוּ כָּל חַד דָּא בִּלְחוֹדוֹי וְדָא בִּלְחוֹדוֹי, לָא אִתְכְּלִילוּ דָּא בְּדָא, לְמֶהֱוִי כֹּלָּא חַד.","כְּלָלָא דְּכָל אוֹרַיְיתָא, הָכִי הוּא וַדַּאי, דְּהָא אוֹרַיְיתָא אִיהִי תּוֹרָה שֶׁבִּכְתָּב, וְאִיהִי תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָּב, דָּא הוּא דִּכְתִּיב יְיָ'. תּוֹרָה שֶׁבְּעַל פֶּה, דִּכְתִּיב הָאֱלֹהִים. וּבְגִין דְּאוֹרַיְיתָא אִיהִי רָזָא דִּשְׁמָא קַדִּישָׁא, אִקְרֵי הָכִי.","תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, דָּא כְּלָל, וְדָא פְּרָט. כְּלַל אִצְּטְרִיךְ לִפְרָט, וּפְרָט אִצְּטְרִיךְ לִכְּלָל, וְאִתְיַיחֲדוּ דָּא בְּדָא, וַהֲוִי כֹּלָּא חַד. וְעַל דָּא כְּלָלָא דְּאוֹרַיְיתָא, אִיהוּ כְּלָלָא דִּלְעֵילָּא וְתַתָּא, בְּגִין דִּשְׁמָא דָּא לְעֵילָּא, וּשְׁמָא דָּא לְתַתָּא. דָּא רָזָא דְּעָלְמָא עִלָּאָה. וְדָא רָזָא דְּעָלְמָא תַּתָּאָה. וְעַל דָּא כְּתִיב אַתָּה הָרְאֵתָ לָדַעַת כִּי יְיָ' הוּא הָאֱלֹהִים, דָּא כְּלָלָא דְּכֹלָּא, וְכָל דָּא דְּאַמָרָן, אִצְּטְרִיךְ בַּר נָשׁ לְמִנְדַּע בְּהַאי עָלְמָא.","וְאִי תֵּימָא, פִּקּוּדֵי אוֹרַיְיתָא אָן אִינּוּן הָכָא, בִּכְלָלָא דָּא. אֶלָּא דָּא אִיהוּ זָכוֹר. וְדָא אִיהוּ שָׁמוֹר. וְכָל פִּקּוּדֵי אוֹרַיְיתָא בְּהָנֵי כְּלִילָן, בְּרָזָא דְּזָכוֹר, וּבְרָזָא דְּשָׁמוֹר, וְכֹלָּא אִיהוּ חַד.","פָּתַח רִבִּי יוֹסִי וְאָמַר, הָא דְּתָנֵינָן צְּלוֹתָא דְּעַרְבִית חוֹבָה אִיהוּ, וַדַּאי בְּגִין דִּקְרִיאַת שְׁמַע דְּעַרְבִית חוֹבָה, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְיָיחָד בְּלֵילְיָא, כְּמָה דְּאִתְיָיחַד בִּימָמָא. וּמִדַּת לַיְלָה אִתְכְּלִיל בִּימָמָא, וּמִדַּת יְמָמָא אִתְכְּלִיל בְּלֵילְיָא, וְאִתְעָבִיד יִחוּדָא. וּמַאן דְּאָמַר רְשׁוּת, בְּגִין אֵימוּרִין וּפְדָרִין דְּמִתְעַכְּלֵי בְּלֵילְיָא. וְהָא אוֹקִימְנָא.","דִּכְתִּיב וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ, הַאי קְרָא אוֹקִימְנָא, וְאוֹקְמוּהָ חַבְרַיָּיא. אֲבָל אִית לְשָׁאֲלָא, אִי בְּהַאי יִחוּדָא דִּשְׁמַע יִשְׂרָאֵל, אִתְכְּלִיל כֹּלָּא, יְמִינָא וּשְׂמָאלָא, אֲמַאי כְּתִיב לְבָתַר וְאָהַבְתָּ, וְהָיָה אִם שָׁמוֹעַ, דְּהָא בְּיִחוּדָא אִתְכְּלִילוּ. אֶלָּא הָתָם בִּכְלָל. הָכָא בִּפְרָט. וְהָכִי אִצְּטְרִיךְ.","וּבְרָזָא דְּיִחוּדָא דְּהָא אִתְּעַרְנָא בֵּיהּ, יִחוּדָא אִיהוּ כְּגַוְונָא דִּתְפִלִּין דְּרֵישָׁא, וּתְפִילִּין דִּדְרוֹעָא, בִּתְפִילִין דְּרֵישָׁא ד' פַּרְשִׁיָּין, וְהָא אִתְּמַר. וְהָכָא ג' שְׁמָהָן אִינּוּן. הָתָם אַרְבַּע פַּרְשִׁיָּין, וְכָל חַד וְחַד בִּלְחוֹדוֹי. וְהָכָא ג' שְׁמָהָן, מַה בֵּין הַאי לְהַאי."],[[0,"וע\"ד אצטריך ב\"נ וכו':","וע\"כ צריך האדם להזהר, שלא יעשה טנוף ולכלוך בשער ביתו ולא ישפוך שם מים עכורים, מב' טעמים, א'. שלא יעשה בזיון אצל שם אדונו, שבמזוזה. וא'. שאז יש רשות לאותו המחבל, דהיינו השד, לחבל. ומשום זה יזהר האדם בזה, ויזהר האדם, שלא ידחה מפתח ביתו את השם של אדונו."],[1,"וכד בר נש וכו':","וכשהאדם מתקן מזוזה לפתחו, כשאותו האדם נכנס לביתו, יצר הרע ההוא והשד ההוא שומרים אותו בעל כרחם, ואומרים זה השער לה' צדיקים יבואו בו. וכשלא נמצאת מזוזה לפתחו של אדם, היצר הרע ואותו השד, מתחזקים ומתתקנים יחד, ומניחים ידיהם על ראשו בזמן שנכנס, ופותחים ואומרים, אוי לו לפלוני שיצא מרשות אדונו. מאותו זמן והלאה, הוא נמצא בלי שמירה, שאין מי שישמור עליו. הרחמן יצילנו."],[1,"","ביאור המאמר. היסוד הוא קו האמצעי שמבחינת למטה מחזה, שהוא המיחד ב' הקוין ימין ושמאל שלמטה מחזה. ונודע שהמלכות נבנית מקו שמאל. ומטרם שקו האמצעי ייחד הימין עם השמאל, שהמלכות קבלה משמאל בלי ימין, נעשתה המלכות בבחינת ימא דקאפו, שנקפאה בתוכו אורותיה ונסתמת (כמ\"ש לעיל ב\"א דף רמ\"ז ד\"ה ימא דקאפו) אלא אחר שבא קו האמצעי, ובכח המסך דחירק שבו ממעט השמאל ומיחדו עם הימין (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) אז נפתחת המלכות מהקפאון והסתימה שבה, והחכמה שבה מתלבשת בחסדים שבימין, והיא מאירה בכל שלימותה."],[1,"","ונתבאר לעיל (אות ס\"ו ד\"ה וסוד היחוד) כי מלבד כחות הדין שבמסך דחירק דקו האמצעי הממעט את הג\"ר דשמאל (כמ\"ש לך י\"ג ד\"ה ונתבאר) צריכים עוד לקומת חסדים שיצא על זווג אור העליון במסך דחירק, וזולת החסדים האלו אין השמאל נכנע להתיחד עם הימין, ע\"ש. באפן, שאין היסוד יכול ליחד הימין והשמאל זב\"ז, לפתוח המלכות מקפאונה, אלא א\"כ, שיש בו כחות הדין למעט הג\"ר דשמאל, ויש בו קומת חסדים המתחברים עם חסדים דימין ואז מכניע השמאל ומיחדו עם הימין. ותדע, שכחות הדין של המסך דחירק שביסוד, ה\"ס \u0003ש\"ד\u0004 דשדי. ואור החסדים שבו, ה\"ס \u0003י'\u0004 דשדי, שבב' אלה מגביל השמאל שלא יאיר אלא ממטה למעלה, ומיחדו עם הימין. והנה המלכות בכללה נקראת בשם \u0003בית\u0004, להיותה בית קבול לכל האורות העליונים, בדומה לבית גשמי, שהוא בית קבול לכל רכושו וצרכיו של האדם. ואותם הדינים והחסדים שהיסוד משפיע אל המלכות מן השם \u0003שדי\u0004 נבחן \u0003לפתח\u0004 הבית, כי זולת הדינים והחסדים האלו, היתה המלכות שה\"ס הבית, נשארת קפואה וסתומה, ועל ידיהם, היא נפתחת, ואפשר לבא אל הבית לקבל משם כל האורות. והמזוזה, ה\"ס שם \u0003שדי\u0004 הזה הפותח את המלכות. שע\"כ רשום עליה השם \u0003שד\"י\u0004."],[1,"","וזה אמרו (באות ע\"ב) \u0003בגין דרזא דמזוזה איהו קאים תדיר לפתחא\u0004, שסוד המזוזה עומד תמיד לבחינת הפתח, \u0003ודא איהו פתחא דלעילא\u0004, שהמזוזה היא הפתח של מעלה, דהיינו של המלכות (כמ\"ש להלן אות ק\"ט) כי מאלו הדינים והחסדים שבשם שדי, נעשה \u0003הפתח\u0004 במלכות, שיהיה אפשר לבא אל הבית לקבל כל האורות שיש שם. וזולת הפתח הזה, היתה המלכות הנקראת בית, קפואה וסתומה מכל צד. כנ\"ל. \u0003ודא איהו דרגא דאקרי שומר\u0004, כי הדינים שבשם שדי, שומרים האדם שלא יכשל למשוך החכמה בדרך האסור, דהיינו, ממעלה למטה, כי אז תיכף ירבצו עליו הדינים האלו. (וז\"ש באות ע\"ג) \u0003ותו, דלא ינשי בר נש דוכרנא דקב\"ה לעלמין\u0004, כי המוחין שהאדם זוכה לקבל אחר פתיחת המלכות ע\"י שם שד\"י, נקראים \u0003זכרון\u0004. ומטרם הפתיחה, בעוד שהיתה המלכות תחת קו שמאל בלי ימין, היתה נמשכת ממנה ה \u0003שכחה\u0004. ונמצא שעי\"ז שרואה את השם שדי בפתח המלכות, ניצל משכחה, וזוכה לזכרון, שה\"ס המוחין. וז\"ש \u0003כיון דחמי\u0004 וכו' \u0003אדכר בגרמיה למעבד פקודא דמאריה\u0004. שכיון שזוכה למוחין דזכרון, הוא זוכר לקיים כל מצות הש\"י. שהסו\"ה אצל הציצית, וראיתם אותו וגו'. וז\"ש, \u0003מזוזה, כללא דכר ונוקבא כחדא\u0004, כי ה\"ס השם \u0003שדי\u0004, שהוא שם של היסוד שהוא דכר. וה\"ס פתח הבית, דהיינו הפתח של המלכות שהיא נוקבא."],[1,"","והנה השם שדי, אינו מקובל אל המלכות בבת אחת, אלא מתחילה מקבלת המלכות את הדינים שבמסך, שה\"ס \u0003ש\"ד\u0004 דשדי, ואח\"כ מקבלת ה \u0003י'\u0004 דשדי, שה\"ס החסדים. ונמצא שבעת שמקבלת הדינים, עוד אינם נעשים פתח אל המלכות, כי הדינים בלבד אינם יכולים ליחד הימין והשמאל מטרם ביאת החסדים, וע\"כ נבחן אז שנתוסף עוד דינים על המלכות. כי מתחילה לא היו לה אלא דינים דשמאל, שה\"ס הקפאון, ועתה נתוספו עליה דינין דנוקבא, הממעטים הג\"ר דשמאל, ונמצא, שנגרעה עוד יותר מחמתם, כי נכפלו דיניה, ע\"כ נבחן זה לבחינת מיעוט וחלל בלבד. ולא לפתח, ובכל מקום שיש מיעוט וחסרון. יש שם מקום לאחיזת הסטרא אחרא והקליפות. אמנם כיון שהיא עומדת לקבל גם ה \u0003י'\u0004 דשדי, שאז נפתחים אורותיה על ידי הדינים והחסדים יחד, ונעשים לה פתח, ע\"כ אין הקליפות נאחזות בה, גם בבחינת החלל והחסרון מטרם שנעשו לפתח, אע\"פ שיש להם רשות."],[1,"","וז\"ש (באות ע\"ד) \u0003סמיך לפתחא\u0004, דהיינו בעת שהמלכות עוד מקבלת ש\"ד דשדי, שה\"ס הדינים דמסך, שאז עוד אינם פתח, אלא חלל וחסרון, אבל הם \u0003סמיך לפתחא\u0004, כלומר שקרובה לקבל את ה \u0003י'\u0004 דשדי, שאז נהפכים הדינים להיות פתח. \u0003לקבל תרין דרגין, אזדמן חד שידא\u0004, כי אז יש ב' מדרגות דינים בהמלכות, כי מלבד הדינים דשמאל שהיו לה מכבר נתוספו לה עוד דינים דמסך שהם דינין דנוקבא, כנ\"ל, שכנגד ב' מדרגות דינים הללו, מוכנה הקליפה להאחז בהם, שקליפה ההיא נקראת \u0003שד\u0004, משום שהיא נאחזת בדינים דש\"ד, של שדי בטרם שבאה ה \u0003י'\u0004 דשדי, כנ\"ל. \u0003ואית ליה רשו לחבלא\u0004, שיש לו רשות להזיק מכח מקום החסרון שנעשה במלכות, אבל מתוך שהוא סמוך לפתח, כלומר, שהיא קרובה להמשיך ה \u0003י'\u0004 דשדי, שאז נעשים הדינים לפתח, ע\"כ אינו מזיק אע\"פ שיש לו רשות. כנ\"ל."],[1,"","ויש להבין, למה קובעים המזוזה לימין הנכנס אל הבית, ולשמאל היוצא מן הבית. והענין הוא, כי הארת הבית, ה\"ס חכמה שבשמאל, בסוד בחכמה יבנה בית. וע\"כ הנכנס, שפירושו שעוד לא קבל המוחין שבבית, נמצא השם שדי שבמזוזה, שה\"ס הפתח, בימין. כי עודו הוא במוחין דימין, שהם חסדים. אבל היוצא מן הבית, שכבר קבל המוחין דו\"ק דחכמה שבבית, ויוצא לו משם למדרגה אחרת, הרי המוחין שלו הם ו\"ק דחכמה שבשמאל, וע\"כ השם שדי שבמזוזה הוא בשמאל. וז\"ש (באות ע\"ב) \u0003למהוי כל בר נש נטיר מעם קב\"ה כד נפיק וכד עייל\u0004 וכו'. כי היוצא מן הפתח מקבל עמו המוחין שקבל בבית, וצריך שמירה שלא ימשוך אותם ממעלה למטה, וע\"כ צריך להסתכל בסוד השם שדי שבמזוזה השומר אותו ומזכיר אותו שלא יכשל בעצת השד, שהוא מסית בני אדם למשוך המוחין ממעלה למטה. שהוא בחינת החטא דעץ הדעת, וכל שכן הנכנס אל הבית שצריך שמירה שלא ינזק בעצת השד. וז\"ש (באות ע\"ד) \u0003ואיהו קאים לסטר שמאלא\u0004, כי השד נמצא בצד שמאל של הפתח, ומוכן להסיתו להגביר השמאל על הימין, דהיינו שימשיך החכמה ממעלה למטה. ואז יוכל להזיק לו בין בדינין דדכורא שהם הדינים דשמאל, ובין בדינין דנוקבא שבמסך, להיות השד כלול מב' המדרגות כנ\"ל."],[1,"","ונודע שהדינין שבמסך דחירק דקו האמצעי, כלולים ממנעולא ומפתחא (כמ\"ש לך דף י\"ג ד\"ה ונתבאר ע\"ש) ונמצא שגם השד כלול משניהם. והמוחין דבחינת השמאל אינם מהפכים הדינים להעשות פתח, רק את הדינים דמפתחא שבמסך, אבל הדינים שבמנעולא, אינם מהפכים אלא שנגנזים (כמ\"ש שם) וא\"כ הם נשארים עוד בהשד, והוא יכול להזיק עמהם למוחין דשמאל. וזהו שמקשה הרעיא מהימנא, \u0003אי הכי כי נפיק בר נש מתרעיה לבר הא ההוא שידא קאים לימיניה\u0004, כלומר שאע\"פ שהאדם כבר קבל המוחין שבבית, שהם ו\"ק דשמאל, עוד השד נשאר בימינו, דהיינו מדינים דנוקבא דמנעולא, שהם מבחינת ימין, ומזוזה, דהיינו בחינת הפתח שנעשה ע\"י גילוי המוחין שבבית, הוא בשמאל, שאין להם פעולה כלל על הדינים דימין האלו, וא\"כ, \u0003והיאך אתנטיר בר נש אי איהו שארי לשמאליה\u0004, שהרי אין להם פעולה זה על זה. ומשיב, \u0003כיון דנפק בר נש מתרעא דביתיה\u0004, כלומר אחר שכבר קבל הארת השמאל שבבית ויוצא משם, \u0003ההוא שידא זקיף עינוי, וחמי ליצר הרע\u0004 וכו' כלומר, שגם השד נהנה מאלו המוחין דשמאל, שז\"ס \u0003וזקיף עינוי\u0004, וע\"כ הוא נמשך ליצר הרע של אדם שהוא בשמאל, שגם היצר הרע נכנע ממוחין האלו, וע\"כ \u0003אתמשך לההוא סטרא\u0004 שהשד נמשך לגמרי לצד שמאל, דהיינו להנות מהם, \u0003ואתעדי מימינא\u0004, והוסר לגמרי מדינים דימין, ואין לו עוד שום אחיזה בהם, שיוכל להזיק עמהם, אמנם עוד הוא יכול להזיקו עי\"ז שיטה אותו למשוך האור ממעלה למטה כנ\"ל, דהיינו בדינים דשמאל, אמנם \u0003ובההוא סטרא קאים שמא דמאריה\u0004, ששם שורה השם \u0003שדי\u0004, שהוא שומר שלא יבוא האדם להמשיך ממעלה למטה כנ\"ל. \u0003ולא יכיל לקרבא ולאבאשא ליה, ונפיק ב\"נ ואשתזיב מניח.\u0004 וע\"כ הוא יוצא וניצל ממנו."],[1,"","וז\"ש (באות ע\"ו) \u0003וע\"ד אצטריך ב\"נ דלא יעביד טנופא ולכלוכא בתרעא\u0004 וכו', היינו שלא ימשיך האור ממעלה למטה, שבזה ממשיך טנוף ולכלוך ומים עכורים, וז\"ש, \u0003חד דלא יעביד קלנא לגבי שמא דמאריה\u0004, כי במעשה זה הוא מבזה השם שדי, שהוא נותן הגבול שלא ימשוך ממעלה למטה, כנ\"ל. \u0003וחד, דאית ליה רשו לההוא מחבלא לחבלא\u0004, כי אז מתבטל הפתח, שנעשה בסוד השם שדי, וחוזרים הדינים דש\"ד למקומם, שבהם נאחז השד ומזיק לו. כנ\"ל."],[1,"","וז\"ש (באות ע\"ז) \u0003וכד בר נש אתקין מזוזה לפתחיה\u0004 וכו' \u0003ההוא יצר הרע וההוא שידא בעל כרחייהו נטרי ליה\u0004 וכו', כי אותם הדינים דנוקבא והדינים דדכורא, שהשד כלול מהם, הם עצמם מתהפכים לפתח, לפתוח כל אוצרות הבית, על ידי השלמת ה \u0003י'\u0004 דשדי, ושומרים אותו, שלא יתקלקל הפתח הזה, \u0003ואמרי, זה השער לה' צדיקים יבואו בו.\u0004 כי הדינים שבידיהם נהפכו ונעשו לשער אל הויה, שיוכלו לקבל כל הארותיו כנ\"ל. \u0003וכד לא קאים מזוזה לפתחיה\u0004, דהיינו שאינו ממשיך ה \u0003י'\u0004 דשדי המהפכת הדינים ד \u0003ש\"ד\u0004 לפתח. \u0003יצר הרע וההוא שידא מתתקנין כחדא\u0004, כלומר, שפועלים ביחד \u0003שוו ידייהו על רישיה\u0004, שמשימים ידיהם, דהיינו הכוחות שלהם, שהם הדינים דדכורא ודנוקבא יחד הכלולים בהשד, על ראשו, דהיינו על הנשמה שלו, \u0003מהאי זמנא קאים בלא נטירו\u0004 וכו', והקליפות עושים בו מה שרוצים."],[2,"שמע ישראל ה' אלקינו וגו':","שמע ישראל וגו' זה הוא יחוד אחד. ברוך \u0003שם\u0004 כבוד מלכותו לעולם ועד, זהו יחוד אחר, שיהיה \u0003שמו\u0004, שהוא המלכות הנקראת \u0003שם\u0004, בסוד אחד. וזה סוד, \u0003הויה הוא האלקים\u0004, ש \u0003הויה\u0004, שהוא ז\"א הוא המלכות הנק' \u0003אלקים\u0004. שזה כתוב, כשז\"א ומלכות הם ביחוד אחד. וע\"כ שמע ישראל ה\"ס \u0003הויה\u0004, ובשכמל\"ו ה\"ס הוא \u0003האלקים\u0004."],[3,"ואי תימא אי וכו':","ואם תאמר, א\"כ, הרי היחוד דשמע ובשכמל\"ו, הם כעין שכתוב, הויה אחד ושמו אחד, שאינו שוה אל ה' הוא האלקים, שאם היה כתוב הויה ושמו הוא אחד, היינו אומרים כך, ששוה אל הויה הוא האלקים, אבל לא כתוב, אלא הויה אחד ושמו אחד, וא\"כ היה צריך לומר כעין זה, הויה הוא, האלקים הוא, והיה שוה אל הויה אחד, ושמו אחד. וכיון שלא כתוב כן, אלא הויה הוא האלקים, הרי אינו דומה להויה אחד ושמו אחד. ואיך נאמר שיחוד שמע ובשכמל\"ו, שהם ב' יחודים, בדומה להויה אחד, ושמו אחד, שהוא שוה להויה הוא האלקים."],[4,"אלא כלא חד וכו':","ומשיב, אלא הכל הוא אחד שיחוד שמע ובשכמל\"ו, שה\"ס הויה אחד בשמע, ושמו אחד בבשכמל\"ו, הם אחד עם ה' הוא האלקים. כי כשמתיחדים ב' שמות אלו, הויה, שהוא ז\"א עם אלקים שהוא מלכות, זה ביחוד אחד, דהיינו ביחוד שמע ישראל וגו', וזה ביחוד אחד, דהיינו ביחוד בשכמל\"ו, אז נעשים ב' שמות אלו אחד, ונכללים זה בזה, ונעשה הכל שם אחד שלם, ביחוד אחד, ואז כתוב, הויה הוא האלקים. כי אז נכלל הכל זה בזה להיות אחד. אבל מטרם שנתיחדו כל אחד זה בפני עצמו, וזה בפני עצמו, אינם נכללים זה בזה להיות הכל אחד. באפן, שהויה אחד ושמו אחד, ודאי אינו שוה אל הויה הוא האלקים, אלא שהויה הוא האלקים הוא תוצאה מן הויה אחד ושמו אחד, כמבואר."],[5,"כללא דכל אורייתא וכו':","הכלל של כל התורה, דהיינו תושב\"כ ותושב\"פ יחד, כך הוא ודאי. כי התורה, היא תורה שבכתב, והיא תורה שבעל פה. תורה שבכתב, זה הוא שכתוב, \u0003הויה\u0004, דהיינו ז\"א. תורה שבעל פה, הוא שכתוב \u0003האלקים\u0004, שהוא המלכות. ומשום שהתורה ה\"ס השם הקדוש, ע\"כ נקראת כך, זה נקרא הויה, וזה האלקים."],[6,"תורה שבכתב ותורה וכו':","תורה שבכתב ותורה שבעל פה, זו כלל, וזו פרט, התושב\"כ היא כלל, דהיינו ז\"א, ותושב\"פ פרט, דהיינו המלכות. הכלל צריך לפרט, והפרט צריך לכלל, שאין שלימות לזה בלי זה עד שיתחברו שניהם, ומתיחדים זה בזה ונעשה הכל אחד. וע\"כ כלל כל התורה, היא כלל שלמעלה, ז\"א, ושלמטה, המלכות. משום ששם הזה הוא למעלה, ושם הזה הוא למטה. זה תושב\"כ, סוד עולם העליון, ז\"א, וזה תושב\"פ, הוא סוד עולם התחתון, מלכות. וע\"כ כתוב, אתה הראת לדעת כי \u0003הויה הוא האלקים\u0004, ששניהם אחד, וזה כלל הכל, של כל העולמות. וכל זה שאמרנו צריך האדם לדעת בעולם הזה."],[7,"ואי תימא פקודי וכו':","ואם תאמר, מצוות התורה איפה הם בכלל הזה, אם הויה הוא האלקים, הוא כלל הכל. ומשיב, אלא זה, הויה, הוא זכור, וזה האלקים, הוא שמור, וכל מצוות התורה באלו כלולות בסוד זכור ובסוד שמור. שזכור כולל רמ\"ח מ\"ע ושמור כולל שס\"ה ל\"ת. והכל הוא אחד."],[8,"פתח ר' יוסי וכו':","פר\"י ואמר, זה שלמדנו שתפלת ערבית היא חובה, הוא ודאי משום, שקריאת שמע של ערבית היא חובה, כי הקב\"ה מתיחד בלילה בסוד ק\"ש, כמו שמתיחד ביום. ומדת לילה נכללת ביום ומדת יום נכללת בלילה, ונעשה היחוד. ומי שאומר רשות, הוא מטעם התפלה שנתקנת כנגד אימורים ופדרים הנעכלים ונשרפים בלילה שהם אינם חוב. כי תפלת שחרית ומנחה הם כנגד ב' תמידים, שהם חוב, ותפלת ערבית כנגד אימורים וכו', שהם רשות. וכבר העמדנו."],[9,"דכתיב ואהבת את וגו':","כתוב, ואהבת את ה' אלקיך. מקרא זה העמדנו. והעמידוהו החברים. אבל יש לשאול, אם ביחוד הזה דשמע ישראל נכלל הכל, ימין ושמאל. כנ\"ל, למה כתוב אח\"כ ואהבת שהוא ימין, והיה אם שמוע, שהוא שמאל, הרי ביחוד קריאת שמע כבר נכללו. ומשיב, אלא שם בקריאת שמע הוא בכלל, שימין ושמאל דדעת נכללו בכלל אחד, בהויה (כנ\"ל אות ל\"ז) וכאן בפרט, שתחלה כתוב, ואהבת בפני עצמו, שהוא חסד, ואח\"כ כתוב, והיה אם שמוע בפני עצמו, שהוא גבורה. וכך צריך להיות."],[10,"וברזא דיחודא דהא וכו':","ובסוד היחוד אשר הערנו בו, היחוד דקריאת שמע הוא. כמו היחוד דתפלין של ראש ותפלין של יד. בתפלין של ראש יש ד' פרשיות, וכבר למדנו אותן, וכאן בקריאת שמע יש ג' שמות, הויה אלקינו הויה. שם ארבע פרשיות שכל אחת ואחת היא בפני עצמה, וכאן רק ג' שמות, מה ההפרש בין זה לזה."]],[[0,"","וְעַל זֶה צָרִיךְ הָאָדָם שֶׁלֹּא יַעֲשֶׂה [יעביר] טִנּוּף וְלִכְלוּךְ בְּשַׁעַר בֵּיתוֹ וְלֹא יִשְׁפֹּךְ מַיִם עֲכוּרִים. אֶחָד, שֶׁלֹּא יַעֲשֶׂה קָלוֹן לְשֵׁם רִבּוֹנוֹ. וְאֶחָד, שֶׁיֵּשׁ רְשׁוּת לְאוֹתוֹ הַמְחַבֵּל לְחַבֵּל. וְלָכֵן יִזָּהֵר הָאָדָם מִזֶּה, וְיִזָּהֵר הָאָדָם שֶׁלֹּא יִמְנַע מִשַּׁעַר בֵּיתוֹ שֵׁם רִבּוֹנוֹ."],[1,"","וּכְשֶׁאָדָם מַתְקִין מְזוּזָה לְפִתְחוֹ, כְּשֶׁנִּכְנָס [אותו האדם], אוֹתוֹ יֵצֶר הָרָע וְאוֹתוֹ שֵׁד בְּעַל כָּרְחָם שׁוֹמְרִים אוֹתוֹ, וְאוֹמְרִים [תהלים קיח] זה השער לה' צדיקים יבאו בו. וכשלא עומדת מזוזה בפתח האיש, יצר הרע ואותו שד מתתקנים כאחד, שמים ידיהם על ראשו בזמן שנכנס, פותחים ואומרים: אוי לו לפלוני שיצא מרשות רבונו! מאותו זמן הוא עומד בלי שמירה, שאין מי שישמר עליו. הרחמן יצילנו."],[2,"","שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, זֶהוּ יִחוּד אֶחָד. בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, זֶהוּ יִחוּד אַחֵר, לִהְיוֹת שְׁמוֹ סוֹד אֶחָד. וְסוֹד זֶה – ה' הוּא הָאֱלֹהִים, זֶה כָּתוּב כְּשֶׁהֵם בְּיִחוּד אֶחָד."],[3,"","וְאִם תֹּאמַר, אִם כָּךְ כְּמוֹ שֶׁכָּתוּב [זכריה יד] ה' אֶחָד וּשְׁמוֹ אֶחָד, לֹא הִיא ה' הוּא הָאֱלֹהִים. שֶׁאִם כָּתוּב ה' וּשְׁמוֹ הוּא אֶחָד, הָיִיתִי אוֹמֵר כָּךְ. לֹא כָתוּב אֶלָּא ה' אֶחָד וּשְׁמוֹ אֶחָד, וְצָרִיךְ לוֹמַר בְּגָוֶן זֶה, ה' הוּא הָאֱלֹהִים הוּא, וְיֵרָאֶה ה' אֶחָד וּשְׁמוֹ אֶחָד."],[4,"","אֶלָּא הַכֹּל אֶחָד. שֶׁכְּשֶׁמִּתְאַחֲדִים שְׁנֵי הַשֵּׁמוֹת הַלָּלוּ, זֶה בְּיִחוּד זֶה, וְזֶה בְּיִחוּד אֶחָד, אָז שְׁנֵי הַשֵּׁמוֹת הָאֵלֶּה נַעֲשִׂים אֶחָד וְנִכְלָלִים זֶה בָּזֶה, וְנִהְיָה הַכֹּל שֵׁם שָׁלֵם בְּיִחוּד אֶחָד, וְאָז ה' הוּא הָאֱלֹהִים, שֶׁהֲרֵי אָז נִכְלָל הַכֹּל זֶה בָּזֶה לִהְיוֹת אֶחָד, וְעַד שֶׁהִתְיַחֲדוּ כָּל אֶחָד, זֶה בִּלְבַדּוֹ וְזֶה בִּלְבַדּוֹ, לֹא נִכְלְלוּ זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד."],[5,"","כְּלַל כָּל הַתּוֹרָה כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי הַתּוֹרָה הִיא תּוֹרָה שֶׁבִּכְתָב, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָב זֶהוּ שֶׁכָּתוּב ה'. תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁכָּתוּב הָאֱלֹהִים. וּמִשּׁוּם שֶׁהַתּוֹרָה הִיא סוֹד הַשֵּׁם הַקָּדוֹשׁ, נִקְרֵאת כָּךְ."],[6,"","תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, זֶה כְּלָל וְזֶה פְּרָט. הַכְּלָל צָרִיךְ אֶת הַפְּרָט, וְהַפְּרָט צָרִיךְ אֶת הַכְּלָל, וְהִתְיַחֲדוּ זֶה בָּזֶה וְנִהְיָה הַכֹּל אֶחָד. וְעַל זֶה כְּלַל הַתּוֹרָה הוּא כְּלָל שֶׁלְּמַעְלָה וּמַטָּה, מִשּׁוּם שֶׁשֵּׁם זֶה לְמַעְלָה, וְשֵׁם זֶה לְמַטָּה. זֶה סוֹד הָעוֹלָם הָעֶלְיוֹן, וְזֶה סוֹד הָעוֹלָם הַתַּחְתּוֹן. וְעַל זֶה כָּתוּב אַתָּה הָרְאֵתָ לָדַעַת כִּי ה' הוּא הָאֱלֹהִים. זֶה הַכְּלָל שֶׁל הַכֹּל. וְכָל זֶה שֶׁאָמַרְנוּ צָרִיךְ אָדָם לָדַעַת בָּעוֹלָם הַזֶּה."],[7,"","וְאִם תֹּאמַר, מִצְווֹת הַתּוֹרָה אֵיפֹה הֵן כָּאן בַּכְּלָל הַזֶּה? אֶלָּא זֶהוּ זָכוֹר וְזֶהוּ שָׁמוֹר. וְכָל מִצְווֹת הַתּוֹרָה בְּאֵלֶּה כְּלוּלִים, בְּסוֹד שֶׁל זָכוֹר וּבְסוֹד שֶׁל שָׁמוֹר, וְהַכֹּל הוּא אֶחָד."],[8,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, זֶה שֶׁשָּׁנִינוּ שֶׁתְּפִלַּת עַרְבִית הִיא חוֹבָה, וַדַּאי מִשּׁוּם שֶׁקְּרִיאַת שְׁמַע שֶׁל עַרְבִית חוֹבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְיַחֵד בַּלַּיְלָה כְּמוֹ שֶׁמִּתְיַחֵד בַּיּוֹם. וּמִדַּת לַיְלָה נִכְלֶלֶת בַּיּוֹם, וּמִדַּת יוֹם נִכְלֶלֶת בַּלַּיְלָה, וְנַעֲשֶׂה יִחוּד. וּמִי שֶׁאָמַר רְשׁוּת, מִשּׁוּם אֵמוּרִים וּפְדָרִים שֶׁמִּתְעַכְּלִים בַּלַּיְלָה, וַהֲרֵי בֵּאַרְנוּ."],[9,"","שֶׁכָּתוּב וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. פָּסוּק זֶה בֵּאַרְנוּ, וּפֵרְשׁוּהוּ הַחֲבֵרִים. אֲבָל יֵשׁ לִשְׁאֹל, אִם בַּיִּחוּד הַזֶּה שֶׁל שְׁמַע יִשְׂרָאֵל נִכְלָל הַכֹּל, יָמִין וּשְׂמֹאל, לָמָּה כָּתוּב אַחַר כָּךְ וְאָהַבְתָּ, וְהָיָה אִם שָׁמוֹעַ, שֶׁהֲרֵי בַּיִּחוּד נִכְלְלוּ? אֶלָּא שָׁם בִּכְלָל, כָּאן בִּפְרָט, וְכָךְ צָרִיךְ."],[10,"","וּבְסוֹד הַיִּחוּד שֶׁהֲרֵי הִתְעוֹרַרְנוּ בוֹ, יִחוּד הוּא כְּמוֹ תְפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ. בִּתְפִלִּין שֶׁל רֹאשׁ יֵשׁ אַרְבַּע פָּרָשִׁיּוֹת, וַהֲרֵי נִתְבָּאֵר. וְכָאן שְׁלֹשָׁה שֵׁמוֹת הֵם. שָׁם אַרְבַּע פָּרָשִׁיּוֹת, וְכָל אַחַת וְאַחַת בִּלְבַדָּהּ. וְכָאן שָׁלֹשׁ שֵׁמוֹת. מַה בֵּין זֶה לָזֶה?"]]],[["אֶלָּא אִינוּן אַרְבַּע פַּרְשִׁיָּין הָא אַתְּעֲרוּ בְּהוּ, חַד נְקוּדָּה (ס\"א עלאה) קַדְמָאָה. וְחַד רָזָא דְּעָלְמָא דְּאָתֵי. וְחַד יְמִינָא וְחַד שְׂמָאלָא. אִלֵּין רָזָא דִּתְפִילִין דְּרֵישָׁא. וְהָכָא בְּרָזָא דָּא, יִחוּדָא דָּא תְּלַת שְׁמָהָן עִלָּאִין, אִינּוּן כְּגַוְונָא דְּאִינּוּן אַרְבַּע פָּרְשִׁיָּין. יְיָ' קַדְמָאָה, דָּא נְקוּדָה עִלָּאָה, רֵאשִׁיתָא דְּכֹלָּא. אֱלֹהֵינוּ, רָזָא דְּעָלְמָא דְּאָתֵי. יְיָ' בַּתְרָאָה, כְּלָלָא דִּימִינָא וּשְׂמָאלָא כַּחֲדָא, בִּכְלָלָא חֲדָא וְאִלֵּין אִינּוּן תְּפִלָּה דְּרֵישָׁא, וְדָא אִיהוּ יִחוּדָא קַדְמָאָה.","תְּפִלִּין דִּדְרוֹעָא, כְּלָלָא (גו תפלין דדרועא כללא) דְּכָל הָנֵי כַּחֲדָא, וְדָא אִיהוּ רָזָא, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. (עיין בהקדמה י\"ג ע\"ב) הָכָא כְּלָלָא דְּאִינּוּן תְּפִלִּין דְּרֵישָׁא, דְּאִתְכְּלִילוּ גּוֹ תְּפִלִּין דִּדְרוֹעָא.","וְרָזָא דָּא, בָּרוּךְ: דָּא רָזָא דִּנְקוּדָה עִלָּאָה, דְּאִיהוּ בָּרוּךְ, דְּכָל בִּרְכָאן נַבְעִין מִתַּמָּן. וְאִי תֵּימָא, עָלְמָא דְּאָתֵי אִקְרֵי בָּרוּךְ. לָאו הָכִי. דְּהָא נְקוּדָּה עִלָּאָה אִיהוּ דְּכַר, עָלְמָא דְּאָתֵי נוּקְבָּא, אִיהוּ בָּרוּךְ, וְאִיהִי בְּרָכָה, בָּרוּךְ דְּכַר, בְּרָכָה נוּקְבָּא. וְעַל דָּא בָּרוּךְ אִיהוּ נְקוּדָּה עִלָּאָה. שֵׁם: דָּא עָלְמָא דְּאָתֵי, דְּאִיהוּ שֵׁם גָּדוֹל. כְּמָה דְאַתְּ אָמֵר (יהושע ז׳:ט׳) וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. כְּבוֹד: דָּא כְּבוֹד עִלָּאָה, דְּאִיהוּ יְמִינָא וּשְׂמָאלָא, וְכֻלְּהוּ כְּלִילָן בְּהַאי תְּפִלָּה שֶׁל יַד, דְּאִיהוּ מַלְכוּתוֹ. וְנָטִיל כֹּלָּא בְּגַוִּיהּ, וּבְהַאי אִתְּכְּלִילָן בְּהַאי מַלְכוּת, עָלְמִין כֻּלְּהוּ, לְמֵיזָן לוֹן, וּלְסַפְּקָא לוֹן, בִּכְמָּה דְּאִצְּטְרִיכוּ.","וְדָא אִיהוּ יִחוּדָא דִּתְפִלִּין דְּרֵישָׁא וּתְפִלִּין דִּדְרוֹעָא, כְּגַוְונָא דְּרָזָא דְּיִחוּדָא דִּתְפִלִּין, הָכִי הוּא יִחוּדָא דְּכֹלָּא. וְדָא אִיהוּ בְּרִירוּ דְּמִלָּה. וְהָא סָדַּרְנָא יִחוּדָא דָּא קַמֵּי בּוּצִּינָא קַדִּישָׁא, וְאָמַר לִי דְּהָא בְּד' גַּוְונִין אִתְסָדַּר יִחוּדָא, וְדָא בְּרִירָא דְּכֻלְּהוּ. וְהָכִי אִיהוּ וַדַּאי, וְכֻלְּהוּ רָזָא דְּיִחוּדָא, אֲבָל סִדּוּרָא דִּתְפִלִּין, דָּא הוּא יִחוּדָא עִלָּאָה כַּדְּקָא יָאוּת.","וּמִגּוֹ דְּאִתְכְּלִילוּ יְמִינָא וּשְׂמָאלָא בְּרָזָא דִּשְׁמָא חַד בְּאֹרַח כְּלָל, אִצְּטְרִיךְ לְבָתַר לְאַפָּקָא לוֹן. בְּאֹרַח פְּרָט, אֲבָל לָאו בְּאֹרַח יִחוּדָא, דְּהָא יִחוּדָא בִּקְרָאֵי קַדְמָאֵי אִיהוּ, לְמֶהֱוִי יְיָ' אֶחָד, בִּתְפִלִּין דְּרֵישָׁא. וּשְׁמוֹ אֶחָד, בִּתְפִלִּין דִּדְרוֹעָא. וַהֲוִי כֹּלָּא חַד. כֵּיוָן דְּיִחוּדָא אִתְסָדָּר כֹּלָּא בִּכְלָלָא, מֵרֵישָׁא דִּנְקוּדָה עִלָּאָה, אִצְּטְרִיךְ לְבָתַר לְאִתְעַטְרָא מֵרֵישָׁא דִּנְהוֹרָא קַדְמָאָה, דְּאִיהוּ רֵישָׁא דְּכֹלָּא. (ע\"כ רעיא מהימנא).","גָּלִיף וְאַתְקִין מֹשֶׁה, כ\"ה אַתְוָון בְּרָזָא דִּפְסוּקָא דְּיִחוּדָא, דִּכְתִּיב שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד. וְאִינּוּן כ\"ה אַתְוָון גְּלִיפִין, מְחֻקָּקִין בְּרָזָא דִּלְעֵילָּא. יַעֲקֹב בָּעָא לְאַתְקְּנָא לְתַתָּא, בְּרָזָא דְּיִחוּדָא, וְאַתְקִין בְּכ\"ד אַתְוָון, וְאִינּוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלָא אַשְׁלִים לְכ\"ה אַתְוָון, בְּגִין דְּעַד לָא אִתְתְּקַּן מַשְׁכְּנָא. כֵּיוָן דְּאִתְתְּקַן מַשְׁכְּנָא, וְאִשְׁתְּלִים מִלָּה דְּהֲוָה נָפִיק מִנֵּיהּ, כַּד אִשְׁתְּלִים, לָא מַלִּיל אֶלָּא בְּכ\"ה אַתְוָון, לְאַחֲזָאָה דְּהָא אִשְׁתְּלִים דָּא, כְּגַוְונָא דִּלְעֵילָּא, דִּכְתִּיב, (ויקרא א׳:א׳) וַיְדַבֵּר יְיָ' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, הָא כ\"ה אַתְוָון.","וְעַל דָּא כ\"ה זִינִין, לְאַשְׁלְמָא תִּקּוּנָא דְּמַקְדְּשָׁא, וְכָל הָנֵי אַתְוָון אוֹקִימְנָא בְּאִינּוּן אַתְוָון גְּלִיפִין דְּאוֹלִיפְנָא מִמַּר. וּבְגִין דְּמַשְׁכְּנָא אִשְׁתְּלִים בְּרָזִין אִלֵּין, אִקְרֵי כ\"ה, בְּיִחוּדָא דִּשְׁלִימוּ דְּמַשְׁכְּנָא. וְעַל דָּא (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה כְּתִיב, רָזָא דִּשְׁלִימוּ דְּכָל מַשְׁכְּנָא, וְתִקּוּנָא דִּילֵיהּ.","כ\"ה: לָקֳבֵל כ\"ב אַתְוָון, וְתוֹרָה וּנְבִיאִים וּכְתוּבִים, דְּאִינּוּן כְּלָלָא חֲדָא, רָזָא חֲדָא. בְּשַׁעֲתָא דְּיִשְׂרָאֵל קָא מְיַחֲדֵי יִחוּדָא בְּהַאי קְרָא, בְּרָזָא דְּכ\"ה אַתְוָון, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, וּבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, דְּאִינּוּן כ\"ד אַתְוָון, וִיכַוֵּין כָּל חַד בְּהוּ, כֻּלְּהוּ אַתְוָון מִתְחַבְּרָן כַּחֲדָא, וְסַלְּקִין לְחִבּוּרָא חַד, תֵּשַׁע וְאַרְבָּעִים תַּרְעִין, בְּרָזָא דְּיוֹבְלָא. וּכְדֵין אִצְטְרִיךְ לְסַלְּקָא וָעֶד, לָא יַתִּיר. וּכְדֵין אִתְפְּתָחוּ תַּרְעִין, וְחָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא בַּר נָשׁ, כְּאִילּוּ קִיֵּים אוֹרַיְיתָא כֻּלָהּ, דְּאִיהִי אַתְיָא בְּמ\"ט פָּנִים בְּכֹלָּא.","וְעַל דָּא אִצְטְרִיךְ לְכַוְּונָא רְעוּתָא בְּכ\"ה וּבְאַרְבַּע וְעֶשְׂרִין, לְסַלְּקָא לוֹן בִּרְעוּתָא דְּלִבָּא, בְּתֵשַׁע וְאַרְבְּעִין תַּרְעִין דְּקַאמְרָן, כֵּיוָן דְּאִתְכָּוַּון בְּהַאי, יִתְכַּוָּון בְּהַהוּא יִחוּדָא דְּאָמַר מַר, שְׁמַע יִשְׂרָאֵל וְגוֹ' בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, כְּלָלָא דְּכָל אוֹרַיְיתָא כֹּלָּא. זַכָּאָה חוּלָקֵיהּ מַאן דְּיִתְכַּוֵּון בְּהוּ, וַדַּאי כְּלָלָא אִיהוּ דְּכָל אוֹרַיְיתָא דְּעֵילָּא וְתַתָּא. וְדָא אִיהוּ רָזָא דְּאָדָם, שְׁלִימוּ דִּדְכַר וְנוּקְבָּא, וְרָזָא דְּכָל מְהֵימְנוּתָא. עֲד כָּאן."],[[0,"אלא אינון ארבע וכו':","ומשיב, אלא אלו ארבע פרשיות הרי העירו בהן, שאחת, דהיינו קדש, היא הנקודה הראשונה דהיינו \u0003י'\u0004 דהויה, שהיא חכמה. ואחת, דהיינו והיה כי יביאך, היא סוד עולם הבא, שהוא בינה. ואחת, דהיינו שמע, היא ימין דדעת. ואחת, שהיא והיה אם שמוע, היא שמאל דדעת. אלו הם סוד תפלין של ראש. וכאן בסוד זה דקריאת שמע, היחוד הזה של ג' שמות העליונים, הויה אלקינו הויה, הם כעין אלו ארבע פרשיות דתפלין. \u0003הויה\u0004 הראשונה, היא נקודה עליונה ראשית הכל, דהיינו חכמה. \u0003אלקינו\u0004, ה\"ס עולם הבא, דהיינו בינה. \u0003הויה\u0004 האחרונה היא כלל ימין ושמאל דדעת, ביחד בכלל אחד. ואלו הם סדר תפלין של ראש, וזה הוא יחוד הראשון שבק\"ש."],[1,"תפלין דדרועא כללא וכו':","תפלין של יד, הן כלל של כל אלו ד' פרשיות ביחד, דהיינו בבית אחד, וזה הוא סוד יחוד הב' שבק\"ש, שהוא, ברוך שם כבוד מלכותו לעולם ועד, כאן, ביחוד הב', הוא הכלל של ד' פרשיות התפלין של ראש הנכללים תוך התפלין של יד בבית אחד. כלומר שיחוד בשכמל\"ו דומה ליחוד ד' פרשיות דתפלה של יד."],[2,"ורזא דא, ברוך וכו':","וסוד זה הוא, \u0003ברוך\u0004, זה סוד נקודה עליונה, שהיא חכמה, שהיא ברוך, משום שכל הברכות נובעות משם. ואם תאמר, שעולם הבא נקרא ברוך, שהיא בינה. אינו כן, כי נקודה עליונה, חכמה, היא זכר, ועולם הבא, בינה, היא נקבה, לפיכך הוא, הזכר, נקרא ברוך, והיא, הנקבה, נקראת ברכה. ברוך הוא זכר, וברכה היא נקבה וע\"כ, ברוך, הוא נקודה עליונה, דהיינו חכמה. \u0003שם\u0004, זהו עולם הבא, דהיינו בינה, שהיא שם גדול, כמש\"א, ומה תעשה לשמך הגדול. \u0003כבוד\u0004, זהו כבוד עליון, דהיינו דעת, שהוא ימין ושמאל דדעת, וכולם כלולים בתפלה של יד ההיא, דהיינו במלכות, שהיא סוד המלה \u0003מלכותו\u0004. והמלכות לוקחת הכל בתוכה, ובזה נכללו במלכות זו כל \u0003העולמות\u0004 לזון אותם ולכלכל אותם במה שצריכים, שזהו \u0003לעולם ועד\u0004. כי \u0003ועד\u0004, לשון מזון כמן בבוקר יאכל \u0003עד\u0004. ולעולם ועד, פירושו, שהמלכות מזינה העולם כולו."],[3,"ודא איהו יחודא וכו':","וזה הוא גם כן היחוד של תפלין של ראש ותפלין של יד, כי כעין סוד היחוד של התפלין כן הוא יחוד הכל. וזה הוא בירורו של הדבר. וכך סדרתי היחוד הזה לפני המאור הקדוש, שהוא ר\"ש, ואמר לי, כי בד' אפנים מסתדר היחוד דקריאת שמע, וסדר הזה, הוא הברור מכולם. וכך הוא ודאי. ובכולם הם סוד היחוד, דהיינו בק\"ש ושאר דברים, אבל הסדר של התפלין, זה הוא יחוד עליון כראוי."],[4,"ומגו דאכלילו ימינא וכו':","ומשום שנכלל ימין ושמאל דדעת, בסוד שם אחד, בקריאת שמע, דהיינו בהויה אחרונה (כנ\"ל אות פ\"ז) בדרך כלל, הוא צריך אח\"כ להוציאם בדרך פרט, דהיינו ואהבת בפני עצמו, והיה אם שמוע בפני עצמו, אבל לא בדרך היחוד, כי היחוד כבר נעשה בפסוקים הראשונים, בשמע ובבשכמל\"ו, שיהיה הויה אחד בתפלין של ראש, שהוא היחוד דשמע ישראל, ושיהיה שמו אחד בתפלין של יד, שהוא היחוד דבשכמל\"ו, ונעשה הכל אחד. כיון שהיחוד נסתדר הכל בכלל, מראש נקודה העליונה, צריכים אח\"כ לעטר מראש של אור הראשון שהוא ראש הכל. דהיינו כתר."],[5,"גליף ואתקין משה וכו':","חקק ותקן משה כ\"ה אותיות בסוד יחוד הפסוק, שכתוב שמע ישראל ה' אלקינו ה' אחד. והן כ\"ה אותיות חקוקות, החקוקות בסוד של מעלה. דהיינו בסוד ז\"א. כי כ\"ה רומז על כ\"ב אותיות התורה, ותנ\"כ שה\"ס ג' קוין. כמ\"ש לפנינו. יעקב רצה לתקן למטה, במלכות, בסוד היחוד, ותקן בכ\"ד אותיות, והם ברוך שם כבוד מלכותו לעולם ועד, שיעקב תקן אותו, שיש בו כ\"ד אותיות, ולא השלים לכ\"ה אותיות, והוא משום שעוד לא נתתקן בזמנו המשכן, שהוא כנגד מלכות, כיון שנתתקן המשכן ונשלם הדבר שהמשכן נמשך ממנו, לא דיבר עמו אחר שנשלם, אלא בכ\"ה אותיות, להראות שזו, המלכות, נשלמה כעין שלמעלה, כמו ז\"א שיש לו כ\"ה אותיות, שכתוב \u0003וידבר ה' אליו מאהל מועד לאמר\u0004, הרי יש בו כ\"ה אותיות. וביאור הדברים עי' לעיל (תרומה אות רמ\"ג)."],[6,"וע\"ד כ\"ה זינין וכו':","וע\"כ יש כ\"ה מינים להשלים תקון המשכן, שהם י\"ג מינים, זהב וכסף וגו'. וי\"ב אבנים שבחשן. וכל אלו האותיות למדנו, באלו אותיות חקוקות שלמדנו מאדוני. ומשום שהמשכן נשלם בסודות אלו כ\"ה אותיות, ע\"כ נקרא המשכן, דהיינו המלכות, בשם \u0003כה\u0004, שמורה על יחוד השלמות שבמשכן, שהוא המלכות, וע\"כ כתוב, וחסידיך יברכוכה. שהוא אותיות \u0003יברכו כה.\u0004 שה\"ס שלימות כל המשכן והתקון שלו."],[7,"כ\"ה לקבל כ\"ב וכו':","כ\"ה הוא כנגד כ\"ב אותיות ותורה נביאים וכתובים, שג' וכ\"ב הם כ\"ה, שהם כלל אחד, וסוד אחד. בשעה שישראל מיחדים היחוד בסוד כ\"ה אותיות שבמקרא הזה, שהם שמע ישראל הוי\"ה אלקינו הוי\"ה אחד. והיחוד של ברוך שם כבוד מלכותו לעולם ועד, שהם כ\"ד אותיות. ומכוין בכל אחד מהם, כל האותיות מתחברות יחד ועולות לחבור אחד, שהם מ\"ט אותיות כנגד מ\"ט שערים שבסוד היובל, שהוא בינה, ואז צריך להעלות היחוד עד המלה \u0003ועד\u0004, ולא יותר, כי במלה ועד, נגמר החשבון מ\"ט, ואז נפתחים מ\"ט שערי בינה. ומחשיב הקב\"ה אותו האדם, כאלו קיים התורה כולה, הבאה בכולה במ\"ט פנים."],[8,"וע\"ד אצטריך לכוונא וכו':","וע\"כ צריך לכוין הרצון בכ\"ה אותיות דשמע, ובכ\"ד של ברוך שם, להעלותם ברצון הלב במ\"ט שערי בינה, שאמרנו. אחר שנתכוין בזה, יכוון באותו היחוד שאמר אדוני, אשר שמע ישראל וגו' וברוך שם כבוד מלכותו לעולם ועד, הם כלל של כל התורה כולה. אשרי חלקו מי שיתכוון בהם, ודאי הוא כלל של כל התורה, שלמעלה, שהוא ז\"א, ושלמטה, שהיא מלכות. וזה הוא סוד אדם, שהוא שלמות דכר ונוקבא. דהיינו השלמות של ז\"א ומלכות. ויחוד הזה הוא סוד כל האמונה. (ע\"כ רעיא מהימנא)."]],[[0,"","אֶלָּא בְּאוֹתָן אַרְבַּע פָּרָשִׁיּוֹת הֲרֵי הִתְעוֹרְרוּ בָהֶן, אַחַת נְקֻדָּה [עליונה] רִאשׁוֹנָה, וְאַחַת סוֹד הָעוֹלָם הַבָּא, וְאַחַת יָמִין, וְאַחַת שְׂמֹאל. אֵלֶּה סוֹד תְּפִלִּין שֶׁל רֹאשׁ. וְכָאן בְּסוֹד זֶה, יִחוּד זֶה שְׁלֹשָׁה שֵׁמוֹת עֶלְיוֹנִים הֵם כְּמוֹ אוֹתָן אַרְבַּע פָּרָשִׁיּוֹת. ה' הָרִאשׁוֹן זוֹ נְקֻדָּה עֶלְיוֹנָה, רֵאשִׁית הַכֹּל. אֱלֹהֵינוּ, סוֹד הָעוֹלָם הַבָּא. ה' הָאַחֲרוֹן, כְּלָל שֶׁל יָמִין וּשְׂמֹאל כְּאֶחָד, בִּכְלָל אֶחָד, וְאֵלֶּה הֵם תְּפִלָּה שֶׁל רֹאשׁ, וְזֶהוּ יִחוּד רִאשׁוֹן."],[1,"","תְּפִלִּין שֶׁל זְרוֹעַ כְּלָל [תוך תפלין של זרוע] שֶׁל כָּל הָאֵלֶּה כְאֶחָד, וְזֶהוּ סוֹד בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּאן כְּלָל שֶׁל אוֹתָן תְּפִלִּין שֶׁל רֹאשׁ שֶׁנִּכְלְלוּ בְתוֹךְ תְּפִלִּין שֶׁל זְרוֹעַ."],[2,"","וְסוֹד זֶה, בָּרוּךְ – זֶה סוֹד שֶׁל נְקֻדָּה עֶלְיוֹנָה, שֶׁהוּא בָּרוּךְ, שֶׁכָּל הַבְּרָכוֹת נוֹבְעוֹת מִשָּׁם. וְאִם תֹּאמַר, הָעוֹלָם הַבָּא נִקְרָא בָּרוּךְ – לֹא כָּךְ, שֶׁהֲרֵי נְקֻדָּה עֶלְיוֹנָה הִיא זָכָר, עוֹלָם הַבָּא נְקֵבָה. הוּא בָּרוּךְ וְהִיא בְּרָכָה. בָּרוּךְ זָכָר, בְּרָכָה נְקֵבָה. וְעַל זֶה בָּרוּךְ הוּא נְקֻדָּה עֶלְיוֹנָה. שֵׁם – זֶה הָעוֹלָם הַבָּא, שֶׁהוּא שֵׁם גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר [יהושע ז] וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. כְּבוֹד – זֶה כָּבוֹד עֶלְיוֹן, שֶׁהוּא יָמִין וּשְׂמֹאל, וְכֻלָּם כְלוּלִים בִּתְפִלָּה זוֹ שֶׁל יָד, שֶׁהִיא מַלְכוּתוֹ. וְלוֹקֵחַ הַכֹּל לְתוֹכָהּ, וּבָזֶה נִכְלָלִים בַּמַּלְכוּת הַזֹּאת כָּל הָעוֹלָמוֹת לָזוּן אוֹתָם וּלְהַנּוֹת אוֹתָם בְּמַה שֶּׁהִצְטָרְכוּ."],[3,"","וְזְהִוּ יִחוּד שֶׁל תְּפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ, כְּמוֹ סוֹד הַיִּחוּד שֶׁל תְּפִלִּין, כָּךְ הוּא יִחוּד הַכֹּל, וְזֶהוּ בֵּרוּר הַדָּבָר. וַהֲרֵי סִדַּרְנוּ יִחוּד זֶה לִפְנֵי הַמְּנוֹרָה הַקְּדוֹשָׁה, וְאָמַר לִי שֶׁהֲרֵי בְּאַרְבָּעָה גְוָנִים הִסְתַּדֵּר הַיִּחוּד, וְזֶה הַבֵּרוּר שֶׁל כֻּלָּם. וְכָךְ הוּא בְּוַדַּאי, וְכֻלָּם סוֹד הַיִּחוּד. אֲבָל סִדּוּר הַתְּפִלִּין זֶהוּ יִחוּד עֶלְיוֹן כָּרָאוּי."],[4,"","וּמִתּוֹךְ שֶׁנִּכְלְלוּ יָמִין וּשְׂמֹאל בְּסוֹד שֶׁל שֵׁם אֶחָד בְּדֶרֶךְ כְּלָל, צָרִיךְ אַחַר כָּךְ לְהוֹצִיא אוֹתָם בְּדֶרֶךְ פְּרָט, אֲבָל לֹא בְּדֶרֶךְ יִחוּד, שֶׁהֲרֵי הַיִּחוּד הוּא בַּפְּסוּקִים הָרִאשׁוֹנִים, לִהְיוֹת ה' אֶחָד, בִּתְפִלִּין שֶׁל רֹאשׁ. וּשְׁמוֹ אֶחָד, בִּתְפִלִּין שֶׁל זְרוֹעַ. וְנִהְיָה הַכֹּל אֶחָד. כֵּיוָן שֶׁהַיִּחוּד הִסְתַּדֵּר הַכֹּל בִּכְלָל מֵרֹאשׁ הַנְּקֻדָּה הָעֶלְיוֹנָה, צָרִיךְ אַחַר כָּךְ לְהִתְעַטֵּר מֵהָרֹאשׁ שֶׁל הָאוֹר הָרִאשׁוֹן, שֶׁהוּא רֹאשׁ הַכֹּל. [ע\"כ רעיא מהימנא]."],[5,"","חָקַק וְהִתְקִין מֹשֶׁה כ\"ה אוֹתִיּוֹת בְּסוֹד שֶׁל הַפָּסוּק שֶׁל הַיִּחוּד, שֶׁכָּתוּב שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וְהֵן כ\"ה אוֹתִיּוֹת חֲקוּקוֹת מְחֻקָּקוֹת בְּסוֹד שֶׁלְּמַעְלָה. יַעֲקֹב רָצָה לְהַתְקִין לְמַטָּה בְּסוֹד הַיִּחוּד, וְהִתְקִין בְּכ\"ד אוֹתִיּוֹת, וְהֵן: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלֹא הִשְׁלִים לְכ\"ה אוֹתִיּוֹת, מִשּׁוּם שֶׁעֲדַיִן לֹא הִתְתַּקֵּן הַמִּשְׁכָּן. כֵּיוָן שֶׁנִּתְתַּקֵּן הַמִּשְׁכָּן וְהִשְׁתַּלֵּם דָּבָר שֶׁהָיָה יוֹצֵא מִמֶּנּוּ, כְּשֶׁהִשְׁתַּלֵּם לֹא דִבֵּר אֶלָּא בְּכ\"ה אוֹתִיּוֹת, לְהַרְאוֹת שֶׁהֲרֵי זֶה הֻשְׁלַם כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב [ויקרא א] וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. הֲרֵי כ\"ה אוֹתִיּוֹת."],[6,"","וְעַל זֶה כ\"ה מִינִים לְהַשְׁלִים תִּקּוּן הַמִּקְדָּשׁ, וְכָל הָאוֹתִיּוֹת הַלָּלוּ בֵּאַרְנוּ בְּאוֹתָן אוֹתִיּוֹת חֲקוּקוֹת שֶׁלָּמַדְנוּ מִמַּר. וּמִשּׁוּם שֶׁהַמִּשְׁכָּן הִשְׁתַּלֵּם בַּסּוֹדוֹת הַלָּלוּ, נִקְרָא כ\"ה בַּיִּחוּד שֶׁל שְׁלֵמוּת הַמִּשְׁכָּן, וְעַל זֶה כָּתוּב [תהלים קמה] וַחֲסִידֶיךְ יְבָרְכוּכָה, סוֹד הַשְּׁלֵמוּת שֶׁל כָּל הַמִּשְׁכָּן וְתִקּוּנוֹ."],[7,"","כ\"ה כְּנֶגֶד כ\"ב אוֹתִיּוֹת הַתּוֹרָה, וְתוֹרָה וּנְבִיאִים וּכְתוּבִים, שֶׁהֵם כְּלָל אֶחָד, סוֹד אֶחָד. בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְיַחֲדִים יִחוּד בְּפָסוּק זֶה בְּסוֹד כ\"ה אוֹתִיּוֹת, שֶׁהֵם שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, וּבָרוּךְ שֵׁם כְּבוֹד כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁהֵם כ\"ד אוֹתִיּוֹת, וִיכַוֵּן כָּל אֶחָד בָּהֶם, הָאוֹתִיּוֹת כֻּלָּן מִתְחַבְּרוֹת כְּאַחַת, וְעוֹלוֹת לְחִבּוּר אֶחָד, אַרְבָּעִים וְתִשְׁעָה שְׁעָרִים בְּסוֹד הַיּוֹבֵל. וְאָז צָרִיךְ לַעֲלוֹת וָעֶד, לֹא יוֹתֵר. וְאָז נִפְתָּחִים הַשְּׁעָרִים, וּמַחֲשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ אָדָם כְּאִלּוּ קִיֵּם אֶת כָּל הַתּוֹרָה, שֶׁהִיא בָּאָה בְּמ\"ט פָּנִים בַּכֹּל."],[8,"","וְעַל זֶה צָרִיךְ לְכַוֵּן רָצוֹן בְּעֶשְׂרִים וְחָמֵשׁ וּבְעֶשְׂרִים וְאַרְבַּע לְהַעֲלוֹתָן בִּרְצוֹן הַלֵּב בְּאַרְבָּעִים וְתִשְׁעָה שְׁעָרִים שֶׁאָמַרְנוּ. כֵּיוָן שֶׁהִתְכַּוֵּן בָּזֶה, יִתְכַּוֵּן בְּאוֹתוֹ יִחוּד שֶׁאָמַר מַר, שְׁמַע יִשְׂרָאֵל וְגוֹ' בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, כְּלָל שֶׁל כָּל הַתּוֹרָה כֻּלָּהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיִּתְכַּוֵּן בָּהֶן, וַדַּאי כְּלָל הוּא שֶׁל כָּל הַתּוֹרָה שֶׁלְּמַעְלָה וּמַטָּה. וְזֶהוּ סוֹד שֶׁל אָדָם, שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה, וְסוֹד כָּל הָאֱמוּנָה. [עד כאן]"]]],[["רִבִּי אַבָּא שָׁלַח לֵיהּ לְרִבִּי שִׁמְעוֹן וְאָמַר לֵיהּ, הַאי דְּאוּקְמֵיהּ מַר בַּתְּפִלִּין דְּמָארֵי עָלְמָא, ד' פָּרְשִׁיָּין אִינּוּן קוּדְשָׁא דְּקוּדְשִׁין, שַׁפִּיר. מִשְׁכָא דְּעַל תְּפִילִּין, וְאִינּוּן רְצוּעִין אִקְרוּ קְדוּשָּׁה, אַסְמַכְתָּא מְנָלָן. שָׁלַח לֵיהּ (בראשית ג׳:כ״א) וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ וְגוֹ', דַּיְיקָא וְהָכִי אוּקְמֵיהּ רַב הַמְנוּנָא סָבָא. וְאִלֵּין אִינּוּן דְּרֵישָׁא, וּדְרוֹעָא יָדְכָה בְּהֵ\"א, וְהָא אוֹקְמוּהָ.","אָמַר רִבִּי שִׁמְעוֹן, אִית מַאן דְּמַתְנֵי בְּהַאי גַּוְונָא, וְהָיָה דְּרוֹעָא שְׂמָאלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִקְרֵי גְּבוּרָה. אִי הָכִי לָא אִשְׁתַּאֲרָן בְּרֵישָׁא אֶלָּא תְּלַת. וְאִינּוּן אַרְבַּע. אֲבָל תְּרֵין רְתִיכִין קַדִּישִׁין אִינּוּן, דָּא אִתְקְשַׁר בְּלִבָּא, וְדָא אִתְקְשַׁר בְּמוֹחָא. וְלִבָּא וּמוֹחָא, אִתְקְשַׁר דָּא בְּדָא. וְזִוּוּגָא חַד לְהוּ, וְשַׁפִּיר קָאַמְרוּ חַבְרַיָּיא. וְהָיָה לְאוֹת עַל יָדְכָה, כְּמָה דְּאִתְּמַר, וְלָא אִקְרֵי אֶלָּא אוֹת.","אָמַר רִבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּבַּר נָשׁ אַקְדִּים בְּפַלְגּוּת לֵילְיָא, וְקָם וְאִשְׁתָּדַּל בְּאוֹרַיְיתָא, עַד דְּנָהִיר צַפְרָא. בְּצַפְרָא אֲנָח תְּפִילִּין בְּרֵישֵׁיהּ, וּתְפִילִּין בִּרְשִׁימָא קַדִּישָׁא בִּדְרוֹעֵיהּ, וְאִתְעַטָּף בְּעִטּוּפָא דְּמִצְוָה, וְאָתֵי לְנָפְקָא מִתַּרְעָא דְּבֵיתֵיהּ. אִעְרַע בַּמְּזוּזָה, רְשִׁימָא דִּשְׁמָא קַדִּישָׁא בְּתַרְעָא דְּבֵיתֵיהּ. אַרְבַּע מַלְאָכִין קַדִּישִׁין מִזְדַוְּוגִין עִמֵּיהּ וְנָפְקִין עִמֵּיהּ מִתַּרְעָא דְּבֵיתֵיהּ, וְאוֹזְפֵי לֵיהּ לְבֵי כְּנִישְׁתָּא. וּמַכְרְזֵי קַמֵּיהּ, הָבוּ יְקָרָא לְדִיּוּקְנָא דְּמַלְכָּא קַדִּישָׁא, הָבוּ יְקָרָא לִבְרֵיהּ דְּמַלְכָּא, לְפַרְצוּפָא יְקָרָא דְּמַלְכָּא. רוּחָא קַדִּישָׁא שַׁרְיָא עָלֵיהּ, אַכְרִיז וְאָמַר (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","כְּדֵין הַהוּא רוּחָא קַדִּישָׁא סַלְּקָא לְעֵילָּא, וְאַסְהִיד עָלֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא, כְּדֵין פָּקִיד מַלְכָּא עִלָּאָה, לְמִכְתַּב קַמֵּיהּ כָּל אִינּוּן בְּנֵי הֵיכָלֵיהּ, כָּל אִינּוּן דְּאִשְׁתְּמוֹדְעָן קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ט״ז) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי יְיָ' וּלְחוֹשְׁבֵי שְׁמוֹ. מַאי וּלְחוֹשְׁבֵי שְׁמוֹ. כְּמָה דְאַתְּ אָמֵר (שמות לה) (ס\"א חשב האפוד) וְחוֹשְׁבֵי מַחֲשָׁבוֹת, אִינּוּן דְּעַבְדִּין לִשְׁמֵיהּ, אוּמָנוּתָא בְּכֹלָּא, אוּמָנוּתָא דִּתְפִילִּין, בְּבָתֵּיהוֹן בִּרְצוּעֵיהוֹן וּכְתִיבַתְהוֹן. אוּמָנוּתָא דְּצִיצִית, בְּחוּטֵיהוֹן, בְּחוּטָא דִּתְכֶלְתָּא. אוּמָנוּתָא דִּמְזוּזָה. וְאִלֵּין אִינּוּן חוֹשְׁבֵי שְׁמוֹ. וּכְתִיב (שם) וְחוֹשְׁבֵי מַחֲשָׁבוֹת.","וְלֹא עוֹד אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּבַּח בֵּיהּ, וּמַכְרִיז עָלֵיהּ בְּכֻלְּהוּ עָלְמִין, חָמוּ מַה בִּרְיָה עַבְדֵּית בְּעוֹלָמִי. וּמַאן דְּיֵיעוּל קַמֵּיהּ לְבֵי כְּנִישְׁתָּא, כַּד נָפִק מִתַּרְעֵיהּ, וְלָא תְּפִילִּין בְּרֵישֵׁיהּ וְצִיצִית בִּלְבוּשֵׁיהּ, וְאוֹמֵר (תהילים ה׳:ח׳) אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךָ בְּיִרְאָתֶךָ. קוּדְשָׁא בְּרִיךְ הוּא אָמַר, אָן הוּא מוֹרָאִי, הָא סָהִיד סַהֲדוּתָא דְּשִׁקְרָא.","אָמַר רִבִּי יוֹסִי, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּהָכָא אָמַר אֱלֹהֵינוּ. (נ\"א אלהיך) דְּאָמַר רִבִּי שִׁמְעוֹן, מֹשֶׁה בְּדַרְגָּא עִלָּאָה יַתִּיר אִתְאֲחָד, עַל שְׁאַר נְבִיאֵי מְהֵימְנֵי. וְאָמַר רִבִּי שִׁמְעוֹן, אִלְמָלֵא הֲווֹ יַדְעֵי בְּנֵי נָשָׁא מִלִּין דְּאוֹרַיְיתָא, לִינְדְּעוּן דְּהָא לֵית שׁוּם מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין וְיַקִּירִין.","תָּא חֲזֵי כְּתִיב, (שמות י״ט:י״ט) מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְתָנֵינָן, מַאי בְקוֹל. בְּקוֹלוֹ שֶׁל מֹשֶׁה. וְשַׁפִּיר הוּא, בְּקוֹלוֹ שֶׁל מֹשֶׁה דַּיְיקָא, בְּהַהוּא קוֹל דְּאִיהוּ אָחִיד בֵּיהּ, עַל כָּל שְׁאַר נְבִיאִין. (מתמן משה אתזן על כלהו) וּבְגִין דְּאִיהוּ אִתְאֲחִיד עַל כֻּלְּהוּ, בְּהַהוּא קוֹל, דַּרְגָּא עִלָּאָה, הֲוָה אָמַר לְהוּ לְיִשְׂרָאֵל, יְיָ' אֱלֹהֶיךָ, אִיהוּ דַּרְגָּא דְּאִקְרֵי שְׁכִינְתָּא, דְּשַׁרְיָיא בְּגַוַויְיהוּ. זַכָּאָה חוּלָקֵיהּ.","וְאָמַר רִבִּי שִׁמְעוֹן, תָּנֵינָן, קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים, מֹשֶׁה מִפִּי הַגְּבוּרָה אַמָרָן. וְשֶׁבְּמִשְׁנֵה תּוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אָמָרָן. מַאי מִפִּי עַצְמוֹ. וְכִי סַלְּקָא דַּעְתָּךְ דְּאֲפִילּוּ אָת זְעֵירָא בְּאוֹרַיְיתָא, מֹשֶׁה אָמַר לֵיהּ מִגַּרְמֵיהּ.","אֶלָּא שַׁפִּיר הוּא, וְהָא אִתְּעַרְנָא, מֵעַצְמוֹ לָא תָּנֵינָן, אֶלָּא מִפִּי עַצְמוֹ. וּמַאי אִיהוּ. הַהוּא קוֹל דְּאִיהוּ אָחִיד בֵּיהּ. וְעַל דָּא, הַלָּלוּ מִפִּי הַגְּבוּרָה. וְהַלָּלוּ מִפִּי עַצְמוֹ. מִפִּי הַהוּא דַּרְגָּא דְּאִתְקְשַׁר בֵּיהּ עַל שְׁאַר נְבִיאֵי מְהֵימְנֵי. וְעַל דָּא, בְּכָל אֲתָר אֱלֹהֶיךָ, וְהָכָא אֱלֹהֵינוּ.","תָּא חֲזֵי, כַּמָּה אִית לְהוּ לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא אוֹרְחַיְיהוּ, בְּגִין דְּיִשְׁתַּדְּלוּן בְּפֻלְחָנָא דְּמָארֵיהוֹן, וְיִזְכּוּן לְחַיֵּי עָלְמִין. תְּחוֹת כּוּרְסְיָיא דְּמַלְכָּא קַדִּישָׁא, אִית מָדוֹרִין עִלָּאִין. וּבְהַהוּא אֲתָר דְּכוּרְסְיָּיא, מְזוּזָה אִתְקְשַׁר, לְאִשְׁתְּזָבָא מִכַּמָּה מָארֵי דִּינִין, דִּזְמִינִין לְאַתְּעָרָא בְּהוּ בִּבְנֵי נָשָׁא, בְּהַהוּא עָלְמָא. כְּגַוְונָא דָּא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וְיָהַב לְהוּ פִּקּוּדֵי אוֹרַיְיתָא, בְּגִין דְּיִשְׁתַּדְּלוּן בָּהּ וְיִשְׁתֵּזְבוּן בְּהַאי עָלְמָא, מִכַּמָּה מָארֵי דִּינִין, מִכַּמָּה מְקַטְרְגֵי, דְּאִזְדַּמְנוּן בְּהוּ בִּבְנֵי נָשָׁא בְּכָל יוֹמָא."],[[0,"ר' אבא שלח וכו':","ר\"א שלח לר' שמעון, ואמר לו, זה שהעמיד אדוני, בתפלין דרבון העולם, ד' פרשיות, שהם קדש קדשים, דהיינו חו\"ב ותו\"מ דדעת, יפה הוא. העור שעל התפלין והרצועות שנקראים קדושה, סמך על זה מאין לנו. שלח לו, ויעש ה' אלקים לאדם ולאשתו כתנות עור וגו' עור הוא בדיוק, דהיינו מלכות הנקראת עור. וכך העמיד רב המנונא סבא. ואלו הם של ראש. שד' פרשיות הם ד' מוחין דז\"א והעור הוא מלכות דז\"א. ותפלין שעל הזרוע כתוב \u0003ידכה\u0004 עם \u0003ה'\u0004 ללמד שד' פרשיות, הן המוחין ד \u0003ה'\u0004 שהיא מלכות. וכבר העמידוהו."],[1,"אר\"ש אית מאן וכו':","א\"ר שמעון, יש מי שלומד, באפן זה, אשר \u0003והיה\u0004 אם שמוע, הוא זרוע שמאל של הקב\"ה, ונקרא ספירת הגבורה. אם כן הרי לא נשאר בראש, דהיינו במוחין, אלא ג' פרשיות: קדש, והיה כי יביאך, שמע, שהם חכמה ובינה וימין דחסד וחסר מוח הד' שהוא שמאל דדעת. שאתה אומר, אשר והיה אם שמע הוא בספירת הגבורה שהוא בגוף, והרי הם בראש ארבעה מוחין. אלא ב' מרכבות קדושות הם, של חו\"ב תו\"מ, זה, דתפלין של יד, נקשר בלב, שהוא מלכות. וזה, דתפלין של ראש, נקשר במוח, שהוא ז\"א. ונמצא שגם פרשה ד' דתפלין של ראש היא ג\"כ במוח, דהיינו שמאל דדעת, ולא בגוף, והלב ומוח, שהם ז\"א ומלכות, נקשרים זה בזה, וזווג אחד להם. ויפה אמרו החברים, והיה \u0003לאות\u0004 על ידכה, סובב על המלכות, כמו שלמדנו, שלא נקראת המלכות אלא \u0003אות\u0004. כי תפלין של יד הם מוחין דמלכות."],[2,"אמר ר\"ש בשעתא וכו':","אר\"ש, בשעה שאדם מקדים עצמו בחצות לילה, וקם ועוסק בתורה עד שמאיר הבוקר. ובבוקר מניח תפלין בראש ותפלין ברושם הקדוש, דהיינו תפלין של המלכות, בזרוע. ונתעטף בעטוף של מצוה. ובא לצאת מפתח ביתו הוא פוגש במזוזה, שהיא רושם של השם הקדוש, שהוא מלכות, בשער ביתו. הנה אז, ארבעה מלאכים קדושים מתחברים עמו, ויוצאים עמו מפתח ביתו ומלוים אותו לבית הכנסת, ומכריזים לפניו, תנו כבוד לצורת המלך הקדוש, תנו כבוד לבן המלך, לצורת הפנים של המלך. ורוח קדוש שורה עליו, מכריז ואומר, ישראל אשר בך אתפאר."],[3,"כדין ההוא רוחא וכו':","אז, אותו רוח הקדוש, עולה למעלה ומעיד עליו לפני המלך הקדוש. אז מצוה המלך העליון לכתוב לפניו כל אלו בני היכלו, כל אלו הנודעים לפניו. ז\"ש, ויכתב בספר זכרון לפניו ליראי ה' ולחושבי שמו. מהו ולחושבי שמו. הוא כש\"א וחושבי מחשבות, שהם מחשבות אומנות, אף כאן, אלו שעושים לשמו, אומנות בכל דבר, אומנות התפלין, בהבתים שלהם ברצועותיהם ובכתיבה שלהם. אומנות הציצית, בחוטים שלהם, בחוט התכלת. אומנות המזוזה. ואלו הם חושבי שמו, כמ\"ש וחושבי מחשבות."],[4,"ולא עוד אלא וכו':","ולא עוד, אלא, שהקב\"ה משתבח בו ומכריז עליו בכל העולמות, ראו מה בני עובד בעולמי. ומי שנכנס לפניו לבית הכנסת, וכשיוצא מפתחו, בלא תפלין בראשו וציצית בלבושו, ואומר אשתחוה אל היכל קדשך ביראתך. אומר הקב\"ה, איפה הוא מוראי, הרי מעיד עדות שקר."],[5,"א\"ר יוסי זכאה וכו':","אר\"י, אשרי חלקו של משה שאמר כאן בשמע ישראל, אלקינו. כי אמר ר\"ש, משה נאחז במדרגה עליונה יותר על שאר נביאים הנאמנים. וא\"ר שמעון, אם היו יודעים בני אדם דברי תורה, היו יודעים שאין מלה בתורה או אות בתורה, שאין בה סודות עליונים ויקרים."],[6,"ת\"ח כתיב משה וכו':","בוא וראה, כתוב, משה ידבר והאלקים יעננו בקול. ולמדנו מהו בקול. היינו בקולו של משה. ויפה הוא, בקולו של משה הוא בדיוק, דהיינו באותו קול שהוא אוחז בו, שהוא ז\"א, שהוא עולה בו על כל שאר הנביאים, שאינם נאחזים אלא במלכות ולא בז\"א. ומשום שהוא נאחז בקול הזה, שהוא ז\"א, יותר מכולם, הנה בקול הזה שהוא מדרגה העליונה, היה אמר לישראל ה' אלקיך, שהיא המדרגה שנקראת שכינה, השורה בתוך ישראל. שהיא למטה ממדרגת ז\"א, שנאחז בו משה. אשרי חלקו."],[7,"ואר\"ש תנינן קללות וכו':","וא\"ר שמעון, למדנו, קללות שבתורת כהנים, שבחומש ויקרא, משה אמרם מפי הגבורה. וקללות שבמשנה תורה, שבדברים, משה מפי עצמו אמרם. מהו מפי עצמו, וכי יעלה על דעתך שאפילו אות קטנה בתורה, היה משה אומר מעצמו."],[8,"אלא שפיר הוא וכו':","ומשיב, אלא יפה הוא, והרי הערנו, מעצמו, לא למדנו, אלא \u0003מפי\u0004 עצמו, ומה הוא. הוא אותו הקול שמשה אחוז בו, דהיינו ז\"א, וע\"כ הללו שבתורת כהנים, מפי הגבורה, שהיא בינה, הנקראת גבורה עליונה. והללו שבמשנה תורה, מפי עצמו, דהיינו מפי מדרגה ההיא שנאחז בה משה יותר מכל נביאים הנאמנים, שהיא מדרגת ז\"א. ועל כן בכל מקום נאמר אלקיך, משום שרומז על מלכות, שהיא למטה מז\"א, וכאן, בשמע ישראל נאמר אלקינו, משום שרומז על בינה. שהיא למעלה מז\"א, שמשה נאחז בו."],[9,"ת\"ח כמה אית וכו':","בוא וראה, כמה יש לבני אדם לשמור דרכיהם כדי שיעסקו בעבודת רבונם ויזכו לחיי עולם. תחת הכסא של המלך הקדוש, שהוא המלכות, יש מדורים עליונים. ובמקום ההוא של הכסא, שהוא המלכות, נקשרת המזוזה, להציל האדם מכמה מיני דינים, המוכנים לעורר בהם בני אדם בעולם ההוא. כעין זה עשה הקב\"ה לישראל ונתן להם מצוות התורה, כדי שיעסקו בהן ויהיו נצולים בעולם הזה מכמה בעלי הדין, מכמה מקטרגים, הפוגשים בבני אדם בכל יום."]],[[0,"","רַבִּי אַבָּא שָׁלַח לוֹ לְרַבִּי שִׁמְעוֹן וְאָמַר לוֹ, זֶה שֶׁבֵּאֵר מַר, בַּתְּפִלִּין שֶׁל רִבּוֹן הָעוֹלָם אַרְבַּע פָּרָשִׁיּוֹת הֵן קֹדֶשׁ הַקְּדָשִׁים – יָפֶה. עוֹר שֶׁעַל הַתְּפִלִּין, וְאוֹתָן רְצוּעוֹת נִקְרָאוֹת קְדֻשָּׁה, אַסְמַכְתָּא מִנַּיִן לָנוּ? שָׁלַח לוֹ, [בראשית ג] וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ וְגוֹ' דַּוְקָא, וְכָךְ בֵּאֲרוֹ רַב הַמְנוּנָא סָבָא. וְאֵלֶּה אוֹתָם שֶׁל רֹאשׁ, וּזְרוֹעַ יָדְכָה בְּהֵ\"א, וַהֲרֵי פֵּרְשׁוּהָ."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, יֵשׁ מִי שֶׁשּׁוֹנֶה בְּצוּרָה זוֹ: וְהָיָה – זְרוֹעַ שְׂמֹאל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרֵאת גְּבוּרָה, אִם כָּךְ לֹא נִשְׁאֲרוּ בָּרֹאשׁ אֶלָּא שָׁלֹשׁ, וְהֵן אַרְבַּע. אֲבָל שְׁתֵּי מֶרְכָּבוֹת קְדוֹשׁוֹת הֵן, זֶה נִקְשָׁר בַּלֵּב וְזֶה נִקְשָׁר בַּמֹּחַ. וְהַלֵּב וְהַמֹּחַ נִקְשְׁרוּ זֶה בָזֶה, וְזִוּוּג אֶחָד לָהֶם, וְיָפֶה אָמְרוּ הַחֲבֵרִים. וְהָיָה לְאוֹת עַל יָדְכָה, כְּמוֹ שֶׁנֶּאֱמַר, וְלֹא נִקְרָא אֶלָּא אוֹת."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהָאָדָם מַקְדִּים בַּחֲצוֹת הַלַּיְלָה וְקָם וּמִשְׁתַּדֵּל בַּתּוֹרָה עַד שֶׁמֵּאִיר הַבֹּקֶר, בַּבֹּקֶר מֵנִיחַ תְּפִלִּין בְּרֹאשׁוֹ וּתְפִלִּין בְּרֹשֶׁם קָדוֹשׁ בִּזְרוֹעוֹ וּמִתְעַטֵּף בְּעִטּוּף שֶׁל מִצְוָה וּבָא לָצֵאת מִשַּׁעַר בֵּיתוֹ, פּוֹגֵשׁ אֶת הַמְּזוּזָה, רֹשֶׁם הַקָּדוֹשׁ בְּשַׁעַר בֵּיתוֹ, אַרְבָּעָה מַלְאָכִים קְדוֹשִׁים מִזְדַּוְּגִים עִמּוֹ וְיוֹצְאִים עִמּוֹ מִשַּׁעַר בֵּיתוֹ וּמְלַוִּים אוֹתוֹ לְבֵית הַכְּנֶסֶת, וּמַכְרִיזִים לְפָנָיו: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ הַקָּדוֹשׁ! תְּנוּ כָבוֹד לְבֶן הַמֶּלֶךְ, לַפַּרְצוּף הַיָּקָר שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ! רוּחַ קְדוֹשָׁה שׁוֹרָה עָלָיו, מַכְרִיזָה וְאוֹמֶרֶת: [ישעיה מט] יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[3,"","אָז אוֹתָהּ רוּחַ קְדוֹשָׁה עוֹלָה לְמַעְלָה, וּמְעִידָה עָלָיו לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְאָז מְצַוֶּה הַמֶּלֶךְ הָעֶלְיוֹן לִכְתֹּב לְפָנָיו אֶת כָּל אוֹתָם בְּנֵי הֵיכָלוֹ, כָּל אֵלּוּ הַנּוֹדָעִים לְפָנָיו. זֶהוּ שֶׁכָּתוּב [מלאכי ג] וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחֹשְׁבֵי שְׁמוֹ. מַה זֶּה וּלְחֹשְׁבֵי שְׁמוֹ? כְּמוֹ שֶׁנֶּאֱמַר [שמות לה] [חשב האפוד] וְחֹשְׁבֵי מַחֲשָׁבוֹת, אוֹתָם שֶׁעוֹשִׂים לִשְׁמוֹ אָמָּנוּת בַּכֹּל. אָמָּנוּת הַתְּפִלִּין – בְּבָתֵּיהֶן, בִּרְצוּעוֹתֵיהֶן וּכְתִיבָתָן. אָמָּנוּת הַצִּיצִית – בְּחוּטֵיהֶן בְּחוּט הַתְּכֵלֶת. אָמָּנוּת הַמְּזוּזָה. וְאֵלֶּה הֵם חֹשְׁבֵי שְׁמוֹ, וְכָתוּב [שם] וְחֹשְׁבֵי מַחֲשָׁבוֹת."],[4,"","וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ וּמַכְרִיז עָלָיו בְּכָל הָעוֹלָמוֹת: רְאוּ אֵיזוֹ בְּרִיָּה בָּרָאתִי בְּעוֹלָמִי! וּמִי שֶׁיִּכָּנֵס לְפָנָיו לְבֵית הַכְּנֶסֶת, כְּשֶׁיּוֹצֵא מֵהַשַּׁעַר שֶׁלּוֹ וְאֵין תְּפִלִּין בְּרֹאשׁוֹ וְצִיצִית בִּלְבוּשׁוֹ, וְאוֹמֵר [תהלים ה] אֶשְׁתַּחֲוֶה אֶת הֵיכַל קָדְשְׁךְ בְּיִרְאָתֶךְ – הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר: אַיֵּה הוּא מוֹרָאִי? הֲרֵי מֵעִיד עֵדוּת שֶׁקֶר!"],[5,"","אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁכָּאן אָמַר אֱלֹהֵינוּ [אלהיך]. שֶׁאָמַר רַבִּי שִׁמְעוֹן, מֹשֶׁה נֶאֱחַז בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה עַל שְׁאָר הַנְּבִיאִים הַנֶּאֱמָנִים. וְאָמַר רַבִּי שִׁמְעוֹן, אִלְמָלֵא הָיוּ יוֹדְעִים בְּנֵי אָדָם דִּבְרֵי תוֹרָה, שֶׁיֵּדְעוּ שֶׁהֲרֵי אֵין שׁוּם דָּבָר אוֹ אוֹת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים."],[6,"","בֹּא וּרְאֵה, כָּתוּב [שמות יט] מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְשָׁנִינוּ, מַה זֶּה בְקוֹל? בְּקוֹלוֹ שֶׁל מֹשֶׁה. וְיָפֶה הוּא. דַּוְקָא בְּקוֹלוֹ שֶׁל מֹשֶׁה, בְּאוֹתוֹ קוֹל שֶׁהוּא אָחוּז בּוֹ עַל כָּל שְׁאָר הַנְּבִיאִים. [משם משה נזון על כלם] וּמִשּׁוּם שֶׁהוּא נֶאֱחָז עַל כֻּלָם בְּאוֹתוֹ קוֹל, דַּרְגָּה עֶלְיוֹנָה, הָיָה אוֹמֵר לְיִשְׂרָאֵל: ה' אֱלֹהֶיךְ. הִיא דַּרְגָּה שֶׁנִּקְרֵאת שְׁכִינָה, שֶׁשּׁוֹרָה בְתוֹכָם. אַשְׁרֵי חֶלְקוֹ."],[7,"","וְאָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ, קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים – מֹשֶׁה מִפִּי הַגְּבוּרָה אֲמָרָן, וְשֶׁבְּמִשְׁנֵה תוֹרָה – מֹשֶׁה מִפִּי עַצְמוֹ אֲמָרָן. מַה זֶּה מִפִּי עַצְמוֹ? וְכִי תַעֲלֶה בְדַעְתְּךְ שֶׁאֲפִלּוּ אוֹתוֹ קְטַנָּה בַּתּוֹרָה אָמַר אוֹתָהּ מֹשֶׁה מֵעַצְמוֹ?!"],[8,"","אֶלָּא יָפֶה הוּא, וַהֲרֵי הִתְעוֹרַרְנוּ. לֹא שָׁנִינוּ מֵעַצְמוֹ, אֶלָּא מִפִּי עַצְמוֹ, וּמַהוּ? אוֹתוֹ קוֹל שֶׁהוּא אָחוּז בּוֹ. וְעַל זֶה, הַלָּלוּ מִפִּי הַגְּבוּרָה, וְהַלָּלוּ מִפִּי עַצְמוֹ, מִפִּי אוֹתָהּ דַּרְגָּה שֶׁנִּקְשַׁר בָּהּ עַל שְׁאָר נְבִיאִים הַנֶּאֱמָנִים. וְעַל זֶה בְּכָל מָקוֹם אֱלֹהֶיךְ, וְכָאן אֱלֹהֵינוּ."],[9,"","בֹּא וּרְאֵה כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לִשְׁמֹר דַּרְכֵיהֶם כְּדֵי שֶׁיִּשְׁתַּדְּלוּ בַּעֲבוֹדַת רִבּוֹנָם וְיִזְכּוּ לְחַיֵּי הָעוֹלָמִים. תַּחַת כִּסֵּא הַמֶּלֶךְ הַקָּדוֹשׁ יֵשׁ מָדוֹרִים עֶלְיוֹנִים, וּבְאוֹתוֹ מָקוֹם שֶׁל הַכִּסֵּא נִקְשֶׁרֶת מְזוּזָה לְהִנָּצֵל מִכַּמָּה בַּעֲלֵי דִינִים שֶׁעֲתִידִים לְהִתְעוֹרֵר בָּהֶם בִּבְנֵי הָאָדָם בְּאוֹתוֹ הָעוֹלָם. כְּמוֹ זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, וְנָתַן לָהֶם מִצְווֹת הַתּוֹרָה כְּדֵי שֶׁיִּשְׁתַּדְּלוּ בָהּ, וְיִנָּצְלוּ בָּעוֹלָם הַזֶּה מִכַּמָּה בַּעֲלֵי דִינִים וּמִכַּמָּה מְקַטְרְגִים שֶׁמִּזְדַּמְּנִים לִבְנֵי אָדָם בְּכָל יוֹם."]]],[["רִבִּי חִיָּיא אָמַר, הַאי מַאן דְּבָעֵי דְּיִסְתָּמַר אוֹרְחוֹי, לָא יֶעְבַּר עַל מַיָּיא דְּאוֹשְׁדִין קַמֵּי פִּתְחָא. בְּגִין דְּתַמָּן שָׁרִי חַד שִׁידָא, וְהוּא בֵּין תְּרֵין דָּשִׁין דְּפִתְחָא, וְאַנְפּוֹי לָקֳבְלֵיהּ דְּפִתְחָא, וְאִסְתָּכֵי כָּל מַה דְּעַבְדִין בְּבֵיתָא, וְלָא לִבְעֵי לֵיהּ לְאֱנוֹשׁ (לאיניש) דְּיִשְׁדֵּי מַיָּיא בֵּין תְּרֵי תַּרְעֵי. רִבִּי יִצְחָק אָמַר, מַיִין צְלִילָן לֵית לָן בָּהּ. וְהוּא דְּלָא יוֹשִׁיט לוֹן אֹרַח קְלָנָא. מַאי טַעֲמָא. בְּגִין דְּאִית לֵיהּ רְשׁוּ לְנַזְקָא. וְלָא עוֹד אֶלָּא דְּיֶהְדַּר רֵישֵׁיהּ לָקֳבְלֵי בֵּיתָא, וּבְכָל מַה דְּאִסְתְּכַל אִתְלַטְּיָיא.","תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ, כְּחוּשְׁבָּן יְמֵי שַׁתָּא, אִית לֵיהּ שַׁמָּשִׁין, דְּהוּא שַׁלִּיט עָלַיְיהוּ, וְכֻלְּהוּ נָפְקִין עִם בַּר נָשׁ, כַּד נָפִק מִתַּרְעָא דְּבֵיתֵיהּ. אָמַר רִבִּי אֶלְעָזָר, כָּל דָּא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַטְרָא לוֹן לְיִשְׂרָאֵל, וְאַתְקִין שְׁמֵיהּ קַדִּישָׁא לְעֵילָּא, דְּאִיהוּ אוֹרַיְיתָא, וְאוֹרַיְיתָא כֹּלָּא חַד שְׁמָא קַדִּישָׁא אִיהוּ, וּמַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, אִשְׁתְּדַּל בִּשְׁמֵיהּ.","תָּא חֲזֵי, בָּעֵי בַּר נָשׁ בְּפִתְחָא דְּבֵיתָא לְרַשְׁמָא שְׁמָא קַדִּישָׁא, דְּאִיהוּ מְהֵימְנוּתָא דְּכֹלָּא. דְּהָא בְּכָל אֲתָר דִּשְׁמָא קַדִּישָׁא אִשְׁתְּכַח, זִינִין בִּישִׁין לָא מִשְׁתַּכְּחֵי תַּמָּן, וְלָא יַכְלִין לְקַטְרְגָא לֵיהּ לְבַּר נָשׁ, כְּמָה דִּכְתִּיב, (תהילים צ״א:י׳) לֹא תְאוּנֶה אֵלֶיךָ רָעָה וְגוֹ'.","(מזוזא אקרי). אֲתָר דְּפִתְחָא דְּבֵיתָא שַׁרְיָא, כְּגַוְונָא דִּלְעֵילָּא, אֲתָר דְּפִתְחָא דְּבֵיתָא עִלָּאָה שַׁרְיָא, מְזוּזָא אִקְרֵי. דְּהוּא תִּקּוּנָא דְּבֵיתָא, וּפִתְחָא דְּבֵיתָא. מֵהַהִיא מְזוּזָה עַרְקִין מָארֵי נִימּוּסִין, מָארֵי דְּדִינִין קַמֵּיהּ לָא מִשְׁתַּכְּחִין. וְקֳבֵל דָּא לְתַתָּא, כַּד בַּר נָשׁ אַתְקִין מְזוּזָה לְפִתְחָא דְּבֵיתָא, וְהַאי שְׁמָא קַדִּישָׁא רָשִׁים בְּאַתווֹי, הַאי בַּר נָשׁ אִתְעֲטָּר בְּעִטְרוֹי דְּמָארֵיהּ, וְלָא קְרָבִין לְפִתְחָא דְּבֵיתֵיהּ זִינִין בִּישִׁין, וְלָא מִשְׁתַּכְּחֵי תַּמָּן.","רִבִּי אַבָּא הֲוָה אָתֵי מִלְּמֵחמֵי לְרַבִּי שִׁמְעוֹן, פָּגַע בֵּיהּ רִבִּי יִצְחָק, אָמַר לֵיהּ מֵאָן אָתֵי, מָארֵיהּ דִּנְהוֹרָא, גְּבָר דְּאִתְדַּבָּק בְּנוּרָא דְּאַכְלָא כָּל יוֹמָא, הָא נְהוֹרָא עִמֵּיהּ שָׁרֵי. אָמַר לֵיהּ, תָּנֵינָן דְּחִיּוּבָא עָלֵיהּ דְּבַּר נָשׁ, לְקַבְּלָא אַפֵּי שְׁכִינְתָּא, בְּכָל רֵישׁ יַרְחֵי וְשַׁבַּתֵּי. וּמַאן אִיהוּ. רַבֵּיהּ. כָּל שֶׁכֵּן בּוּצִינָא עִלָּאָה קַדִּישָׁא, דְּכָל בְּנֵי עָלְמָא בָּעָאן לְקַבְּלָא אַנְפּוֹי. אָמַר רִבִּי יִצְחָק, אַהֲדַרְנָא עִמָּךְ, וְאַקְבֵּל אַנְפֵּי שְׁכִינְתָּא, וְאַטְעַם מֵאִינּוּן מִלִּין עִלָּאִין, דְּאַטְעֲמַת קַמֵּיהּ.","פָּתַח רִבִּי אַבָּא וְאָמַר, (תהילים קכ״ג:א׳) שִׁיר הַמַּעֲלוֹת אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמַיִם. שִׁיר דָּא, לָא כְּתִיב מַאן אָמָרוֹ. אֶלָּא בְּכָל אֲתָר דְּאִיהוּ סָתִים, רוּחַ הַקֹּדֶשׁ אַמָרוֹ עָלַיְיהוּ דְּיִשְׂרָאֵל בְּגָלוּתָא. הַיּוֹשְׁבִי בַּשָּׁמַיִם, הַיּוֹשֵׁב מִבָּעֵי לֵיהּ, מַאי הַיּוֹשְׁבִי.","אֶלָּא אוֹקִימְנָא, מַאן דְּבָעֵי לְצַלָּאָה צְלוֹתֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא, בָּעֵי לְמִבָּעֵי מֵעֲמִיקְתָא דְּכֹלָּא, לְאַרְקָא בִּרְכָאן לְתַתָּא, כְּמָה דִּכְתִּיב, (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. וְהַאי יוֹ\"ד יַתִּיר, עֲמִיקְתָא דְּכֹלָּא הִיא, וּבְהַאי בָּעֵי לְמִבָּעֵי בָּעוּתֵיהּ, לְאַרְקָא בִּרְכָאן לְהַהוּא אֲתָר דְּאִקְרֵי שָׁמַיִם, לְאַתְּזְנָא מִנֵּיהּ כֹּלָּא, וְעַל דָּא הַיּוֹשְׁבִי בַּשָּׁמַיִם, בַּשָּׁמַיִם מַמָּשׁ, דְּכַד אִינּוּן בִּרְכָאן נְגִידוּ וְאִתְמְשָׁכוּ מֵהַהוּא אֲתָר עוּמְקָא דְּכֹלָּא, וְאִתְיַשְּׁבָן בַּאֲתָר דְּאִקְרֵי שָׁמַיִם, כְּדֵין בִּרְכָאן מִשְׁתַּכְּחֵי בְּעִלָּאֵי וְתַתָּאֵי.","כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם, מַאי כְעֵינֵי עֲבָדִים. אִלֵּין אִינּוּן שְׁאַר רַבְרְבֵי עַמִּין, דְּלָא אִתְּזָנוּ אֶלָּא מִשִּׁיּוּרַא (משיורי) (ס\"א גופא) נוֹפָא דְּאִילָנָא, דְּיִשְׂרָאֵל מִתְדַּבְּקֵי בֵּיהּ. וְכַד יִשְׂרָאֵל נַטְלִין בִּרְכָאן מֵהַהוּא אֲתָר, כֻּלְּהוּ מִתְבָּרְכָן מִיִּשְׂרָאֵל.","כְעֵינֵי שִׁפְחָה אֶל יַד גְּבִירְתָּהּ, דָּא הִיא שִׁפְחָה דְּאוֹקִימְנָא, דְּקָטִיל קוּדְשָׁא בְּרִיךְ הוּא חֵילָא דִּילָהּ בְּמִצְרַיִם, דְּהָא לֵית חֵילָא דִּידָהּ, אֶלָּא כַּד אִתְנְגִיד מִתַּמְצִית דְּהַאי אֶרֶץ יִשְׂרָאֵל. וְאֶרֶץ יִשְׂרָאֵל גְּבִרְתָּהּ אִקְרֵי. וְעַל הַאי כְּתִיב, (משלי ל׳:כ״א) תַּחַת שָׁלֹשׁ רָגְזָה אֶרֶץ. מַאן אֶרֶץ. דָּא אֶרֶץ יִשְׂרָאֵל, כְּמָה דְּאִתְּמַר. תַּחַת עֶבֶד כִּי יִמְלוֹךְ, אִלֵּין אִינּוּן עֲבָדִים דְּקָאַמְרָן. כַּד אִתְיְהִיב שֻׁלְטָנוּתָא לְחַד מִנַּיְיהוּ. וְדָא הוּא דִּכְתִּיב, אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם מִבֵּית עֲבָדִים. שִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ (ס\"א מאי היא) דָּא הִיא שִׁפְחָה דְּקָאַמְרָן."],[[0,"ר' חייא אמר וכו':","רח\"א, כל מי שרוצה להשמר בדרכיו, לא יעבור על מים ששופכים לפני הפתח. משום ששם שורה שד אחד, והוא בין ב' דלתות הפתח, ופניו כנגד הפתח, ורואה כל מה שעושים בבית. וע\"כ אין אדם צריך לשפוך מים בין ב' שערי הפתח. ר' יצחק אמר, מים צלולים, אין איסור בהם. אלא שלא ישפוך אותם דרך בזיון. מהו הטעם. הוא משום שיש לו, לשד, רשות להזיק. ולא עוד, אלא שמחזיר ראשו. כנגד הבית. ובכל מה שמסתכל נעשה מקולל. (ועי' לעיל אות ע\"ז בהסולם)."],[1,"תלת מאה ושתין וחמש וכו':","שס\"ה כחשבון ימות השנה, יש לו, לשד, משמשים, שהוא שולט עליהם, וכולם יוצאים עם האדם כשיוצא מפתח ביתו. א\"ר אלעזר, כל זה, כי רצה הקב\"ה לשמור את ישראל, והתקין שמו הקדוש למעלה, שהוא התורה, וכל התורה היא שם קדוש אחד, ומי שעוסק בתורה, עוסק בשמו."],[2,"ת\"ח בעי ב\"נ וכו':","בוא וראה, אדם צריך לרשום בפתח ביתו את השם הקדוש, שהוא אמונת כל. כי בכל מקום שהשם הקדוש נמצא, מינים רעים אינם נמצאים שם, ואינם יכולים לקטרג על האדם, כמ\"ש לא תאונה אליך רעה וגו'."],[3,"אתר דפתחא דביתא וכו':","המקום שפתח הבית שורה שם הוא כעין שלמעלה. המקום שפתח הבית העליון שורה, נקרא \u0003מזוזה\u0004, (כמ\"ש לעיל אות ע\"ז בהסולם ד\"ה וזה אמרו באות ע\"ב) שהוא תקון הבית, ופתח הבית. ממזוזה ההיא בורחים בעלי חוק, ובעלי הדין אינם נמצאים לפניו. וכנגד זה למטה, כשהאדם מתקן מזוזה לפתח ביתו, וזה השם הקדוש שדי, רשום באותיותיו, הרי אותו האדם מעוטר בעטרותיו של אדונו, ומינים הרעים אינם קרבים לפתח ביתו, ואינם נמצאים שם. (כמ\"ש שם כ\"ז היטב ע\"ש)."],[4,"ר' אבא הוה אתי וכו':","ר\"א היה בא מלראות את ר' שמעון. פגש בו ר' יצחק, אמר לו, מאין אתה בא בעל האור. איש המתדבק באש אוכלה כל יום, הרי האור שורה עמו. ואינו צריך לבקש ממי. אמר לו, למדנו, שחוב מוטל על אדם לקבל פני השכינה בכל ראש חודש ושבת. ומי הוא. זה הוא רבו. וכל שכן מאור עליון קדוש, שהוא ר\"ש, שכל העולם צריכים לקבל פניו. אמר ר' יצחק, אחזור עמך לר\"ש, ואקבל פני השכינה. ואטעם מאלו דברים העליונים, שטעמת לפניו."],[5,"פתח ר' אבא וכו':","פר\"א, ואמר, שיר המעלות אליך נשאתי את עיני היושבי בשמים. שיר זה לא כתוב מי אמרו. אלא בכל מקום שהוא סתום ולא נזכר מי אמרו, רוח הקדש, שהוא מלכות, אמרו על ישראל בגלות. \u0003היושבי בשמים\u0004, היה צריך לומר היושב, מהו היושבי."],[6,"אלא אוקימנא מאן וכו':","ומשיב, אלא העמדנו, מי שרוצה להתפלל תפלתו לפני המלך הקדוש צריך לבקש מן העמוקה מכל, דהיינו מבינה, שתשפיע ברכות למטה. כמ\"ש שיר המעלות ממעמקים קראתיך ה'. ואותה \u0003י'\u0004 היתרה, בהיושבי בשמים, היא העמוקה מכל, בינה, ומזו צריך לבקש בקשתו להריק ברכות למקום ההוא שנקרא שמים, שהוא ז\"א, שיזונו ממנו הכל. וע\"כ כתוב, \u0003היושבי בשמים\u0004, בשמים ממש, דהיינו בז\"א שנקרא שמים, כי כשהברכות נוזלות ונמשכות מאותו המקום העמוק מכל, שהוא בינה, ומתישבות במקום שנקרא שמים, דהיינו בז\"א, נמצאות אז הברכות בעליונים ותחתונים."],[7,"כעיני עבדים אל וגו':","כעיני עבדים אל יד אדוניהם. שואל, מהו כעיני עבדים. ומשיב, אלו הם שאר שרי העמים, שהם ע' שרים העליונים, שאינם נזונים אלא משיורי נוף האילן, שהוא ז\"א, שישראל מתדבקים בו. וכשישראל לוקחים ברכות ממקום ההוא, כולם מתברכים מישראל."],[8,"כעיני שפחה אל יד גבירתה:","זו היא השפחה שהעמדנו, שהרג הקב\"ה הכח שלה במצרים, דהיינו שכתוב עד בכור השפחה. כי אין הכח שלה נמצא אלא כשנמשך מתמצית השפע של ארץ ישראל, שהיא המלכות, וארץ ישראל נקראת גברתה של השפחה. ועל זה כתוב, תחת שלש רגזה ארץ. מי היא ארץ, זו ארץ ישראל, שהיא המלכות, כמו שלמדנו. תחת עבד כי ימלוך אלו הם העבדים שאמרנו, שהם ע' שרי האומות, שזה נאמר בעת שניתנה ממשלה לאחד מהם. וזה הוא שכתוב, אשר הוצאתיך מארץ מצרים מבית עבדים. דהיינו משעבוד השרים של האומות. שפחה כי תירש גבירתה, זו היא השפחה שאמרנו. שנאמר עליה עד בכור השפחה."]],[[0,"","רַבִּי חִיָּיא אָמַר, זֶה מִי שֶׁרוֹצֶה שֶׁיִּשָּׁמֵר דְּרָכָיו, לֹא יַעֲבֹר עַל מַיִם שֶׁשָּׁפְכוּ לִפְנֵי הַפֶּתַח, כִּי שָׁם שׁוֹרֶה שֵׁד אֶחָד, וְהוּא בֵּין שְׁנֵי מַשְׁקוֹפֵי הַפֶּתַח, וּפָנָיו כְּנֶגֶד הַפֶּתַח, וּמִסְתַּכֵּל עַל כָּל מַה שֶּׁעוֹשִׂים בַּבַּיִת, וְלֹא צָרִיךְ לָאָדָם לִשְׁפֹּךְ מַיִם בֵּין בְּנֵי שְׁעָרִים. רַבִּי יִצְחָק אָמַר, אֵין לָנוּ עֵסֶק בְּמַיִם צְלוּלִים, וְהוּא שֶׁלֹּא יִשְׁפֹּךְ אוֹתָם בְּדֶרֶךְ קָלוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַזִּיק. וְלֹא עוֹד, אֶלָּא שֶׁיַּחֲזִיר רֹאשׁוֹ כְּנֶגֶד הַבַּיִת, וּבְכָל מַה שֶּׁמִּסְתַּכֵּל – מִתְקַלֵּל."],[1,"","יִשִׁ לוֹ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה שַׁמָּשִׁים כְּמִנְיַן יְמוֹת הַשָּׁנָה, שֶׁהוּא שׁוֹלֵט עֲלֵיהֶם, וְכֻלָּם יוֹצְאִים עִם הָאָדָם כְּשֶׁיּוֹצֵא מִשַּׁעַר בֵּיתוֹ. אָמַר רַבִּי אֶלְעָזָר, כָּל זֶה רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת יִשְׂרָאֵל, וְהִתְקִין שְׁמוֹ הַקָּדוֹשׁ לְמַעְלָה, שֶׁהִיא הַתּוֹרָה, וְהַתּוֹרָה כֻּלָּהּ הִיא שֵׁם קָדוֹשׁ אֶחָד, וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה מִשְׁתַּדֵּל בִּשְׁמוֹ."],[2,"","בֹּא וּרְאֵה, צָרִיךְ אָדָם לִרְשֹׁם בְּפֶתַח בֵּיתוֹ שֵׁם הַקָּדוֹשׁ, שֶׁהוּא אֱמוּנַת הַכֹּל. שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁהַשֵּׁם הַקָּדוֹשׁ נִמְצָא, לֹא נִמְצָאִים שָׁם מִינִים רָעִים, וְלֹא יְכוֹלִים לְקַטְרֵג לָאָדָם, שֶׁכָּתוּב [תהלים לא] לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְגוֹ'."],[3,"","[מזוזה נקראת] מָקוֹם שֶׁפֶּתַח הַבַּיִת שׁוֹרֶה, כְּדֻגְמָא שֶׁלְּמַעְלָה, מָקוֹם שֶׁפֶּתַח הַבַּיִת הָעֶלְיוֹן שׁוֹרֶה נִקְרָא מְזוּזָה, שֶׁהוּא תִּקּוּן הַבַּיִת וּפֶתַח הַבַּיִת. מֵאוֹתָהּ מְזוּזָה בּוֹרְחִים בַּעֲלֵי שְׁמִירַת הַחֻקִּים. בַּעֲלֵי הַדִּינִים לֹא נִמְצָאִים לְפָנֶיהָ. וּכְנֶגֶד זֶה לְמַטָּה, כְּשֶׁאָדָם מַתְקִין מְזוּזָה לַבַּיִת וְהַשֵּׁם הַקָּדוֹשׁ הַזֶּה רָשׁוּם בְּאוֹתִיּוֹתָיו, הָאָדָם הַזֶּה מִתְעַטֵּר בְּעַטְרוֹת רִבּוֹנוֹ, וְלֹא קְרֵבִים לְפֶתַח בֵּיתוֹ מִינִים רָעִים וְלֹא נִמְצָאִים שָׁם."],[4,"","רַבִּי אַבָּא הָיָה בָּא מִלִּרְאוֹת אֶת רַבִּי שִׁמְעוֹן, פָּגַע בּוֹ רַבִּי יִצְחָק, אָמַר לוֹ, מֵאַיִן בָּאתָ בַּעַל הָאוֹר? אִישׁ שֶׁנִּדְבָּק בְּאֵשׁ אוֹכֶלֶת כָּל יוֹם, הֲרֵי הָאוֹר שׁוֹרֶה עִמּוֹ. אָמַר לוֹ, שָׁנִינוּ שֶׁחִיּוּב עַל הָאָדָם לְקַבֵּל פְּנֵי שְׁכִינָה בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת, וּמִיהוּ? רַבּוֹ. כָּל שֶׁכֵּן מְנוֹרָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה שֶׁכָּל בְּנֵי הָעוֹלָם רוֹצִים לְקַבֵּל פָּנָיו. אָמַר רַבִּי יִצְחָק, אֶחֱזֹּר עִמְּךְ וַאֲקַבֵּל פְּנֵי הַשְּׁכִינָה, וְאֶטְעַם מֵאוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁטָּעַמְתָּ לְפָנָיו."],[5,"","פָּתַח רַבִּי אַבָּא וְאָמַר, [שם קכג] שִׁיר הַמַּעֲלוֹת אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי הַיֹּשְׁבִי בַּשָּׁמָיִם. שִׁיר זֶה לֹא כָתוּב מִי אֲמָרוֹ. אֶלָּא בְּכָל מָקוֹם שֶׁהוּא סָתוּם, רוּחַ הַקֹּדֶשׁ אָמְרָה עַל כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. הַיֹּשְׁבִי בַּשָּׁמָיִם?! הַיּוֹשֵׁב צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה הַיֹּשְׁבִי?"],[6,"","אֶלָּא בֵּאַרְנוּ, מִי שֶׁרוֹצֶה לְהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, צָרִיךְ לְבַקֵּשׁ מֵעֹמֶק הַכֹּל לְהוֹרִיק בְּרָכוֹת לְמַטָּה, כְּמוֹ שֶׁכָּתוּב [שם קל] שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. וְיוֹ\"ד זוֹ הִיא יְתֵרָה, עֹמֶק הַכֹּל הִיא, וּבָזֶה צָרִיךְ לְבַקֵּשׁ בַּקָּשָׁתוֹ, לְהוֹרִיק בְּרָכוֹת לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, לְהָזִין מִמֶּנּוּ אֶת הַכֹּל. וְעַל זֶה הַיֹּשְׁבִי בַּשָּׁמָיִם, בַּשָּׁמַיִם מַמָּשׁ. שֶׁכְּשֶׁאוֹתָן בְּרָכוֹת שׁוֹפְעוֹת וְנִמְשָׁכוֹת מֵאוֹתוֹ מָקוֹם עֹמֶק הַכֹּל, וּמִתְיַשְּׁבִים בְּמָקוֹם שֶׁנִּקְרָא שָׁמַיִם, אָז בְּרָכוֹת נִמְצָאוֹת בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים."],[7,"","כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם, מַה זֶּה כְעֵינֵי עֲבָדִים? אֵלּוּ אוֹתָם שְׁאָר גְּדוֹלֵי הָעַמִּים שֶׁלֹּא נִזּוֹנִים אֶלָּא מִשְּׁיָרֵי [גוף] נוֹף הָאִילָן שֶׁיִּשְׂרָאֵל נִדְבָּקִים בּוֹ. וּכְשֶׁיִּשְׂרָאֵל לוֹקְחִים בְּרָכוֹת מֵאוֹתוֹ מָקוֹם, כֻּלָּם מִתְבָּרְכִים מִיִּשְׂרָאֵל."],[8,"","כְּעֵינֵי שִׁפְחָה אֶל יַד גְּבִרְתָּהּ – זוֹהִי הַשִּׁפְחָה שֶׁבֵּאַרְנוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג אֶת הַכֹּחַ שֶׁלָּהּ בְּמִצְרַיִם, שֶׁהֲרֵי אֵין כֹּחַ שֶׁלָּהּ אֶלָּא רַק כְּשֶׁשּׁוֹפֵעַ מִתַּמְצִית שֶׁל אֶרֶץ יִשְׂרָאֵל. וְאֶרֶץ יִשְׂרָאֵל נִקְרֵאת גְּבִרְתָּהּ, וְעַל זֶה כָּתוּב [משלי ל] תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ. אֵיזוֹ אֶרֶץ? זוֹ אֶרֶץ יִשְׂרָאֵל, כְּמוֹ שֶׁנִּתְבָּאֵר. תַּחַת עֶבֶד כִּי יִמְלוֹךְ – אֵלֶּה אוֹתָם עֲבָדִים שֶׁאָמַרְנוּ, כְּשֶׁנִּתָּן הַשִּׁלְטוֹן לְאֶחָד מֵהֶם. וְזֶהוּ שֶׁכָּתוּב אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם מִבֵּית עֲבָדִים. שִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ [מי היא] – זוֹהִי שִׁפְחָה כְּמוֹ שֶׁאָמַרְנוּ."]]],[["תָּא חֲזֵי, מִסִּטְרָא דְּהַאי שִׁפְחָה, נַפְקֵי כַּמָה גַּרְדִּינֵי טְהִירִין, מְקַטְרְגִין לָקֳּבְלַיְיהוּ דְּיִשְׂרָאֵל, וּלְקַטְרְגָא לוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְהוּ לְיִשְׂרָאֵל נְטִירוּ, כְּאַבָּא דְּבָעֵי לְנַטְרָא לִבְרֵיהּ מִן כֹּלָּא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, כַּמָה מְקַטְרְגִין זְמִינִין לָקֳבְלַיְיכוּ, אִשְׁתְּדָלוּ בְּפוּלְחָנִי, וַאֲנָא אֱהֵא נָטִיר לְכוּ לְבַר. וְאַתּוּן תֶּהֱווֹן זְמִינִין בְּבָתֵּיכוֹן מִלְּגוֹ, וְנַיְימֵי בְּעַרְסֵיכוֹן, וַאֲנָא אֱהֵא נָטִיר לְכוּ לְבַר, וְסוֹחֲרָנֵי עַרְסַיְיכוּ.","וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּאִינּוּן זִינִין בִּישִׁין קְרִיבִין לְפִתְחָא דְּבַּר נָשׁ זַקְפָן רֵישָׁא, וּמִסְתַּכְּלָן בִּשְׁמָא קַדִּישָׁא דְּאִתְחָזֵי לְבַר, דְּאִיהוּ שַׁדַּי, דְּמִתְעַטָּר בְּעִטְרוֹי, שְׁמָא דָּא שַׁלִּיט עַל כֻּלְּהוּ, מִנֵּיהּ דַּחֲלִין וְעַרְקִין, וְלָא קְרָבִין לְפִתְחָא דְּבַּר נָשׁ.","אָמַר לֵיהּ רִבִּי יִצְחָק, אִי הָכִי, יִרְשׁוֹם בַּר נָשׁ שְׁמָא דָּא בְּפִתְחָא דְּבֵיתָא, וְלָא יַתִּיר, אֲמַאי כָּל פַּרְשְׁתָּא. אָמַר לֵיהּ שַׁפִּיר הוּא, דְּהָא שְׁמָא דָּא לָא אִתְעֲטָּר, אֶלָּא בְּאִינּוּן אַתְוָון כֻּלְּהוּ, רְשִׁימִין בִּרְשִׁימָא דְּמַלְכָּא, וְכַד אַכְתָּב כָּל פַּרְשְׁתָּא, כְּדֵין שְׁמָא דָּא מִתְעֲטָּר בְּעִטְרוֹי וְנָפִיק מַלְכָּא בְּכָל חֵילוֹי, כֻּלְּהוּ רְשִׁימִין בִּרְשִׁימָא דְּמַלְכָּא, כְּדֵין דַּחֲלִין מִנֵּיהּ, וְעַרְקִין מִקַּמֵּיהּ.","תָּא חֲזֵי, וְהָיָה שְׁמָא קַדִּישָׁא, מִתַּתָּא לְעֵילָּא. וְעַל דָּא, שַׁדַּי אִתְרְשִׁים מִלְבַר, לָקֳבְלֵי שְׁמָא דָּא. וְהָיָ\"ה מִלְּגַו, שַׁדָּ\"י מִלְבַר. לְמֶהֱוֵי נָטִיר בַּר נָשׁ מִכָּל סִטְרִין מִלְּגַאו וּמִלְּבַר. אָמַר רִבִּי אַבָּא, כַּמָה חַיָּילִין קַדִּישִׁין זְמִינִין בְּהַהִיא שַׁעֲתָא דְּאָנַח בַּר נָשׁ מְזוּזָה לְתַרְעֵיהּ, כֻּלְּהוּ מַכְרְזֵי וְאַמְרֵי (תהלים קיח) זֶה הַשַּׁעַר לַיְיָ' וְגוֹ'.","זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, כְּדֵין אִשְׁתְּמוֹדְעָן יִשְׂרָאֵל דְּאִינּוּן בְּנֵי מַלְכָּא קַדִּישָׁא, דְּהָא כֻּלְּהוּ אִתְרְשִׁימוּ מִנֵּיהּ. אִתְרְשִׁימוּ בְּגוּפַיְיהוּ, בִּרְשִׁימָא קַדִּישָׁא. אִתְרְשִׁימוּ בִּלְבוּשַׁיְיהוּ, בְּעִטּוּפַיְיהוּ דְּמִצְוָה. אִתְרְשִׁימוּ בְּרֵישַׁיְיהוּ, בְּבָתֵּי דִּתְפִילֵי, בִּשְׁמָא דְּמָארֵיהוֹן. אִתְרְשִׁימוּ בִּידַיְיהוּ, בִּרְצוּעֵי דִּקְדוּשָּׁא. אִתְרְשִׁימוּ בִּמְסָאנַיְיהוּ, בִּמְסָאנָא דְּמִצְוָה. אִתְרְשִׁימוּ לְבַר, בִּזְרִיעָה בְּחַצְדָּא. אִתְרְשִׁימוּ בְּבָתֵּיהוֹן, בִּמְּזוּזָה דְּפִתְחָא. בְּכֹלָּא רְשִׁימִין דְּאִינּוּן בְּנֵי מַלְכָּא עִלָּאָה, זַכָּאָה חוּלָקֵיהוֹן.","עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב, (ירמיהו ב׳:י״ג) אוֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים לַחְצוֹב לָהֶם בֹּארוֹת וְגוֹ'. אוֹתִי עָזְבוּ, דָּא הוּא מַאן דִּמְשַׁקֵּר בְּאָת רְשִׁימָא קַדִּישָׁא. וּבְמָּה מְשַׁקֵּר בֵּיהּ. דְּעָיִיל לֵיהּ בִּרְשׁוּתָא אַחֲרָא, כְּמָה דְאַתְּ אָמֵר (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר, דְּאִקְרֵי (ירמיהו ב׳:י״ג) בּוֹרוֹת נִשְׁבָּרִים. דְּהָא עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִקְרוּ בּוֹרוֹת נִשְׁבָּרִים.","וּדְיִשְׂרָאֵל, אִקְרֵי בְּאֵר מְקוֹר מַיִם חַיִּים, דָּא רְשׁוּתָא קַדִּישָׁא, מְהֵימְנוּתָא קַדִּישָׁא. וְאִקְרֵי בְּאֵר מַבּוּעֵי דְּמַיִין צְלִילָן, נָפְקִין וְנַזְלִין מִנָהּ, כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:ט״ו) וְנוֹזְלִים מִן לְבָנוֹן. (משלי ה׳:ט״ו) וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךָ. וּכְתִיב (שיר השירים ד׳:ט״ו) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים. סִטְרָא אַחֲרָא אִקְרֵי בּוֹרוֹת נִשְׁבָּרִים. אֲשֶׁר לֹא יָכִילוּ הַמָּיִם. (ס\"א מהו, אלא ההוא וכו').","תָּא חֲזֵי, נַהֲרָא דְּנָגִיד וְנָפִיק, אַשְׁקֵי לְכָל גִּינְתָּא, (ס\"א ורוי לכל גינתא) וְרַוֵּי לְכָל אֲתָר וַאֲתָר, כְּמָה דְּאוֹקִימְנָא, עַד דְּמָלֵּי (נ\"א דמטי) לְהַהוּא אֲתָר בְּגִנְתָּא, דְּאִקְרֵי בְּאֵר מַיִם חַיִּים. וּמִתַּמָּן אִתְּזָנוּ עִלָּאִין וְתַתָּאִין, (נ\"א עלמין תתאין) כְּמָה דְאַתְּ אָמֵר (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד.","וְכָל אִינּוּן סִטְרִין דִּסְטָר שְׂמָאלָא, לָא מִשְׁתַּקְיָין מֵהַהוּא נְבִיעוּ דְּמַיִין נְבִיעִין, בְּגִין דְּאִינּוּן מִסִּטְרָא דִּשְׁאַר עַמִּין, וְאִקְרוּ בּוֹרוֹת נִשְׁבָּרִים. וּמַאן דִּמְשַׁקֵּר בִּשְׁמָא (נ\"א ברשימא) קַדִּישָׁא בְּהַהוּא סִטְרָא, אִתְדְּבַק בְּבוֹרוֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִילוּ הַמָּיִם, וְלָא עַיְילֵי לְתַמָּן. וְהַהוּא דְּזָכֵי לְנַטְרָא לֵיהּ, זָכֵי לְאִתְשַׁקְיָיא מֵהַהוּא נְבִיעוּ דְּנַחֲלָא (בעלמא דין) בְּעָלְמָא דְּאָתֵי, וְזָכֵי דְּאִתְמְלֵּי הַהוּא בְּאֵר עִלָּאָה, לְנַגְדָּא בִּרְכָאן לְעֵילָּא וְתַתָּא. זַכָּאָה אִיהוּ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עַל דָּא כְּתִיב, (ישעיהו נ״ח:י״א) וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו."],[[0,"ת\"ח מסטרא דהאי וכו':","בוא וראה מצד שפחה זו יצאו כמה רוחות חוקרי דין שמקטרגים כנגד ישראל, ובאים לקטרג עליהם. והקב\"ה עשה שמירה לישראל כמו אב הרוצה לשמור את בנו מכל מקרה. אמר הקב\"ה לישראל, כמה מקטרגים מוכנים כנגדכם, עסקו בעבודתי, ואני אהיה שומר אתכם מבחוץ. אתם תהיו נתונים בבתיכם מבפנים ותהיו ישנים במטתכם, ואני אהיה שומר עליכם מבחוץ. ומסביב מטותיכם."],[1,"ות\"ח בשעתא דאינון וכו':","ובוא וראה, בשעה שאלו מינים הרעים קרבים לפתחו של אדם, נושאים ראשם ומסתכלים בהשם הקדוש הנראה מבחוץ, שהוא \u0003שדי\u0004, המתעטר בעטרותיו, דהיינו הממשיך כל המוחין אל המלכות (כנ\"ל אות ע\"ו בהסולם). שם הזה שולט על כולם, ממנו יראים ובורחים, ואינם קרבים לפתחו של האדם."],[2,"א\"ל ר' יצחק וכו':","א\"ל ר\"י, אם כן, ירשום האדם שם הזה, \u0003שדי\u0004, בפתח הבית, ולא יותר, למה צריכים כל הפרשה שבמזוזה. אמר לו, יפה הוא, כי שם הזה, שדי, שהוא יסוד, אינו מתעטר, אלא באלו האותיות כולם הרשומים ברשימת המלך, דהיינו הנכתבים במזוזה, שה\"ס המוחין הנמשכים ע\"י אותו השם, וכשנכתבת כל הפרשה, אז מתעטר שם הזה בעטרותיו. והמלך, ז\"א, יוצא בכל צבאותיו, כולם רשומים ברשימת המלך, שהיא המלכות, אז מפחדים מפניו, ובורחים מפניו. כי אחר שמתגלה ע\"י שם שד\"י כל המוחין אל המלכות, אז מתהפך החלל להיות מזוזה. (כנ\"ל אות ע\"ז בהסולם)."],[3,"ת\"ח והיה שמא וכו':","בוא וראה \u0003והיה\u0004, של והיה אם שמוע, הוא שם קדוש, הויה, ממטה למעלה. כי כתוב תחילה \u0003ו\"ה\u0004 ואח\"כ \u0003י\"ה\u0004. שזה מורה על החכמה שבקו שמאל שאינה מאירה אלא ממטה למעלה. ועל כן, נרשם השם \u0003שדי\u0004 מבחוץ כנגד השם הזה. השם \u0003והי\"ה\u0004 מבפנים, \u0003ושדי\u0004 מבחוץ. כי השם שדי הוא המגביל את החכמה שבהשם והי\"ה, שלא תאיר אלא ממטה למעלה (כנ\"ל אות ע\"ז בהסולם ד\"ה ונתבאר) כדי שיהיה האדם נשמר מכל הצדדים מבפנים ומבחוץ. א\"ר אבא, כמה צבאות קדושים מוכנים בשעה ההיא שאדם מניח מזוזה לפתחו. כולם מכריזים ואומרים זה השער לה' וגו'. (כמ\"ש שם)."],[4,"זכאה חולקיהון דישראל וכו':","אשרי חלקם של ישראל, כי אז ניכרים ישראל, שהם בני המלך הקדוש, כי כולם רשומים ממנו, רשומים בגופם, ברושם הקדוש של ברית מילה. רשומים בלבושם, בעטוף של מצוה. רשומים בראשם בבתים של התפלין, שהם שם של אדונם. רשומים בידיהם, ברצועות של קדושה. רשומים בנעליהם בנעל של מצוה, דהיינו בקרבן פסח שנאמר נעליכם ברגליכם רשומים בבתיהם, במזוזה בפתח. בכל דבר הם רשומים שהם בני מלך העליון, אשרי חלקם."],[5,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, א\"ר אבא, מה שכתוב, אותי עזבו מקור מים חיים לחצוב להם בארות וגו'. \u0003אותי עזבו.\u0004 זה הוא שמשקר באות רושם הקדוש. ובמה משקר בו. היינו שמכניסו ברשות אחר. כש\"א, ובעל בת אל נכר, שנקראים בורות נשברים. כי העמים עובדי עבודה זרה נקראים בורות נשברים."],[6,"ודישראל אקרי באר וכו':","ושל ישראל, שהיא המלכות, נקראת, באר מקור מים חיים. זהו רשות הקדוש של האמונה הקדושה, שהיא המלכות ונקראת באר מבועים שמים צלולים יוצאים ונוזלים ממנה, כש\"א, \u0003ונוזלים\u0004 מן לבנון. וכן, \u0003ונוזלים\u0004 מתוך בארך וכתוב, מעין גנים באר מים חיים. הסטרא אחרא נקרא, בורות נשברים אשר לא יכילו המים."],[7,"ת\"ח נהרא דנגיד וכו':","בוא וראה, נהר הנמשך ויוצא, שהוא יסוד, משקה לכל הגן, שהוא מלכות, ומרוה לכל מקום ומקום, כמו שהעמדנו, עד שממלא לאותו מקום של הגן, הנקרא באר מים חיים, שהוא יסוד המלכות, שמשם נזונים העליונים ותחתונים. כמש\"א, ומשם יפרד וגו'."],[8,"וכל אינון סטרין וכו':","וכל אלו הצדדים של צד שמאל, אינם נשקים, מאותו מבוע מים נובעים, משום שהם מצד שאר העמים, ונקראים בורות נשברים. ומי שמשקר ברושם הקדוש בצד ההוא, מתדבק בבורות נשברים אשר לא יכילו המים, שאינם נכנסים שם. ואותו שזכה לשמרו זוכה להישקות מאותו מבוע הנחל, בעולם הבא. וזוכה שתתמלא הבאר ההיא העליונה שתמשכנה ברכות למעלה ולמטה. אשרי הוא בעולם הזה ובעולם הבא. על זה כתוב, והיית כגן רוה וכמוצא מים אשר לא יכזבו מימיו."]],[[0,"","בֹּא וּרְאֵה, מִצַּד הַשִּׁפְחָה הַזּוֹ יוֹצְאִים כַּמָּה שׁוֹמְרֵי חֹק בַּעֲלֵי דִינִים, מְקַטְרְגִים כְּנֶגֶד יִשְׂרָאֵל כְּדֵי לְקַטְרֵג עֲלֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְיִשְׂרָאֵל שְׁמִירָה כְּאָב שֶׁרוֹצֶה לִשְׁמֹר אֶת בְּנוֹ מֵהַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, כַּמָּה מְקַטְרְגִים מְזֻמָּנִים כְּנֶגְדְּכֶם, הִשְׁתַּדְּלוּ בַעֲבוֹדָתִי, וַאֲנִי אֶשְׁמֹר אֶתְכֶם מִבַּחוּץ, וְאַתֶּם תִּהְיוּ זְמִינִים בְּבָתֵּיהֶם בִּפְנִים וִישֵׁנִים בְּמִטּוֹתֵיכֶם, וַאֲנִי אֶשְׁמֹר אֶתְכֶם מִבַּחוּץ וּסְבִיב מִטּוֹתֵיכֶם."],[1,"","וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁאוֹתָם מִינִים רָעִים קְרֵבִים לְפִתְחוֹ שֶׁל הָאָדָם, זוֹקְפִים רֹאשׁ וּמִסְתַּכְּלִים בַּשֵּׁם הַקָּדוֹשׁ שֶׁנִּרְאֶה בַחוּץ, שֶׁהוּא שַׁדַּי, שֶׁמִּתְעַטֵּר בְּעַטְרוֹתָיו. שֵׁם זֶה שׁוֹלֵט עַל כֻּלָּם, מִמֶּנּוּ הֵם פּוֹחֲדִים וּבוֹרְחִים, וְלֹא קְרֵבִים לְפֶתַח הָאָדָם."],[2,"","אָמַר לוֹ רַבִּי יִצְחָק, אִם כָּךְ, שֶׁיִּרְֹשם הָאָדָם שֵׁם זֶה בְּפֶתַח הַבַּיִת וְלֹא יוֹתֵר. לָמָּה כָּל הַפָּרָשָׁה? אָמַר לוֹ, יָפֶה הוּא, שֶׁהֲרֵי שֵׁם זֶה לֹא מִתְעַטֵּר אֶלָּא בְּאוֹתָן אוֹתִיּוֹת כֻּלָּן, רְשׁוּמוֹת בְּרֹשֶׁם הַמֶּלֶךְ, וּכְשֶׁנִּכְתֶּבֶת כָּל הַפָּרָשָׁה, אָז שֵׁם זֶה מִתְעַטֵּר בְּעַטְרוֹתָיו, וְיוֹצֵא הַמֶּלֶךְ עִם כָּל חֵילוֹתָיו, כֻּלָּם רְשׁוּמִים בְּרֹשֶׁם הַמֶּלֶךְ, וְאָז פּוֹחֲדִים מִמֶּנּוּ וּבוֹרְחִים מִפָּנָיו."],[3,"","בֹּא וּרְאֵה, וְהָיָ\"ה שֵׁם קָדוֹשׁ מִלְּמַטָּה לְמַעְלָה, וְעַל זֶה שַׁדַּי נִרְשָׁם מִבַּחוּץ כְּנֶגֶד שֵׁם זֶה. וְהָיָ\"ה מִבִּפְנִים, שַׁדַּ\"י מִבַּחוּץ. שֶׁיִּהְיֶה הָאָדָם שָׁמוּר מִכָּל הַצְּדָדִים, מִבִּפְנִים וּמִבַּחוּץ. אָמַר רַבִּי אַבָּא, כַּמָּה חֲיָלוֹת קְדוֹשִׁים זְמִינִים בְּאוֹתָהּ שָׁעָה שֶׁמַּנִּיחַ אָדָם מְזוּזָה בַּשַּׁעַר שֶׁלּוֹ, כֻּלָּם מַכְרִיזִים וְאוֹמְרִים: [תהלים קיח] זֶה הַשַּׁעַר לַה' וְגוֹ'."],[4,"","אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, אָז נוֹדָעִים יִשְׂרָאֵל שֶׁהֵם בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי כֻּלָּם נִרְשְׁמוּ מִמֶּנּוּ. נִרְשְׁמוּ בְגוּפָם בְּרֹשֶׁם קָדוֹשׁ, נִרְשְׁמוּ בִלְבוּשָׁם בְּעִטּוּפָם שֶׁל מִצְוָה, נִרְשְׁמוּ בְרָאשֵׁיהֶם בְּבָתֵּי הַתְּפִלִּין בְּשֵׁם רִבּוֹנָם, נִרְשְׁמוּ בִידֵיהֶם בִּרְצוּעוֹת הַקְּדֻשָּׁה, נִרְשְׁמוּ בְנַעֲלֵיהֶם בְּנַעֲלֵי מִצְוָה, נִרְשְׁמוּ בַחוּץ בִּזְרִיעָה בִּקְצִירָה, נִרְשְׁמוּ בְּבָתֵּיהֶם בִּמְזוּזַת הַפֶּתַח. רְשׁוּמִים בַּכֹּל שֶׁהֵם בְּנֵי הַמֶּלֶךְ הָעֶלְיוֹן. אַשְׁרֵי חֶלְקָם."],[5,"","עֵד שֶׁהָיוּ הוֹלְכִים אָמַר רַבִּי אַבָּא, מַה זֶּה שֶׁכָּתוּב [ירמיה ב] אֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים לַחְצֹב לָהֶם בּארוֹת וְגוֹ'? אֹתִי עָזְבוּ – זֶהוּ מִי שֶׁמְּשַׁקֵּר בְּאוֹת הָרֹשֶׁם הַקָּדוֹשׁ. וּבַמֶּה מְשַׁקֵּר בּוֹ? שֶׁמַּכְנִיסוֹ בִּרְשׁוּת אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר [מלאכי ב] וּבָעַל בַּת אֵל נֵכָר, שֶׁנִּקְרֵאת בּארוֹת נִשְׁבָּרִים. שֶׁהֲרֵי עַמִּים עוֹבְדֵי עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת נִקְרְאוּ בּוֹרוֹת נִשְׁבָּרִים."],[6,"","וְשֶׁל יִשְׂרָאֵל נִקְרֵאת בְּאֵר מְקוֹר מַיִם חַיִּים, זוֹ הָרְשׁוּת הַקְּדוֹשָׁה, הָאֱמוּנָה הַקְּדוֹשָׁה, וְנִקְרֵאת בְּאֵר נוֹבַעַת, שֶׁמַּיִם צְלוּלִים יוֹצְאִים וְנוֹזְלִים מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר [שיר ד] וְנֹזְלִים מִן לְבָנוֹן. [משלי ה] וְנוֹזְלִים מִתּוֹךְ בְּאֵרְךְ. וְכָתוּב [שיר ד] מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים. הַצַּד הָאַחֵר נִקְרָא בֹּארֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִלוּ הַמָּיִם. [מהו, ' אלא ההוא וכו']."],[7,"","בֹּא וּרְאֵה, נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מַשְׁקֶה לְכָל הַגָּן [ומרוה לכל הגן] וּמַרְוֶה לְכָל מָקוֹם וּמָקוֹם, כְּמוֹ שֶׁבֵּאַרְנוּ, עַד שֶׁמְּמַלֵּא [שמגיע] אוֹתוֹ מָקוֹם בַּגָּן, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים. וּמִשָּׁם נִזּוֹנִים עֶלְיוֹנִים וְתַחְתּוֹנִים [עולמות תחתונים], כְּמוֹ שֶׁנֶּאֱמַר [בראשית ב] וּמִשָּׁם יִפָּרֵד."],[8,"","וְכָל אוֹתָם צְדָדִים שֶׁל צַד שְׂמֹאל לֹא מֻשְׁקִים מֵאוֹתָהּ נְבִיעַת הַמַּיִם הַנּוֹבְעִים, מִשּׁוּם שֶׁהֵם מִצַּד שְׁאָר הָעַמִּים, וְנִקְרְאוּ בּארֹת נִשְׁבָּרִים. וּמִי שֶׁמְּשַׁקֵּר בַּשֵּׁם [ברשם] הַקָּדוֹשׁ בְּאוֹתוֹ צַד, נִדְבָּק בְּבֹארֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִלוּ הַמָּיִם, וְלֹא נִכְנָסִים לְשָׁם. וְאוֹתוֹ שֶׁזּוֹכֶה לִשְׁמֹר אוֹתוֹ, זוֹכֶה לִהְיוֹת מֻשְׁקֶה מֵאוֹתוֹ מַבּוּעַ שֶׁל הַנַּחַל [בעולם הזה] בָּעוֹלָם הַבָּא, וְזוֹכֶה שֶׁתִּתְמַלֵּא אוֹתָהּ בְּאֵר עֶלְיוֹנָה לְהַשְׁפִּיעַ בְּרָכוֹת לְמַעְלָה וּלְמַטָּה. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל זֶה כָּתוּב, [ישעיה נח] וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו."]]],[["וַוי לְמַאן דִּמְשַׁקֵּר בִּרְשִׁימָא קַדִּישָׁא, דְּהָא מְשַׁקֵּר בִּשְׁמָא עִלָּאָה. וְלֹא עוֹד, אֶלָּא דְּגָרִים לְהַאי בְּאֵר דְּלָא אִתְבָּרְכָא, וְקָרֵינָן עָלֵיהּ (דברים כ״ב:י״ט) כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. בְּתוּלַת יִשְׂרָאֵל דַּיְיקָא. וְאוֹקְמֵיהּ רִבִּי שִׁמְעוֹן בְּאַתְרֵיהּ, מַאן דְּשַׁוֵּי תִּסְקוֹפֵי מִלִּין עַל אִנְתְּתֵיהּ קַדְמִיתָא, וְאַפִּיק עֲלָהּ שׁוּם בִּישׁ, כְּמָה דְּאַפִּיק לְעֵילָּא, דִּכְתִּיב כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל סְתָם.","וְאַזְלָא הָא, כִּי הָא דְּאָמַר רִבִּי חִיָּיא אָמַר רִבִּי יוֹסִי, בְּתוּלָה יָרְתָא שֶׁבַע בְּרָכוֹת, דְּאִתְבָּרְכָא בְּשֶׁבַע, בְּגִין דִּבְתּוּלַת יִשְׂרָאֵל יָרְתָא שֶׁבַע בִּרְכָן, וְעַל דָּא אִתְקְרֵי בַּת שֶׁבַע.","וְאִנְתְּתָא אַחֲרָא, מַאן בִּרְכָאן דִּילָהּ. בִּרְכָתָא דְּבֹעַז וְרוּת, כְּמָה דְאַתְּ אָמֵר, (רות ד׳:י״א) וַיֹּאמְרוּ כָּל הָעָם אֲשֶׁר בַּשַּׁעַר וְהַזְּקֵנִים עֵדִים יִתֵּן יְיָ' אֶת וְגוֹ', דְּוַדַּאי בְּתוּלָה בְּז' אִתְבָּרְכָא, וְלָא אִתְּתָא אַחֲרָא בְּרָזָא דָּא. כֵּיוָן דְּמָטוּ בַּחֲקָל חַד, חָמוּ אִילָנִין, יָתְבוּ תְּחוֹתַיְיהוּ. אָמַר רִבִּי אַבָּא, הָא צָחוּתָא דְּמִלֵּי דְּאוֹרַיְיתָא. נְתִיב.","פָּתַח וְאָמַר, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְגוֹ'. וְהָיָה בְּיוֹם הַהוּא, מַאן בַּיּוֹם הַהוּא. אֶלָּא הַהוּא יוֹמָא דְּאִתְיְדַע לְקוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאַתְּ אָמֵר (זכריה י״ד:ד׳) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ'. תּוּ, בַּיוֹם הַהוּא, כְּמָה דְאַתְּ אָמֵר (יחזקאל ל״ח:י״ח) בְּיוֹם בֹּא גּוֹג עַל אַדְמַת יִשְׂרָאֵל.","יִתָּקַע בְּשׁוֹפָר גָּדוֹל. מַה לָן בֵּיהּ, אִי הוּא רַב אוֹ זְעֵיר. אֶלָּא הַהוּא שׁוֹפָר עִלָּאָה, דְּבֵיהּ נָפְקִין עַבְדִּין לְחֵירוּ תָּדִיר, וְהַאי אִיהוּ יוֹבְלָא, דְּיוֹבְלָא עִלָּאָה וְרַבְרְבָא הוּא. וְכַד הַאי אִתְּעַר, כָּל חֵירוּ דְּעָלְמִין מִתְעָרִין בֵּיהּ, וְהַהוּא אִקְרֵי שׁוֹפָר גָּדוֹל.","וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. הָאֲבוּדִים מִבָּעֵי לֵיהּ, אוֹ הַנֶּאֱבָדִים, מַאי הָאוֹבְדִים. הָאוֹבְדִים מַמָּשׁ, בְּגִין דְּאִינּוּן בְּאַרְעָא אַחֲרָא, וּמַאן דְּשָׁארִי בְּאַרְעָא אַחֲרָא, יָנִיק מֵרְשׁוּתָא אַחֲרָא וּכְאִלּוּ לָא שַׁרְיָא בִּמְהֵימְנוּתָא, בְּגִין כָּךְ אוֹבְדִים אִקְרוּן. אוֹבְדִים אִינּוּן בְּכָל סִטְרִין, דְּכַד יִשְׂרָאֵל שַׁרְיָין בְּאַרְעָא קַדִּישָׁא, זַכָּאִין, זַכָּאִין תָּדִיר בְּכֹלָּא, זַכָּאן לְעֵילָּא וְתַתָּא.","דָּבָר אַחֵר וּבָאוּ הָאוֹבְדִים, מַאן אִינּוּן. אִלֵּין צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל. דְּאִקְרוּן אוֹבְדִים. מְנָלָן. כְּנֶסֶת יִשְׂרָאֵל, דִּכְתִּיב, (ירמיהו ט׳:י״א) עַל מַה אָבְדָה הָאָרֶץ, אֲבוּדָה אוֹ נֶאֱבֶדֶת לָא כְּתִיב, אֶלָּא אָבְדָה הָאָרֶץ, דָּא כְּנֶסֶת יִשְׂרָאֵל. צַדִּיק, דִּכְתִּיב, (ישעיהו נ״ז:א׳) הַצַּדִיק אָבָד, אָבוּד אוֹ נֶאֱבַד לָא כְּתִיב, אֶלָּא אָבָד, וְהָא אוֹקְמוּהָ.","וְאִי תֵּימָא, וּבָאוּ, מֵאָן אֲתָר אַתְיָין אִלֵּין אוֹבְדִים. אֶלָּא, כְּנֶסֶת יִשְׂרָאֵל מִן גָּלוּתָא. צַדִּיק, כְּמָה דְּאוֹקְמוּהָ, דִּכְתִּיב (תהילים קכ״ו:א׳) בְּשׁוּב יְיָ' אֶת שִׁיבַת צִיּוֹן, בְּגִין דְּיֵיתוּב לְאַתְרֵיהּ, וְיֵיתֵי לְאִתְחַבְּרָא בִּכְנֶסֶת יִשְׂרָאֵל. וְעַל דָּא, וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. וְהִשְׁתַּחֲווּ לַיְיָ' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלַיִם, מַאי קָא מַיְירֵי. אֶלָּא מִלָּה דָּא דְּהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם, כִּבְיָכוֹל, יִשְׂרָאֵל לָא יִפְּקוּן מִן גָּלוּתָא, אֶלָּא בִּשְׁכִינְתָּא, כְּמָה דְּאוֹקְמוּהָ, וְאִינּוּן נִדָּחִים הִשְׁתַּחֲווּ לַיְיָ'.","תּוּ אָמַר רִבִּי אַבָּא, כְּתִיב, (תהילים קכ״א:ח׳) יְיָ' יִשְׁמוֹר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. יִשְׁמָר צֵאתְךָ תִּינַח. אֶלָּא וּבוֹאֶךָ, מַאי קָא מַיְירֵי, דְּהָא מַאן דְּעָאל לְבֵיתֵיהּ לָא מִסְתָּפֵי. אֶלָּא הַאי בַּר נָשׁ דְּשַׁוֵּי רְשִׁימָא קַדִּישָׁא לְבֵיתֵיהּ, בְּמִלִּין דִּשְׁמָא עִלָּאָה, הַאי אִתְנְטִיר מִכֹּלָּא. כַּד נָפִיק הַהוּא דְּמָדוֹרֵיהּ לְתַרְעָא דְּבֵיתֵיהּ, זָקִיף וְחָמֵי רְשִׁימָא קַדִּישָׁא, וְעָיִיִן (ס\"א נעיץ) בְּפִתְחֵיהּ. כַּד נָפִיק בַּר נָשׁ, הוּא אוֹזִיף לֵיהּ, וְנָטִיר לֵיהּ. כַּד עָיִּיל לְבֵיתֵיהּ, הוּא אַכְרִיז קַמֵּיהּ, אִזְדָּהֲרוּ בִּיקָרָא דְּדִיּוּקְנָא דְּמַלְכָּא קַדִּישָׁא. וְכָל דָּא, בְּגִין הַהוּא רְשִׁימָא דִּשְׁמָא קַדִּישָׁא, דְּאִתְרְשִׁים בְּתַרְעֵיהּ.","וְלָאו דַּי לֵיהּ לְבַּר נָשׁ דְּאִתְנְטַר בְּבֵיתֵיהּ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לֵיהּ כַּד עָיִּיל, וְכַד נָפִיק. דִּכְתִּיב, יְיָ' יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי."],[[0,"ווי למאן דמשקר וכו':","אוי למי שמשקר ברושם הקדוש, כי משקר בשם העליון, ולא עוד אלא שגורם לאותה הבאר, שהיא מלכות, שלא תתברך, וקוראים עליו, כי הוציא שם רע על בתולת ישראל. בתולת ישראל הוא בדיוק, דהיינו המלכות שנקראת בתולת ישראל. בסוד שחוזרת תמיד להיות בתולה. והעמיד ר\"ש במקומו, שמי שמשים עלילת דברים על אשתו הראשונה ומוציא עליה שם רע, הוא דומה כמו שמוציא שם רע למעלה, במלכות, שכתוב, כי הוציא שם רע על בתולת ישראל, סתם. שרומז על המלכות."],[1,"ואזלא הא כי וכו':","וזה הולך על דרך שאמר ר' חייא, בשם ר' יוסי, שבתולה יורשת שבע ברכות, כי מתברכת בשבע ספירות, משום שבתולת ישראל, שהיא המלכות, יורשת שבע ברכות שה\"ס שבע ספירות, ועל כן נקראת בת שבע."],[2,"ואנתתא אחרא מאן וכו':","שואל, ואשה אחרת, דהיינו אשה אלמנה או גרושה, שנשאת לאיש, מאין הן הברכות שלה. ומשיב, מן הברכות של בעז ורות. כש\"א, ויאמרו כל העם אשר בשער והזקנים עדים יתן ה' את וגו'. כי ודאי רק בתולה מתברכת בשבע ברכות, ואין אשה אתרת בסוד זה. כיון שהגיעו לשדה אחד ראו אילנות. ישבו תחתיהם. אמר ר' אבא הרי צחות לדברי תורה כאן. נשב."],[3,"פתח ואמר והיה וגו':","פתח ואמר, והיה ביום ההוא יתקע בשופר גדול ובאו האובדים בארץ אשור והנדחים בארץ מצרים וגו'. \u0003והיה ביום ההוא\u0004, מי הוא ביום ההוא. ומשיב, אלא יום ההוא הנודע אל הקב\"ה, כש\"א והיה יום אחד הוא יודע לה'. עוד. ביום ההוא, הוא כש\"א ביום בא גוג על אדמת ישראל."],[4,"יתקע בשופר גדול:","שואל, מה לנו בו, אם הוא שופר גדול או קטן. ומשיב, אלא הוא שופר עליון, שבו יוצאים תמיד עבדים לחירות, וזה הוא יובל, דהיינו בינה, שיובל עליון וגדול הוא, וכשזה מתעורר להשפיע, כל חירות העולמות מתעוררים בו, וההוא, נקרא שופר גדול."],[5,"ובאו האובדים בארץ אשור:","שואל, האבודים היה צריך לומר, או הנאבדים, מהו האובדים. ומשיב, האובדים ממש, משום שהם בארץ אחרת, ומי ששורה בארץ אחרת יונק מרשות אחרת וכאלו אינו שורה באמונה, משום זה הם נקראים אובדים שאבדו האמונה, אובדים הם בכל הצדדים, למעלה ולמטה. כי כשישראל שורים בארץ הקדושה, הם צדיקים וזוכים תמיד בכל, למעלה, בשפע ז\"א. ולמטה, בשפע המלכות. וכשהם בחוץ לארץ אובדים כל זה."],[6,"ד\"א ובאו האובדים וכו':","פירוש אחר. ובאו האובדים, מי הם. אלו הם צדיק, שהוא יסוד, וכנסת ישראל, שהיא מלכות, הנקראים אובדים. מאין לנו. בכנסת ישראל כתוב, על מה אבדה הארץ, דהיינו המלכות הנקראת ארץ. אבודה או נאבדת לא כתוב, אלא אבדה הארץ שהיא כנסת ישראל. \u0003בצדיק\u0004 כתוב, הצדיק אבד, אבוד או נאבד לא כתוב, אלא אבד. הרי שצדיק וכנסת ישראל נקראים אובדים. כמו שהעמדנו. (וישב אות ס\"ז)."],[7,"ואי תימא ובאו וכו':","ואם תאמר, \u0003ובאו\u0004, מאיזה מקום באים אלו אובדים, הצדיק וכנסת ישראל שהם יסוד ומלכות. ומשיב, אלא כנסת ישראל באה מן הגלות. צדיק, כמו שהעמידו שכתוב בשוב ה' את שיבת ציון, שהוא יסוד הנקרא ציון, כדי שישוב למקומו, ויבא להתחבר עם כנסת ישראל. ועל כן ובאו האובדים מארץ אשור. שואל, והשתחוו לה' בהר הקדש בירושלים. מה פירושו, אם האובדים הם יסוד ומלכות. ומשיב, אלא דבר זה, והשתחוו לה' וגו', סובב על הנדחים בארץ מצרים, שהם ישתחוו לה', כי ישראל אינם יוצאים מן הגלות אלא כביכול עם השכינה, כמו שהעמדנו, ואלו נדחים השתחוו לה'. שהוא השכינה."],[8,"תו אמר ר' אבא וכו':","עוד אמר ר\"א, כתוב, ה' ישמר צאתך ובואך מעתה ועד עולם. שואל, \u0003ישמר צאתך\u0004, נכון. אבל \u0003ובואך\u0004, מה פירושו, הרי מי שנכנס לביתו אינו מפחד, שיהיה צריך לשמירה. ומשיב, אלא אדם הזה המשים רושם קדוש לביתו בדברי שם העליון, דהיינו המזוזה, הוא משומר מכל. כשיוצא אותו אדם ממדורו לשער הבית, נושא עיניו ורואה הרושם הקדוש, ומעיין בפתחו. כשיוצא האדם הוא מלוה אותו ושומרו. כשנכנס האדם הוא מכריז לפניו, הזהרו בכבוד צורת המלך הקדוש. וכל זה הוא, משום אותו הרושם של השם הקדוש שנרשם בפתחו."],[9,"ולאו די ליה וכו':","ולא די לו לאדם שנשמר בביתו, אלא שהקב\"ה שומר אותו כשנכנס וכשיוצא, שכתוב, ה' ישמר צאתך ובואך מעתה ועד עולם. אשרי הם ישראל בעולם הזה ובעולם הבא."]],[[0,"","אוֹי לְמִי שֶׁמְּשַׁקֵּר בָּרֹשֶׁם הַקָּדוֹשׁ, שֶׁהֲרֵי מְשַׁקֵּר בַּשֵּׁם הָעֶלְיוֹן, וְלֹא עוֹד, אֶלָּא שֶׁגּוֹרֵם לַבְּאֵר הַזֹּאת שֶׁלֹּא תִתְבָּרֵךְ, וְקוֹרְאִים עָלָיו [דברים כב] כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. בְּתוּלַת יִשְׂרָאֵל דַּוְקָא. וּבֵאֲרוֹ רַבִּי שִׁמְעוֹן בִּמְקוֹמוֹ, מִי שֶׁשָּׂם עֲלִילוֹת דְּבָרִים עַל אִשְׁתּוֹ הָרִאשׁוֹנָה וּמוֹצִיא עָלֶיהָ שֵׁם רַע – כְּמוֹ שֶׁהוֹצִיא לְמַעְלָה, שֶׁכָּתוּב כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל סְתָם."],[1,"","וְהָלַךָ זֶה, כְּמוֹ זֶה שֶׁאָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, בְּתוּלָה יָרְשָׁה שֶׁבַע בְּרָכוֹת, שֶׁמִּתְבָּרֶכֶת בְּשֶׁבַע, מִשּׁוּם שֶׁבְּתוּלַת יִשְׂרָאֵל יָרְשָׁה שֶׁבַע בְּרָכוֹת, וְעַל זֶה נִקְרֵאת בַּת שֶׁבַע."],[2,"","וְאִשָּׁה אַחֶרֶת, מִי הַבְּרָכוֹת שֶׁלָּהּ? בִּרְכַּת בּעַז וְרוּת, כְּמוֹ שֶׁנֶּאֱמַר [רות ד] וַיּאמְרוּ כָּל הָעָם אֲשֶׁר בַּשַּׁעַר וְהַזְּקֵנִים עֵדִים יִתֵּן ה' אֶת וְגוֹ'. שֶׁוַּדַּאי בְּתוּלָה מִתְבָּרֶכֶת בְּשֶׁבַע, וְלֹא אִשָּׁה אַחֶרֶת בְּסוֹד זֶה. כֵּיוָן שֶׁהִגִּיעוּ לְשָׂדֶה אֶחָד, רָאוּ אִילָנוֹת וְיָשְׁבוּ תַחְתֵּיהֶם. אָמַר רַבִּי אַבָּא, הֲרֵי צַחוּת שֶׁל דִּבְרֵי תוֹרָה. נֵשֵׁב."],[3,"","פָּתַח וְאָמַר, [ישעיה כז] וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְגוֹ'. וְהָיָה בַּיּוֹם הַהוּא, מַה זֶּה בַּיּוֹם הַהוּא? אֶלָּא אוֹתוֹ יוֹם הַיָּדוּעַ לַקָּדוֹשׁ־בָּרוּךְ־הוּא, כְּמוֹ שֶׁנֶּאֱמַר [זכריה יד] וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה'. עוֹד בַּיּוֹם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר [יחזקאל לח] בְּיוֹם בֹּא גּוֹג עַל אַדְמַת יִשְׂרָאֵל."],[4,"","יִתָּקַע בְּשׁוֹפָר גָּדוֹל. מַה לָּנוּ בּוֹ אִם הוּא גָּדוֹל אוֹ קָטָן? אֶלָּא אוֹתוֹ הַשּׁוֹפָר הָעֶלְיוֹן שֶׁבּוֹ יוֹצְאִים הָעֲבָדִים לַחֵרוּת תָּמִיד, וְזֶהוּ הַיּוֹבֵל, שֶׁהַיּוֹבֵל עֶלְיוֹן וְגָדוֹל הוּא. וּכְשֶׁזֶּה מִתְעוֹרֵר, כָּל הַחֵרוּת שֶׁל הָעוֹלָמוֹת מִתְעוֹרְרִים בּוֹ, וְהַהוּא נִקְרָא שׁוֹפָר גָּדוֹל."],[5,"","וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר. הָאֲבוּדִים צָרִיךְ הָיָה לוֹ לִכְתֹּב!, אוֹ הַנֶּאֱבָדִים. מַה זֶּה הָאֹבְדִים? הָאוֹבְדִים מַמָּשׁ, מִשּׁוּם שֶׁהֵם בְּאֶרֶץ אַחֶרֶת, וּמִי שֶׁשָּׁרוּי בְּאֶרֶץ אַחֶרֶת יוֹנֵק מֵרְשׁוּת אַחֶרֶת, וּכְאִלּוּ לֹא שָׁרוּי בָּאֱמוּנָה, מִשּׁוּם כָּךְ נִקְרָאִים אוֹבְדִים. הֵם אוֹבְדִים בְּכָל הַצְּדָדִים, שֶׁכַּאֲשֶׁר יִשְׂרָאֵל שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה, הֵם צַדִּיקִים, צַדִּיקִים תָּמִיד בַּכֹּל, צַדִּיקִים לְמַעְלָה וּלְמַטָּה."],[6,"","דָּבָר אַחֵר וּבָאוּ הָאֹבְדִים, מִי הֵם? אֵלּוּ הַצַּדִּיק וּכְנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרָאִים אוֹבְדִים. מִנַּיִן לָנוּ? כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב [ירמיה ט] עַל מָה אָבְדָה הָאָרֶץ. לֹא כָתוּב אֲבוּדָה אוֹ נֶאֱבֶדֶת, אֶלָּא אָבְדָה הָאָרֶץ, זוֹ כְּנֶסֶת יִשְׂרָאֵל. הַצַּדִּיק, שֶׁכָּתוּב [ישעיה נז] הַצַּדִּיק אָבָד. לֹא כָתוּב אָבוּד אוֹ נֶאֱבָד, אֶלָּא אָבָד, וַהֲרֵי פֵּרְשׁוּהָ."],[7,"","וְאִם תֹּאמַר, וּבָאוּ, מֵאֵיזֶה מָקוֹם בָּאִים הָאוֹבְדִים הַלָּלוּ? אֶלָּא כְּנֶסֶת יִשְׂרָאֵל, מִן הַגָּלוּת. וְהַצַּדִּיק, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב [תהלים קכו] בְּשׁוּב ה' אֶת שִׁיבַת צִיּוֹן, כְּדֵי שֶׁיָּשׁוּב לִמְקוֹמוֹ וְיָבֹא לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. וְעַל כֵּן, וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר, וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלם. מַה זֶּה אוֹמֵר? אֶלָּא הַדָּבָר הַזֶּה שֶׁהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם, כִּבְיָכוֹל לֹא יָצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת אֶלָּא עִם הַשְּׁכִינָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְאוֹתָם נִדָּחִים הִשְׁתַּחֲווּ לַה'."],[8,"","עוֹד אָמַר רַבִּי אַבָּא, כָּתוּב [שם קכא] ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. יִשְׁמָר צֵאתְךְ בָּרוּר, אֶלָּא וּבוֹאֶךְ מַה זֶּה אוֹמֵר? שֶׁהֲרֵי מִי שֶׁנִּכְנָס לְבֵיתוֹ אֵינוֹ פּוֹחֵד. אֶלָּא הָאָדָם הַזֶּה שֶׁשָּׂם רֹשֶׁם קָדוֹשׁ לְבֵיתוֹ בַּדְּבָרִים שֶׁל הַשֵּׁם הָעֶלְיוֹן, זֶה נִשְׁמָר מֵהַכֹּל. וּכְשֶׁיּוֹצֵא הַהוּא שֶׁמְּדוֹרוֹ לְשַׁעַר בֵּיתוֹ, זוֹקֵף וְרוֹאֶה אֶת הַשֵּׁם הַקָּדוֹשׁ וּמְעַיֵּן [נעוץ] בְּפִתְחוֹ. כְּשֶׁיּוֹצֵא הָאָדָם, הוּא מְלַוֶּה אוֹתוֹ וְשׁוֹמֵר אוֹתוֹ. כְּשֶׁנִּכְנָס לְבֵיתוֹ הוּא מַכְרִיז לְפָנָיו: הִזָּהֲרוּ בַדְּיוֹקָן שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ! וְכָל זֶה מִשּׁוּם אוֹתוֹ הָרֹשֶׁם שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּרְשָׁם בַּשַּׁעַר שֶׁלּוֹ."],[9,"","וְלֹא דַי לוֹ לָאָדָם שֶׁנִּשְׁמָר בְּבֵיתוֹ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ כְּשֶׁנִּכְנָס וּכְשֶׁיּוֹצֵא, שֶׁכָּתוּב ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."]]],[["תָּא חֲזֵי, הַאי רוּחָא בִּישָׁא דְּשָׁארִי בֵּין תַּרְעֵי. וַוי לֵיהּ לְבַּר נָשׁ, דְּלָא יָדַע לְאִזְדַּהֲרָא מִנֵּיהּ, וְלָא רָשִׁים לְפִתְחָא דְּבֵיתֵיהּ שְׁמָא עִלָּאָה קַדִּישָׁא, דְּיִשְׁתְּכַח עִמֵּיהּ. דְּהָא אִית לֵיהּ תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ שַׁמָּשִׁין בִּישִׁין מְקַטְרְגִין, כָּל חַד מְשַׁמֵשׁ יוֹמֵיהּ, וְכֻלְּהוּ מִשְׁתַּכְּחֵי עִמֵּיהּ כָּל יוֹמֵי שַׁתָּא, וּמְקַטְרְגֵי בֵּיהּ לְעֵילָּא וְתַתָּא. וְכֻלְּהוּ מִשְׁתַּכְּחֵי בֵּיהּ בִּימָמָא וּבְלֵילְיָא. בִּימָמָא, לְקַטְרְגָא לֵיהּ. בְּלֵילְיָא, לְצַעֲרָא לֵיהּ בְּחֶלְמֵיהּ.","כַּד נָפִיק לְקַטְרְגָא לֵיהּ, כַּד עָאל, שַׁוְּויָן יְדַיְיהוּ עָלֵיהּ דְּכִתְפֵיהּ, וְאַמְרִין לֵיהּ, וַוי לֵיהּ לִפְלַנְיָּא דְּנָפַק מֵרְשׁוּתָא דְּמָארֵיהּ. וַוי לֵיהּ לִפְלַנְיָּא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. בְּגִין כָּךְ בָּעָאן בְּנֵי מְהֵימְנוּתָא, לְמֶהֱוֵי רְשִׁימִין בְּכֹלָּא, לְמֶהֱוֵי רְשִׁימִין בִּרְשִׁימָא דְּמָארֵיהוֹן, לִאִזְדַּעְזְעָא מִנַּיְיהוּ כָּל סִטְרִין זִינִין בִּישִׁין, לְמֶהֱוֵי נְטִירִין בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. זַכָּאִין חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, עָלַיְיהוּ כְּתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'.","(דברים ו׳:ה׳) וְאָהַבְתָּ אֵת יְיָ' אֱלֹהֶיךָ. רִבִּי יוֹסִי פָּתַח, (ישעיהו נ״ב:ה׳) וְעַתָּה מַה לִי פֹה נְאֻם יְיָ' כִּי לֻקַּח עַמִּי חִנָּם וְגוֹ'. תָּא חֲזֵי, רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּיִשְׂרָאֵל אַף עַל גַּב דְּחוֹבַיְיהוּ גָּרְמוּ לְאִסְתַּלְּקָא מִבֵּינַיְיהוּ, וְאִתְבָּדָּרוּ בֵּינֵי עַמָמַיָא, הוּא תָּבַע עֶלְבּוֹנָא דִּלְהוֹן. וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל שָׁרָאן בְּאַרְעֲהוֹן, קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּגִנְתֵּיהּ, וְקָרִיב לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, וְשָׁמַע קַלֵּיהוֹן, וְאִשְׁתְּבַּח בְּהוּ.","כֵּיוָן דְּגַרְמוּ חוֹבַיְיהוּ, וְאִתְגְּלֵי יִשְׂרָאֵל מֵאַרְעָא קַדִּישָׁא, קוּדְשָׁא בְּרִיךְ הוּא לָא עָאל בְּגִנְתֵּיהּ, וְלָא מִשְׁתַּעֲשָׁע בֵּיהּ. וְלָא עוֹד, אֶלָּא דְּאִיהוּ צָוַוח וְאָמַר, וְעַתָּה מַה לִּי פֹה נְאֻם יְיָ', וּכְתִיב הָתָם (תהילים קל״ב:י״ד) פֹּה אֵשֵׁב כִּי אִוִּיתִיהָ. כִּי לֻקַּח עַמִּי חִנָּם, כְּמָה דְּאַתְּ אָמֵר, (ישעיהו נ״ב:ה׳) חִנָּם נִמְכַּרְתֶּם.","וּמֵהַהוּא יוֹמָא דְּאִתְגְּלִיאוּ יִשְׂרָאֵל מֵאַרְעֲהוֹן, לָא אִשְׁתְּכַח חֶדְוָותָא קָמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. וְכָל דָּא, בְּגִין רְחִימוּתָא דִּלְהוֹן, דְּרָחִים לוֹן קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאַתְּ אָמֵר, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ'. (ועל דא) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. וְאָהַבְתָּ: דְּבָעֵי בַּר נָשׁ לְאִתְקַשְּׁרָא בֵּיהּ בִּרְחִימוּתָא עִלָּאָה, דְּכָל פּוּלְחָנָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח לְקוּדְשָׁא בְּרִיךְ הוּא, דְּיִפְלַח בִּרְחִימוּ. דְּלֵית לָךְ פּוּלְחָנָא, כְּמוֹ רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא. רִבִּי אַבָּא אָמַר, הָנֵי מִלֵּי כְּלָלָא דְּאוֹרַיְיתָא אִינּוּן, בְּגִין דְּעֶשֶׂר אֲמִירָן דְּאוֹרַיְיתָא, הָכָא אִתְכְּלִילוּ, וְהָא אוֹקְמוּהָ חַבְרַיָּיא.","תָּא חֲזֵי, לֵית לָךְ מִלָּה בַּחֲבִיבוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כְּמַאן דְּרָחִים לֵיהּ כַּדְּקָא יָאוּת. וּמַה הוּא. כְּמָה דִּכְתִּיב, בְּכָל לְבָבְךָ. בְּכָל, מַאי קָא מַיְירֵי, בִּלְבָבְךָ מִבָּעֵי לֵיהּ. בְּנַפְשְׁךָ, בִּמְאֹדֶךָ, מַהוּ בְּכָל לְבָבְךָ. אֶלָּא לְאַכְלְלָא תְּרֵין לִבִּין, חַד טַב וְחַד בִּישׁ. בְּכָל נַפְשְׁךָ: חַד טַב, וְחַד בִּישׁ. בְּכָל מְאֹדֶךָ, דָּא לָא אַתְיָא לִדְּרָשָׁא. אָמַר רִבִּי אֶלְעָזָר, וַאֲפִילּוּ הַאי לִדְּרָשָׁא הוּא. מַאי טַעְמָא. בֵּין דְּנָפַל לֵיהּ מָמוֹנָא מִיְּרוּתָא, אוֹ מִסִּטְרָא אַחֲרָא, אוֹ בֵּין דְּאִיהוּ רָוַוח לֵיהּ, וְעַל דָּא כְּתִיב בְּכָל מְאֹדֶךָ.","אָמַר רִבִּי אַבָּא, אַהֲדַרְנָא לַקְּרָא וְאָהַבְתָּ. מַאן דְּרָחִים לְקוּדְשָׁא בְּרִיךְ הוּא, אִתְעֲטָּר בְּחֶסֶד מִכָּל סִטְרִין, וְעָבִיד חֶסֶד בְּכֹלָּא, וְלָא חָיִיס עַל גּוּפֵיהּ וְעַל מָמוֹנֵיהּ. מְנָלָן. מֵאַבְרָהָם. כְּמָה דְּאִתְּמַר, דְּהָא לָא חָס בִּרְחִימוּתָא דְּמָארֵיהּ, עַל לִבֵּיהּ, (דהוא יצריה) וְעַל נַפְשֵׁיהּ, וְעַל מָמוֹנֵיהּ.","עַל לִבֵּיהּ לָא אַשְׁגַּח, עַל רְעוּתָא דִּילֵיהּ, בְּגִין רְחִימוּתָא דְּמָארֵיהּ. עַל נַפְשֵׁיהּ, דְּלָא חָס עַל בְּרֵיהּ, וְעַל אִתְּתֵיהּ, בְּגִין רְחִימוּתָא דְּמָארֵיהּ. עַל מָמוֹנֵיהּ, דְּהֲוָה קָאִים בְּפָרָשַׁת אָרְחִין, וְאַתְקִין מְזוֹנֵי לְכָל עָלְמָא. בְּגִין כָּךְ, אִתְעֲטָּר בְּעִטְרָא דְּחֶסֶד. כְּמָה דִּכְתִּיב, (מיכה ז׳:כ׳) חֶסֶד לְאַבְרָהָם. וּמַאן דְּאִתְקְשַּׁר בִּרְחִימוּתָא דְּמָארֵיהּ, זָכָה לְהַאי. וְלֹא עוֹד, אֶלָּא דְּעָלְמִין כֻּלְּהוּ מִתְבָּרְכָן בְּגִינֵיהּ. הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה, אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹּ\"ה. (דכתיב, (בראשית י״ב:ג׳) ונברכו בך כל משפחות האדמה)","יוֹמָא חַד, הֲוָה חָלַשׁ רִבִּי יוֹסִי, עָאל (עאלו) לְגַבֵּיהּ רִבִּי אַבָּא וְרִבִּי יְהוּדָה וְרִבִּי יִצְחָק, חָמוּ לֵיהּ דְּהֲוָה נָפִיל עַל אַנְפּוֹי וְנָאִים. יָתְבוּ. כַּד אִתְּעַר, חָמוּ לֵיהּ לְאַנְפּוֹי דְּחַיְיכִין. אָמַר לֵיהּ רִבִּי אַבָּא, מִלָּה חַדְתָּא חֲמֵיתָא. אָמַר לֵיהּ וַדַּאי, דְּהַשְׁתָּא סַלְּקָא נַפְשִׁי, וְחָמֵית יְקָרָא, מֵאִינּוּן דְּמָסָרוּ גַּרְמַיְיהוּ עַל קְדוּשָּׁה דְּמָארֵיהוֹן, דַּהֲווֹ עָאלִין בִּתְלֵיסָר נַהֲרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא. וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּהוּ. וַחֲמֵינָא מַה דְּלָא יָהֲבוּ לִי רְשׁוּתָא לְמֵימַר. וְשָׁאִילְנָא לוֹן, אֲמֵינָא, הַאי יְקָרָא דְּמַאן הוּא. אָמְרוּ לִי, מֵאִינּוּן דִּרְחִימוּ לְמָארֵיהוֹן בְּהַהוּא עָלְמָא. וּמִמָּה דְּחָמִית, נַפְשָׁאי וְלִבָּאי אִתְנְהִיר, וְעַל דָּא אַנְפָּאִי חַיְּיכִין."],[[0,"ת\"ח האי רוחא וכו':","בוא וראה, רוח רע הזה, השורה בין הפתחים, אוי לו לאדם שאינו יודע להזהר ממנו, ואינו רושם פתח ביתו בשם עליון קדוש, דהיינו המזוזה, שימצא עמו. כי יש לו, לאותו רוח רע, שס\"ה משמשים רעים מקטרגים בשס\"ה ימות השנה, כל אחד משמש ביומו, וכולם נמצאים עמו, עם האדם, בכל ימי השנה, ומקטרגים עליו למעלה ולמטה. וכולם נמצאים עמו ביום ובלילה. ביום הם מקטרגים עליו, ובלילה מצערים אותו בחלומו."],[1,"כד נפיק לקטרגא וכו':","כשיוצא לקטרג עליו, כשהוא נכנס לביתו, משימים ידיהם על כתפיו, ואומרים לו, אוי לו לפלוני שיצא מרשות אדונו. אוי לו לפלוני בעולם הזה ובעולם הבא. משום זה צריכים בני האמונה להיות רשומים בכל, להיות רשומים ברושם אדונם, דהיינו במצוות, שיראו מהם כל צדדי מינים הרעים, ויהיו שמורים בעולם הזה ובעולם הבא. אשרי חלקם של ישראל, עליהם כתוב, ועמך כלם צדיקים לעולם ירשו ארץ וגו'."],[2,"ואהבת את ה' אלקיך:","רבי יוסי פתח, ועתה מה לי פה נאם ה' כי לקח עמי חנם וגו'. בוא וראה אהבת הקב\"ה לישראל, אע\"פ שהעונות גרמו שיסתלק מביניהם, ונתפזרו בין האומות, הוא תובע עלבון שלהם. ובוא וראה, בשעה שישראל שורים בארצם, הקב\"ה משתעשע בגנתו, שהיא המלכות, וקרב אל ישראל, ושומע קולם, ומשתבח בהם."],[3,"כיון דגרמו חובייהו וכו':","כיון שגרמו עונותיהן, וישראל גלו מארץ הקדושה, הקב\"ה לא נכנס בגנתו, שהיא המלכות, ואינו משתעשע בו. ולא עוד, אלא שהוא צוח ואמר, ועתה מה לי \u0003פה\u0004 נאם ה'. וכתוב שם, \u0003פה\u0004 אשב כי אויתיה, מה \u0003פה\u0004 הנאמר שם הוא השכינה אף \u0003פה\u0004 הנאמר כאן הוא השכינה. \u0003כי לקח עמי חנם\u0004, הוא כש\"א, חנם נמכרתם."],[4,"ומההוא יומא דאתגליאו וכו':","ומיום ההוא שגלו ישראל מארצם לא נמצאת שמחה לפני הקב\"ה. ז\"ש אלביש שמים קדרות ושק אשים כסותם. וכל זה, בשביל אהבתם שאהב אותם הקב\"ה, כש\"א אהבתי אתכם אמר ה'. ועל כן, ואהבת את ה' אלקיך. \u0003ואהבת\u0004, פירושו, שצריך האדם להתקשר בו באהבה עליונה, שכל עבודה שצריך האדם לעבוד להקב\"ה, יעבוד באהבה. שאין לך עבודה כמו אהבת הקב\"ה. ר' אבא אמר, דברים אלו, דהיינו אהבה, הם כלל התורה, משום שעשרת הדברות שבתורה נכללו כאן. וכבר העמידו החברים."],[5,"ת\"ח לית לך וכו':","בוא וראה, אין לך דבר שחביב לפני הקב\"ה, כמי שאוהב אותו כראוי, ומה הוא. הוא כמו שכתוב, \u0003בכל לבבך\u0004, בכל, מהו פירושו, בלבבך היה צריך לומר. וכן, בנפשך, במאדך, מהו בכל לבבך, ומשיב, אלא בא לכלול ב' לבבות, אחד טוב ואחד רע. \u0003בכל נפשך\u0004, בב' נפשות, אחת טובה ואחת רעה. \u0003בכל מאדך\u0004, זה הוא כפשוטו, ואינו בא לדרש. א\"ר אלעזר, אפילו זה בא לדרש, מהו הטעם. הוא, בין שנופל לו כסף בירושה, או מצד אחר, או בין שהוא הרויח אותו, עליהם כתוב בכל מאדך."],[6,"א\"ר אבא אהדרנא וכו':","אר\"א נחזור אל הכתוב, ואהבת. מי שאוהב את הקב\"ה, מתעטר בחסד מכל הצדדים, ועושה חסד עם כל, ואינו דואג על גופו ועל כספו. מאין לנו זה, מאברהם, כמו שלמדנו, שמשום אהבת רבונו, לא חמל על לבו, על נפשו, ועל כספו."],[7,"על לביה לא וכו':","ומפרש הדברים. \u0003על לבו\u0004, היינו, שאברהם לא השגיח על רצונו מחמת אהבת אדונו. \u0003על נפשו\u0004, היינו, שלא חמל על בנו ועל אשתו מחמת אהבת אדונו. \u0003על כספו\u0004, היינו שהיה עומד בפרשת דרכים, ותקן מזונות לכל העולם. משום זה נתעטר בעטרה של חסד, דהיינו בספירת חסד. כמו שכתוב, חסד לאברהם. ומי שנקשר באהבת אדונו זוכה לזה. ולא עוד אלא שכל העולמות מתברכים בשבילו. ז\"ש וחסידיך יברכוכה. אל תקרא יברכוכה, אלא יברכו \u0003כה\u0004. דהיינו שהחסידים, שהם אותם שזכו לספירת חסד, יברכו השכינה, הנקראת \u0003כה\u0004. הרי שאפילו השכינה מתברכת בשבילם."],[8,"יומא חד הוה וכו':","יום אחד היה חולה ר' יוסי, נכנסו אליו ר' אבא ור' יהודה ור' יצחק. ראו אותו שהיה נופל על פניו וישן. ישבו. כשהקיץ משנתו, ראו את פניו שהיו שוחקות. אמר להם ר' אבא, דבר חדש ראיתי. אמר להם, ודאי כי עתה עלתה נפשי וראתה כבוד אלו שמסרו עצמם על קדושת אדונם, שהיו נכנסים בי\"ג נהרות אפרסמון הטהור. והקב\"ה משתעשע בהם. וראיתי מה שלא נתנו לי רשות לומר. ושאלתי להם ואמרתי, כבוד זה של מי הוא. אמרו לי, שהוא של אלו שאהבו את אדונם בעולם ההוא, דהיינו בעולם הזה. וממה שנפשי ראתה הואר לבי, ועל כן פני שוחקות."]],[[0,"","בֹּא וּרְאֵה, הָרוּחַ הָרָעָה הַזּוֹ שֶׁשְּׁרוּיָה בֵּין הַשְּׁעָרִים, אוֹי לוֹ לָאָדָם שֶׁלֹּא יוֹדֵעַ לְהִזָּהֵר מִמֶּנּוּ וְלֹא רוֹשֵׁם עַל פֶּתַח בֵּיתוֹ אֶת הַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ שֶׁיִּמָּצֵא עִמּוֹ, שֶׁהֲרֵי יֵשׁ לוֹ שְׁלֹשׁ מֵאוֹת שִׁשִּׁים וַחֲמִשָּׁה שַׁמָּשִׁים רָעִים שֶׁמְּקַטְרְגִים, כָּל אֶחָד מְשַׁמֵּשׁ בְּיוֹמוֹ, וְכֻלָּם נִמְצָאִים עִמּוֹ כָּל יְמוֹת הַשָּׁנָה וּמְקַטְרְגִים עָלָיו לְמַעְלָה וּלְמַטָּה, וְכֻלָּם נִמְצָאִים עִמּוֹ בַּיּוֹם וּבַלַּיְלָה. בַּיּוֹם לְקַטְרֵג לוֹ, בַּלַּיְלָה לְצַעֵר אוֹתוֹ בַּחֲלוֹמוֹ."],[1,"","כְּשֶׁיּוֹצֵא לְקַטְרֵג עָלָיו, כְּשֶׁנִּכְנָס, שָׂמִים יְדֵיהֶם עַל כְּתֵפוֹ וְאוֹמְרִים לוֹ: אוֹי לוֹ לִפְלוֹנִי שֶׁיָּצָא מֵרְשׁוּת אֲדוֹנוֹ! אוֹי לוֹ לִפְלוֹנִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא! מִשּׁוּם כָּךְ צְרִיכִים בְּנֵי הָאֱמוּנָה לִהְיוֹת רְשׁוּמִים בַּכֹּל, לִהְיוֹת רְשׁוּמִים בָּרֹשֶׁם שֶׁל רִבּוֹנָם, שֶׁיִּזְדַּעְזְעוּ מֵהֶם כָּל הַצְּדָדִים הַמִּינִים הָרָעִים, שֶׁיִּהְיוּ שְׁמוּרִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, עֲלֵיהֶם כָּתוּב [ישעיה ס] וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'."],[2,"","וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. רַבִּי יוֹסֵי פָּתַח, [שם נב] וְעַתָּה מַה לִּי פֹה נְאֻם ה' כִּי לֻקַּח עַמִּי חִנָּם וְגוֹ'. בֹּא וּרְאֵה אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, אַף עַל גַּב שֶׁחֲטָאֵיהֶם גָּרְמוּ לְהִסְתַּלֵּק מִבֵּינֵיהֶם וְהִתְפַּזְּרוּ בֵּין הָעַמִּים, הוּא תּוֹבֵעַ אֶת עֶלְבּוֹנָם. וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּאַרְצָם, הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּגַנּוֹ וּמִתְקָרֵב לְיִשְׂרָאֵל, וְשׁוֹמֵעַ קוֹלָם וּמִשְׁתַּבֵּחַ בָּהֶם."],[3,"","כֵּיוָן שֶׁגָּרְמוּ חֲטָאֵיהֶם וְהֻגְלוּ יִשְׂרָאֵל מֵהָאָרֶץ הַקְּדוֹשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִכְנָס לְגַנּוֹ וְלֹא מִשְׁתַּעֲשֵׁעַ בּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁהוּא צוֹוֵחַ וְאוֹמֵר, וְעַתָּה מַה לִּי פֹה נְאֻם ה'? וְכָתוּב שָׁם, [תהלים קלב] פֹּה אֵשֵׁב כִּי אִוִּתִיהָ. כִּי לֻקַּח עַמִּי חִנָּם, כְּמוֹ שֶׁנֶּאֱמַר [ישעיה נב] חִנָּם נִמְכַּרְתֶּם."],[4,"","וּמֵאוֹתוֹ יוֹם שֶׁגָּלוּ יִשְׂרָאֵל מֵאַרְצָם לֹא נִמְצֵאת שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב [ישעיה נ] אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. וְכָל זֶה מִשּׁוּם אַהֲבָתָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם, כְּמוֹ שֶׁנֶּאֱמַר [מלאכי א] אָהַבְתִּי אֶתְכֶם אָמַר ה'. [ועל זה] וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. וְאָהַבְתָּ, שֶׁצָּרִיךְ אָדָם לְהִתְקַשֵּׁר עִמּוֹ בְּאַהֲבָה עֶלְיוֹנָה. שֶׁכָל עֲבוֹדָה שֶׁאָדָם צָרִיךְ לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיַּעֲבֹד בְּאַהֲבָה, שֶׁאֵין לְךְ עֲבוֹדָה כְּמוֹ אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אַבָּא אָמַר, הַדְּבָרִים הַלָּלוּ הֵם הַכְּלָל שֶׁל הַתּוֹרָה, מִשּׁוּם שֶׁעֶשֶׂר הָאֲמִירוֹת שֶׁל הַתּוֹרָה כָּאן נִכְלְלוּ, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים."],[5,"","בֹּא וּרְאֵה, אֵין לְךְ דָּבָר בַּחֲבִיבוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמִי שֶׁאוֹהֵב אוֹתוֹ כָּרָאוּי. וּמַה הוּא? כַּכָּתוּב בְּכָל לְבָבְךְ. בְּכָל, מַה זֶּה אוֹמֵר? הָיָה צָרִיךְ לוֹ לִכְתֹּב בִּלְבָבְךְ, בְּנַפְשְׁךְ, בִּמְאֹדֶךְ. מַהוּ בְּכָל לְבָבְךְ? אֶלָּא לְהַכְלִיל שְׁנֵי לְבָבוֹת, אֶחָד טוֹב וְאֶחָד רַע. בְּכָל נַפְשְׁךְ, אֶחָד טוֹב וְאֶחָד רַע. בְּכָל מְאֹדֶךְ, זֶה לֹא בָא לִדְרָשָׁה. אָמַר רַבִּי אֶלְעָזָר, וַאֲפִלּוּ זֶה הוּא לִדְרָשָׁה. מָה הַטַּעַם? בֵּין שֶׁנָּפַל לוֹ מָמוֹן מִירֻשָּׁה, אוֹ מִצַּד אַחֵר, אוֹ בֵּין שֶׁהוּא הִרְוִיחַ אוֹתוֹ, וְעַל זֶה כָּתוּב בְּכָל מְאֹדֶךְ."],[6,"","אָמַר רַבִּי אַבָּא, חָזַרְנוּ לַפָּסוּק שֶׁל וְאָהַבְתָּ. מִי שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִתְעַטֵּר בְּחֶסֶד מִכָּל הַצְּדָדִים וְעוֹשֶׂה חֶסֶד עִם הַכֹּל, וְלֹא חָס עַל גּוּפוֹ וְעַל מָמוֹנוֹ. מִנַּיִן לָנוּ? מֵאַבְרָהָם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי לֹא חָס בְּאַהֲבַת רִבּוֹנוֹ עַל לִבּוֹ [שהוא יצרו] וְעַל נַפְשׁוֹ וְעַל מָמוֹנוֹ."],[7,"","עַל לִבּוֹ לֹא הִשְׁגִּיחַ, עַל רְצוֹנוֹ, מִשּׁוּם אַהֲבַת רִבּוֹנוֹ. עַל נַפְשׁוֹ – שֶׁלֹּא חָס עַל בְּנוֹ וְעַל אִשְׁתּוֹ בִּשְׁבִיל אַהֲבַת רִבּוֹנוֹ. עַל מָמוֹנוֹ – שֶׁהָיָה עוֹמֵד בְּפָרָשַׁת דְּרָכִים וּמְתַקֵּן מְזוֹנוֹת לְכָל הָעוֹלָם. מִשּׁוּם כָּךְ הִתְעַטֵּר בַּעֲטָרָה שֶׁל חֶסֶד, כַּכָּתוּב [מיכה ז] חֶסֶד לְאַבְרָהָם. וּמִי שֶׁמִּתְקַשֵּׁר בְּאַהֲבַת רִבּוֹנוֹ זוֹכֶה לָזֶה, וְלֹא עוֹד, אֶלָּא שֶׁכָּל הָעוֹלָמוֹת מִתְבָּרְכִים בִּגְלָלוֹ. זֶהוּ שֶׁכָּתוּב [תהלים קמה] וַחֲסִידֶיךְ יְבָרְכוּכָה. אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹ\"ה. [שכתוב [בראשית יב] ונברכו בך כל משפחות האדמה]."],[8,"","יוֹם אֶחָד הָיָה חַלָּשׁ רַבִּי יוֹסֵי, נִכְנְסוּ אֵלָיו רַבִּי אַבָּא וְרַבִּי יְהוּדָה וְרַבִּי יִצְחָק, רָאוּ אוֹתוֹ שֶׁהָיָה נוֹפֵל עַל פָּנָיו וְיָשֵׁן. יָשְׁבוּ. כְּשֶׁהִתְעוֹרֵר, רָאוּ שֶׁפָּנָיו מְחַיְּכוֹת. אָמַר לוֹ רַבִּי אַבָּא, דָּבָר חָדָשׁ רָאִיתָ? אָמַר לוֹ, וַדַּאי, שֶׁעַכְשָׁו עָלְתָה נַפְשִׁי, וְרָאִיתִי אֶת הַכָּבוֹד שֶׁל אוֹתָם שֶׁמָּסְרוּ עַצְמָם עַל קְדֻשַּׁת רִבּוֹנָם, שֶׁהָיוּ נִכְנָסִים בִּשְׁלֹשָׁה עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִמָּם, וְרָאִיתִי מַה שֶּׁלֹּא נָתְנוּ לִי רְשׁוּת לוֹמַר. וְשָׁאַלְתִּי אוֹתָם, אָמַרְתִּי שֶׁל מִי הַכָּבוֹד הַזֶּה? אָמְרוּ לִי, שֶׁל אוֹתָם שֶׁאָהֲבוּ אֶת רִבּוֹנָם בְּאוֹתוֹ הָעוֹלָם. וּמִמַּה שֶּׁרָאִיתִי הוּאֲרוּ נַפְשִׁי וְלִבִּי, וְעַל כֵּן פָּנַי מְחַיְּכוֹת."]]],[["אָמַר לֵיהּ רִבִּי אַבָּא, זַכָּאָה חוּלָקָךְ, אֲבָל אוֹרַיְיתָא אַסְהִיד בְּהוּ, דִּכְתִּיב, (ישעיהו ס״ד:ג׳) עַיִן לָא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. אָמַר לֵיהּ רִבִּי יְהוּדָה, הָא שָׁאִילוּ חַבְרַיָּיא, דָּא דִּכְתִּיב יַעֲשֶׂה, תַּעֲשֶׂה מִבָּעֵי לֵיהּ.","אָמַר לֵיהּ, הָא אִתְּמַר. אֲבָל רָזָא דְּמִלָּה, הַיְינוּ דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ' וּלְבַקֵּר בְּהֵיכָלוֹ. וְאוֹקְמוּהָ, נֹעַם יְיָ', הַהוּא דְּאַתְיָא מֵעַתִּיקָא קַדִּישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בֵּיהּ. דְּהָא הַהוּא נֹעַם מֵעַתִּיקָא נָפְקָא. וּלְבַקֵּר בְּהֵיכָלוֹ, בְּהֵיכָלָא עִילָּאָה עַל כֹּלָּא. אוּף הָכָא, עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה. מַאן, הַהוּא עַתִּיקָא סְתִימָא דְּכֹלָּא, דְּהָא בֵּיהּ תַּלְיָא, אָמַר לֵיהּ, וַדַּאי הָכִי הוּא. זַכָּאָה חוּלָקֵיהוֹן דְּאִינּוּן דִּרְחִימוּתָא דְּמָארֵיהוֹן מִתְדַּבְּקָן בְּהוּ, לְאִלֵּין לֵית שִׁעוּרָא לְחוּלָקֵיהוֹן בְּהַהוּא עָלְמָא.","אָמַר רִבִּי יִצְחָק, כַּמָה מָדוֹרִין עַל מָדוֹרִין אִית לְהוּ לְצַדִּיקַיָּיא בְּהַהוּא עָלְמָא, וּמָדוֹרָא עִלָּאָה דְּכֹלָּא, אִינּוּן דִּרְחִימוּתָא דְּמָארֵיהוֹן אִתְקְשַּׁר בְּהוּ, דְּהָא מָדוֹרֵיהוֹן אִתְקְשַּׁר בְּהֵיכָלָא דְּסָלִיק עַל כֹּלָּא. מַאי טַעְמָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי אִתְעֲטָּר.","תָּא חֲזֵי, (ס\"א כלא אהבה) הֵיכָלָא דָּא, אַהֲבָה אִתְקְרֵי, וּבְגִין אַהֲבָה קַיְּימָא כֹּלָּא. כְּמָה דִּכְתִּיב, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. וְכֹלָּא בִּרְחִימוּתָא קַיְּימָא, דְּהָא שְׁמָא קַדִּישָׁא הָכִי אִשְׁתְּכַח דְּהָא אוּקְמוּהָ, י' לָא מִתְפְּרַשׁ קוֹצָא דִּלְעֵילָּא מִן י' לְעָלְמִין. דְּהָא בִּרְחִימוּתָא שַׁרְיָא עָלֵיהּ, וְלָא מִתְפְּרַשׁ מִנֵּיהּ לְעָלְמִין. ה', הָא אוּקְמוּהָ, דְּיוֹד לָא מִתְפְּרַשׁ מִנָהּ, וְאִשְׁתְּכָחוּ כַּחֲדָא בַּחֲבִיבוּתָא, לָא אִתְפָּרְשָׁן דָּא מִן דָּא. כְּגַוְונָא דָּא ה' וְהָא אִתְּמַר, כְּמָה דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן, יוֹצֵא תָּדִיר לְעָלְמִין, בַּחֲבִיבוּתָא אִתְדַּבְּקָן.","ו\"ה כַּד אִתְדַּבְּקָן דָּא בְּדָא, אִתְדַּבְּקָן בַּחֲבִיבוּתָא כַּחֲדָא, חָתָן בְּכַלָּה, דְּאָרְחַיְיהוּ תָּדִיר בַּחֲבִיבוּתָא אִשְׁתְּכַח. י' בְּה', ה' עִם ו', ו' עִם ה'. וְדָא בְּדָא אִתְקְשַּׁר בַּחֲבִיבוּתָא. וְכֹלָּא אַהֲבָה אִקְרֵי. וְעַל דָּא מַאן דְּרָחִים לְמַלְכָּא, הָא אִתְקְשַׁר בְּהַהוּא אַהֲבָה. וּבְּגִין כָּךְ, וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ.","וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ'. רִבִּי יִצְחָק פָּתַח, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָּה יְיָ' מִי כָמוֹךָ מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ וְעָנִי וְאֶבְיוֹן מִגּוֹזְלוֹ. הַאי קְרָא דָּוִד אַמְרֵיהּ (אמרו) בְּרוּחָא דְּקוּדְשָׁא, כָּל עַצְמוֹתַי תֹּאמַרְנָּה, וְכִי מַאן חָמָא גַּרְמֵי דְּאָמְרוּ שִׁירָתָא. אֶלָּא הַאי קְרָא, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאַחֲיָיא מֵתַיָּיא, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַתְקְנָא גַּרְמֵי, וּלְקָרְבָא כָּל חַד וְחַד לְאַתְרַיְיהוּ, דִּכְתִּיב, (יחזקאל ל״ז:ז׳) וַתִּקְרְבוּ עֲצָמוֹת עֶצֶם אֶל עַצְמוֹ. וּכְתִיב (ישעיהו נ״ח:י״א) וְעַצְמוֹתֶיךָ יַחֲלִיץ. כְּדֵין זְמִינִין אִינּוּן לְמֵימַר שִׁירָתָא.","מַאי שִׁירָתָא אַמְרֵי. יְיָ' מִי כָמוֹךָ (מקדמי) וְדָא שִׁירָתָא מְעַלְּיָיא, מִמַּה דְּאָמְרוּ יִשְׂרָאֵל עַל יַמָּא, דְּהָא אִינּוּן לָא אַדְכְּרוּ שְׁמָא קַדִּישָׁא, אֶלָּא בָּתַר תְּלַת מִלִּין, דִּכְתִּיב, (שמות ט״ו:י״א) מִי כָמוֹכָה בָּאֵלִים יְיָ'. וְהָכָא אִינּוּן מַקְדְּמֵי לִשְׁמָא קַדִּישָׁא, דִּכְתִּיב יְיָ' מִי כָמוֹךָ. מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ, דָּא יֵצֶר טוֹב, מִיֵּצֶר רָע. בְּגִין דְּיֵצֶר הָרָע תַּקִּיף הוּא כְּאַבְנָא. כְּמָה דִּכְתִּיב, (יחזקאל ל״ו:כ״ו) וַהֲסִירוֹתִי אֶת לֵב הָאֶבֶן. וְיֵצֶר טוֹב הוּא בִּשְׂרָא, דִּכְתִּיב, (שם) וְנָתַתִּי לָכֶם לֵב בָּשָׂר.","תָּא חֲזֵי, יֵצֶר הָרָע לְמָה הוּא דּוֹמֶה. בְּשַׁעֲתָא דְּאָתֵי לְאִזְדַּוְּוגָא בְּבַּר נָשׁ, הוּא כְּפַרְזְלָא, עַד דְּעָאלִין לֵיהּ בְּנוּרָא. בָּתַר דְּיִתְחַמֵּם אִתְהַדָּר כֹּלָּא כְּנוּרָא.","רִבִּי חִיָּיא אָמַר, יֵצֶר הָרָע כַּד אָתֵי לְאִזְדַּוְּוגָא בֵּיהּ לְבַּר נָשׁ, דָּמֵי לְבַּר נָשׁ דְּקָרִיב לְפִתְחָא, וְחָמֵי דְּלָא אִית מַאן דְּמָחֵי בִּידֵיהּ. עָאל לְבֵיתָא, וְאִתְעָבִיד לֵיהּ אֹרֵחַ. חָמָא דְּלָא אִית מַאן דִּמְחֵי בִּידֵיהּ, וְיֵיזִיל לֵיהּ לְאָרְחֵיהּ. כֵּיוָן דְּעָיִּיל לְבֵיתָא, וְלָא אִית דְּיִמְחֵי בִּידֵיהּ, אִתְמְנָא עָלֵיהּ וְאִתְעָבִיד מָארֵיהּ דְּבֵיתָא עַד דְּיִשְׁתְּכַח דְּכָל בֵּיתָא קָאִים בִּרְשׁוּתֵיהּ."],[[0,"א\"ל ר' אבא וכו':","א\"ל ר\"א אשרי חלקך, אבל התורה מעידה בהם, שכתוב, עין לא ראתה אלקים זולתך יעשה למחכה לו. א\"ל ר' יהודה, הרי שאלו החברים, זה שכתוב, יעשה, תעשה היה צריך לומר. ע\"ד שכתוב זולתך לשון נוכח."],[1,"א\"ל הא אתמר וכו':","א\"ל הרי למדנו. אבל סוד הדבר הוא, היינו שכתוב, לחזות בנעם ה' ולבקר בהיכלו. והעמדנו, \u0003נעם ה'\u0004, היינו השפע הבא מעתיקא קדישא, שהוא הכתר, שהקב\"ה משתעשע בו. כי נועם ההוא יוצא מעתיקא. \u0003ולבקר בהיכלו\u0004, היינו היכל העליון על כל, שהוא בינה. אף כאן עין לא ראתה אלקים זולתך יעשה, מי יעשה, היינו אותו עתיקא הסתום מכל, כי בו תלוי שפע זה. וע\"כ כתוב יעשה לשון נסתר. אמר לו, ודאי כך הוא. אשרי חלקם של אלו שאהבת אדונם נתדבקה בהם. לאלו, אין שיעור לחלקם בעולם ההוא."],[2,"אמר ר' יצחק וכו':","אר\"י, כמה מדורים על מדודים יש לצדיקים בעולם ההוא, ומדור העליון מכולם, הוא לאותם שאהבת אדונם נקשרת בהם, כי המדור שלהם נקשר בהיכל העולה על הכל. מה הטעם. הוא משום שהקב\"ה מתעטר בזה. באהבה."],[3,"ת\"ח היכלא דא וכו':","בוא וראה היכל זה העליון על הכל, נקרא אהבה, ועל אהבה עומד הכל. כמ\"ש מים רבים לא יוכלו לכבות את האהבה. והכל עומד באהבה. כי השם הקדוש הויה, נמצא כך. כי העמדנו, ה \u0003י'\u0004 דהויה, שהיא חכמה, אין נפרד ממנה הקוץ שלה של מעלה, שהוא כתר, לעולם, כי באהבה שורה עליה הכתר, ואינו נפרד ממנה לעולם. \u0003ה'\u0004 של הויה, שהיא בינה, הרי העמידו, שה \u0003י'\u0004 שהיא חכמה, אינה נפרדת ממנה, ונמצאים יחד באהבה, ואינם נפרדים זה מזה, וכמו זה היא \u0003ה'\u0004 דהויה. שלמדנו, שהיא כמו שכתוב, ונהר יוצא מעדן, שנהר היא בינה, ועדן הוא חכמה, והבינה יוצאת תמיד מן החכמה, ומתדבקים לעולם באהבה."],[4,"ו\"ה כד אתדבקן וכו': ו\"ה",", שהם ז\"א ומלכות, כשהם מתדבקים זה בזה, מתדבקים באהבה יחד, חתן בכלה, שדרכם תמיד נמצא באהבה. נמצא, אשר \u0003י'\u0004 ב \u0003ה'\u0004, \u0003ה'\u0004 עם \u0003ו', ו'\u0004 עם \u0003ה'\u0004 אחרונה, מתקשרים זה בזה באהבה. והכל נקרא אהבה. וע\"כ מי שאוהב את המלך, נקשר באהבה ההיא, ומשום זה. ואהבת את ה' אלקיך."],[5,"והיו הדברים האלה וגו':","רבי יצחק פתח, כל עצמותי תאמרנה ה' מי כמוך מציל עני מחזק ממנו ועני ואביון מגוזלו. מקרא זה אמרו דוד ברוח הקדש. שואל, כל עצמותי תאמרנה, ומי ראה, שעצמות תאמרנה שירה. ומשיב, אלא מקרא זה נאמר, בזמן שהקב\"ה עתיד להחיות מתים. ועתיד הקב\"ה לתקן העצמות ולקרב כל אחת ואחת למקומה. שכתוב, ותקרבו עצמות עצם אל עצמו. וכתוב, ועצמותיך יחליץ. אז עתידים ישראל לומר שירה."],[6,"מאי שירתא אמרי וכו':","שואל, איזו שירה אומרים. ומשיב, ה' מי כמוך. וזו שירה יותר חשובה ממה שאמרו ישראל על הים, כי הם לא הזכירו את השם הקדוש, אלא אחר ג' מלים, שכתוב, מי כמוכה באלים ה', וכאן הם מקדימים את השם הקדוש, שכתוב, ה' מי כמוך. \u0003מציל עני מחזק ממנו\u0004 זהו יצר הטוב שמצילו מיצר הרע. משום שיצר הרע הוא חזק כאבן. כמ\"ש, והסירותי את לב האבן. ויצר הטוב הוא בשר, שכתוב, ונתתי לכם לב בשר."],[7,"ת\"ח יצר הרע למה וכו':","בוא וראה, יצר הרע למה הוא דומה. בשעה שבא להתחבר עם האדם, הוא כברזל מטרם שמביאים אותו באש. אחר שנתחמם חזר כולו כמו אש."],[8,"רבי חייא אמר וכו':","רח\"א, יצר הרע, בשעה שבא להתחבר עם האדם, הוא דומה לאדם הקרב לפתח ורואה שאין מי בבית שיעכב בידו. נכנס לבית ונעשה שמה ארח, ורואה שאין מי שיעכב בידו שיצא משם לדרכו. כיון שנכנס לבית ואין מי שיעכב בידו, הוא נתמנה על הבית, ונעשה בעל הבית, עד שנמצא שכל הבית עומד ברשותו."]],[[0,"","אָמַר לוֹ רַבִּי אַבָּא, אַשְׁרֵי חֶלְקְךְ, אֲבָל הַתּוֹרָה מְעִידָה עֲלֵיהֶם, שֶׁכָּתוּב [ישעיה סד] עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. אָמַר לוֹ רַבִּי יְהוּדָה, הֲרֵי שָׁאֲלוּ הַחֲבֵרִים, זֶה שֶׁכָּתוּב יַעֲשֶׂה, הָיָה צָרִיךְ לוֹ לִהְיוֹת תַּעֲשֶׂה!"],[1,"","אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, אֲבָל סוֹד הַדָּבָר הַיְנוּ שֶׁכָּתוּב [תהלים כז] לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. וּפֵרְשׁוּהָ, נֹעַם ה', אוֹתוֹ שֶׁבָּא מֵהָעַתִּיק הַקָּדוֹשׁ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בּוֹ, שֶׁהֲרֵי אוֹתוֹ נֹעַם יוֹצֵא מֵהָעַתִּיק. וּלְבַקֵּר בְּהֵיכָלוֹ, בַּהֵיכָל הָעֶלְיוֹן עַל הַכֹּל. אַף כָּאן, עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה – מִי? אוֹתוֹ הָעַתִּיק הַנִּסְתָּר שֶׁל הַכֹּל, שֶׁהֲרֵי בּוֹ תָּלוּי. אָמַר לוֹ, וַדַּאי כָּךְ הוּא. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁבְּאַהֲבַת רִבּוֹנָם נִדְבָּקִים בָּהֶם, לְאֵלֶּה אֵין שִׁעוּר לְחֶלְקָם בָּעוֹלָם הַהוּא."],[2,"","אָמַר רַבִּי יִצְחָק, כַּמָּה מְדוֹרִים עַל מְדוֹרִים יֵשׁ לַצַּדִּיקִים בָּעוֹלָם הַהוּא, וְהַמָּדוֹר הָעֶלְיוֹן שֶׁל הַכֹּל – אוֹתָם שֶׁנִּקְשְׁרָה בָהֶם אַהֲבַת רִבּוֹנָם, שֶׁהֲרֵי מְדוֹרָם נִקְשָׁר לַהֵיכָל שֶׁעוֹלֶה עַל הַכֹּל. מָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בָּזֶה."],[3,"","בֹּא וּרְאֵה, [הכל אהבה] הַהֵיכָל הַזֶּה נִקְרָא אַהֲבָה, וּבִשְׁבִיל הָאַהֲבָה הַכֹּל קַיָּם, כַּכָּתוּב [שיר השירים ח] מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. וְהַכֹּל קַיָּם בְּאַהֲבָה, שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ כָּךְ נִמְצָא, שֶׁהֲרֵי פֵּרְשׁוּהָ, י' לֹא נִפְרָד הַקּוֹץ שֶׁלְּמַעְלָה מִן י' לְעוֹלָמִים, שֶׁהֲרֵי בְּאַהֲבָה שׁוֹרֶה עָלָיו, וְלֹא נִפְרָד מִמֶּנּוּ לְעוֹלָמִים. ה' הֲרֵי פֵּרְשׁוּהָ, שֶׁי' לֹא נִפְרֶדֶת מִמֶּנָּה, וְנִמְצָאוֹת יַחַד בַּחֲבִיבוּת, לֹא נִפְרָדוֹת זוֹ מִזּוֹ. כְּמוֹ כֵן ה', וַהֲרֵי נִתְבָּאֵר, כְּמוֹ שֶׁכָּתוּב [בראשית ב] וְנָהָר יֹצֵא מֵעֵדֶן, יוֹצֵא תָמִיד לְעוֹלָמִים, נִדְבָּקִים בַּחֲבִיבוּת."],[4,"","ו\"ה כְּשֶׁנִּדְבָּקוֹת זוֹ בָּזוֹ, נִדְבָּקוֹת יַחַד בַּחֲבִיבוּת, חָתָן עִם כַּלָּה, שֶׁדַּרְכָּן תָּמִיד נִמְצֵאת בַּחֲבִיבוּת. י' עִם ה', ה' עִם ו', ו' עִם ה', וְזוֹ עִם זוֹ נִקְשָׁרוֹת בַּחֲבִיבוּת, וְהַכֹּל נִקְרָא אַהֲבָה. וְעַל כֵּן מִי שֶׁאוֹהֵב אֶת הַמֶּלֶךְ, הֲרֵי הוּא נִקְשָׁר בְּאוֹתָהּ הָאַהֲבָה, וּמִשּׁוּם כָּךְ וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ."],[5,"","וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ'. רַבִּי יִצְחָק פָּתַח, [תהלים לה] כָּל עַצְמֹתַי תֹּאמַרְנָה ה' מִי כָמוֹךְ מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ וְעָנִי וְאֶבְיוֹן מִגֹּזְלוֹ. פָּסוּק זֶה אָמַר אוֹתוֹ דָּוִד בְּרוּחַ הַקֹּדֶשׁ. כָּל עַצְמֹתַי תֹּאמַרְנָה, וְכִי מִי רָאָה עֲצָמוֹת שֶׁאוֹמְרוֹת שִׁירָה? אֶלָּא הַפָּסוּק הַזֶּה בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת אֶת הַמֵּתִים, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַתְקִין הָעֲצָמוֹת וּלְקָרֵב כָּל אַחַת וְאַחַת לִמְקוֹמָן, שֶׁכָּתוּב [יחזקאל לז] וַתִּקְרְבוּ עֲצָמוֹת עֶצֶם אֶל עַצְמוֹ, וְכָתוּב [ישעיה נח] וְעַצְמֹתֶיךְ יַחֲלִיץ. אָז עֲתִידוֹת הֵן לוֹמַר שִׁירָה."],[6,"","אֵיזוֹ שִׁירָה אוֹמְרוֹת? ה' מִי כָמוֹךְ [מקדימים], וְזוֹ הַשִּׁירָה הַמְעֻלָּה מִמַּה שֶּׁאָמְרוּ יִשְׂרָאֵל עַל הַיָּם, שֶׁהֲרֵי הֵם לֹא הִזְכִּירוּ אֶת הַשֵּׁם הַקָּדוֹשׁ אֶלָּא אַחֲרֵי שָׁלֹשׁ מִלִּים, שֶׁכָּתוּב [שמות טו] מִי כָמֹכָה בָּאֵלִם ה'. וְכָאן הֵם מַקְדִּימִים אֶת הַשֵּׁם הַקָּדוֹשׁ, שֶׁכָּתוּב ה' מִי כָמוֹךְ. מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ – זֶה יֵצֶר טוֹב מִיֵּצֶר הָרָע, מִשּׁוּם שֶׁיֵּצֶר הָרָע תַּקִּיף הוּא כְּמוֹ אֶבֶן, כַּכָּתוּב [יחזקאל לו] וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן, וְיֵצֶר הַטּוֹב הוּא בָּשָׂר, שֶׁכָּתוּב וְנָתַתִּי לָכֶם לֵב בָּשָׂר."],[7,"","בֹּא וּרְאֵה, יֵצֶר הָרָע לְמָה הוּא דּוֹמֶה? בְּשָׁעָה שֶׁהוּא בָּא לְהִזְדַּוֵּג עִם הָאָדָם הוּא כְּמוֹ בַּרְזֶל, עַד שֶׁמַּכְנִיסִים אוֹתוֹ לָאֵשׁ. אַחַר שֶׁיִּתְחַמֵּם, הַכֹּל חוֹזֵר כָּאֵשׁ."],[8,"","רַבִּי חִיָּיא אָמַר, כְּשֶׁבָּא יֵצֶר הָרָע לְהִזְדַּוֵּג עִם הָאָדָם, דּוֹמֶה לְאִישׁ שֶׁקָּרֵב לְפֶתַח וְרוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, נִכְנָס לַבַּיִת וְנַעֲשֶׂה לוֹ אוֹרֵחַ. רוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, וְיֵלֵךְ לוֹ לְדַרְכּוֹ. כֵּיוָן שֶׁנִּכְנָס לַבַּיִת וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ, מִתְמַנֶּה עָלָיו וְנַעֲשֶׂה בַּעַל הַבַּיִת, עַד שֶׁנִּמְצָא שֶׁכָּל הַבַּיִת עוֹמֵד לִרְשׁוּתוֹ."]]],[["מֵאַן אוֹלִיפְנָא. מִפַּרְשְׁתָּא דְּדָוִד אוֹלִיפְנָא. מַה כְּתִיב, (שמואל ב י״ב:ד׳) וַיָּבֹא הֵלֶךְ לְאִישׁ הֶעָשִׁיר, הֵלֶךְ דְּקָרִיב לְפִתְחָא, וְלָא בָּעֵי לְאִתְעַכְּבָא תַּמָּן, אֶלָּא לְמֵהַךְ לְאָרְחֵיהּ. כַּךְ הוּא יֵצֶר הָרָע, כְּמָה דְּמִקְרַב לְבֵיתָא, מִתְקָרֵב גַּבֵּי דְּבַּר נָשׁ, אִתְּעַר עָלֵיהּ בְּחוֹבָא זְעֵיר, דָּא הוּא אוֹרֵחַ עֲרָאי. חָמֵי דְּלֵית דִּמְחֵי בִּידֵיהּ, מַה כְּתִיב, לַעֲשׂוֹת לָאוֹרֵחַ הַבָּא אֵלָיו, אִתְעָבִיד לֵיהּ אוֹרֵחַ אַכְסְנַאי בְּבֵיתָא, אִתְּעַר עָלֵיהּ בְּחוֹבוֹי יַתִּיר, יוֹמָא חַד, אוֹ תְּרֵין יוֹמִין, כְּהַאי אוֹרֵחַ דְּשָׁרָאן לֵיהּ בְּבֵיתָא, יוֹמָא חֲדָא, אוֹ ב' יוֹמִין, (בגין דאיהו אורח) כֵּיוָן דְּחָמֵי דְּלֵית מַאן דִּמְחֵי בִּידֵיהּ, מַה כְּתִיב, (שם) וַיַּעַשׂ לְאִישׁ הַבָּא אֵלָיו, אִתְעָבִיד מָארֵי דְּבֵיתָא, כְּמָה דְאַתְּ אָמֵר (בראשית מ״ב:ל׳) הָאִישׁ אֲדוֹנֵי הָאָרֶץ. (רות א׳:ג׳) אִישׁ נָעֳמִי. כַּךְ הוּא יֵצֶר הָרָע, אִתְעָבִיד לָקֳבְלֵיהּ דְּבַּר נָשׁ, אִישׁ, בַּעַל הַבַּיִת, הָא אִתְקְשַׁר בַּר נָשׁ בְּפוּלְחָנֵיהּ, וְהוּא עָבִיד בֵּיהּ רְעוּתֵיהּ.","וְעַל דָּא בָּעֵי בַּר נָשׁ לְשַׁוָּאָה מִלִּין דְּאוֹרַיְיתָא עָלֵיהּ תָּדִיר, בְּגִין דִּיְהֵא הַהוּא יֵצֶר הָרָע תָּבִיר בְּהוּ, דְּלֵית לֵיהּ מְקַטְרֵג לְיֵצֶר הָרָע, בַּר מִלֵּי דְּאוֹרַיְיתָא. וְעַל דָּא כְּתִיב, וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ', עַל לְבָבֶךָ, עַל תְּרֵי יְצָרֶיךָ, יֵצֶר הַטּוֹב אִתְעֲטָּר בְּהוּ, וְיֵצֶר הָרָע אִתְכָּנַע בְּהוּ. אָמַר רִבִּי יְהוּדָה, יֵצֶר הַטּוֹב, מַה בָּעֵי מִלֵּי דְּאוֹרַיְיתָא. אָמַר לֵיהּ, יֵצֶר הַטּוֹב אִתְעֲטָּר בְּהוּ. וְיֵצֶר הָרָע, כֵּיוָן דְּחָמֵי בַּר נָשׁ לָא תָּב, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּדֵין הוּא סָלִיק לְעֵילָּא, וְאוֹלִיף עָלֵיהּ חוֹבָה, הֲדָא הוּא דִכְתִיב, (משלי ג׳:ל״ה) וּכְסִילִים מֵרִים קָלוֹן.","כַּד אָתָא רִבִּי שִׁמְעוֹן, אָמַר, הָא וַדַּאי פַּרְשְׁתָּא דִּקְרִיאַת שְׁמַע רְמִיזָא בֵּיהּ י' אֲמִירָן כְּמָה דְּאוּקְמוּהָ, וְהָכִי הוּא וַדַּאי. וְהָיוּ הַדְּבָרִים הָאֵלֶּה, כְּלָלָא דְּעֶשֶׂר אֲמִירָן אִינּוּן. וּבְּגִין כָּךְ י' פִּקּוּדִין אִית הָכָא, לָקֳבֵל י' פִּקּוּדִין דְּאוֹרַיְיתָא. וּמַאן אִינּוּן. וְשִׁנַּנְתָּם לְבָנֶיךָ. וְדִבַּרְתָּ בָּם. בְּשִׁבְתְּךָ בְּבֵיתֶךָ. וּבְלֶכְתְּךָ בַדֶרֶךְ. וּבְשָׁכְבְּךָ. וּבְקוּמֶךָ. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ. וְהָיוּ לְטוֹטָפוֹת בֵּין עֵינֶיךָ. וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ. וּבִשְׁעָרֶיךָ. הָא י', לָקֳבֵל י' אֲמִירָן. וְעַל דָּא פָּרְשִׁיָּין אִלֵּין כְּלַל רַב אִינּוּן בְּאוֹרַיְיתָא, זַכָּאָה חוּלָקֵיהּ, מַאן דְּאַשְׁלִים לֵיהּ בְּכָל יוֹמָא תְּרֵי זִימְנֵי, דְּהָא אִתְקַדָּשׁ בְּפוּמֵיהּ שְׁמָא קַדִּישָׁא כַּדְּקָא יָאוּת.","רִבִּי אֲחָא, הֲוָה קָאִים עִמֵּיהּ דְּרִבִּי אֶלְעָזָר לֵילְיָא חַד בָּתַר פַּלְגּוּת לֵילְיָא, וַהֲווּ מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר, (נ\"א רבי אחא) וְאָמַר, (דברים לב) כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ וְגוֹ'. תָּא חֲזֵי, עַל כָּל תְּנָאִין (נ\"א פקודין) דְּגָזַר קוּדְשָׁא בְּרִיךְ הוּא כַּד עָאלוּ לְאַרְעָא דְּיִשְׂרָאֵל, גְּזֵרָה דְּאוֹרַיְיתָא הֲוָה. מַאי טַעֲמָא, בְּגִין דִּשְׁכִינְתָּא לָא מִתְיַישְּׁבָא בְּאַרְעָא, אֶלָּא בְּאוֹרַיְיתָא. וְלָא מִתְיַישְּׁבָא לְעֵילָּא, אֶלָּא בְּאוֹרַיְיתָא.","דְּהָכִי אָמַר (רבי שמעון) אַבָּא, תּוֹרָה שֶׁבְּעַל פֶּה לָא אִשְׁתְּמוֹדָע, אֶלָּא בְּגִין תּוֹרָה שֶׁבִּכְתָב. שְׁכִינְתָּא לָא מִתְיַישְּׁבָא לְעֵילָּא אֶלָּא עִם תּוֹרָה דִּלְתַּתָּא. דְּכָל זִמְנָא דְּאוֹרַיְיתָא אִשְׁתְּכַח עִמֵּיהּ (דבר נש), יַכְלָא לְמֵיקָם בְּעָלְמָא. (נ\"א תורה שבכתב לא אשתמודעא אלא בגין תורה שבעל פה, ותורה שבעל פה לא אשתמודעא אלא מתורה שבכתב, ודאי כלל הצריך לפרט, ופרט הצריך לכלל. שכינתא לא מתיישבא לעילא אלא באורייתא דלתתא. דכל זמנא דאורייתא אשתכחת יכילא למיקם בעלמא) הֲדָא הוּא דִכְתִיב, כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ לָשֶׁבֶת עַל הָאֲדָמָה. עַל הָאֲדָמָה סְתָם. וְאִי לָאו דְּאַפְסִיק מִלֵּי דְּאוֹרַיְיתָא לָא יַכְלָא לְמֵיקָם. דִּכְתִּיב, (ירמיהו ט׳:י״ב) עַל מַה אָבְדָה הָאָרֶץ. וּכְתִיב, וַיֹּאמֶר יְיָ' עַל עָזְבָם אֶת תּוֹרָתִי.","עַד דַּהֲווֹ יַתְבֵי, מָאִיךְ רִבִּי שִׁמְעוֹן רֵישֵׁיהּ. אָמַר, וַדַּאי הָכִי הוּא וְדָא הוּא רָזָא דְּאַשְׁכַּחְנָא בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, וְאוֹקִים קְרָא דָּא, בְּרָזָא דִּכְנֶסֶת יִשְׂרָאֵל, דִּכְתִּיב, (שמות כ״א:י׳) שְׁאֵרָהּ כְּסוּתָהּ וְעוֹנָתָהּ לָא יִגְרָע. וְאִי אִתְמְנָעוּ מִנָהּ, מָה כְּתִיב, וְיָצְאָה חִנָּם אֵין כָּסֶף. כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ׳:א׳) אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. וּכְתִיב, (ישעיהו נ״ב:ג׳) חִנָּם נִמְכַּרְתֶּם וְלֹא בְכֶסֶף תִּגָּאֵלוּ. וּמַאן דְּמָנַע אוֹרַיְיתָא מִנָהּ, כְּמַאן דְּנָסַב מָארֵי (ס\"א שארה) דְּאִתְּתָא, וּמָנַע לֵיהּ מִנָהּ, דָּא אִשְׁתְּאָרַת כְּאַרְמַלְתָּא, וְלָא אַרְמַלְתָא. הֲדָא הוּא דִכְתִיב, (איכה א׳:א׳) הָיְתָה כְּאַלְמָנָה, וְלָא אַלְמָנָה.","יָתְבוּ אִתְעַסְּקוּ בְּאוֹרַיְיתָא, עַד דְּנָהִיר יוֹמָא. בָּתַר דְּנָהִיר יוֹמָא, קָמוּ וְאָזְלוּ. עַד דַּהֲווֹ אָזְלוּ, חָמוּ חַד גְּבָר דְּהֲוָה אָזִיל בְּאָרְחָא, וְרֵישֵׁיהּ עָטִיף, קְרִיבוּ גַּבֵּיהּ, וַהֲוָה רָחִישׁ בְּשִׂפְוָותֵיהּ, וְלָא אָתִיב לוֹן מִדִי. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי הַאי אִמְלַךְ בְּמָארֵיהּ. יָתִיב רִבִּי אֶלְעָזָר וְרַבִּי אֲחָא וְצַלּוּ צְלוֹתָא, וְהַהוּא גְּבַר קָאִים בְּקִיּוּמֵיהּ בַּאֲתָר אַחֲרָא. בָּתַר דְּסִיְּימוּ צְלוֹתָא, אַזְלוּ בְּאָרְחָא, וְהַהוּא גַּבְרָא אִשְׁתְּמִיט מִנַּיְיהוּ. אָמַר רִבִּי אֶלְעָזָר, הַאי גַּבְרָא, אוֹ טִפְּשָׁא הוּא, אוֹ אָרְחוֹי לָא מִתְיַשְּׁרָן. אָמַר, נִתְעֲסָק בְּאוֹרַיְיתָא, דְּהָא שַׁעֲתָא הִיא."],[[0,"מאן אוליפנא מפרשתא וכו':","מאין אני לומד זה, אני לומד מפרשה של דוד. מה כתוב, ויבא הלך לאיש העשיר, \u0003הלך\u0004, היינו שקרב אל הפתח ואינו רוצה להתעכב שמה אלא ללכת לדרכו. כך הוא היצר הרע בתחילה, אשר כמי שמתקרב אל בית, הוא מתקרב אל האדם ומעוררו לחטוא מעט, וזהו רק בדרך מקרה. רואה שאין מי שיעכב בידו, מה כתוב, לעשות ל \u0003אורח\u0004 הבא אליו, כאן הוא נעשה ארח מתארח בבית. דהיינו שמעוררו לחטוא יותר, יום אחד או יומים, כאותו אורח שמחזיקים אותו בבית יום אחד או יומים. כיון שרואה שאין מי שיעכב בידו, מה כתוב, ויעש ל \u0003איש\u0004 הבא אליו, כי נעשה בעל הבית, כש\"א ה \u0003איש\u0004. אדוני הארץ. \u0003איש\u0004 נעמי. כך הוא יצר הרע, שנעשה \u0003איש\u0004, בעל הבית על האדם, כי נקשר האדם לעבודתו. והיצר הרע עושה בו כרצונו."],[1,"וע\"ד בעי ב\"נ וכו':","ועל כן צריך האדם לשום תמיד דברי תורה עליו, כדי שאותו יצר הרע יהיה נשבר על ידיהם, שאין לו ליצר הרע צורר, כמו דברי תורה. וע\"כ כתוב, והיו הדברים האלה על לבבך וגו'. \u0003על לבבך\u0004, היינו על ב' יצריך, כי יצר הטוב מתעטר עמהם, ויצר הרע נכנע בהם. א\"ר יהודה, למה צריך יצר הטוב דברי תורה. אמר לו, יצר הטוב מתעטר בהם. ויצר הרע, כיון שרואה שהאדם אינו שב, ואינו רוצה לעסוק בתורה, אז הוא עולה למעלה ומלמד עליו חוב. ז\"ש וכסילים מרים קלון."],[2,"כד אתא ר\"ש וכו':","כשבא ר\"ש אמר, הנה ודאי פרשת קריאת שמע רמוזים בה עשרת הדברות, כמו שהעמידוהו. וכך הוא ודאי. והיו הדברים האלה, הם כלל של עשרת הדברות. וע\"כ יש כאן עשר מצוות כנגד עשר מצוות שבתורה, דהיינו שבעשרת הדברות. ומי הם. ושננתם לבניך, א'. ודברת בם, ב'. בשבתך בביתך, ג'. ובלכתך בדרך, ד'. ובשכבך, ה'. ובקומך, ו'. וקשרתם לאות על ידיך, ז'. והיו לטוטפות בין עיניך, ח'. וכתבתם על מזוזות ביתך ט'. ובשעריך, יוד. הרי עשר כנגד עשרת הדברות. וע\"כ פרשות אלו הן כלל רב בתורה. אשרי חלקו של מי שמשלים אותן בכל יום ב' פעמים, כי השם הקדוש נתקדש בפיו כראוי."],[3,"ר' אחא הוה וכו':","ר' אחא היה נמצא לילה אחד עם ר' אלעזר, לאחר חצות לילה. והיו עוסקים בתורה. פתח ר' אלעזר ואמר, כי הוא חייך ואורך ימיך וגו'. למעלה מכל המצוות שגזר הקב\"ה כשנכנסו לארץ ישראל, היתה גזרת לימוד התורה. מהו הטעם. הוא משום שהשכינה אינה מתישבת בארץ אלא בתורה, ואינה מתישבת למעלה, אלא בתורה שהוא ז\"א."],[4,"דהכי אמר אבא וכו':","כי כך אמר אבי, דהיינו ר\"ש, תורה שבעל פה, שהיא השכינה, אינה נודעת, אלא בשביל תורה שבכתב. שהיא ז\"א. והשכינה אינה מתישבת למעלה, אלא על ידי התורה שלומדים למטה. שכל זמן שהתורה נמצאת עמה, יכולה השכינה להמצא בעולם. ז\"ש, כי הוא חייך ואורך ימיך לשבת על האדמה. \u0003על האדמה\u0004 סתם, שהיא המלכות. ואם לא, אלא שמבטלים למוד התורה, אינה יכולה להתקיים. שכתוב, על מה אבדה הארץ, וכתוב, ויאמר ה', על עזבם את תורתי."],[5,"עד דהוו יתבי וכו':","בעוד שהיו יושבים השפיל ר\"ש ראשו, אמר, ודאי כך הוא. וזהו סוד שמצאתי בספרו של רב המנונא סבא, שהעמיד מקרא זה, בסוד כנסת ישראל, שהיא המלכות, שכתוב, שארה כסותה ועונתה לא יגרע. דהיינו ע\"י שלומדים בתורה, לא יגרעו הזווג והשפע מן המלכות. ואם מונעים ממנה, מה כתוב, ויצאה חנם אין כסף. כש\"א, אי זה ספר כריתות אמכם אשר שלחתיה. וכתוב, חנם נמכרתם ולא בכסף תגאלו. ומי שמונע התורה מן המלכות, הוא כמי שלוקח את הבעל מן האשה, ומונע אותה ממנו, כי גורם להסתלקות תורה של מעלה, שהיא ז\"א בעלה, שהיא נשארת כאלמנה, ולא אלמנה ממש. ז\"ש, היתה כאלמנה, ולא אלמנה."],[6,"יתבו אתעסקו באורייתא וכו':","ישבו ועסקו בתורה, עד שהאיר היום. אחר שהאיר היום, קמו והלכו. בעוד שהיו הולכים ראו איש אחד שהיה הולך בדרך וראשו עטוף. קרבו אליו, והיה דובב בשפתיו, ולא השיב להם כלום. אמר ר' אלעזר, ודאי שזה נמלך באדונו, דהיינו שמתפלל תפלת הדרך. ישבו ר' אלעזר ור' אחא והתפללו התפלה. ואותו האיש עמד על מעמדו במקום אחר. אחר שגמרו תפלתם הלכו בדרך. ואותו האיש נשמט מהם. אמר ר' אלעזר, איש הזה או הוא כסיל, או דרכיו אינם ישרים. אמר, נעסוק בתורה. כי הזמן הוא, לעסוק בתורה."]],[[0,"","מִמִּי לָמַדְנוּ? מִפָּרָשַׁת דָּוִד לָמַדְנוּ. מַה כָּתוּב? [שמואל ב יב] וַיָּבֹא הֵלֶךְ לְאִישׁ הֶעָשִׁיר. הֵלֶךְ שֶׁקָּרֵב לַפֶּתַח וְלֹא רוֹצֶה לְהִתְעַכֵּב שָׁם, אֶלָּא לָלֶכֶת לְדַרְכּוֹ. כָּךְ הוּא יֵצֶר הָרָע, כְּמוֹ שֶׁקָּרֵב לַבַּיִת מִתְקָרֵב לָאָדָם. מִתְעוֹרֵר עָלָיו בְּחֵטְא קָטָן, זֶהוּ אוֹרֵחַ עֲרַאי. רוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, מַה כָּתוּב? לַעֲשׂוֹת לָאֹרֵחַ הַבָּא לוֹ [אליו], נַעֲשֶׂה לוֹ אוֹרֵחַ אַכְסְנַאי בַּבַּיִת, מִתְעוֹרֵר עָלָיו בְּחֵטְא יוֹתֵר, יוֹם אֶחָד אוֹ יוֹמַיִם, כָּאוֹרֵחַ הַזֶּה שֶׁמַּשְׁהִים אוֹתוֹ בַּבַּיִת יוֹם אֶחָד אוֹ יוֹמַיִם, [בגלל שהוא אורח] כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, מַה כָּתוּב? [שם] וַיַּעֲשֶׂ [ה] לָאִישׁ הַבָּא אֵלָיו, נַעֲשָׂה בַּעַל הַבַּיִת, כְּמוֹ שֶׁנֶּאֱמר [בראשית מב] הָאִישׁ אֲדנֵי הָאָרֶץ. [רות א] אִישׁ נָעֳמִי. כָּךְ הוּא יֵצֶר הָרָע, נַעֲשֶׂה כְנֶגֶד הָאָדָם אִישׁ, בַּעַל הַבַּיִת, וְהִנֵּה נִקְשָׁר הָאָדָם לַעֲבוֹדָתוֹ, וְהוּא עוֹשֶׂה בּוֹ כִּרְצוֹנוֹ."],[1,"","וְעַל כֵּן צָרִיךְ אָדָם לָשִׂים דִּבְרֵי תוֹרָה עָלָיו תָּמִיד, כְּדֵי שֶׁיִּהְיֶה אוֹתוֹ יֵצֶר הָרָע שָׁבוּר בָּהֶם, שֶׁאֵין לַיֵּצֶר הָרָע מְקַטְרֵג פְּרָט לְדִבְרֵי תוֹרָה, וְעַל כֵּן כָּתוּב וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ', עַל לְבָבְךְ – עַל שְׁנֵי יְצָרֶיךְ, שֶׁיֵּצֶר הַטּוֹב מִתְעַטֵּר בָּהֶם, וְיֵצֶר הָרָע נִכְנָע בָּהֶם. אָמַר רַבִּי יְהוּדָה, מַה יֵּצֶר הַטּוֹב צָרִיךְ דִּבְרֵי תוֹרָה? אָמַר לוֹ, יֵצֶר הַטּוֹב מִתְעַטֵּר בָּהֶם. וְיֵצֶר הָרָע, כֵּיוָן שֶׁרוֹאֶה שֶׁאָדָם לֹא שָׁב וְלֹא רוֹצֶה לְהִשְׁתַּדֵּל בַּתּוֹרָה, אָז הוּא עוֹלֶה לְמַעְלָה וּמְלַמֵּד עָלָיו חוֹבָה, זֶהוּ שֶׁכָּתוּב [משלי ג] וּכְסִילִים מֵרִים קָלוֹן."],[2,"","כְּשֶׁבָּא רַבִּי שִׁמְעוֹן, אָמַר, הֲרֵי וַדַּאי פָּרָשַׁת קְרִיאַת שְׁמַע רְמוּזָה בּוֹ עֶשֶׂר אֲמִירוֹת כְּמוֹ שֶׁבֵּאֲרוּהָ, וְכָךְ הוּא וַדַּאי. וְהָיוּ הַדְּבָרִים הָאֵלֶּה, הֵם הַכְּלָל שֶׁל עֶשֶׂר הָאֲמִירוֹת, וּמִשּׁוּם כָּךְ יֵשׁ כָּאן עֶשֶׂר מִצְווֹת, כְּנֶגֶד עֶשֶׂר מִצְווֹת שֶׁל הַתּוֹרָה. וּמִי הֵן? וְשִׁנַּנְתָּם לְבָנֶיךְ. וְדִבַּרְתָּ בָּם. בְּשִׁבְתְּךְ בְּבֵיתֶךְ. וּבְלֶכְתְּךְ בַדֶּרֶךְ. וּבְשָׁכְבְּךְ. וּבְקוּמֶךְ. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךְ. וְהָיוּ לְ טָפֹת בֵּין עֵינֶיךְ. וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךְ. וּבִשְׁעָרֶיךְ. הֲרֵי עֶשֶׂר כְּנֶגֶד עֶשֶׂר אֲמִירוֹת. וְעַל כֵּן הַפָּרָשִׁיּוֹת הַלָּלוּ הֵן כְּלָל גָּדוֹל בַּתּוֹרָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמַּשְׁלִים אוֹתוֹ בְּכָל יוֹם פַּעֲמַיִם, שֶׁהֲרֵי הִתְקַדֵּשׁ בְּפִיו הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי."],[3,"","רַבִּי אָחָא הָיָה עוֹמֵד עִם רַבִּי אֶלְעָזָר לַיְלָה אֶחָד אַחֲרֵי חֲצוֹת הַלַּיְלָה, וְהָיוּ עוֹסְקִים בַּתּוֹרָה. פָּתַח רַבִּי אֶלְעָזָר [רבי אחא] וְאָמַר, [דברים ל] כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ וְגוֹ'. בֹּא וּרְאֵה, עַל כָּל הַתְּנָאִים [המצוות] שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנִּכְנְסוּ לְאֶרֶץ יִשְׂרָאֵל, גְּזֵרַת הַתּוֹרָה הָיְתָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה לֹא מִתְיַשֶּׁבֶת בָּאָרֶץ אֶלָּא בַּתּוֹרָה, וְלֹא מִתְיַשֶּׁבֶת לְמַעְלָה אֶלָּא בַּתּוֹרָה."],[4,"","שֶׁכָּךָ אָמַר [רבי שמעון] אַבָּא, תּוֹרָה שֶׁבְּעַל פֶּה לֹא נוֹדַעַת, אֶלָּא בִּשְׁבִיל תּוֹרָה שֶׁבִּכְתָב. הַשְּׁכִינָה לֹא מִתְיַשֶּׁבֶת לְמַעְלָה וּלְמַטָּה, אֶלָּא עִם הַתּוֹרָה שֶׁלְּמַטָּה. שֶׁכָּל זְמַן שֶׁהַתּוֹרָה נִמְצֵאת עִמּוֹ, יָכוֹל לַעֲמֹד בָּעוֹלָם. [תורה שבכתב לא נודעת אלא משום תורה שבעל פה, ותורה שבעל פה לא נודעת אלא מתורה שבכתב. ודאי כלל הצריך לפרט, ופרט הצריך לכלל. השכינה לא מתישבת למעלה אלא בתורה שלמטה. שכל זמן שהתורה נמצאת, יכולה להתקים בעולם] זֶהוּ שֶׁכָּתוּב כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ לָשֶׁבֶת עַל הָאֲדָמָה. עַל הָאֲדָמָה סְתָם. וְאִם לֹא שֶׁמַּפְסִיק דִּבְרֵי תוֹרָה, לֹא יָכוֹל לַעֲמֹד, שֶׁכָּתוּב [ירמיה ט] עַל מָה אָבְדָה הָאָרֶץ. וְכָתוּב, וַיֹּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי."],[5,"","בְּעוֹדָם יוֹשְׁבִים, הִנְמִיךְ רַבִּי שִׁמְעוֹן אֶת רֹאשׁוֹ וְאָמַר, וַדַּאי כָּךְ הוּא, וְזֶהוּ הַסּוֹד שֶׁמָּצָאנוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וּבֵאֵר הַפָּסוּק הַזֶּה בְּסוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב [שמות כא] שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע. וְאִם מוֹנְעִים מִמֶּנָּה, מַה כָּתוּב? וְיָצְאָה חִנָּם אֵין כָּסֶף, כְּמוֹ שֶׁנֶּאֱמַר [ישעיה נ] אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. וְכָתוּב [שם נב] חִנָּם נִמְכַּרְתֶּם וְלֹא בְכֶסֶף תִּגָּאֵלוּ. וּמִי שֶׁמּוֹנֵעַ מִמֶּנָּה תּוֹרָה, כְּמִי שֶׁלּוֹקֵחַ בַּעַל [שארה] שֶׁל אִשָּׁה וּמוֹנֵעַ אוֹתוֹ מִמֶּנָּה. זוֹ נִשְׁאֶרֶת כְּאַלְמָנָה, וְלֹא אַלְמָנָה. זֶהוּ שֶׁכָּתוּב [איכה א] הָיְתָה כְּאַלְמָנָה, וְלֹא אַלְמָנָה."],[6,"","יָשְׁבוּ וְהִתְעַסְּקוּ בַתּוֹרָה עַד שֶׁהֵאִיר הַיּוֹם. אַחַר שֶׁהֵאִיר הַיּוֹם, קָמוּ וְהָלְכוּ. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אִישׁ אֶחָד שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ וְרֹאשׁוֹ עָטוּף. קָרְבוּ אֵלָיו, וְהָיָה מְרַחֵשׁ בְּשִׂפְתוֹתָיו וְלֹא הֵשִׁיב לָהֶם דָּבָר. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי זֶה נִמְלָךְ בְּרִבּוֹנוֹ. יָשְׁבוּ רַבִּי אֶלְעָזָר וְרַבִּי אָחָא וְהִתְפַּלְלוּ תְפִלָּה, וְאוֹתוֹ הָאִישׁ עָמַד בִּמְקוֹמוֹ בְּמָקוֹם אַחֵר. אַחַר שֶׁסִּיְּמוּ הַתְּפִלָּה הָלְכוּ לַדֶּרֶךְ, וְאוֹתוֹ הָאִישׁ נִשְׁמַט מֵהֶם. אָמַר רַבִּי אֶלְעָזָר, הָאִישׁ הַזֶּה, אוֹ שֶׁהוּא טִפֵּשׁ, אוֹ שֶׁדְּרָכָיו לֹא יְשָׁרוֹת. אָמַר, נִתְעַסֵּק בַּתּוֹרָה, שֶׁהֲרֵי הַשָּׁעָה הִיא לָזֶה."]]],[["פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. כָּבוֹד חֲכָמִים יִנְחָלוּ, זַכָּאִין אִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא. עַד לָא פָּתַח מִלָּה, קָרִיב הַהוּא בַּר נָשׁ גַּבַּיְיהוּ. אָמַר רִבִּי אֶלְעָזָר, לֵית לָן לְמִפְסַק מִלֵּי דְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, זָכֵי לְמֵירַת יְרוּתָא דְּאַחֲסָנָא דִּלְעֵילָּא, בִּיקָרָא דְּמַלְכָּא עִלָּאָה קַדִּישָׁא, וְזָכֵי לְמֵירַת יְרוּתָא דְּאַחֲסָנָא בְּהַאי עָלְמָא, וּמַאי אִיהוּ. הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ', דְּלָא פָּסַק מִנַּיְיהוּ לְעָלְמָא. הֲדָא הוּא דִכְתִיב, כָּבוֹד חֲכָמִים יִנְחָלוּ, הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ'.","וּכְסִילִים מֵרִים קָלוֹן, מַאי הוּא. תָּא חֲזֵי, כַּד בַּר נָשׁ אָזַל בְּאֹרַח מֵישָׁר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתָּדַּל בְּאוֹרַיְיתָא, הָא הַהוּא כְּבוֹד יְיָ' יָרִית לְגַרְמֵיהּ, וְכַמָּה אַפֹּטְרוֹפְּסִין סַנֵּיגוֹרִין אִשְׁתַּכְּחוּ לְעֵילָּא עָלֵיהּ דְּבַּר נָשׁ, וְכֻלְּהוּ אוֹלְפִין עָלֵיהּ זְכוּ, קַמֵּי מַלְכָּא קַדִּישָׁא, וְאִי בַּר נָשׁ לָא אִשְׁתְּדַּל בְּאוֹרַיְיתָא, וְלָא אָזַל בְּאָרְחָא דְּמָארֵיהּ, הוּא עָבִיד קַטֵיגוֹרָא עָלֵיהּ. וְהַהוּא קַטֵיגוֹרָא שָׁאט בַּאֲוִירָא (ואזיל ליה), וְלָא סָלִיק לְעֵילָּא, דִּלְמָא יְתוּב אָדָם מֵחוֹבוֹי. כֵּיוָן דְּחָמֵי דְּבַר נָשׁ לָא תָּב, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּדֵין הוּא סָלִיק לְעֵילָּא, וְאוֹלִיף עָלֵיהּ חוֹבָא. הֲדָא הוּא דִכְתִיב, וּכְסִילִים מֵרִים קָלוֹן, וְסָלִיק לְעֵילָּא וְעָבִיד קִטְרוּגָא.","פָּתַח וְאָמַר, (זכריה י״ד:י״ח) וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְלֹא עֲלֵיהֶם תִּהְיֶה הַמַּגֵּפָה וְגוֹ'. מַאי שְׁנָא מִצְרַיִם הָכָא, מִכָּל שְׁאַר עַמִּין, דְּהָא לְכֻלְּהוּ כְּתִיב (שם) וְלֹא עֲלֵיהֶם יְהִי הַגָּשֶׁם, וְהָכָא לָא. אֶלָּא הָא אוֹקְמוּהָ חַבְרַיָּיא, דְּהָא אַרְעָא דְּמִצְרַיִם לָא אִצְטְרִיךְ לְמִטְרָא, וְעַל דָּא לָאו הִיא בִּכְלָלָא דְּאִינּוּן דְּבָעָן מִטְרָא, אֲבָל אִינּוּן, דִּינָא אַחֲרָא אִסְתַּלָּק עָלַיְיהוּ, וְשַׁפִּיר קָאַמְרוּ.","תָּא חֲזֵי, כְּתִיב (דברים י״א:י׳) כִּי הָאָרֶץ אֲשֶׁר אַתָּה בָא שָׁמָּה לְרִשְׁתָּה לֹא כְאֶרֶץ מִצְרַיִם הִיא אֲשֶׁר יְצָאתֶם מִשָּׁם וְגוֹ'. דְּהָא נַהֲרָא סָלִיק, (ומניה) מִנֵּיהּ מִשְׁתַּקְיָּיא אַרְעָא, אֲבָל הָכָא לִמְטַר הַשָּׁמַיִם תִּשְׁתֶּה מָּיִם, דְּהָא אַרְעָא קַדִּישָׁא מִן שְׁמַיָיא אִתְשַׁקְיָיא תָּדִיר. וְכַד יִשְׂרָאֵל הֲווֹ עַסְקִין בְּאוֹרַיְיתָא, הֲוָה אִתְשַׁקְיָיא כְּדְקָא יָאוּת. וּמַאן דְּמָנַע אוֹרַיְיתָא מִנָהּ, כְּאִילּוּ מָנַע טַב מִן כָּל עָלְמָא. עָאלוּ לְגוֹ מְעַרְתָּא חֲדָא דְּהֲוָה בְּאָרְחָא, עָאל הַהוּא גְּבַר עִמְּהוֹן, יָתְבוּ.","פָּתַח הַהוּא גַּבְרָא וְאָמַר, (שמות ל״ג:י״א) וְדִבֶּר יְיָ' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים כַּאֲשֶׁר יְדַבֵּר וְגוֹ', הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. וְלָא מִלָּה דָּא כְּמִלָה דָּא, בְּקַדְמִיתָא וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים שַׁפִּיר, לְבָתַר וְשָׁב אֶל הַמַּחֲנֶה, לְבָתַר וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, מַהוּ. אָמַר רִבִּי אֶלְעָזָר וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בִּיקָרָא דִּילָן, דְּהַשְׁתָּא זִוּוּגָא דִּילָן בִּשְׁכִינְתָּא, וּשְׁכִינְתָּא לָא אִתְעָדֵי מִנָן. מַאן דְּפָתַח פִּתְחָא, לֵימָּא מִלָּה.","פָּתַח וְאָמַר, וְדִבֶּר יְיָ' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים, בְּכַמָּה דַּרְגִּין עִלָּאִין וְיַקִּירִין, אִתְפְּרַשׁ מֹשֶׁה נְבִיאָה מְהֵימָנָא, עַל כָּל שְׁאַר נְבִיאֵי דְּעָלְמָא. דְּהָא כֻּלְּהוּ לָקֳבְלֵיהּ, כְּקוֹף בִּפְנֵי בְּנֵי נָשָׁא. שְׁאַר נְבִיאֵי הֲווֹ מִסְתַּכְּלֵי בְּאַסְפָּקָלַרְיָא דְּלָא נָהִיר, וְעִם כָּל דָּא לָא הֲווֹ זַקְפָן אַנְפִּין לְעֵילָּא לְאִסְתַּכְּלָא, אֶלָּא כְּמָה דִּכְתִּיב, (דניאל י׳:ט׳) וַאֲנִי הָיִיתִי נִרְדָּם עַל פָּנַי וּפָנַי אָרְצָה. וְלֹא עוֹד אֶלָּא דְּמִלִּין לָא הֲווֹ גַּבַּיְיהוּ בְּאִתְגַּלְיָיא.","וּמֹשֶׁה נְבִיאָה מְהֵימָנָא לָאו הָכִי, דְּהוּא הֲוָה מִסְתָּכַּל בְּאַסְפָּקָלַרְיָא דְּנַהֲרָא, וְקָאִים בְּקִיּוּמֵיהּ. וְלֹא עוֹד, אֶלָּא דְּהֲוָה זָקִיף רֵישָׁא לְאִסְתַּכְּלָא, כְּמַאן דְּאָמַר לְחַבְרֵיהּ, זָקוֹף רֵישָׁךְ, וְיִסְתַּכְּלוּן אַנְפָּךְ בְּאַנְפִּי (באנפאי), בְּגִין דְּתִנְדַּע מִלֵּי. כַּךְ מֹשֶׁה, פָּנִים אֶל פָּנִים זָקִיף רֵישָׁא, בְּלָא דְּחִילוּ, אַנְפּוֹי זַקְפָאן וּמִסְתְּכַּל בְּזִיו יְקָרָא עִלָּאָה, וְלָא אִשְׁתַּנֵי דַּעְתּוֹי וְאַנְפּוֹי, כִּשְׁאַר נְבִיאִין, דְּכַד הֲווֹ (מתנבאן) נַבְאָן (ס\"א בעאן) לְאִסְתַּכְּלָא, נַפְקָא מֵרְשׁוּתַיְיהוּ וּמִדַּעֲתַּיְיהוּ, וְאִשְׁתָּנֵי זִיו אַנְפַּיְיהוּ, וְלָא הֲווֹ יַדְעֵי מֵהַאי עָלְמָא כְּלוּם."],[[0,"פתח ר' אלעזר וכו':","פר\"א ואמר, כבוד חכמים ינחלו וכסילים מרים קלון. \u0003כבוד חכמים ינחלו\u0004, אשרי הם העוסקים בתורה. עד שלא הספיק לפתוח הדברים, קרב אותו איש אליהם. אמר ר' אלעזר, אין לנו להפסיק דברי תורה, כי כל מי שעוסק בתורה, זוכה לרשת ירושת הנחלה שלמעלה בכבוד מלך העליון הקדוש, ז\"א, וזוכה לרשת ירושת נחלה בעולם הזה, ומה הוא. הוא אותו שנקרא כבוד ה'. דהיינו המלכות הנקראת עולם הזה. שאינו פוסק מהם לעולם, ז\"ש \u0003כבוד\u0004 חכמים ינחלו. דהיינו שינחלו המלכות, אותה הנקראת כבוד ה'."],[1,"וכסילים מרים קלון:","שואל, וכסילים מרים קלון מה הוא. ומשיב, ת\"ח, כשאדם הולך בדרך הישר לפני הקב\"ה, ועוסק בתורה, הנה הוא יורש לעצמו אותו כבוד ה'. וכמה מגינים ומליצי יושר נמצאים למעלה על האדם, וכולם מלמדים עליו זכות לפני המלך הקדוש. ואם האדם אינו עוסק בתורה, ואינו הולך בדרך אדונו הוא עושה קטרוג עליו, ואותו הקטגור משוטט באויר ואינו עולה עוד למעלה, שחושב, אולי ישוב האדם בתשובה, לאחר שרואה שהאדם אינו שב, ואינו רוצה לעסוק בתורה, אז הוא עולה למעלה ומלמד עליו חוב. ז\"ש, וכסילים מרים קלון. כי עולה למעלה ועושה קטרוג."],[2,"פתח ואמר ואם וגו':","פו\"א, ואם משפחת מצרים לא תעלה ולא באה ולא עליהם תהיה המגפה וגו'. שואל, מה השינוי של מצרים כאן מכל שאר העמים, שבכולם כתוב, ולא עליהם יהיה הגשם, וכאן לא כתוב כן. ומשיב, אלא הרי העמידו החברים, אשר ארץ מצרים אינה צריכה לגשם, כי שותה ממימי הנילוס, וע\"כ אין היא בכלל של אותם הצריכים גשם, אבל הם, יבא עליהם דין אחר. ויפה אמרו."],[3,"ת\"ח כתיב כי וגו':","בוא וראה, כתוב, כי הארץ אשר אתה בא שמה לרשתה לא היא כארץ מצרים אשר יצאתם משם וגו' שהנהר עולה ומשקה הארץ, אבל כאן למטר השמים תשתה מים, כי ארץ הקדושה שותה משמים תמיד. וכשישראל היו עוסקים בתורה, היתה שותה כראוי. ומי שמונע התורה ממנה, כאלו מונע הטוב מכל העולם. נכנסו למערה אחת שהיתה בדרך. נכנס עמהם אותו האיש, וישבו."],[4,"פתח ההוא גברא וכו':","פתח אותו איש ואמר. ודבר ה' אל משה פנים אל פנים כאשר ידבר וגו'. מקרא זה אין ראשו סופו ואין סופו ראשו. ולא מלה זו כמלה זו. כי בתחילה אמר, ודבר ה' אל משה פנים אל פנים, טוב הוא. ואח\"כ אומר ושב אל המחנה, שאין לו קשר אל ודבר ה', ואח\"כ ומשרתו יהושע בן נון נער לא ימיש וגו', מהו, הרי אין לו קשר אל ושב אל המחנה. א\"ר אלעזר, ודאי, הקב\"ה רוצה ביקר שלנו, כי עתה חיבורינו היא בהשכינה, והשכינה לא תסור ממנו. מי שפתח הפתח יאמר הדבר."],[5,"פתח ואמר ודבר וגו':","פו\"א ודבר ה' אל משה פנים אל פנים. בכמה מדרגות עליונות ויקרות נבדל משה נביא הנאמן מכל שאר נביאי העולם. שכולם היו לפניו, כקוף בפני אדם. שאר הנביאים היו מסתכלים במראה שאינה מאירה, ועם כל זה לא היו נושאים פניהם למעלה להסתכל, אלא כמ\"ש, ואני הייתי נרדם על פני ופני ארצה. ולא עוד, אלא שהדברים לא היו אצלם בגלוי."],[6,"ומשה נביאה מהימנא וכו':","ומשה נביא הנאמן, לא היה כן, שהוא היה מסתכל במראה המאירה, ועמד במעמדו, ולא עוד אלא שהיה נושא ראשו להסתכל, כמי שאומר לחבירו נשא את ראשך ויסתכלו פניך בפני, כדי שתדע דברי. כך משה פנים אל פנים נשא ראשו בלא פחד, פניו היו נשואים למעלה ומסתכל בזיו יקר העליון, ולא נשתנה דעתו ופניו כשאר הנביאים, כי שאר הנביאים, כי היו מתנבאים להסתכל, יצאו מרשותם ודעתם, ונשתנה זיו פניהם, ולא היו יודעים מעולם זה כלום."]],[[0,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, [משלי ג] כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. כָּבוֹד חֲכָמִים יִנְחָלוּ, אַשְׁרֵי אוֹתָם שֶׁמִּתְעַסְּקִים בַּתּוֹרָה. וְטֶרֶם שֶׁפָּתַח בַּדָּבָר, קָרַב אֲלֵיהֶם אוֹתוֹ אָדָם. אָמַר רַבִּי אֶלְעָזָר, אֵין לָנוּ לְהַפְסִיק בְּדִבְרֵי תוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, זוֹכֶה לָרֶשֶׁת יְרֻשָּׁה שֶׁל הַנַּחֲלָה שֶׁלְּמַעְלָה, בַּכָּבוֹד שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, וְזוֹכֶה לָרֶשֶׁת יְרֻשָּׁה שֶׁל נַחֲלָה בָּעוֹלָם הַזֶּה. וּמִי הִיא? אוֹתוֹ שֶׁנִּקְרָא כְּבוֹד ה', שֶׁלֹּא פוֹסֵק מֵהֶם לְעוֹלָם. זֶהוּ שֶׁכָּתוּב כָּבוֹד חֲכָמִים יִנְחָלוּ, הַהוּא שֶׁנִּקְרָא כְּבוֹד ה'."],[1,"","וּכְסִילִים מֵרִים קָלוֹן, מַה הוּא? בֹּא וּרְאֵה, כְּשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִשְׁתַּדֵּל בַּתּוֹרָה, הֲרֵי אוֹתוֹ כְּבוֹד ה' הוּא יוֹרֵשׁ לְעַצְמוֹ, וְכַמָּה אֶפִּיטְרוֹפְּסִים וְסָנֵגוֹרִים נִמְצָאִים לְמַעְלָה עַל הָאָדָם, וְכֻלָּם מְלַמְּדִים עָלָיו זְכוּת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. וְאִם אֵין הָאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה וְלֹא הוֹלֵךְ בְּדֶרֶךְ רִבּוֹנוֹ, הוּא נַעֲשֶׂה עָלָיו קָטֵגוֹר. וְאוֹתוֹ קָטֵגוֹר מְשׁוֹטֵט בָּאֲוִיר [והולך לו], וְלֹא עוֹלֶה לְמַעְלָה, אוּלַי יָשׁוּב הָאָדָם מֵחֶטְאוֹ. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין הָאָדָם שָׁב וְלֹא רוֹצֶה לְהִשְׁתַּדֵּל בַּתּוֹרָה, אָז הוּא עוֹלֶה לְמַעְלָה וּמְלַמֵּד עָלָיו חוֹבָה. זֶהוּ שֶׁכָּתוּב וּכְסִילִים מֵרִים קָלוֹן, וְעוֹלֶה לְמַעְלָה וְעוֹשֶׂה קִטְרוּג."],[2,"","פָּתַח וְאָמַר, [זכריה יד] וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְלֹא עֲלֵיהֶם תִּהְיֶה הַמַּגֵּפָה וְגוֹ'. מַה שּׁוֹנֶה מִצְרַיִם כָּאן מִכָּל שְׁאָר הָעַמִּים, שֶׁהֲרֵי לְכֻלָּם כָּתוּב וְלֹא עֲלֵיהֶם יְהִי הַגָּשֶׁם, וְכָאן לֹא? אֶלָּא הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁהֲרֵי אֶרֶץ מִצְרַיִם אֵינָהּ צְרִיכָה מָטָר, וְעַל כֵּן אֵינָהּ בִּכְלַל אוֹתָן שֶׁצְּרִיכוֹת מָטָר, אֲבָל הֵם, דִּין אַחֵר עוֹלֶה עֲלֵיהֶם, וְיָפֶה אָמְרוּ."],[3,"","בֹּא וּרְאֵה, כָּתוּב [דברים יא] כִּי הָאָרֶץ אֲשֶׁר אַתָּה בָא שָׁמָּה לְרִשְׁתָּהּ לֹא כְאֶרֶץ מִצְרַיִם הִיא אֲשֶׁר יְצָאתֶם מִשָּׁם וְגוֹ'. שֶׁהֲרֵי הַנָּהָר הָעוֹלֶה, מִמֶּנּוּ מֻשְׁקֵית הָאָרֶץ, אֲבָל כָּאן – לִמְטַר הַשָּׁמַיִם תִּשְׁתֶּה מָּיִם, שֶׁהֲרֵי הָאָרֶץ הַקְּדוֹשָׁה מֻשְׁקֵית תָּמִיד מִן הַשָּׁמַיִם, וּכְשֶׁיִּשְׂרָאֵל הָיוּ עוֹסְקִים בַּתּוֹרָה, הָיְתָה מֻשְׁקֵית כָּרָאוּי. וּמִי שֶׁמּוֹנֵעַ מִמֶּנָּה תּוֹרָה, כְּאִלּוּ מוֹנֵעַ טוֹב מִכָּל הָעוֹלָם. נִכְנְסוּ לְתוֹךְ מְעָרָה אַחַת שֶׁהָיְתָה בַּדֶּרֶךְ, נִכְנַס עִמָּהֶם אוֹתוֹ הָאִישׁ. יָשְׁבוּ."],[4,"","פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, [שמות לג] וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים כַּאֲשֶׁר יְדַבֵּר וְגוֹ'. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ, וְלֹא מִלָּה זוֹ כְּמִלָּה זוֹ. בַּתְּחִלָּה וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים – יָפֶה. אַחַר כָּךְ וְשָׁב אֶל הַמַּחֲנֶה, אַחַר כָּךְ וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, מַהוּ? אָמַר רַבִּי אֶלְעָזָר, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בִכְבוֹדֵנוּ, שֶׁכָּעֵת הַזִוּוּג שֶׁלָּנוּ עִם הַשְּׁכִינָה, וְהַשְּׁכִינָה לֹא סָרָה מֵעִמָּנוּ. מִי שֶׁפּוֹתֵחַ פֶּתַח, יֹאמַר דָּבָר."],[5,"","פָּתַח וְאָמַר, וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים, בְּכַמָּה דְרָגוֹת עֶלְיוֹנוֹת וְנִכְבָּדוֹת נִפְרָד מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם, שֶׁהֲרֵי כֻּלָּם כְּנֶגְדּוֹ כְּמוֹ קוֹף בִּפְנֵי בְּנֵי אָדָם. שְׁאָר הַנְּבִיאִים הָיוּ מִסְתַּכְּלִים בְּאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, וְעִם כָּל זֶה לֹא הָיוּ זוֹקְפִים פָּנִים לְמַעְלָה לְהִסְתַּכֵּל, אֶלָּא כְּמוֹ שֶׁכָּתוּב [דניאל י] וַאֲנִי הָיִיתִי נִרְדָּם עַל פָּנַי וּפָנַי אָרְצָה. וְלֹא עוֹד, אֶלָּא שֶׁהַדְּבָרִים לֹא הָיוּ אֲלֵיהֶם בְּגָלוּי."],[6,"","וּמֹשֶׁה הַנָּבִיא הַנֶּאֱמָן לֹא כָּךְ, שֶׁהוּא הָיָה מִסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה וְעוֹמֵד בְּקִיּוּמוֹ, וְלֹא עוֹד, אֶלָּא שֶׁהָיָה זוֹקֵף רֹאשׁ לְהִסְתַּכֵּל, כְּמִי שֶׁאוֹמֵר לַחֲבֵרוֹ: זְקֹף רֹאשְׁךְ, וְיִסְתַּכְּלוּ פָנֶיךְ בְּפָנַי, כְּדֵי שֶׁתֵּדַע הַדְּבָרִים שֶׁלִּי. כָּךְ מֹשֶׁה, פָּנִים אֶל פָּנִים זוֹקֵף רֹאשׁ, בְּלִי פַחַד, פָּנִים זְקוּפוֹת, וּמִסְתַּכֵּל בְּזִיו הַכָּבוֹד הָעֶלְיוֹן, וְלֹא הִשְׁתַּנְּתָה דַעְתּוֹ וּפָנָיו כְּמוֹ שְׁאָר הַנְּבִיאִים, שֶׁכְּשֶׁהָיוּ מִתְנַבְּאִים [רוצים] לְהִסְתַּכֵּל, יָצְאוּ מֵרְשׁוּתָם וּמִדַּעְתָּם וְהִשְׁתַּנָּה זִיו פְּנֵיהֶם, וְלֹא הָיוּ יוֹדְעִים מֵהָעוֹלָם הַזֶּה כְּלוּם."]]],[["וּמֹשֶׁה לָאו הָכִי, דְּמֹשֶׁה בְּהַהוּא דַּרְגָּא עִלָּאָה מַמָּשׁ הֲוָה מִסְתָּכַּל, וְלָא נָפַק מֵרְשׁוּתֵיהּ וּמִן דַּעְתֵּיהּ, דְּהָא בְּשַׁעֲתָא דְּהֲוָה מִסְתָּכַּל בְּזִיו יְקָרָא עִלָּאָה, מִיַּד וְשָׁב אֶל הַמַּחֲנֶה, לְמַלְּלָא עִמְּהוֹן בְּכָל מַה דְּאִצְטְרִיכָאן, וְדַעְתּוֹי מִתְיַשְּׁבָא בֵּיהּ כְּקַדְמִיתָא, וְיַתִּיר. וְדָא הוּא וְשָׁב אֶל הַמַּחֲנֶה. וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, וַדַּאי דְּהֲוָה יָנִיק מִתּוֹךְ הָאֹהֶל, אוֹלִיף לְאִסְתַּכְּלָא בְּרוּחַ קוּדְשָׁא, כְּמָה דְאַתְּ אָמֵר (שמואל א ג׳:א׳) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת אֶת יְיָ'.","תָּא חֲזֵי, כָּל זִמְנָא דְּהֲוָה יְהוֹשֻׁעַ לְגַבֵּי דְּמֹשֶׁה, הֲוָה אוֹלִיף (ויניק) וְאָנִיק מִתּוֹךְ הָאוֹהֶל, וְלָא דָּחִיל. בָּתַר דְּאִתְפְּרַשׁ מִמֹּשֶׁה, וַהֲוָה בִּלְחוֹדוֹי, מַה כְּתִיב, (יהושע ה׳:י״ד) וַיִּפּוֹל יְהוֹשֻׁעַ עַל פָּנָיו אַרְצָה וְיִשְׁתָּחוּ, דְּלָא הֲוָה יָכִיל לְאִסְתַּכָּל, וְהַאי מֵחַד שְׁלִיחָא, כָּל שֶׁכֵּן מֵאֲתָר אַחֲרָא.","לְבַר נָשׁ, דְּאַפְקִיד מַלְכָּא גַּבֵּיהּ מָאנֵי דְּהָב וְאַבְנֵי יְקָר, כָּל זִמְנָא דְּמִשְׁתַּכַּח גַּבֵּיהּ, שַׁמָּשָׁא דְּבֵיתֵיהּ, אָחִיד בְּהוּ וְאִסְתְּכַּל בְּהוּ. כֵּיוָן דְּסָלִיק הַהוּא בַּר נָשׁ מֵעָלְמָא, לָא שָׁבִיק מַלְכָּא לְגַבֵּי שַׁמָּשָׁא כְּלוּם, וְאָחִיד פִּקְדּוֹנָא דִּילֵיהּ. אָמַר הַהוּא שַׁמָּשָׁא, וַוי דְּאָבָדִית. בְּיוֹמוֹי דְּמָארִי, כָּל אִלֵּין הֲווֹ בִּידִי.","כַּךְ יְהוֹשֻׁעַ, בְּיוֹמוֹי דְּמֹשֶׁה הֲוָה יָנִיק בְּכָל יוֹמָא מִתּוֹךְ הָאֹהֶל, וְלָא דָּחִיל. בָּתַר דְּשָׁכִיב, וַיִּפּוֹל יְהוֹשֻׁעַ עַל פָּנָיו. וַאֲנָא בְּגִין דַּאֲנָא שְׁכִיחַ בְּגַּוַויְיכוּ, אֶסְתָּכַּל בְּמִלֵי דְּאוֹרַיְיתָא, וְלָא אֱהֵא דָּחִיל. בָּתַר דְּאֶתְפְּרַשׁ מִנַּיְיכוּ, וְלָא אִיכוּל לְאִסְתַּכְּלָא בִּלְחוֹדָאי.","תּוּ פָּתַח וְאָמַר, (דברים ו׳:ז׳) וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם וְגוֹ'. כְּמָה דְאַתְּ אָמֵר (תהילים מ״ה:ו׳) חִצֶּיךָ שְׁנוּנִים. דְּבָעֵי בַּר נָשׁ לְחַדְּדָא מִלֵּי דְּאוֹרַיְיתָא לִבְרֵיהּ, כְּחַרְבָּא דְּאִיהוּ שִׁנָּנָא בִּתְרֵי סִטְרוֹי, בְּגִין דְּיֵיעוּל לֵיהּ חִדוּדָא וְחֶדְוָה (דאורייתא) בְּאוֹרַיְיתָא, וְלָא יִשְׁתְּכַּח לִבֵּיהּ בְּטִפְּשׁוּתָא. וְדִבַּרְתָּ בָּם, כָּל מִלִּין דְּאוֹרַיְיתָא, כָּל חַד וְחַד אוֹרְחָא לֵיהּ בִּלְחוֹדוֹי. וְדִבַּרְתָּ בָּם, וּתְדַבֵּר מִבָּעֵי לֵיהּ. אֶלָּא בָּעֵי בַּר נָשׁ לְאַנְהָגָא גַּרְמֵיהּ בְּהוּ, וּלְאִתְנַהֲגָא גַּרְמֵיהּ, דְּלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא.","בְּשִׁבְתְּךָ בְּבֵיתֶךָ, לְאַנְהָגָא גַּרְמֵיהּ בְּבֵיתֵיהּ בְּאֹרַח מֵישָׁר וּבְאֹרַח תִּקּוּנָא, דְּיִלְפוּן מִנֵּיהּ בְּנֵי בֵּיתֵיהּ לְאַנְהָגָא גַּרְמֵיהּ עִמְּהוֹן בְּנַחַת וּבְחֵידוּ, וְלָא יָטִיל דְּחִילוּ בִּבְנֵי בֵּיתֵיהּ יַתִּיר, וְכָל עוֹבָדוֹי בְּבֵיתֵיהּ בְּאֹרַח תִּקּוּנָא. וּבְלֶכְתְּךָ בַדֶּרֶךְ, לְאַנְהָגָא בְּמִלֵּי דְּאוֹרַיְיתָא, וּלְתַקְּנָא גַּרְמֵיהּ בְּהוּ כְּמָה דְּאִצְטְרִיךְ, וּלְדַבְּרָא גַּרְמֵיהּ בְּאוֹרְחוֹי דְּאוֹרַיְיתָא. וּמַאי אִיהוּ. כְּמָה דְּיַעֲקֹב. לְדוֹרוֹן. לִקְרָבָא. לִצְלוֹתָא. וּצְלוֹתָא בָּעֵי לְצַלָּאָה לְמָארֵיהּ, וְעֵילָּא מִנְּהוֹן מִלֵּי דְּאוֹרַיְיתָא.","וּבְשָׁכְבְּךָ, לְדַבְּרָא גַּרְמֵיהּ בִּדְחִילוּ דְּמָארֵיהּ, בִּקְדוּשָּׁה, בַּעֲנָוָה דְּלָא יִשְׁתְּכַח חָצִיף לָקֳבְלֵיהּ דְּמָארֵיהּ. וּבְקוּמֶךָ, לְמֵיהַב תּוּשְׁבְּחָן לְמָארֵיהּ דְּאָתִיב נִשְׁמָתֵיהּ. דְּהָא בְּכַמָּה חִיּוּבִין אִשְׁתְּכַח קַמֵּי מָארֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד עִמֵּיהּ חֶסֶד, וְאָתִיב לָהּ לְגוּפֵיהּ. (דברים ו׳:ח׳) וּקְשַׁרְתָּם לְאוֹת עַל יָדְכָה. הָא אוּקְמוּהָ, עַל יַד כֵּהָה, וְדָא הוּא שְׂמָאלָא. וּבְסִפְרָא דְּאַגַּדְתָּא אָמַר, עַל יַד כֹּ\"ה. כְּמָה דְאַתְּ אָמֵר (בראשית ט״ו:ה׳) כֹּ\"ה יִהְיֶה זַרְעֶךָ.","וְחַבְרַיָּיא יַתְבֵי דָּרוֹמָא אוֹקְמוּהָ בְּרָזָא דִּלְהוֹן, אַרְבַּע בָּתֵּי דִּתְפִילִין כְּהַאי גַּוְונָא. (נ\"א בגוונא אחרא) קַדֶּשׁ לִי כָל בְּכוֹר סְתָם, לָקֳבֵל כִּתְרָא עִלָּאָה דְּכֹלָּא. וְהָיָה כִּי יְבִיאֲךָ, לָקֳבֵל חָכְמָה. שְׁמַע יִשְׂרָאֵל וְאָהַבְתָּ, לָקֳבֵל בִּינָה. וְהָיָה לָקֳבֵל חֶסֶד. לְבָתַר כְּלִילָן כֻּלְּהוּ בִּדְרוֹעָא שְׂמָאלָא, דְּאִקְרֵי עֹז. וּכְתִיב, (ישעיהו ס״ב:ח׳) וּבִזְרוֹעַ עְֵזּוֹ. וְאֵין עֹז, אֶלָּא תּוֹרָה, וְאֵין עֹז, אֶלָּא תְּפִלִּין."],[[0,"ומשה לאו הכי וכו':","ומשה לא היה כן, כי משה באותה מדרגה עליונה ממש היה מסתכל, שהוא ז\"א, ולא יצא מרשותו ומדעתו, כי בשעה שהיה מסתכל בזיו יקר העליון, מיד ושב אל המחנה, שדבר עמהם בכל מה שצריכים, ודעתו היתה מיושבת עליו כבתחילה, ועוד יותר. וע\"כ אחר ודבר ה' אל משה פנים בפנים, נאמר ושב אל המחנה. ואח\"כ נאמר, ומשרתו יהושע בן נון נער, ודאי שהיה יונק מתוך האהל, שהיה לומד להסתכל ברוח הקדש, כש\"א והנער שמואל משרת את ה'."],[1,"ת\"ח כל זמנא וכו':","בוא וראה, כל זמן שהיה יהושע אצל משה, היה לומד ויונק מתוך האהל, שהוא מלכות, ולא היה מתירא. אחר שנפרד ממשה והיה לבדו, מה כתוב, ויפול יהושע אל פניו ארצה וישתחו. שלא היה יכול להסתכל. וזה היה מפני שליח אחד, ומכל שכן ממקום אחר."],[2,"לבר נש דאפקיד וכו':","וזה דומה, לאדם שהמלך הפקיד אצלו כלי זהב ואבני יקר. כל זמן שנמצא אצלו, היה גם המשמש של הבית אוחז בהם ומסתכל בהם, כיון שנפטר אותו אדם מן העולם, לא עזב המלך אצל המשמש כלום ולקח הפקדון שלו. אמר אותו המשמש, אוי לי שאבדתי, כל אלו דברים היקרים, בימיו של אדוני, כל אלו היו בידי."],[3,"כך יהושע ביומוי וכו':","כך יהושע. בימיו של משה היה יונק בכל יום מתוך האהל, שהוא המלכות, ולא היה מתירא, אחר שמת משה, ויפול יהושע על פניו. ואני, בשביל שאני נמצא בתוככם אסתכל בדברי תורה ולא אהיה מתירא. אחר שאפרד מכם, לא אוכל להסתכל לבדי."],[4,"תו פתח ואמר וכו':","עוד פו\"א, ושננתם לבניך ודברת בם וגו'. ושננתם, פירושו כש\"א חציך \u0003שנונים\u0004. כי אדם צריך לשנן דברי תורה לבנו, כחרב שהיא שנונה בב' צדדיה, כדי שיכניס בו חדוד ושמחה של תורה, ולא יהיה נמצא לבו בסכלות. \u0003ודברת בם\u0004, היינו שכל הדברים שבתורה יש לו לכל דבר ודבר דרך בפני עצמו. \u0003ודברת בם\u0004, שואל, ותדבר בם היה צריך לומר. ומשיב, אלא האדם צריך לנהוג עצמו בהם, ולהתנהג עצמו, שלא יטה לימין ולשמאל."],[5,"בשבתך בביתך:","היינו לנהוג עצמו בביתו בדרך הישר, ובדרך תקון, שילמדו ממנו בני ביתו. וינהוג עמהם בנחת ובשמחה. ולא יטיל אימה יתרה בתוך ביתו. וכל מעשיו בבית יהיו בדרך תקון. \u0003ובלכתך בדרך\u0004, להתנהג בדברי תורה, ויתקן עצמו בהם כמו שצריך, ולהנהיג עצמו בדרך התורה. ומה הוא. הוא כמו שהתנהג יעקב בדרך, בג' דברים, לדורון, ולתפלה ולמלחמה. ותפלה צריך להתפלל לאדונו, אבל דברי תורה, הם חשובים מתפלה."],[6,"ובשכבך, לדברא גרמיה וכו': ובשכבך",", פירושו, לנהוג עצמו ביראת אדונו, בקדושה, בענוה, שלא יהיה עז פנים לפני אדונו. \u0003ובקומך\u0004, היינו לתת תשבחות לאדונו, שהשיב נשמתו. כי בכמה עונות הוא נמצא לפני אדונו, והקב\"ה עשה עמו חסד והשיב נשמתו לגופו. \u0003וקשרתם לאות על ידכה\u0004, הרי העמידו על יד כהה, שזו היא יד שמאל, שהיא כהה וחלושה מיד ימין. ובספר אגדה אמר, ידכה, היינו על \u0003יד כה\u0004. שהיא המלכות הנקראת \u0003כה\u0004. כש\"א, \u0003כה\u0004 יהיה זרעך."],[7,"וחבריא יתבי דרומא וכו':","והחברים יושבי הדרום העמידו בסודות שלהם, ארבעה בתים של התפלין באפן זה. \u0003קדש לי כל בכור\u0004, בכור סתם הוא כנגד כתר עליון על הכל. שהוא נקרא בכור. \u0003והיה כי יביאך\u0004, הוא כנגד חכמה. \u0003שמע ישראל ואהבת\u0004, הוא כנגד בינה. \u0003והיה אם שמוע\u0004, הוא כנגד חסד. אח\"כ כלולים כולם בתפלין אשר בזרוע שמאל, הנקרא \u0003עז\u0004, שכתוב, ובזרוע עזו. ואין עז אלא תורה. ואין עז אלא תפלין."]],[[0,"","וּמֹשֶׁה לֹא כָּךְ, שֶׁמֹּשֶׁה הָיָה מִסְתַּכֵּל מַמָּשׁ בַּדַּרְגָּה הָעֶלְיוֹנָה הַהִיא, וְלֹא יָצָא מֵרְשׁוּתוֹ וּמִדַּעְתּוֹ, שֶׁהֲרֵי בְּשָׁעָה שֶׁהָיָה מִסְתַּכֵּל בְּזִיו הַכָּבוֹד הָעֶלְיוֹן, מִיָּד וְשָׁב אֶל הַמַּחֲנֶה, לְדַבֵּר עִמָּהֶם בְּכָל מַה שֶּׁהִצְטָרְכוּ, וְדַעְתּוֹ מִתְיַשֶּׁבֶת בּוֹ כְּבָרִאשׁוֹנָה, וְיוֹתֵר. וְזֶהוּ וְשָׁב אֶל הַמַּחֲנֶה. וּמְשָׁרֲתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, וַדַּאי שֶׁהָיָה יוֹנֵק מִתּוֹךְ הָאֹהֶל, לָמַד לְהִסְתַּכֵּל בְּרוּחַ הַקֹּדֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר [שמואל א ג] וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת אֶת ה'."],[1,"","בֹּא וּרְאֵה, כָּל זְמַן שֶׁהָיָה יְהוֹשֻׁעַ אֵצֶל מֹשֶׁה, הָיָה לוֹמֵד וְיוֹנֵק מִתּוֹךְ הָאֹהֶל וְלֹא פוֹחֵד. אַחַר שֶׁנִּפְרַד מִמֹּשֶׁה וְהָיָה לְבַדּוֹ, מַה כָּתוּב? [יהושע ה] וַיִּפֹּל יְהוֹשֻׁעַ אֶל פָּנָיו אַרְצָה וַיִּשְׁתָּחוּ. שֶׁלֹּא הָיָה יָכוֹל לְהִסְתַּכֵּל. וְזֶה מִשָּׁלִיחַ אֶחָד, כָּל שֶׁכֵּן מִמָּקוֹם אַחֵר."],[2,"","לְאָדָם אֶחָד שֶׁהִפְקִיד אֶצְלוֹ הַמֶּלֶךְ כְּלֵי זָהָב וַאֲבָנִים יְקָרוֹת. כָּל זְמַן שֶׁנִּמְצָאִים אֶצְלוֹ, הַשַּׁמָּשׁ שֶׁל בֵּיתוֹ אוֹחֵז בָּהֶם וּמִסְתַּכֵּל בָּהֶם. כֵּיוָן שֶׁהִסְתַּלֵּק אוֹתוֹ אָדָם מֵהָעוֹלָם, לֹא הִשְׁאִיר הַמֶּלֶךְ אֵצֶל הַשַּׁמָּשׁ כְּלוּם, וְאָחַז אֶת פִּקְדוֹנוֹ. אָמַר אוֹתוֹ שַׁמָּשׁ: אוֹי עַל מַה שֶּׁאִבַּדְתִּי. בִּימֵי אֲדוֹנִי הָיוּ כָּל אֵלֶּה בְּיָדִי."],[3,"","כָּךָ יְהוֹשֻׁעַ, בִּימֵי מֹשֶׁה הָיָה יוֹנֵק בְּכָל יוֹם מִתּוֹךְ הָאֹהֶל וְלֹא פוֹחֵד. אַחַר שֶׁנִּפְטַר, וַיִּפֹּל יְהוֹשֻׁעַ עַל פָּנָיו. וַאֲנִי, מִשּׁוּם שֶׁאֲנִי מָצוּי בְּתוֹכֲכֶם, אֶסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה וְלֹא אֶפְחַד. אַחַר שֶׁאֶפָּרֵד מִכֶּם, וְלֹא אוּכַל לְהִסְתַּכֵּל לְבַדִּי."],[4,"","עוֹד פָּתַח וְאָמַר, וְשִׁנַּנְתָּם לְבָנֶיךְ וְדִבַּרְתָּ בָּם וְגוֹ'. כְּמוֹ שֶׁנֶּאֱמַר [תהלים מה] חִצֶּיךְ שְׁנוּנִים. שֶׁצָּרִיךְ אָדָם לְחַדֵּד דִּבְרֵי תוֹרָה לִבְנוֹ כַּחֶרֶב שֶׁהִיא שְׁנוּנָה בִּשְׁנֵי הַצְּדָדִים, כְּדֵי שֶׁיַּכְנִיס לוֹ הַחִדּוּד וְהַשִּׂמְחָה בַּתּוֹרָה, וְלֹא יִמָּצֵא לִבּוֹ בְּטִפְּשׁוּת. וְדִבַּרְתָּ בָּם, כָּל דִּבְרֵי הַתּוֹרָה, לְכָל אֶחָד וְאֶחָד יֵשׁ לוֹ דֶּרֶךְ לְבַדּוֹ. וְדִבַּרְתָּ בָּם?! וּתְדַבֵּר הָיָה צָרִיךְ לוֹ לִכְתֹּב! אֶלָּא צָרִיךְ אָדָם לְהַנְהִיג עַצְמוֹ בָּהֶם, וּלְהַנְהִיג עַצְמוֹ שֶׁלֹּא יִסְטֶה לְיָמִין וְלִשְׂמֹאל."],[5,"","בְּשִׁבְתְּךָ בְּבֵיתֶךְ, לְהַנְהִיג עַצְמוֹ בְּבֵיתוֹ בְּדֶרֶךְ יְשָׁרָה וּבְדֶרֶךְ תְּקִינָה, שֶׁיִּלְמְדוּ מִמֶּנּוּ בְּנֵי בֵיתוֹ לְהַנְהִיג עַצְמָם בְּנַחַת וּבְשִׂמְחָה, וְלֹא יַטִּיל פַּחַד בִּבְנֵי בֵיתוֹ יוֹתֵר, וְכָל מַעֲשָׂיו בְּבֵיתוֹ בְּדֶרֶךְ תְּקִינָה. וּבְלֶכְתְּךְ בַדֶּרֶךְ, לְהַנְהִיג בְּדִבְרֵי תוֹרָה, וּלְתַקֵּן אֶת עַצְמוֹ בָהֶם כְּמוֹ שֶׁצָּרִיךְ, וּלְהַנְהִיג עַצְמוֹ בְּדַרְכֵי הַתּוֹרָה. וּמַה הוּא? כְּמוֹ שֶׁיַּעֲקֹב, לְדוֹרוֹן, לִקְרָב וְלִתְפִלָּה. וְהַתְּפִלָּה צָרִיךְ לְהִתְפַּלֵּל לְרִבּוֹנוֹ, וּמֵעַל כֻּלָּם דִּבְרֵי תוֹרָה."],[6,"","וּבְשָׁכְבְּךָ, לְהַנְהִיג עַצְמוֹ בְּיִרְאַת רִבּוֹנוֹ, בִּקְדֻשָּׁה וּבַעֲנָוָה, שֶׁלֹּא יִמָּצֵא חָצוּף כְּנֶגֶד רִבּוֹנוֹ. וּבְקוּמֶךְ, לָתֵת תִּשְׁבָּחוֹת לְרִבּוֹנוֹ שֶׁהֵשִׁיב נִשְׁמָתוֹ. שֶׁהֲרֵי בְּכַמָּה חִיּוּבִים הוּא נִמְצָא לִפְנֵי רִבּוֹנוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה עִמּוֹ חֶסֶד וּמֵשִׁיב אוֹתָהּ לְגוּפוֹ. וּקְשַׁרְתָּם לְאוֹת עַל [ידך] יָדְכָה, הֲרֵי פֵּרְשׁוּהָ עַל יָד כֵּהָה, וְזוֹהִי הַשְּׂמֹאל. וּבְסֵפֶר הָאַגָּדָה אָמַר, עַל יַד כֹּ\"ה, כְּמוֹ שֶׁנֶּאֱמַר [בראשית טו] כֹּ\"ה יִהְיֶה זַרְעֶךְ."],[7,"","וַחֲבֵרֵינוּ יוֹשְׁבֵי הַדָּרוֹם פֵּרְשׁוּהָ בַּסּוֹד שֶׁלָּהֶם, אַרְבַּע בָּתֵּי הַתְּפִלִּין כְּמוֹ זֶה [בצורה אחרת]. קַדֶּשׁ לִי כָל בְּכוֹר, סְתָם – כְּנֶגֶד הַכֶּתֶר הָעֶלְיוֹן שֶׁל הַכֹּל. וְהָיָה כִּי יְבִיאֲךְ – כְּנֶגֶד חָכְמָה. שְׁמַע יִשְׂרָאֵל וְאָהַבְתָּ – כְּנֶגֶד בִּינָה. וְהָיָה – כְּנֶגֶד חֶסֶד. אַחַר כָּךְ כְּלוּלִים כֻּלָּם בִּזְרוֹעַ שְׂמֹאל שֶׁנִּקְרֵאת עֹז, וְכָתוּב [ישעיה סב] וּבִזְרוֹעַ עֻזּוֹ. וְאֵין עֹז אֶלָּא תּוֹרָה, וְאֵין עֹז אֶלָּא תְּפִלִּין."]]],[["וּמִלִּין לָא מִתְיַשְּׁבָן לְגַבָּן. מַאי טַעְמָא. בְּגִין דְּכִתְרָא עִלָּאָה הוּא כָּלִיל כֹּלָּא, דְּלָאו הוּא בְּחוּשְׁבָּנָא. וְעוֹד, וְהָיָה כִּי יְבִיאֲךָ בִּיצִיאַת מִצְרַיִם תַּלְיָיא, הַהוּא אֲתָר דְּאִשְׁתְּכַח בֵּיהּ חֵירוּ לְעַבְדִין, וְעַל דָּא לָא מִתְתַּקְּנָן בְּאָרְחַיְיהוּ. וַאֲנָן מֵחָכְמָה שַׁרְיָין, וְהָכִי הוּא וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיל לוֹן, אַרְבַּע לְעֵילָּא, אַרְבַּע לְתַתָּא, אַרְבַּע בַּאֲתָר דְּמוֹחָא. אַרְבַּע בַּאֲתָר דְּלִבָּא שַׁרְיָיא. בְּגִין דְּדָא בְּדָא אִתְקְשַּׁר.","וּבָעֵי בַּר נָשׁ לְאִתְעַטְּרָא בְּהוּ, בְּגִין דְּאִיהוּ שְׁמָא קַדִּישָׁא עִלָּאָה. דִּכְתִּיב, (דברים כ״ח:י׳) וְרָאוּ כֹּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' וְגוֹ'. וְכָל מַאן דְּמִתְעַטָּר בְּעִטְרָא קַדִּישָׁא עִלָּאָה דָּא, אִקְרֵי מֶלֶךְ בְּאַרְעָא. וְקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ בִּרְקִיעָ. הֲדָא הוּא דִכְתִיב, (שיר השירים ז׳:ו׳) מֶלֶךְ אָסוּר בָּרְהָטִים. כְּמָה דְּקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ לְעֵילָּא, הָכִי נָמֵי הוּא מֶלֶךְ לְתַתָּא. (ועם כל דא) וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ, בְּגִין דִּיהֱוֵי בַּר נָשׁ שְׁלִים בְּכֹלָּא, וְיִשְׁתְּכַּח שְׁלִים בְּפִקּוּדֵי דְּמָארֵיהּ, רָשִׁים לְעֵילָּא, רָשִׁים לְתַתָּא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, תְּרֵי קְרָאֵי אַשְׁכַּחְנָא, דְּאַף עַל גַּב דְּכֹלָּא בְּחַד דַּרְגָּא תַּלְיָין, לָאו אִינּוּן מִדַּרְגָּא חַד. חַד קְרָא כְּתִיב, (חגי א) כֹּה אָמַר יְיָ' צְבָאוֹת. וְחַד קְרָא כְּתִיב, (ישעיה ו) כֹּה אָמַר יְיָ' אֱלֹהִים. מַה בֵּין הַאי לְהַאי. אֶלָּא בְּזִמְנָא דִּכְתִּיב כֹּה אָמַר יְיָ' צְבָאוֹת, כְּדֵין מִלָּה אַתְיָא בְּרַחֲמֵי. וּבְזִמְנָא דִּכְתִּיב כֹּה אָמַר יְיָ' אֱלֹהִים, כְּדֵין מִלָּה אַתְיָא בְּדִינָא.","כֹּה אָמַר יְיָ' צְבָאוֹת, בְּגִין דְּהַאי כֹּה, אִתְבָּרְכָא מִצַדִּיק וּמִנֶצַח וְהוֹד, דְּאִקְרֵי יְיָ' צְבָאוֹת. וּכְדֵין, מִלָּה בְּאִתְבַּסְּמוּתָא אַתְיָיא, דְּהָא מֵאֲתָר דָּא קָא אַתְיָא. כֹּה אָמַר יְיָ' אֱלֹהִים, כְּדֵין הַאי כֹּה יַנְקָא מִסִּטְרָא דְּדִינָא, מֵאֲתָר דִּגְבוּרָה עִלָּאָה, וְאוֹלִיפְנָא מֵאַבָּא, דְּדִינָא הוּא בְּרַחֲמֵי, בְּגִין דִּכְתִּיב יְיָ' אֱלֹהִים.","דְּהָא אֱלֹהִים גְּבוּרָה הוּא בְּכָל אֲתָר אֲדֹנָי, גְּבוּרָה תַּתָּאָה הִיא בְּכָל אֲתָר. וְעַל דָּא אִשְׁתְּמוֹדְעָן מִלֵּי מִפּוּמָא דִּנְבִיאָה, וְהוּא הֲוָה מִתְכַּוֵּין לְמֵימַר מִלָּה מֵאַתְרֵיהּ. וּכְדֵין הֲווֹ יַדְעֵי אִלֵּין בְּנֵי מְהֵימְנוּתָא, מֵאָן אֲתָר תַּלְיָיא מִלְּתָא.","פָּתַח רִבִּי אֲחָא וְאָמַר (שופטים ה׳:כ״ג) אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ יְיָ' וְגוֹ'. תָּא חֲזֵי, הַאי קְרָא רָזָא הוּא בְּרָזִין עִלָּאִין. בְּשַׁעֲתָא דְּמַלְכָּא קַדִּישָׁא מָסַר בֵּיתֵיהּ בִּידָא דְּמַטְרוֹנִיתָא כָּל זַיְינִין וְרוּמְחִין וּבַלֵיסְטְרָאוֹת דִּילֵיהּ אַפְקִיד בִּידָהָא, וְכָל אִינּוּן מַגִיחֵי קְרָבָא דִּילֵיהּ אַפְקִיד עִמָּהּ. הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל, וְהָא אוֹקְמוּהָ, וְכַד אֲגַח קוּדְשָׁא בְּרִיךְ הוּא קְרָבָא, בְּאִינּוּן גִּבּוֹרִין מַגִיחֵי קְרָבָא דְּקָאָמַרָן אַגָח, וְאִינּוּן אִקְרוּן מְלוּמְּדֵי מִלְחָמָה.","כְּתִיב (שופטים ה׳:כ׳) מִן שָׁמַיִם נִלְחָמוּ הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא וְגוֹ'. וּתְנָן, בְּהַאי שַׁעֲתָא דְּאִתְנְדִיבוּ יִשְׂרָאֵל לְגַלָּאָה רְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵהוֹן, כְּדֵין הַאי חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, כָּנַשׁ כָּל חֵילָא דִּילֵיהּ, וְכָל זַיְינִין, וְכָל אִינּוּן מַגִיחֵי קְרָבָא, לְאַגָּחָא קְרָבָא עִמֵּיהּ (נ\"א דסיהרא) דְּסִיסְרָא. וְכוֹכָבַיָּיא הֲווֹ אוֹשְׁדִין נוּרָא מִלְעֵילָּא. וְאָמַר רִבִּי שִׁמְעוֹן, כָּל כּוֹכָב וְכוֹכָב אִית לֵיהּ שְׁמָא בִּלְחוֹדוֹי, וְכֻלְּהוּ בִּשְׁמָהָן אִקְרוּן.","אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִתְעַתְּדוּ לְנַקְמָא נוּקְמָא דְּבָנַי. תְּרֵי נוּקְמֵי אֲנָא זַמִּין לְאִתְפָּרְעָא מִנַּיְיהוּ. חַד נוּקְמָא דְּשִׁית מְאָה רְתִיכִין דְּאוֹזִיף לֵיהּ לְרַבְרְבָא דְּמִצְרָאֵי, בְּגִין לְאַגָחָא קְרָבָא בְּהוּ בְּיִשְׂרָאֵל. דִּכְתִּיב, (שמות י״ד:ז׳) וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְכֹל רֶכֶב מִצְרָיִם. וְחַד נוּקְמָא דְּבָנַי, דְּעָאקוּ לְהוּ עַד הַשְׁתָּא. וּבְגִין כַּךְ אִתְדָּנוּ בִּתְרֵין דִּינִין, חַד בְּמַיָּיא, וְחַד בְּאֶשָּׁא. בְּמַיָּיא, דִּכְתִּיב, (שופטים ה׳:כ״א) נַחַל קִישׁוֹן גְּרָפָם. בְּאֶשָּׁא, דִּכְתִּיב הַכּוֹכָבִים מִמְּסִלּוֹתָם.","וּבְאִינּוּן כֹּכָבַיָיא, אִית כֹּכָבָא חַד דְּלָא אָתָא לְהַהוּא נוּקְמָא, וְאִתְלַטְּיָּא לְעָלְמִין, דְּכַד שָׁארֵי לְאַנְהָרָא, אָתָאן שְׁאַר כֹּכָבַיָיא וּבַלְעִין לֵיהּ, וּלְכָל סִיעָתָא דִּילֵיהּ, וְאִתְאֲבִידוּ כֻּלְּהוּ כַּחֲדָא. כְּמָה דְאַתְּ אָמֵר, אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ יְיָ'. וְכִי רְשׁוּת אִית לְמַלְאָכָא בְּהַאי. אֶלָּא דָּא הוּא מַלְאָךְ, דִּכְתִּיב בֵּיהּ (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְדָא הוּא דְּכָל קְרָבִין דִּילֵיהּ אִינּוּן."],[[0,"ומלין לא מתיישבן וכו':","והדברים אינם מיושבים אצלנו. מה הטעם. הוא משום שהכתר העליון כולל הכל, והוא אינו בחשבון, של ד' הפרשיות. ועוד. והיה כי יביאך, תלויה ביציאת מצרים, שהוא אותו מקום שנמצא בו חירות לעבדים, דהיינו בינה, ועל כן אין דרכם של חברינו יושבי הדרום מתוקן. אלא אנו מתחילים מחכמה, שקדש לי כל בכור הוא חכמה, ולא כתר, וכך הוא. והקב\"ה, שהוא ז\"א, מניח אותם התפלין. ארבעה פרשיות הם למעלה, וארבעה למטה. ומפרש, ארבעה הם במקום המוח. דהיינו שהם ארבעה מוחין דז\"א. ארבעה הם במקום שהלב שורה, שהוא המלכות. משום שזה נקשר בזה. שז\"א נקשר במלכות."],[1,"ובעי ב\"נ לאתעטרא וכו':","וצריך האדם להתעטר בהם. משום שהם שם הקדוש העליון, דהיינו הוי\"ה, שכתוב, וראו כל עמי הארץ כי שם ה' נקרא עליך וגו'. וכל מי שמתעטר בעטרה הקדושה העליונה הזו, נקרא מלך בארץ. והקב\"ה מלך ברקיע. ז\"ש מלך אסור ברהטים. כמו שהקב\"ה הוא מלך למעלה, הוא גם כן מלך למטה, \u0003וכתבתם על מזוזות ביתך\u0004, היינו כדי שהאדם יהיה שלם בכל, ויהיה שלם במצות אדונו, רשום למעלה רשום למטה. אשרי חלקם של ישראל."],[2,"פתח ר' אלעזר וכו':","פתח ר\"א ואמר, ב' כתובים מצאתי, ואע\"פ שהכל במדרגה אחת תלוי, עכ\"ז אינם ממדרגה אחת. מקרא אחד כתוב, כה אמר הויה צבאות. ומקרא אחד כתוב כה אמר הויה אלקים. מה בין זה לזה. ומשיב, אלא בזמן שכתוב, כה אמר הויה צבאות, אז הדבר בא ברחמים. ובזמן שכתוב, כה אמר הויה אלקים, אז הדבר בא בדין."],[3,"כה אמר ה' וגו':","ומפרש הדברים. בכתוב, \u0003כה\u0004 אמר הויה צבאות, הוא משום ש \u0003כה\u0004 הזה, שהוא מלכות, מתברכת מן צדיק, שהוא יסוד, ומנצח והוד הנקראים ה' צבאות. ואז הדבר בא בהמתקה, כי ממקום זה בא, מיסוד. והכתוב, \u0003כה\u0004 אמר ה' אלקים, אז \u0003כה\u0004 הזו שהיא מלכות, יונקת מצד הדין, ממקום גבורה עליונה, דהיינו גבורה דז\"א, ולמדתי מאבי, שהדין הוא ברחמים, משום שכתוב, הויה אלקים. שהויה הוא רחמים ואלקים הוא דין."],[4,"דהא אלקים גבורה וכו':","כי \u0003אלקים\u0004 הוא בכל מקום גבורה. \u0003אדני\u0004, הוא בכל מקום גבורה תחתונה. ועל כן ניכרים הדברים מפי הנביא על פי השם שהזכיר, מאיזו מדרגה הוא מתנבא, שהוא היה מתכוין לומר דבר ממקומו. ואז היו יודעים בני האמונה, מאיזה מקום תלוי הדבר."],[5,"פתח ר' אחא וכו':","פר\"א ואמר, אורו מרוז אמר מלאך ה' וגו'. בוא וראה מקרא זה סוד הוא בסודות עליונים. בשעה שהמלך הקדוש מסר ביתו ליד המלכה, כל כלי זיין ורמחים ומרגמות שלו, הפקיד בידיה. וכל אלו עושי מלחמה שלו הפקיד עמה. ז\"ש, הנה מטתו שלשלמה, שה\"ס המלכות, ששים גבורים סביב לה מגבורי ישראל. וכבר העמידוהו. שה\"ס חג\"ת נה\"י מצד הגבורה, שכל אחד כלול מעשר וכשעושה הקב\"ה מלחמה עושה באלו הגבורים עושי מלחמה שאמרנו. והם נקראים מלומדי מלחמה."],[6,"כתיב מן שמים וגו':","כתוב מן שמים נלחמו הכוכבים ממסלותם וגו'. ולמדנו באותה שעה שהתנדבו ישראל לגלות רושם הקדוש של מילה בבשרם, אז אותה החרב הנוקמת נקם ברית, שהיא המלכות, אספה כל הצבאות שלה וכל כלי זיין וכל אלו עושי מלחמה, לעשות מלחמה עם סיסרא. והכוכבים היו שופכים אש מלמעלה. ואמר ר' שמעון כל כוכב וכוכב יש לו שם בפני עצמו. כמ\"ש וכולם בשמות יקרא."],[7,"אמר לון קב\"ה וכו':","אמר להם הקב\"ה אל הכוכבים, הכינו עצמכם לנקום מסיסרא נקמת בני. ב' נקמות אני עתיד להפרע מהם, נקמה א', על שש מאות רכב שהשאיל לשרי מצרים, כדי שיעשו מלחמה בישראל. שכתוב, ויקח שש מאות רכב בחור וכל רכב מצרים. ועוד נקמה של בני, על שהצירו להם עד עתה. ומשום זה נדונו בב' דינים א' במים וא' באש. במים, כי כתוב, נחל קישון גרפם. באש, שכתוב הככבים ממסלותם."],[8,"ובאינון כוכביא אית וכו':","ובאלו הכוכבים היה כוכב אחד שלא בא לאותה הנקמה, ונתקלל לעולם, אשר כשמתחיל להאיר באים שאר הכוכבים ובולעים אותו ואת כל המחנה שלו ונאבדים כולם כאחד. כש\"א אורו מרוז אמר מלאך ה'. שואל, וכי יש לו רשות למלאך בזה. שיקלל למי. ומשיב, אלא זהו מלאך שכתוב בו, ויסע מלאך האלקים ההולך לפני מחנה ישראל. וזה הוא שכל המלחמות הן שלו. דהיינו המלכות."]],[[0,"","וְהַדְּבָרִים לֹא מְיֻשָּׁבִים אֶצְלֵנוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַכֶּתֶר הָעֶלְיוֹן כּוֹלֵל הַכֹּל, שֶׁאֵינוֹ בְחֶשְׁבּוֹן. וְעוֹד, וְהָיָה כִּי יְבִיאֲךְ תָּלוּי בִּיצִיאַת מִצְרַיִם, אוֹתוֹ מָקוֹם שֶׁנִּמְצֵאת בּוֹ חֵרוּת לָעֲבָדִים, וְעַל כֵּן לֹא מְתֻקָּנִים בְּדַרְכֵיהֶם. וְאָנוּ שְׁרוּיִים מֵחָכְמָה, וְכָךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אוֹתָם; [וכן] אַרְבַּע לְמַעְלָה, וְאַרְבַּע לְמַטָּה, וְאַרְבַּע בִּמְקוֹם הַמֹּחַ, וְאַרְבַּע בְּמָקוֹם שֶׁשָּׁרוּי הַלֵּב. מִשּׁוּם שֶׁזֶּה נִקְשָׁר בָּזֶה."],[1,"","וְצָרִיךָ הָאָדָם לְהִתְעַטֵּר בָּהֶם, מִשּׁוּם שֶׁהוּא שֵׁם קָדוֹשׁ עֶלְיוֹן, שֶׁכָּתוּב [דברים כח] וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' וְגוֹ'. וְכָל מִי שֶׁמִּתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה עֶלְיוֹנָה זוֹ, נִקְרָא מֶלֶךְ בָּאָרֶץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ בָּרָקִיעַ. זֶהוּ שֶׁכָּתוּב [שיר ז] מֶלֶךְ אָסוּר בָּרְהָטִים. כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ לְמַעְלָה, כָּךְ גַּם הוּא מֶלֶךְ לְמַטָּה. וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךְ, כְּדֵי שֶׁיִּהְיֶה אָדָם שָׁלֵם בַּכֹּל, וְיִמָּצֵא שָׁלֵם בַּמִּצְווֹת שֶׁל רִבּוֹנוֹ, רָשׁוּם לְמַעְלָה רָשׁוּם לְמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל."],[2,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, שְׁנֵי פְסוּקִים מָצָאתִי, שֶׁאַף עַל גַּב שֶׁהַכֹּל תְּלוּיִים בְּדַרְגָּה אַחַת, אֵינָם מִדַּרְגָּה אַחַת. בְּפָסוּק אֶחָד כָּתוּב, [חגי א] כֹּה אָמַר ה' צְבָאוֹת. וּבְפָסוּק אֶחָד כָּתוּב, כֹּה אָמַר ה' אֱלֹהִים. מַה בֵּין זֶה לָזֶה? אֶלָּא בִּזְמַן שֶׁכָּתוּב כֹּה אָמַר ה' צְבָאוֹת, אֲזַי הַדָּבָר בָּא בְרַחֲמִים. וּבִזְמַן שֶׁכָּתוּב כֹּה אָמַר ה' אֱלֹהִים, אֲזַי הַדָּבָר בָּא בְדִין."],[3,"","כֹּה אָמַר ה' צְבָאוֹת, מִשּׁוּם שֶׁהַכֹּה הַזּוֹ מִתְבָּרֶכֶת מִצַּדִּיק וּמִנֵּצַח וְהוֹד, שֶׁנִּקְרָא ה' צְבָאוֹת. וְאָז הַדָּבָר בָּא בְּהִתְבַּסְּמוּת, שֶׁהֲרֵי מֵהַמָּקוֹם הַזֶּה הוּא בָּא. כֹּה אָמַר ה' אֱלֹהִים, אָז הַכֹּה הַזּוֹ יוֹנֶקֶת מִצַּד הַדִּין מִמְּקוֹם הַגְּבוּרָה הָעֶלְיוֹנָה, וְלָמַדְנוּ מֵאַבָּא שֶׁהַדִּין הוּא בְּרַחֲמִים, מִשּׁוּם שֶׁכָּתוּב ה' אֱלֹהִים."],[4,"","שֶׁהֲרֵי אֱלֹהִים הוּא גְּבוּרָה בְּכָל מָקוֹם. אֲדנָי, גְּבוּרָה תַחְתּוֹנָה הִיא בְּכָל מָקוֹם. וְעַל כֵּן נוֹדָעִים הַדְּבָרִים מִפִּי הַנָּבִיא, וְהוּא הָיָה מִתְכַּוֵּן לוֹמַר דָּבָר מִמְּקוֹמוֹ. וְאָז הָיוּ יוֹדְעִים בְּנֵי הָאֱמוּנָה הַלָּלוּ, מֵאֵיזֶה מָקוֹם תָּלוּי הַדָּבָר."],[5,"","פָּתַח רַבִּי אָחָא וְאָמַר, [שופטים ה] אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ ה' וְגוֹ'. בּא וּרְאֵה, הַפָּסוּק הַזֶּה הוּא סוֹד בַּסּוֹדוֹת הָעֶלְיוֹנִים. בְּשָׁעָה שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ מָסַר אֶת בֵּיתוֹ בִּידֵי הַגְּבִירָה, כָּל כְּלֵי הַזַּיִן וְהָרְמָחִים וְהַבַּלִּיסְטְרָאוֹת שֶׁלּוֹ הִפְקִיד בְּיָדֶיהָ, וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב שֶׁלּוֹ הִפְקִיד עִמָּהּ. זֶהוּ שֶׁכָּתוּב [שיר השירים ג] הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ מִגִּבֹּרֵי יִשְׂרָאֵל, וַהֲרֵי פֵּרְשׁוּהָ. וּכְשֶׁנִּלְחָם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּקְרָב, עִם אוֹתָם הַגִּבּוֹרִים לוֹחֲמֵי הַקְּרָב שֶׁאָמַרְנוּ הוּא נִלְחָם, וְהֵם נִקְרָאִים מְלֻמְּדֵי מִלְחָמָה."],[6,"","כָּתוּב [שופטים ה] מִן שָׁמַיִם נִלְחָמוּ הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא וְגוֹ'. וְשָׁנִינוּ, בַּשָּׁעָה הַזּוֹ שֶׁהִתְנַדְּבוּ יִשְׂרָאֵל לְגַלּוֹת אֶת הָרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרָם, אָז זוֹ [ויקרא כו] חֶרֶב נֹקֶמֶת נְקַם בְּרִית, כִּנְּסָה אֶת כָּל חֵילוֹתֶיהָ וְכָל כְּלֵי הַזַּיִן וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב לְהִלָּחֵם בִּקְרָב עִם [הלבנה] סִיסְרָא, וְהַכּוֹכָבִים הָיוּ שׁוֹפְכִים אֵשׁ מִלְמַעְלָה. וְאָמַר רַבִּי שִׁמְעוֹן, כָּל כּוֹכָב וְכוֹכָב יֵשׁ לוֹ שֵׁם לְבַדּוֹ, וְכֻלָּם נִקְרָאִים בְּשֵׁמוֹת."],[7,"","אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, הִזְדַּמְּנוּ לִנְקֹם אֶת נִקְמַת בָּנַי. שְׁתֵּי נְקָמוֹת אֲנִי עָתִיד לְהִפָּרַע מֵהֶם. נְקָמָה אַחַת שֶׁל שֵׁשׁ מֵאוֹת מֶרְכָּבוֹת שֶׁהִלְוָה לַשַּׂר הַגָּדוֹל שֶׁל הַמִּצְרִים כְּדֵי לְהִלָּחֵם בִּקְרָב עִם יִשְׂרָאֵל, שֶׁכָּתוּב [שמות יד] וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְכֹל רֶכֶב מִצְרָיִם. וּנְקָמָה אַחַת שֶׁל הַבָּנִים שֶׁלִּי, שֶׁהֵצִיקוּ לָהֶם עַד עַכְשָׁו. וּמִשּׁוּם כָּךְ נִדּוֹנוּ בִּשְׁנֵי דִינִים – אֶחָד בְּמַיִם וְאֶחָד בְּאֵשׁ. בְּמַיִם, שֶׁכָּתוּב [שופטים ה] נַחַל קִישׁוֹן גְּרָפָם. בְּאֵשׁ, שֶׁכָּתוּב הַכּוֹכָבִים מִמְּסִלּוֹתָם."],[8,"","וּבְאוֹתָם הַכּוֹכָבִים יֵשׁ כּוֹכָב אֶחָד שֶׁלֹּא בָא לְאוֹתָהּ הַנְּקָמָה, וְהִתְקַלֵּל לְעוֹלָמִים, שֶׁכַּאֲשֶׁר מַתְחִיל לְהָאִיר, בָּאִים שְׁאָר הַכּוֹכָבִים וּבוֹלְעִים אוֹתוֹ וְאֶת כָּל סִיעָתוֹ, וְכֻלָּם אוֹבְדִים יַחַד, כְּמוֹ שֶׁנֶּאֱמַר אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ ה'. וְכִי יֵשׁ רְשׁוּת לְמַלְאָךְ בָּזֶה? אֶלָּא זֶה הוּא הַמַּלְאָךְ שֶׁכָּתוּב בּוֹ [שמות יד] וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְזֶה הוּא שֶׁכָּל הַקְּרָבוֹת הֵן שֶׁלּוֹ."]]],[["כִּי לֹא בָאוּ לְעֶזְרַת יְיָ', כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. לְעֶזְרַת יְיָ' בַּגִּבּוֹרִים, בְּאִינּוּן שִׁשִּׁים גִּבּוֹרִים כַּד אִזְדְּמָנוּ קְרָבָא עִם סִיסְרָא. וְדָא מַלְאָךְ, רָזָא דְּכָל דִּינִין וְכָל קְרָבִין דְּמַלְכָּא בִּרְשׁוּתֵיהּ. וְעַל דָּא אָמַר, מַלְאַךְ יְיָ'. וְדָא הוּא דִּכְתִּיב, (בראשית מ״ח:ט״ז) הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי וְגוֹ', וְהָא אוּקְמוּהָ חַבְרַיָּא. וְדָא זְמִינָא לְמֶהֱוֵי עִלָּאָה וְיַקִּירָא לְזִמְנָא דְּאָתֵי. וּבְדָא יִתְרַבֵּי שְׁמָא קַדִּישָׁא. וּבְדָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְפָּרְעָא מֵעַמִּין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְעַל דָּא כְּתִיב, (יחזקאל ל״ח:כ״ג) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'. אַזְלוּ, עַד דְּמָטוּ לְגַבֵּיהּ דְּרַבִּי שִׁמְעוֹן. כֵּיוָן דְּחָמָא לוֹן, אָמַר רִבִּי שִׁמְעוֹן, הָא שְׁכִינְתָּא הָכָא. וַדַּאי צְרִיכִין אֲנָן לְמֶחְזָק טִיבוּ לְאַנְפֵּי שְׁכִינְתָּא.","פָּתַח וְאָמַר (בראשית כ״ט:ז׳) הֵן עוֹד הַיּוֹם גָּדוֹל וְגוֹ'. הַאי קְרָא אוֹקְמוּהָ, דְּכַד יִשְׂרָאֵל יִתְּעֲרוּן תְּשׁוּבָה לְקָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בִּזְכוּ אוֹרַיְיתָא יְתוּבוּן לְאַרְעָא קַדִּישָׁא, וְיִתְכַּנְּשׁוּן מִן גָּלוּתָא. דְּהָא וַדַּאי יוֹמָא חַד יְהֵא גָּלוּתָא לְיִשְׂרָאֵל, וְלָא יַתִּיר. הֲדָא הוּא דִכְתִיב, (איכה א׳:י״ג) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. וְאִי לָא יְתוּבוּן, קוּדְשָׁא בְּרִיךְ הוּא אָמַר, הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, בְּלָא זְכוּ וּבְלָא עוֹבָדִין דְּכַשְׁרָן. אֲבָל אַסְוָתָא חַד לְכוּ, הַשְׁקוּ הַצֹאן, אִשְׁתְּדָּלוּ בְּאוֹרַיְיתָא, דְּאִתְשַׁקְייוּ מֵימֵי אוֹרַיְיתָא. וּלְכוּ רְעוּ, לַאֲתָר דְּנַיְיחָא לַאֲתָר טָבָא וְכִסּוּפָא דְּאַחֲסַנְתֵּיכוֹן.","דָּבָר אַחֵר הֵן עוֹד הַיּוֹם גָּדוֹל, דָּא הוּא יוֹם דְּאִקְרֵי (ישעיהו כ״ב:ה׳) יוֹם מְהוּמָה וּמְבוּסָה וּמְבוּכָה, דִּי בְּהַהוּא יוֹם אִתְחֲרִיב בֵּי מַקְדְּשָׁא, וְנָפְלוּ יִשְׂרָאֵל בְּגָלוּתָא. וּבְגִין עוֹבָדִין בִּישִׁין, הַהוּא יוֹמָא אִתְמְשַׁךְ וְאִתְרְבֵּי, הֲדָא הוּא דִכְתִיב הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, בְּגִין דְּאִינּוּן מַשְׁכִין לֵיהּ לְהַהוּא יוֹמָא. הַשְׁקוּ הַצֹּאן, כְּמָה דְּאִתְּמַר בְּמִלֵּי דְּאוֹרַיְיתָא, דְּהָא בִּזְכוּתָא דְּאוֹרַיְיתָא יִפְּקוּן יִשְׂרָאֵל מִן גָּלוּתָא.","יִשְׂרָאֵל מַאי קָא אַמְרֵי. וַיֹּאמְרוּ לֹא נוּכַל עַד אֲשֶׁר יֵאָסְפוּ כָּל הָעֲדָרִים, עַד דְּיִתְכַּנְּשׁוּ כָּל שְׁאַר יוֹמִין עִלָּאִין. וְגָלְלוּ אֶת הָאֶבֶן, וְיִגַּנְדְּרוּן לְהַהוּא דִּינָא קַשְׁיָא דְּהַהוּא יוֹמָא דְּשַׁלְטָא עַל פִּי הַבְּאֵר, וְאִשְׁתְּכָחַת הַהִיא בְּאֵ\"ר בְּגָלוּתָא עִמָּנָא. וְכַד אִתְגַּלְיָיא הַאי בְּאֵ\"ר, וְהַהוּא אֶבֶן לָא שַׁלְטָא עָלָהּ, מִיַּד וְהִשְׁקִינוּ הַצֹּאן.","וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא בְּסוֹף יוֹמַיָּיא, לְאָהַדְרָא לְיִשְׂרָאֵל לְאַרְעָא קַדִּישָׁא, וּלְאַכְנְשָׁא לוֹן מִגָּלוּתָא. וּמַאן אִינּוּן סוֹף יוֹמַיָּיא, הַהוּא דְּהִיא אַחֲרִית הַיָּמִים. בְּהַאי אַחֲרִית הַיָּמִים, יִשְׂרָאֵל סַבְלוּ גָּלוּתָא. הֲדָא הוּא דִכְתִיב, (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וּכְתִיב (דברים ל״א:כ״ט) וְקָרָאת אֶתְכֶם הָרָעָה בְּאַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים דַּיְיקָא, וְדָא הִיא כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא. וְעִם אַחֲרִית הַיָּמִים דָּא, קַבִּילוּ עוֹנְשָׁא בְּגָלוּתָא. וּבְדָא יַעְבִּיד קוּדְשָׁא בְּרִיךְ הוּא נוּקְמִין לְיִשְׂרָאֵל תְּדִירָא. הֲדָא הוּא דִכְתִיב, (במדבר כ״ד:י״ד) אֲשֶׁר יַעֲשֶׂה הָעָם הַזֶּה לְעַמְּךָ בְּאַחֲרִית הַיָּמִים. וּבְכָל אֲתָר דָּא הִיא, וְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאָתָבָא לָהּ לְאַתְרָהָא, הֲדָא הוּא דִכְתִיב, (ישעיהו ב׳:ב׳) וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית יְיָ' וְגוֹ' וְדָא הוּא יוֹם.","וּמִדְּשָׁארֵי צֵל לְמֶעְבַּד בְּשֵׁירוּתָא דְּיוֹמָא אָחֳרָא, כְּמָה בְּזִמְנָא דְּאִתְחֲרִיב מַקְדְּשָׁא הֲוָה, וְנָטָה צֵל לְמֵיעַל. הֲדָא הוּא דִכְתִיב, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָּנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. יוֹם וְצֵל, הוּא סוֹף גָּלוּתָא. וְשִׁיעוּרָא דְּהַאי צֵל, שִׁית קְמָצִין וּפַלְגָּא. וּבְגוּדָל דְּמִשְׁחָא דְּבַר נָשׁ, גְּבַר בֵּין גּוּבְרִין. וְדוּכְרָנָא דְּהַאי רָזָא דְּבֵין חַבְרַיָּיא, דִּכְתִּיב, (איוב ח׳:ט׳) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי תְמוֹל אֲנַחְנוּ בְּגָלוּתָא, וְלָא הֲוֵינָא יַדְעֵי כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ, לְאַשְׁרָאָה לוֹן קוּדְשָׁא בְּרִיךְ הוּא עֲלֵי אָרֶץ.","זַכָּאָה חוּלָקֵיהּ מַאן דְּחָמֵי לֵיהּ, וְזַכָּאָה חוּלָקֵיהּ מַאן דְּלָא חָמֵי לֵיהּ. וַוי לְמַאן דְּיִזְדָּמַן כַּד יִתְבַּע אַרְיָא רַבְרְבָא, לְאִתְחַבְּרָא לְנוּקְבֵיהּ. כָּל שֶׁכֵּן בְּשַׁעֲתָא דְּיִזְדַּוְּוגֻן כַּחֲדָא, עַל הַהִיא שַׁעֲתָא כְּתִיב, (עמוס ג׳:ח׳) אַרְיֵה שָׁאָג מִי לֹא יִירָא וְגוֹ'.","תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב, (ירמיהו כ״ה:ל׳) שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וּבְהַהוּא זִמְנָא כַּד יִפּוּק לְקַבְּלָא לְבַת זוּגוֹ, כְּדֵין אַרְיֵה שָׁאָג מִי לֹא יִירָא יְיָ' אֱלֹהִים דִּבֶּר מִי לֹא יִנָּבֵא. בְּהַהִיא שַׁעֲתָא כְּתִיב, (דברים ל׳:ג׳) וְשָׁב יְיָ' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְגוֹ'. וְשָׁב מַאי הוּא, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא שָׁב כְּנֶסֶת יִשְׂרָאֵל מִגָּלוּתָא, וְשָׁב צַדִּיק לְאִזְדַּוְּוגָא בְּאַתְרֵיהּ. כְּדֵין כְּתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ."],[[0,"כי לא באו וגו':","כי לא באו לעזרת ה'. היינו כשיצאו ישראל ממצרים, \u0003לעזרת ה' בגבורים\u0004, היינו באלו ששים גבורים שנזדמנו להלחם עם סיסרא. דהיינו ששים גבורים שסביב מטתו שלשלמה (כנ\"ל אות קע\"ט) ומלאך זה הוא סוד שכל הדינין וכל המלחמות של המלך הם ברשותו. ועל זה אמר מלאך ה'. וזה הוא שכתוב, המלאך הגואל אותי וגו' דהיינו המלכות. וכבר העמידו החברים. ומלאך זה עתיד להיות עליון ויקר לעתיד לבא. ובזה יתגדל השם הקדוש. ובמלאך זה עתיד הקב\"ה להפרע מעמים עכו\"ם. ועל זה כתוב, והתגדלתי והתקדשתי וגו'. הלכו עד שהגיעו לר\"ש. כיון שראה אותם, א\"ר שמעון השכינה היא כאן. ודאי צריכים אנו להחזיק טובה לפני השכינה."],[1,"פתח ואמר הן וגו':","פו\"א, הן עוד היום גדול וגו'. מקרא זה העמידו, כשישראל יתעוררו בתשובה לפני הקב\"ה, בזכות התורה ישובו לארץ הקדושה, ויתקבצו מן הגלות. כי ודאי יום אחד תהיה גלות לישראל ולא יותר, דהיינו יומו של הקב\"ה שהוא אלף שנים, והיינו אלף החמישי, ז\"ש נתנני שוממה כל היום דוה. ואם לא ישובו אז יאמר הקב\"ה, \u0003הן עוד היום גדול, לא עת האסף המקנה\u0004, בלא זכות ובלי מעשים טובים. אבל רפואה אחת יש לכם, \u0003השקו הצאן\u0004, עסקו בתורה, שתהיינה נשקות ממימי התורה, \u0003ולכו רעו\u0004, ותלכו, למקום המנוחה, למקום טוב וחמדה של נחלתכם."],[2,"ד\"א הן עוד וגו':","פירוש אחר. הן עוד היום גדול, זה היום שנקרא יום מהומה ומבוסה ומבוכה, אשר ביום ההוא נחרב בית המקדש וישראל נפלו בגלות. ומשום המעשים הרעים שעושים ישראל, יום ההוא נמשך ומתגדל. ז\"ש, \u0003הן עוד היום גדול לא עת האסף המקנה\u0004, משום שהם מאריכים ליום ההוא של הגלות. \u0003השקו הצאן\u0004, הוא כמו שלמדנו, דהיינו בדברי תורה, כי בזכות התורה יצאו ישראל מן הגלות."],[3,"ישראל מה קא אמרי וכו':","ישראל מה הם אומרים. היינו, \u0003ויאמרו, לא נוכל עד אשר יאספו כל העדרים\u0004, היינו עד אשר יאספו כל שאר הימים העליונים, דהיינו הספירות הקדושות, \u0003וגללו את האבן\u0004, וגללו דין קשה ההוא שבאותו יום השולט על פי הבאר, שמשום זה, נמצאת הבאר, שהיא המלכות, עמנו בגלות. וכשתתגלה הבאר ההיא ואותה אבן, שהיא דין הקשה, לא תשלוט עליה, מיד \u0003והשקינו הצאן.\u0004"],[4,"וזמין קב\"ה בסוף וכו':","ועתיד הקב\"ה באחרית הימים להחזיר את ישראל לארץ הקדושה, ולקבצם מן הגלות. ומה הוא סוף הימים. היינו אותה שהיא אחרית הימים, דהיינו מלכות, שהיא סוף כל הספירות, הנק' ימים. באחרית הימים הזה סובלים ישראל גלות. ז\"ש, בצר לך ומצאוך כל הדברים האלה באחרית הימים. וכתוב, וקראת אתכם הרעה באחרית הימים. באחרית הימים הוא בדיוק, כי זו היא כנסת ישראל, שהיא המלכות, שהיא בגלות. ועם אחרית הימים זו, מקבלים עונש בגלות. ובזו, יעשה הקדוש ברוך הוא נקמות לישראל תמיד, ז\"ש, אשר יעשה העם הזה לעמך באחרית הימים. ובכל מקום שכתוב אחרית הימים, זו היא, דהיינו המלכות. והקב\"ה עתיד להשיבה למקומה, וז\"ש, והיה באחרית הימים נכון יהיה הר בית ה' וגו'. וזו היא שנקראת יום. דהיינו יום האחרון. כי כל ספירה נקראת יום."],[5,"ומדשארי צל למעבד וכו':","ומשהתחיל הצל להעשות בתחילת יום האחר אחר אלף החמישי, כמו שבזמן שנחרב בית המקדש שהיה נוטה הצל להאסף, כמש\"א אוי לנו כי פנה היום כי ינטו צללי ערב, כלומר כמו שהחורבן היה בזמן שהתחיל הצל להאסף, כך תהיה הגאולה בזמן שיתחיל הצל לצאת. שבזמן שיהיה, יום וצל, הוא סוף הגלות. ושיעור של צל הזה, הוא שש קמצין, וחצי, קמצין היא מדה שנקראת קמצא, שהוא מדת גדלו של אדם, איש בין אנשים, כלומר של אדם בינוני. וזכרון של סוד זה בין החברים, הוא בכתוב, כי תמול אנחנו ולא נדע כי צל ימינו עלי ארץ. \u0003כי תמול אנחנו\u0004, היינו בגלות. ולא היינו יודעים, כי \u0003צל ימינו\u0004 עלי ארץ, דהיינו שהקב\"ה רוצה להשרות אותם צל \u0003ויום\u0004, עלי ארץ."],[5,"","פירוש. כבר נתבאר במקומות הרבה, שכל השלמות באה מכח היחוד של קו ימין עם קו שמאל, שאז גם המלכות הנמשכת מקו שמאל, מזדווגת עם ז\"א, שהוא ימין. ומקבלת ממנו בשביל ישראל כל טוב. וכן כל החורבן בא, מצד פרוד קו השמאל מן קו הימין, שאז גם המלכות נפרדת מן ז\"א, שהפרוד הזה נבחן לשכינתא בגלותא. גם נודע שאין קו האמצעי יכול ליחד הימין ושמאל אלא ע\"י שממעט הג\"ר דשמאל בכח המסך דחירק שבו (כמ\"ש לעיל לך י\"ג ד\"ה ונתבאר) ולפי\"ז נמצא, כשהשמאל מתגבר ונפרד מימין, אז יש בו גם הג\"ר. וזה נבחן לבחינת יום, שאין בו צל, כי אין בו מיעוט. וכשהוא מיוחד עם הימין, שולט בו המסך דקו אמצעי הממעטו מג\"ר ואין בו אלא ו\"ק. ואז נבחן קו שמאל לבחינת יום וצל. כי בחינת ו\"ק דחכמה המאירים עם החסדים שבימין ביחד, נבחן ל \u0003יום\u0004. ובחינת מיעוט הג\"ר שבו נבחן ל \u0003צל\u0004, שפירושו העלם האור. ולפיכך בעת שעונות ישראל גרמו שיתגבר קו השמאל על הימין ויאיר בנפרד מימין, אז נחרב בית המקדש, שה\"ס המלכות, כי מכח פרוד קו השמאל גם המלכות נפרדה מן ז\"א שהוא ימין. ונבחן שאז נטה הצל להאסף ולעבור מן העולם. מטעם שאין צל בשמאל, אלא בשעה שמחובר עם הימין. ובשעה שהתחתונים ישובו בתשובה ויעלו מ\"ן לקו אמצעי שיחזור וייחד קו ימין עם קו השמאל, אז תהיה הגאולה, דהיינו שהשכינה תצא מן הגלות, ותחזור להזדווג עם ז\"א. אבל אז יתעלמו ג\"ר דקו שמאל, מכח המסך דחירק שבקו האמצעי. ונמצא \u0003שיום וצל\u0004 יהיו משמשים בקו השמאל. וזה שמשמיענו הזהר, שכמו שהחורבן היה מחמת ביטול הצל, שהיה יום בלי צל, כנ\"ל. כך הגאולה לא תהיה אלא אם כן הצל יחזור ויתחדש, וישמשו יחד, יום וצל."],[5,"","וז\"ש \u0003ומדשארי צל למעבד בשרותא דיומא אחרא\u0004, דהיינו שיחזור ויתחדש הצל, באותו הזמן, \u0003כמה בזמנא דאתחריב מקדשא, הוה, ונטה צל למיעל\u0004, דהיינו כמו שנטה הצל לעבור מן העולם בשעת חורבן בית המקדש, כן יחזור ויתחדש הצל בתחילת יום האחר שהוא אלף הששי, ויהיה \u0003יום וצל\u0004, שישמשו \u0003אור\u0004 מצד הו\"ק דחכמה בחסדים, \u0003וצל\u0004 מצד הג\"ר דחכמה הנעלמים, \u0003הוא סוף גלותא\u0004, אז תלך ותסתיים הגלות, ותתחיל הגאולה, שהיא יחוד ז\"א ומלכות."],[5,"","ונודע שמיעוט הג\"ר בא מכח מסך דחירק הממותק בבינה, הנקרא מפתחא, כי אז אפשר שיאירו הו\"ק דחכמה בחסדים (כמ\"ש לעיל לך י\"ג ד\"ה ונתבאר, ע\"ש) גם נודע שמסך הזה דמלכות הממותקת בבינה, אינו מאיר בכל ז' ספירות חג\"ת נהי\"מ של המלכות, אלא בשש ספירות וחצי ספירה, כי במלכות של מלכות דמלכות אינה מאירה אלא חצי ספירה עד החזה, ומחזה ולמטה חסרה. כי המפתחא היא בחינת ט\"ר, ולא עצם המלכות ע\"כ נפסקת בחזה דמלכות דמלכות כמ\"ש זה באורך (לעיל בראשית ב' דף קנ\"ח ד\"ה בארבעין)."],[5,"","וז\"ש, \u0003ושיעורא דהאי צל, שית קמצין ופלגא\u0004, כי הצל הזה להיותו בא ממלכות דמפתחא אינו מתפשט בכל הפרצוף דמלכות, אלא עד החצי של מלכות דמלכות, ונמצא שאין בה אלא שש ספירות וחצי ספירה. \u0003ובגודל דמשחא דבר נש\u0004 וכו', שזהו מדת גדלו של אדם בינוני. כלומר שהאדם נמשך מן הצל הזה שבמלכות דמפתחא, ע\"כ גם בו אין יותר משש ספירות וחצי, כמו במלכות העליונה. וז\"ש \u0003כי תמול אנחנו, בגלותא, ולא הוינא ידעי כי צל ימינו עלי ארץ לאשראה לון קב\"ה עלי ארץ.\u0004 כי תמול אנחנו, דהיינו, כשהיינו בגלות לא ידענו, שכל המשך הגלות הוא, משום שהקב\"ה רוצה להשרות, \u0003צל, ימינו\u0004, עלי ארץ, דהיינו שישמשו יחד. צל, על הג\"ר דחכמה, \u0003וימינו\u0004, על ו\"ק דחכמה שבחסדים. ואם היינו יודעים זה היינו יכולים למהר הגאולה. כי \u0003יום וצל, הוא סוף גלותא\u0004, כנ\"ל."],[6,"זכאה חולקיה מאן וכו':","אשרי חלקו מי שרואה אותו, את המשיח, ואשרי חלקו מי שלא ראה אותו. אוי למי שיזדמן בעת שיתבע אריה הגדול להתחבר בנוקביה. כל שכן בשעה שיזדווגו יחד, דהיינו ז\"א ומלכות בעת הגאולה. על שעה ההיא כתוב, אריה שאג מי לא יירא וגו'."],[7,"ת\"ח בקדמיתא כתיב וכו':","בוא וראה בתחילה כתוב שאג ישאג על נוהו, שזהו בגלות, ובאותו זמן כשיצא, ז\"א, לקבל בת זוגו, מלכות, אז נאמר, אריה שאג מי לא יירא ה' אלקים דבר מי לא ינבא. בשעה ההיא כתוב, ושב ה' אלקיך את שבותך וגו'. מהו \u0003ושב\u0004. ומשיב, אלא הקב\"ה שב את כנסת ישראל, מן הגלות, ושב צדיק להתחבר במקומו. אז כתוב, אך צדיקים יודו לשמך ישבו ישרים את פניך."]],[[0,"","כִּי לֹא בָאוּ לְעֶזְרַת ה' – כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. לְעֶזְרַת ה' בַּגִּבּוֹרִים – עִם אוֹתָם שִׁשִּׁים גִּבּוֹרִים שֶׁהִזְדַּמְּנוּ בַּקְּרָב עִם סִיסְרָא. וְהַמַּלְאָךְ הַזֶּה, הַסּוֹד שֶׁל כָּל הַדִּינִים וְהַקְּרָבוֹת שֶׁל הַמֶּלֶךְ הֵם בִּרְשׁוּתוֹ, וְעַל כֵּן אָמַר מַלְאַךְ ה', וְזֶהוּ שֶׁכָּתוּב [בראשית מח] הַמַּלְאָךְ הַגֹּאֵל אֹתִי וְגוֹ', וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. וְזֶה עָתִיד לִהְיוֹת עֶלְיוֹן וְנִכְבָּד לֶעָתִיד לָבֹא, וּבָזֶה יִתְגַּדֵּל הַשֵּׁם הַקָּדוֹשׁ, וּבָזֶה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מֵהָעַמִּים עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב [יחזקאל לח] וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'. הָלְכוּ עַד שֶׁהִגִּיעוּ אֶל רַבִּי שִׁמְעוֹן. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר רַבִּי שִׁמְעוֹן, הִנֵּה הַשְּׁכִינָה כָּאן, וַדַּאי צְרִיכִים אָנוּ לְהַחֲזִיק טוֹבָה לַפָּנִים שֶׁל הַשְּׁכִינָה."],[1,"","פָּתַח וְאָמַר, [בראשית כט] הֵן עוֹד הַיּוֹם גָּדוֹל וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, שֶׁכַּאֲשֶׁר יִשְׂרָאֵל יִתְעוֹרְרוּ בִתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בִּזְכוּת הַתּוֹרָה יָשׁוּבוּ לָאָרֶץ הַקְּדוֹשָׁה וְיִתְקַבְּצוּ מִן הַגָּלוּת. שֶׁהֲרֵי וַדַּאי יוֹם אֶחָד תִּהְיֶה גָלוּת לְיִשְׂרָאֵל, וְלֹא יוֹתֵר, זֶהוּ שֶׁכָּתוּב [איכה א] נְתָנַנִי שּמֵמָה כָּל הַיּוֹם דָּוָה. וְאִם לֹא יָשׁוּבוּ, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה בְּלִי זְכוּת וּבְלִי מַעֲשִׂים כְּשֵׁרִים. אֲבָל רְפוּאָה אַחַת יֵשׁ לִי לָכֶם: הַשְׁקוּ הַצּאן, הִשְׁתַּדְּלוּ בַתּוֹרָה, שֶׁתֻּשְׁקוּ מֵהַמַּיִם שֶׁל הַתּוֹרָה, וּלְכוּ רְעוּ, לְמָקוֹם שֶׁל מְנוּחָה, לְמָקוֹם טוֹב וְכִסּוּף שֶׁל נַחֲלַתְכֶם."],[2,"","דָּבָר אַחֵר הֵן עוֹד הַיּוֹם גָּדוֹל – זֶהוּ הַיּוֹם שֶׁנִּקְרָא [ישעיה כב] יוֹם מְהוּמָה וּמְבוּסָה וּמְבוּכָה, שֶׁבְּאוֹתוֹ הַיּוֹם נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנָפְלוּ יִשְׂרָאֵל בַּגָּלוּת. וּמִשּׁוּם הַמַּעֲשִׂים הָרָעִים, הַיּוֹם הַהוּא נִמְשַׁךְ וְהִתְגַּדֵּל. זֶהוּ שֶׁכָּתוּב, הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, מִשּׁוּם שֶׁהֵם מוֹשְׁכִים אֶת אוֹתוֹ הַיּוֹם. הַשְׁקוּ הַצֹּאן, כְּמוֹ שֶׁנֶּאֱמַר בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי בִּזְכוּת הַתּוֹרָה יֵצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת."],[3,"","וּמַה יִּשְׂרָאֵל אוֹמְרִים? וַיֹּאמְרוּ לֹא נוּכַל עַד אֲשֶׁר יֵאָסְפוּ כָּל הָעֲדָרִים, עַד שֶׁיִּתְכַּנְּסוּ כָּל שְׁאָר הַיָּמִים הָעֶלְיוֹנִים, וְגָלֲלוּ אֶת הָאֶבֶן, וִיבַטְּלוּ אוֹתוֹ הַדִּין הַקָּשֶׁה שֶׁל אוֹתוֹ הַיּוֹם שֶׁשּׁוֹלֵט עַל פִּי הַבְּאֵר, וְנִמְצֵאת אוֹתָהּ הַבְּאֵר עִמָּנוּ בַּגָּלוּת. וּכְשֶׁמִּתְגַּלָּה הַבְּאֵר הַזּוֹ וְאוֹתָהּ הָאֶבֶן לֹא שׁוֹלֶטֶת עָלֶיהָ, מִיָּד וְהִשְׁקִינוּ הַצּאן."],[4,"","וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹף הַיָּמִים לְהַחֲזִיר אֶת יִשְׂרָאֵל לָאָרֶץ הַקְּדוֹשָׁה וּלְכַנֵּס אוֹתָם מִן הַגָּלוּת. וּמִי הֵם סוֹף הַיָּמִים? אוֹתָהּ שֶׁהִיא אַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים הַזּוֹ יִשְׂרָאֵל סָבְלוּ אֶת הַגָּלוּת. זֶהוּ שֶׁכָּתוּב, [דברים ד] בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וְכָתוּב [שם לא] וְקָרָאת אֶתְכֶם הָרָעָה בְּאַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים דַּוְקָא, וְזוֹ הִיא כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. וְעִם אַחֲרִית הַיָּמִים הַזּוֹ קִבְּלוּ עֹנֶשׁ בַּגָּלוּת, וּבָזוֹ יַעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת לְיִשְׂרָאֵל תָּמִיד. זֶהוּ שֶׁכָּתוּב [במדבר כד] אֲשֶׁר יַעֲשֶׂה הָעָם הַזֶּה לְעַמְּךְ בְּאַחֲרִית הַיָּמִים. וּבְכָל מָקוֹם זֹּאת הִיא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לַהֲשִׁיבָהּ לִמְקוֹמָהּ. זֶהוּ שֶׁכָּתוּב [ישעיה ב] וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה' וְגוֹ', וְזֶהוּ יוֹם."],[5,"","וּמִשֶּׁהִתְחִיל הָצֵּל לְהֵעָשׂוֹת בְּרֵאשִׁית הַיּוֹם הָאַחֵר, הָיָה כְּמוֹ בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, וְנָטָה הַצֵּל לְהִכָּנֵס. זֶהוּ שֶׁכָּתוּב [ירמיה ו] אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. יוֹם וָצֵל הוּא סוֹף הַגָּלוּת, וְהַשִּׁעוּר שֶׁל הַצֵּל הַזֶּה שִׁשָּׁה קְמָצִים וָחֵצִי, וְגוּדָל שֶׁל מִדָּה שֶׁל אָדָם, גֶּבֶר בֵּין גְּבָרִים. וְהַזִּכָּרוֹן שֶׁל הַסּוֹד הַזֶּה שֶׁבֵּין הַחֲבֵרִים, שֶׁכָּתוּב [איוב ח] כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי תְמוֹל אֲנַחְנוּ – בַּגָּלוּת, וְלֹא הָיִינוּ יוֹדְעִים כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ, לְהַשְׁרוֹת אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵי אָרֶץ."],[6,"","אַשְׁרֵי חֶלְקוֹ מִי שֶׁרוֹאֶה אוֹתוֹ, וְאַשְׁרֵי חֶלְקוֹ מִי שֶׁלֹּא רוֹאֶה אוֹתוֹ. אוֹי לְמִי שֶׁיִּזְדַּמֵּן כְּשֶׁיְּבַקֵּשׁ הָאַרְיֵה הַגָּדוֹל לְהִתְחַבֵּר עִם נְקֵבָתוֹ, כָּל שֶׁכֵּן כְּשֶׁיִּזְדַּוְּגוּ יַחַד. עַל אוֹתָהּ שָׁעָה כָּתוּב, [עמוס ג] אַרְיֵה שָׁאָג מִי לֹא יִירָא וְגוֹ'."],[7,"","בֹּא וּרְאֵה, בַּהַתְחָלָה כָּתוּב [ירמיה כה] שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וּבְאוֹתוֹ הַזְּמַן כְּשֶׁיֵּצֵא לְקַבֵּל אֶת בַּת זוּגוֹ, אֲזַי אַרְיֵה שָׁאָג מִי לֹא יִירָא ה' אֱלֹהִים דִּבֶּר מִי לֹא יִנָּבֵא. בְּאוֹתָהּ שָׁעָה כָּתוּב, [דברים ל] וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְגוֹ'. מַה זֶּה וְשָׁב? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב אֶת כְּנֶסֶת יִשְׂרָאֵל מֵהַגָּלוּת, וְשָׁב הַצַּדִּיק לְהִזְדַּוֵּג בִּמְקוֹמוֹ. אֲזַי כָּתוּב, [תהלים קמ] אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ."]]],[["מַתְנִיתִין, לְכוֹן בְּנֵי נָשָׁא, מָארֵי דְּחָכְמְתָא, מָארֵי דְּסֻכְלְתָנוּ, קָלָא קָרֵי. מַאן מִנְּכוֹן דְּאִתְחַכָּם וְיָדַע, בְּשַׁעֲתָא דְּרֵישָׁא חִיוָּורָא, אַתְקִין רֵישָׁא, רְשִׁימָא מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. אַתְקִין סְטָר צָפוֹן, בְּעִטּוּרָא דְּקוּנָארִיתָא, בֵּיהּ רָשִׁים עוּמְקָא דִּתְהוֹמָא עִלָּאָה, דְּסָלִיק וְנָחִית בְּגַוֵּויהּ. נָחִית חַד דַּרְגָּא טְמִירָא, בְּאֶלֶף וַחֲמֵשׁ מְאָה רְשִׁימִין, דְּאֶלֶף וַחֲמֵשׁ מְאָה עָלְמִין.","(דניאל ד׳:ט׳) תְּחוֹתֵיהּ תַּטְלֵל חַד חֵיוַת בָּרָא, (דניאל ז׳:ז׳) וְקַרְנַיִן עֶשֶׂר לָהּ. וַאֲרוּ עַיְינִין כְּעַיְינֵי אֱנָשָׁא לְחֵיוָתָא, וּפוּם מְמַלֵּל רַבְרְבָן. כַּד סַלְּקָא, אַזְלַא בִּימָמָא, טְמִירָא בְּלֵילְיָא. כַּד נַחְתָּא, טְמִירָא בִּימָמָא, וְאַזְלָא בְּלֵילְיָא. כַּד נַטְלָא, מִזְדַּעְזְעָן אַרְבַּע מַגְרוֹפֵי דַּאֲחִידָן בִּידָהָא. וְנַטְלִין עִמָּהּ שִׁתִּין פּוּלְסִין דְּנוּרָא, כָּל חַד חַרְבָּא שִׁנָּנָא עַל יְרֵיכֵיהּ.","סָלִיק בִּרְעוּתָא, לְאַפָּקָא בַּר נָשׁ שַׁלִּיטָא לְתַתָּא. אַתְקִין בְּהַאי חֵיוָתָא חַד עַפְרָא דְּקִיקָא, כָּלִיל מִכֹּלָּא. נָשַׁב בֵּיהּ, אִתְפְּשַׁט בְּד' סִטְרֵי עָלְמָא. וְד' פּוּלְסִין אִתְגַּלְגָּלוּ, חַד לְעֵילָּא, חַד לְתַתָּא, חַד לַצָּפוֹן, חַד לַדָּרוֹם.","אִילָנָא חַד רַבְרְבָא וְתַקִּיף, אִתְחַבָּר וְאִזְדְּוַוג בָּהּ בְּחַד עַנְפָּא שַׁפִּירָא, דְּחֵזוּ חֶדְוָותָא דְּכֹלָּא. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. בֵּיהּ אִזְדְּוַוג, אַפִּיקוּ חַד רוּחָא טְמִירָא, וּמַלְיָא לְהַהוּא גְּבִילוּ דְּעַפְרָא, וְקָאִים עַל רַגְלוֹי, וְאַמְלְכֵיהּ עַל כָּל עָלְמָא, וְשַׁלְטֵיהּ עַל כֹּלָּא. הֲדָא הוּא דִכְתִיב, (תהילים ח׳:ז׳) תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךָ וְגוֹ'. אִתְפְּקִיד עַל הַהוּא אִילָנָא, לָא נָטַר פִּקּוּדָא, אָתִיב מַלְכָּא רוּחֵיהּ לְגַבֵּיהּ, וְהַהוּא חֵיוָתָא נַטְלָא לֵיהּ.","כְּדֵין זְמִינִין מָנָא אַחֲרָא, וְקָאִים בֵּינַיְיהוּ. בְּקוּטְרָא דִּגְלִיפִין בֵּין מַלְאָכִין קַדִּישִׁין, בְּטוּפְסְרָא (ס\"א בטפסא) דְּעִטּוּרִין אִתְאַחֲדָן.","דָּרִין בַּתְרָאִין, תְּפִיסִין בְּחוֹבַיְיהוּ. אִשְׁתְּלִיף רוּחֵיהוֹן מֵהַהוּא מָאנָא דִּלְבוּשָׁא, לְבָתַר אַגְנִיז בְּעַפְרָא, בֵּין רִגְבֵי נַחֲלָא אִתְטְמָרוּ וְאִתְגְּנִיזוּ. בְּחַד גַּרְמָא תַּקִּיף דְּהַהוּא מָאנָא, יִתְבְּנוּן בְּקַדְמִיתָא, וִיקוּמוּן חֵילִין חֵילִין תִּנְיָינוּת, בְּאַרְעָא קַדִּישָׁא מִתְעָרִין.","וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְמִגְבַּל הַהוּא עַפְרָא קַדְמִיתָא, דְּהַהוּא מָאנָא מַמָּשׁ. וּלְאַעֲלָא בֵּיהּ גְּבִילוּ דָּקִיק כְּהַאי חֲמִירָא דְּעִיסָה. וּמֵהַהוּא גְּבִילוּ דְּאִיהוּ צָחוּתָא דִּלְעֵילָּא, יִתְתָּקַּן וְיִתְיְשַׁר מָאנָא דְּכַשְׁרָא. כְּגַוְונָא דְּאָמַר קְרָא, (יואל ד׳:י״ח) וּמַעְיָן מִבֵּית יְיָ' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִׁטִּים. בְּגִין דְּהַהוּא נַחַל אַסְגֵּי חֲבִיבוּתָא (ס\"א זכותא) (ס\"א זנותא) בְּעָלְמָא. וְכַד הַהוּא מַעְיָינָא קַדִּישָׁא, יִפּוּק וְיֵיעוּל לְגַבֵּיהּ, כְּדֵין יִתְתָּקַּן וְיִתְיְשַׁר, וְלָא יְהֵא בְּסוּרְחָנֵיהּ כְּקַדְמִיתָא.","וְאִינּוּן דְּלָא זָכָּאן, יְקוּמוּן לְאִתְדְּנָא בְּדִינָא דְּמַלְכָּא עִלָּאָה. הֲדָא הוּא דִכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. וּכְדֵין כְּתִיב, (ישעיהו ס״ו:כ״ב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עוֹשֶׂה עוֹמְדִים לְפָנַי נְאֻם יְיָ' כֵּן יַעֲמוֹד זַרְעֲכֶם וְשִׁמְכֶם. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן"],[[0,"מתניתין. לכן בני וכו':","משנה. לכם בני אדם, בעלי החכמה בעלי התבונה. קול קורא. מי מכם שהחכים ויודע, בשעה שראש הלבן שהוא כתר, התקין ראש ב', שהוא חכמה, הרשום ממעלה למטה וממטה למעלה, התקין צד צפון, דהיינו קו שמאל שבבינה, בעטרה של חפירת מים, בה רשם העומק של תהום העליון, דהיינו עומק הבינה הנקראת תהום העליון, העולה ויורד בתוכו. מדרגה אחת נעלמת ירדה באלף ות\"ק רשימות, ובאלף ות\"ק עולמות. \u0003קונאריתא\u0004 הוא מלשון אריתא, שפירושו, אגם מים. כי על אגם מים מתרגם אריתא (תהלים ק\"ז ל\"ה)."],[0,"","ביאור הדברים. המשנה מבארת לנו כאן ביאור מקיף כולל מראש האצילות עד תחיית המתים בקיצור נמרץ. ותחילה מבאר, כתר חכמה בינה וז\"א ומלכות דאצילות. וז\"ש, \u0003בשעתא דרישא חוורא\u0004 שהוא הכתר דאצילות, \u0003אתקין רישא רשימא מעילא לתתא ומתתא לעילא\u0004, היינו החכמה דאצילות. \u0003אתקין סטר צפון\u0004 וכו' היינו הבינה דאצילות, ובה מאריך מעט לבאר ג' הקוין שבה. \u0003אתקין\u0004, פירושו קו האמצעי דבינה, שהוא המתקן את הקוין ימין ושמאל ומיחדם זה בזה והחכמה שבשמאל מתלבשת בחסדים שבימין, וז\"ש \u0003אתקין סטר צפון\u0004, שקו האמצעי התקין קו השמאל, \u0003בעטורא דקונאריתא\u0004 שיתעטר באגם מים דהיינו ברוב החסדים שבקו ימין, \u0003ביה\u0004, היינו בתקון זה דקו האמצעי, \u0003רשים עומקא דתהומא עלאה\u0004, שרשם שיעור ההעלם, המכונה עומק, אשר בבינה, הנקראת תהומא עלאה, והוא תקן, \u0003דסליק\u0004 שאור קו השמאל יאיר ממטה למעלה. \u0003ונחית\u0004, ואור קו הימין יאיר ממעלה למטה. (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת). \u0003בגויה\u0004, היינו בתוך הבינה. ואחר שביאר הבינה בג' קוין שבה, מתחיל לבאר את ז\"א. וז\"ש \u0003נחית חד דרגא טמירא\u0004, שירד מאור הבינה מדרגה אחת נסתרת, שהיא ז\"א שהחכמה שבו נסתרת ונעלמת. \u0003באלף וחמש מאה רשימין\u0004, היינו חכמה וחסד דדעת שהם רשומים בז\"א. \u0003דאלף וחמש מאה עלמין\u0004, היינו בינה וגבורה דדעת שהם נעלמים בו ואינם מאירים, להיותם בחינת השמאל דראש, ששם הארת החכמה הנעלמת בז\"א, שהוא מאיר בחסדים בלבד, שה\"ס חכמה וחסד שבימין הראש, ונמצא שהימין שהוא חכמה וחסד שבדעת רשומים בו ומאירים, והשמאל, שהוא בינה וגבורה דדעת הם בבחינת עלמין, דהיינו שנעלמים. ומה שמכנה אותם במספר אלף וחמש מאות, הוא שזה מורה על קו וחצי שבראש. כי ג' קוין שבראש הנקראים חב\"ד הם במספר ג' אלפים. כי הספירות שבמוחין הם במספר אלף. ונמצא שקו וחצי הם אלף ות\"ק. וקן הימין וחצי הימין של קו אמצעי, שהם חכמה וחסד דדעת, הם במספר אלף ות\"ק. וכן קו שמאל וחצי השמאל דקו אמצעי, הם אלף ות\"ק."],[1,"תחותיה תטלל חד וכו':","תחתיו, דהיינו תחת ז\"א, תטייל חית השדה אחת, דהיינו מלכות, ועשר קרנים לה, דהיינו עשרה אורות. כי קרן היא.לשון זיו ואור, ויש עינים אל החיה כעיני אדם. החכמה נקראת עינים. והמלכות ה\"ס פני אדם, שאין החכמה מאירה רק בה, (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד כמה) וע\"כ מיחס בה העינים, לעיני אדם. ופה מדבר גדולות. היינו שמשפעת מוחין דגדלות. כי דבור ה\"ס השפעה. כשהיא עולה, הולכת ביום ונסתרת בלילה. כשהיא יורדת, היא נסתרת ביום והולכת בלילה. וכשהיא נוסעת, מזדעזעים ד' מגרופים שאוחזת בידיה, ונוסעים עמה ששים שבטים של אש, כל אחד חרב שנונה על ירכו."],[1,"","פירוש. כי נתבאר, שהחכמה נעלמת בז\"א שהיא בו בסוד אלף ות\"ק עלמין כנ\"ל בדבור הסמוך. ומקום גילוי החכמה היא במלכות. כנ\"ל, בסוד וארו עיינין כעייני אנשא לחיותא, ומשום זה יש במלכות ג' מדרגות, א) \u0003כד סלקא\u0004, כשהמלכות עולה ומזדווגת עם ז\"א, והיא נכללת בו, שאז \u0003אזלא ביממא טמירא בליליא\u0004, שמבחינה זו היא הולכת ומשפעת ביום, ובלילה היא נסתרת, שאינה משפעת. ב) \u0003כד נחתא\u0004, כשהיא יורדת לרשות עצמה, \u0003טמירא ביממא ואתגליא בליליא\u0004 (כצ\"ל) כי בחינתה עצמה היא חכמה, שביום היא נכללת בזווג ז\"א, ומשפעת רק חסדים שהיא מדרגת ז\"א, ובחינתה עצמה שהיא חכמה מתגלה בלילה. בס\"ה ותקם בעוד לילה וגו'. ג) \u0003כד נטלא\u0004, כשהמלכות נוסעת, בסוד ג' קוין שמקבלת מז\"א בזה אחר זה בג' דוכתי, המכונים נסיעה, שאז מתגלה החכמה עם דינים קשים (כנ\"ל בשלח ל\"ט ד\"ה וג' ע\"ש) ומסבת הדינים שמתגלים עם החכמה, \u0003מזדעזען ארבע מגרופי דאחידן בידהא\u0004, שה\"ס חו\"ג תו\"מ שבה. המזדעזעים מחמת הדינים. \u0003ונטלין עמה שתין פולסין דנורא\u0004, שה\"ס חג\"ת נה\"י הכלולים בקו שמאל שמקבלת, שכל אחד מהם כלול מעשרה והם ששים. וה\"ס הנה מטתו שלשלמה \u0003ששים גבורים\u0004 סביב לה איש \u0003חרבו על ירכו\u0004 מפחד בלילות. וז\"ש, \u0003כל חד חרבא שננא על ירכיה.\u0004 כי שתין פולסין דנורא ה\"ס ששים גבורים. שהם שומרים מטת שלמה, שה\"ס המלכות הנקראת מטה, ושומרים אותה בעת הארת החכמה, שהחיצונים לא יוכלו לינק ממנה. \u0003וחרב שנון\u0004, ה\"ס הדינים הקשים. \u0003על ירכו\u0004, ה\"ס היסוד, שמשם יוצאים ומתגלים."],[2,"סליק ברעותא לאפקא וכו':","עלה ברצונו, להוציא אדם שליט למטה. והתקין בחיה האחת הזו, הנ\"ל שהיא המלכות, עפר דק, כלול מכל הספירות, נשב בו, ונתפשט בארבע רוחות העולם, דהיינו שנתפשט לגוף, לארבע רוחות העולם. וד' חתיכות מן הגוף, נתגלגלו, אחד למעלה, שהוא נצח. ואחד למטה, שהוא הוד. שה\"ס הרגלים המכונים נו\"ה. ואחד לצפון, שהוא יד שמאל, שה\"ס גבורה. ואחד לדרום, שהוא יד ימין, שה\"ס חסד."],[2,"עפר דקיק",", ה\"ס מלכות הנמתקת כל כך בבינה, עד שהמלכות הנקראת עפר, אינה נתפסת, ונחשבת כולה לבינה, ונקראת משום זה, עפר דקיק. שז\"ס וייצר ה' אלקים את האדם עפר מן האדמה וגו'. \u0003אדמה\u0004 ה\"ס הבינה המכונית אדום, \u0003עפר\u0004 ה\"ס המלכות, וה' צר את האדם בעפר הנלקח מן האדמה, שכולו בצורת אדמה, שהיא בינה. אלא שכלול מכל עשר ספירות. כנ\"ל."],[3,"אילנא חד רברבא וכו':","אילן אחד גדול וחזק, שהוא עץ החיים, דהיינו ז\"א, נתחבר ונזדווג בענף יפה אחד, שהוא המלכות, שמראהו היא שמחת הכל, כש\"א, יפה נוף משוש כל הארץ. בו נזדווג, והוציאו רוח אחד נסתר, ומילא לאותה עיסת העפר, והאדם קם על רגליו. והמליכו על כל העולם והשליטו על כל. ז\"ש, תמשילהו במעשי ידיך וגו'. נצטוה על אותו האילן, שהוא עץ הדעת, שלא לאכול ממנו. ולא שמר המצוה. השיב המלך את רוחו של אדם אליו, ואותה החיה, שהיא המלכות, לקחה את הרוח. מן האדם. \u0003גבילו\u0004 פירושו עסה, מלשון גביל וספי ליה לתורא, (שבת קנ\"ו)."],[4,"כדין זמינין מנא וכו':","אז הכינו ז\"א ומלכות, כלי אחרת, דהיינו גוף אחר, והאדם קם ביניהם בקשר של נפש רוח החקוקים בין מלאכים קדושים שנתאחדו בציור העטרות של המלאכים. פירוש, שמקודם החטא היה לו נר\"ן מאצילות. וגוף מבחינת בריאה. ואחר שחטא ניתן לו גוף אחר, מעולם הזה. ונר\"ן מבחינת המלאכים הקדושים."],[5,"דרין בתראין תפיסין וכו':","הדורות שלאחריהם נתפשו בחטא שלהם דעצה\"ד, ונגזרה עליהם מיתה, שלבסוף הרוח שלהם נשלף מכלי ולבוש ההוא שלהם, דהיינו הגוף, והגוף מת. ואח\"כ נגנז בעפר בין רגבי נחל, שהוא הקבר, מלשון מתקו לו רגבי נחל (איוב כ\"א ל\"ג). וכל המתים נסתרו ונגנזו בעצם אחת חזקה שנשארה מהכלי ההוא, דהיינו עצם לוז שאינה נרקבת בקבר. ונקראת ג\"כ בתואל הארמי. (כנ\"ל תולדות אות נ\"א בהסולם שנתבאר היטב) שיהיו נבנים ממנו בתחילה, ויקומו מחנות מחנות. ויתערו שנית בארץ ישראל. דהיינו ע\"י גלגול מחילות יבואו כולם לארץ ישראל. ושם תגמר שלמות תחיתם."],[6,"וזמין קב\"ה למגבל וכו':","ועתיד הקב\"ה ללוש אותו העפר הקודם, של אותו הכלי, דהיינו הגוף הקודם לחטא עצה\"ד, ממש. ולהכניס בו עיסה דקה מן הדקה, כשאור הזה שבעיסה, ומאותה העיסה, שהיא צחות שלמעלה, יתתקן ויתישר הכלי השלם, כעין שאמר הכתוב, ומעיין מבית ה' יצא והשקה את נחל השטים. משום שהנחל ההוא מרבה אהבה בעולם, וכשאותו המעיין הקדוש יצא ויכנס בו, בנחל השטים, אז יתתקן ויתישר, ולא יהא בקלקולו כבתחילה."],[6,"","פירוש. מתחילה נברא גופו של אדם מבחינת עולם הבריאה, שהוא בחינת בינה, ואע\"פ שנאמר וייצר ה' אלקים את האדם עפר מן האדמה, ועפר הוא מלכות, אמנם מן האדמה כתוב, ואדמה, ה\"ס בינה שנקראת אדום. דהיינו מלכות דבריאה, אשר מלכות זו היא כמו בינה, והעפר אשר שם אינו נתפש ואינו ניכר, וז\"ש \u0003אתקין בהאי חיותא חד\u0004, שהתקין מבחינת מלכות, \u0003עפרא דקיקא\u0004, דהיינו כנ\"ל שהיתה דקה מן הדקה עד שלא היתה נתפסת כלל. ולפיכר היה הגוף נצחי. שלא היתה בו שום אחיזה לקליפות. אבל אחר שחטא בעץ הדעת טוב ורע, נפל ממדרגתו ונבנה גופו מעולם הזה, שהוא נמשך מבחינת המלכות הנקראת ג\"כ עץ הדעת טוב ורע. מטעם שיש בה \u0003ב' נקודות\u0004, מנעולא, ומפתחא, \u0003שמנעולא\u0004 הוא בחינת מלכות דמדת הדין, הבלתי נמתקת בבינה, שעליה רובץ צמצום א' והמסך, שלא לקבל מאור העליון. ובחינת \u0003מפתחא\u0004, היא המלכות המעורבת וממותקת בבינה, שהיא ראויה לקבל כל האורות העליונים כמו הבינה. ומאלו ב' נקודות נבנית המלכות, וכן גופו של אדם. ואם אדם זוכה נגנזת נקודה דמנעולא ונקודה דמפתחא שולטת במלכות, ואז האדם ראוי לקבל כל האורות העליונים לפי מדרגתו. ואם האדם אינו זוכה, אז מתגלה בחינת המנעולא, ונגלה שהיא מלכות המצומצת ואז פורחים כל האורות מן האדם. כמ\"ש כל זה לעיל (בהקסה\"ז אות קכ\"ז) שע\"כ נקראת המלכות עץ הדעת טוב, מטעם \u0003זכי הא טוב, לא זכי הא רע\u0004, כמו שבארנו. עש\"ה."],[6,"","ומשום זה עם אכילת עצה\"ד נפלו למדרגת עץ הדעת טו\"ר, ונגזרה המיתה על האדם והבאים אחריו. כי הגוף ירד לבחינת המלכות מבחינת עץ הדעת טוב ורע, שהם הכלים דנקודת המפתחא שהוא מקבל מן המלכות, והם נמשכים מז' ספירות שלה שכל אחת כלולה מעשר, והם ע' ספירות, שמהם נמשכים שבעים שנה לאדם. ובסופה של המלכות מתעוררת נקודת המנעולא, ולפיכך כשנקודה זו מתעוררת על האדם, תיכף פורחים ממנו אורות החיים והוא מת. ולפיכך אחר שבעים שנה מוכרח האדם למות, דהיינו בהגעת זמן גילוי המנעולא. אמנם אם לא זכה האדם, מתגלה עליו המנעולא גם מקודם שהשלים ע' שנותיו, שז\"ס כרת ומיתה בידי שמים."],[6,"","וז\"ש, \u0003לא נטר פקודא אתיב מלכא רוחא לגביה\u0004, וכו', שאותו הרוח דאצילות, לקח ממנו הקב\"ה, \u0003כדין זמינין מנא אחרא\u0004, דהיינו הגוף מבחינת עץ הדעת טוב ורע. שיש בו אחיזה לקליפה, וע\"כ אם זכי הא טוב לא זכי הא רע. והוא מוכרח למות אחר ע' שנה כנ\"ל. \u0003וקאים בינייהו בקוטרא דגליפין\u0004 וכו', שתחת הרוח דאצילות, נתנו לו רוח ממקום המלאכים שבעולם היצירה. \u0003דרין בתראין תפיסין בחובייהו\u0004, שכל הדורות אחריו שיצאו ממנו נתפסו בעונם של אדם וחוה, שלהיותם צאצאיו, גם הם קבלו גוף מבחינת עץ הדעת טו\"ר, ונגזרה המיתה גם עליהם. וז\"ש, \u0003אשתליף רוחיהון מההוא מאנא, דלבושא\u0004, דהיינו שהרוח יוצא מהם לבסוף ומתים, \u0003לבתר אגניז בעפרא בין רגבי נחלא\u0004, דהיינו שנקבר בקבר."],[6,"","ונודע, שכל העצמות נרקבות בקבר חוץ מעצם קשה אחת, שנקראת לוז, או בתואל הארמי. והוא מטעם המבואר לעיל (תולדות אות נ\"א) \u0003דלית סביל טעמא דמזונא\u0004, שפירושו, כי העצם הזו היא מבחינת מנעולא, ששורשה גנוז במלכות כל ע' שנות חיים, ולפיכך אינה יכולה לקבל מזונות. וגם אינה ראויה לקבל מזונות, להיותה מבחינת מלכות המצומצמת שלא לקבל אור עליון כנ\"ל. ולפיכך כל העצמות שהם מבחינת מפתחא וקבלו מזונות מן המלכות, הנה בשעת מיתה, שנגלה שלא היו ראויות לקבל מזונות, יש בהן אחיזה לקליפות וצריכות להרקב. משא\"כ אותה העצם שהיתה תמיד בבחינת מנעולא ולא קבלה שום מזונות ממלכות, אין לקליפות במה לאחוז בה. וע\"כ אינה נרקבת בקבר (כמ\"ש שם)."],[6,"","וז\"ש \u0003אתטמרו ואתגניזו\u0004, דהיינו שנגנזים בקבר. \u0003בחד גרמא תקיף דההוא מאנא\u0004, דהיינו בעצם לוז, \u0003יתבנון בקדמיתא ויקומון חילין חילין\u0004 שזה יהיה בגמר התקון אחר שתתוקן מלכות דצמצום א' והמלכות תהיה ראויה לקבל אור מבחינתה עצמה, דהיינו מבחינת מנעולא. הנה אז כל הגופים שמתו מחמת גילוי מנעולא, יקומו עתה לתחיה, כי עתה גם המנעולא ראויה לקבל אור. ומתחילה בעת שיקומו לתחיה, יבנה כל הגוף מכלים דמנעולא בלבד, להיותו ראוי אז לקבלת אור העליון, כמו הכלים דבינה. וז\"ש \u0003בחד גרמא תקיף דההוא מאנא יתבנון בקדמיתא.\u0004 אמנם עכ\"ז, צריכים להמשכת קדושה מבינה. וע\"כ כל המתים שיעמדו לתחיה, בכל מקום שהם, צריכים לבא לארץ ישראל, ושם מקבלים השלמה מן הבינה. וז\"ש, \u0003תניינות, בארעא קדישא מתערין.\u0004 כי שם הם מקבלים קדושתם האחרונה."],[6,"","ומפרש סוד התחיה, ואומר \u0003וזמין קב\"ה למגבל ההוא עפרא קדמיתא, דההוא מאנא ממש\u0004, שחוזר הקב\"ה ללוש עפר הראשון של האדם, של אותו הגוף ממש שמת, דהיינו מבנין הנמשך מעצם המנעולא שנשאר מאותו הגוף. \u0003ולאעלא ביה גבילו דקיק כהאי חמירא דעיסה\u0004, דהיינו שיכניס בו המסך דבינה עליונה, שישמש בבנין הגוף לחזקו ולהשלימו כמו שאור בעיסה. שזה נעשה בארץ ישראל כנ\"ל. \u0003ומההוא גבילו, דאיהו צחותא דלעילא\u0004, ומעיסה זו של הבינה שהיא צחות הבינה שלמעלה, \u0003יתתקן ויתישר מאנא דכשרא\u0004, דהיינו שיקבל גמר תקונו."],[6,"","וז\"ש לעיל (פרשת אמור אות נ\"א) שעתידים המתים לעמוד במומם ואח\"כ יתרפאו, ויהיו שלמים בכל, ואז ביום ההוא יהיה ה' אחד ושמו אחד. שפירושו, שאע\"פ שאחר גמר התקון מקבלת המנעולא כל תקונה, עכ\"ז כיון שהמנעולא, ה\"ס הרצון לקבל הגדול שהיתה במלכות דצמצום א', ע\"כ אחר תקונו יש בו ג\"כ מרצון לקבל ההוא, שמשם היו כל המומים שבגוף. כמ\"ש הטעם לעיל בהקדמה שלי בחלק א' דף ל\"ז אות כ\"ח, ע\"ש ואין להאריך כאן. וז\"ש, כאן, \u0003וזמין קב\"ה למגבל ההוא עפרא קדמיתא דההוא מאנא ממש\u0004, דהיינו עם כל המומים שהיה לו בגוף הראשון, מטעם שליטת הרצון לקבל. כי המנעולא הוא שורש השרשים לרצון לקבל הזה. ואח\"כ \u0003ולאעלא ביה גבילו דקיק\u0004 וכו' שה\"ס הבינה, כנ\"ל, \u0003ומההוא גבילו\u0004 וכו' \u0003יתתקן ויתישר מאנא דכשרא\u0004, שאז יתרפא מכל המומים."],[6,"","וז\"ש \u0003בגוונא דאמר קרא ומעיין מבית ה' יצא\u0004, שה\"ס הבינה, \u0003והשקה את נחל השטים\u0004, שה\"ס הגופים שעמדו לתחיה, עם כל המומים שבהם. ולמה לא ריפא אותם מקודם התחיה, הוא, \u0003בגין דההוא נחל אסגי חביבותא בעלמא\u0004, כי הרצון לקבל הזה מרבה החביבות והתענוג, כי מדת התענוג היא לפי מדת הרצון לקבל. אלא שצריכים לישר אותו שיהיה מוגבל לקבל על מנת להשפיע, וזה נעשה ע\"י הארות הבינה, דהיינו אותו \u0003גבילו דקיק\u0004 הנ\"ל. וז\"ש \u0003וכד ההוא מעיינא קדישא יפוק וייעול לגביה\u0004, דהיינו הארות הבינה, כדין \u0003יתתקן ויתיישר ולא יהא בסורחניה כקדמיתא\u0004, כי הרצון לקבל יתתקן ויתישר שתהיה קבלה על מנת להשפיע ואז לא יהיה הרצון לקבל מקולקל כמו בתחילה. שבזה הוא מתרפא מכל המומים שהיו בו. ולהבין היטב ענין הרצון לקבל, צריך שתעיין בהקדמה שלי הנ\"ל (מאות א' עד כ\"ט)."],[7,"ואינון דלא זכאן וכו':","ואלו שאינם זוכים, יקומו להיות נדונים בדין מלך העליון. ז\"ש ורבים מישני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות ולדראון עולם. ואז כתוב, כי כאשר השמים החדשים והארץ החדשה אשר אני עושה עומדים לפני נאם ה' כן יעמוד זרעכם ושמכם. בילא\"ו יילא\"ו."]],[[0,"","מִשְׁנָה, לָכֶם בְּנֵי אָדָם, בַּעֲלֵי הַחָכְמָה, בַּעֲלֵי הַתְּבוּנָה, קוֹל קוֹרֵא: מִי מִכֶּם שֶׁהִתְחַכֵּם וְיוֹדֵעַ, בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן הִתְקִין הָרֹאשׁ, רָשׁוּם מִמַּעְלָה לְמַטָּה וּמִמַּטָּה לְמַעְלָה, הִתְקִין צַד הַצָּפוֹן בְּעִטּוּר שֶׁל אֲגַם מַיִם, בּוֹ רָשׁוּם הָעֹמֶק שֶׁל הַתְּהוֹם הָעֶלְיוֹן שֶׁעוֹלֶה וְיוֹרֵד בְּתוֹכוֹ, יָרְדָה דַרְגָּה טְמִירָה אַחַת בְּאֶלֶף וַחֲמֵשׁ מֵאוֹת רִשּׁוּמִים שֶׁל אֶלֶף וַחֲמֵשׁ מֵאוֹת עוֹלָמוֹת."],[1,"","תַּחְתָּיו בְּצִלּוֹ חוֹסָה חַיַּת בָּר אַחַת, [דניאל ז] וְלָהּ עֶשֶׂר קַרְנַיִם, [שם] וְאֵלּוּ עֵינַיִם כְּמוֹ עֵינֵי אֱנוֹשׁ לַחַיָּה, וּפֶה מְדַבֵּר גְּדוֹלוֹת. כְּשֶׁעוֹלָה, הוֹלֶכֶת בַּיּוֹם, נִסְתֶּרֶת בַּלַּיְלָה. כְּשֶׁיּוֹרֶדֶת, נִסְתֶּרֶת בַּיּוֹם, וְהוֹלֶכֶת בַּלַּיְלָה. כְּשֶׁנּוֹסַעַת, מִזְדַּעְזְעִים אַרְבַּע מַגְרֵפוֹת שֶׁאֲחוּזִים בְּיָדֶיהָ. וְנוֹסְעִים עִמָּהּ שִׁשִּׁים שִׁבְטֵי אֵשׁ, כָּל אֶחָד חֶרֶב שְׁנוּנָה עַל יְרֵכוֹ."],[2,"","עָלָה בְרָצוֹן, לְהוֹצִיא אָדָם שַׁלִּיט לְמַטָּה. הִתְקִין בַּחַיָּה הַזּוֹ עָפָר דַּקִּיק אֶחָד שֶׁכָּלוּל מֵהַכֹּל. נָשַׁב בּוֹ וְהִתְפַּשֵּׁט בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם. וְאַרְבַּע חֲתִיכוֹת הִתְגַּלְגְּלוּ, אַחַת לְמַעְלָה, אַחַת לְמַטָּה, אַחַת לַצָּפוֹן, אַחַת לַדָּרוֹם."],[3,"","אִילָן אֶחָד גָּדוֹל וְחָזָק הִתְחַבֵּר וְהִזְדַּוֵּג עִמָּהּ בְּעָנָף אֶחָד יָפֶה שֶׁמַּרְאֵהוּ שִׂמְחַת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר [תהלים מח] יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. עִמּוֹ הִזְדַּוֵּג, הוֹצִיאוּ רוּחַ טְמִירָה אַחַת, וּמִלֵּא אוֹתָהּ עִסַּת הֶעָפָר, וְעָמַד עַל רַגְלָיו, וְהִמְלִיךְ אוֹתוֹ עַל כָּל הָעוֹלָם וְהִשְׁלִיט אוֹתוֹ עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב [שם ח] תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךְ וְגוֹ'. נִצְטַוָּה עַל אוֹתוֹ הָאִילָן, לֹא שָׁמַר אֶת הַמִּצְוָה. הֵשִׁיב הַמֶּלֶךְ אֶת רוּחוֹ אֵלָיו, וְאוֹתָהּ הַחַיָּה לָקְחָה אוֹתוֹ."],[4,"","אָז הִזְמִינוּ כְּלִי אַחֵר וְעָמַד בֵּינֵיהֶם, בְּקֶשֶׁר הַחִקּוּקִים בֵּין מַלְאָכִים קְדוֹשִׁים שֶׁנֶּאֶחְזוּ בַּצִּיּוּר [בדפוס] שֶׁל הָעִטּוּרִים."],[5,"","הַדּוֹרוֹת הָאַחֲרוֹנִים תְּפוּסִים בַּחֲטָאֵיהֶם. נִשְׁלְפָה רוּחָם מֵאוֹתוֹ הַכְּלִי שֶׁל הַלְּבוּשׁ, אַחַר כָּךְ נִגְנַז בֶּעָפָר בֵּין רִגְבֵי הַנַּחַל. נִטְמְנוּ וְנִגְנְזוּ בְּעֶצֶם קָשָׁה אַחַת שֶׁל אוֹתוֹ הַכְּלִי, וְיָקוּמוּ שֵׁנִית חֲיָלוֹת חֲיָלוֹת, מִתְעוֹרְרִים בָּאָרֶץ הַקְּדוֹשָׁה."],[6,"","וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָלוּשׁ אוֹתוֹ הֶעָפָר הָרִאשׁוֹן שֶׁל אוֹתוֹ הַכְּלִי מַמָּשׁ, וּלְהַכְנִיס בּוֹ גְּבוּל דַּק כְּמוֹ הַשְּׂאוֹר הַזֶּה שֶׁל הָעִסָּה. וּמֵאוֹתָהּ עִסָּה, שֶׁהִיא הַצַּחוּת שֶׁלְּמַעְלָה, יִתְתַּקֵּן וְיִתְיַשֵּׁר כְּלִי כָּשֵׁר, כְּמוֹ שֶׁאָמַר הַכָּתוּב, [יואל ד] וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים. מִשּׁוּם שֶׁאוֹתוֹ הַנַּחַל מַגְדִּיל הַחֲבִיבוּת [הזנות] בָּעוֹלָם. וּכְשֶׁאוֹתוֹ הַמַּעְיָן הַקָּדוֹשׁ יֵצֵא וְיִכָּנֵס אֵלָיו, אֲזַי יִתְתַּקֵּן וְיִתְיַשֵּׁר, וְלֹא יִהְיֶה בְסִרְחוֹנוֹ כְבָרִאשׁוֹנָה."],[7,"","וְאוֹתָם שֶׁלֹּא זוֹכִים, יָקוּמוּ לְהִדּוֹן בַּדִּין שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב [דניאל יב] וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת [ו] לְדִרְאוֹן עוֹלָם. וְאָז כָּתוּב, [ישעיה סו] כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עֹשֶׂה עֹמְדִים לְפָנַי נְאֻם ה' כֵּן יַעֲמֹד זַרְעֲכֶם וְשִׁמְכֶם. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
